-- 13. dbo.WN_AccessCards_GetList (ALTERED)
-- Ensures CustomerEmail is sourced ONLY from dbo.WN_Customers (c.Email).
-- ==============================================================================
CREATE   PROCEDURE [dbo].[WN_AccessCards_GetList]
    @Page       INT           = 1,
    @Limit      INT           = 20,
    @Search     NVARCHAR(100) = NULL,
    @BookingId  INT           = NULL,
    @CustomerId INT           = NULL,
    @SpaceId    INT           = NULL,
    @Status     INT           = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @Page < 1 SET @Page = 1;
    IF @Limit < 1 SET @Limit = 20;
    DECLARE @Offset INT = (@Page - 1) * @Limit;

    SELECT
        ac.Id,
        ac.IdGUID,
        ac.LocationId,
        l.Name AS LocationName,
        ac.CustomerId,
        ISNULL(NULLIF(RTRIM(LTRIM(ISNULL(c.FirstName, '') + ' ' + ISNULL(c.LastName, ''))), ''), u.Name) AS CustomerName,
        c.Email AS CustomerEmail,
        ac.BookingId,
        ac.SpaceId,
        s.Name AS SpaceName,
        s.Code AS SpaceCode,
        ac.CardNumber,
        ac.StartDate,
        ac.EndDate,
        ac.Status,
        CASE WHEN ac.Status = 1 THEN 'Active'
             WHEN ac.Status = 2 THEN 'Restricted'
             WHEN ac.Status = 3 THEN 'Inactive'
             ELSE 'Unknown' END AS StatusLabel,
        ac.CreatedOn,
        ac.UpdatedOn,
        COUNT(*) OVER() AS TotalCount
    FROM dbo.WN_AccessCards ac WITH (NOLOCK)
    LEFT JOIN dbo.WN_Locations l WITH (NOLOCK) ON l.Id = ac.LocationId
    LEFT JOIN dbo.WN_Customers c WITH (NOLOCK) ON c.Id = ac.CustomerId
    LEFT JOIN dbo.WN_Users u WITH (NOLOCK) ON u.Id = c.UserId
    LEFT JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = ac.SpaceId
    WHERE (@BookingId IS NULL OR ac.BookingId = @BookingId)
      AND (@CustomerId IS NULL OR ac.CustomerId = @CustomerId)
      AND (@SpaceId IS NULL OR ac.SpaceId = @SpaceId)
      AND (@Status IS NULL OR ac.Status = @Status)
      AND (@Search IS NULL OR @Search = ''
           OR ac.CardNumber LIKE '%' + @Search + '%'
           OR c.FirstName   LIKE '%' + @Search + '%'
           OR c.LastName    LIKE '%' + @Search + '%'
           OR c.Email       LIKE '%' + @Search + '%'
           OR s.Name        LIKE '%' + @Search + '%')
    ORDER BY ac.Id DESC
    OFFSET @Offset ROWS FETCH NEXT @Limit ROWS ONLY;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_AccessCards_Insert]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
