-- 3. WN_AccessCards_Insert
CREATE   PROCEDURE [dbo].[WN_AccessCards_Insert]
    @LocationId INT,
    @CustomerId INT,
    @BookingId INT,
    @SpaceId INT,
    @CardNumber NVARCHAR(100) = NULL,
    @StartDate DATETIME,
    @EndDate DATETIME,
    @Status INT = 1,
    @CreatedById INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @CardNumber IS NULL OR RTRIM(LTRIM(@CardNumber)) = ''
    BEGIN
        SET @CardNumber = 'AC-' + CAST(@BookingId AS NVARCHAR(20)) + '-' + RIGHT(REPLACE(CAST(NEWID() AS NVARCHAR(36)), '-', ''), 4);
    END;

    INSERT INTO dbo.WN_AccessCards (
        IdGUID, LocationId, CustomerId, BookingId, SpaceId, CardNumber, StartDate, EndDate, Status, CreatedOn, CreatedById
    )
    VALUES (
        NEWID(), @LocationId, @CustomerId, @BookingId, @SpaceId, @CardNumber, @StartDate, @EndDate, @Status, SYSUTCDATETIME(), @CreatedById
    );

    DECLARE @NewId INT = SCOPE_IDENTITY();

    EXEC dbo.WN_AccessCards_GetById @Id = @NewId;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_AccessCards_PopulateAllBookings]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_AccessCards_PopulateAllBookings]
    @TargetBookingId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- Clean up cards if target booking was cancelled or deleted
    IF @TargetBookingId IS NOT NULL
    BEGIN
        DELETE ac
        FROM dbo.WN_AccessCards ac
        JOIN dbo.WN_Bookings b ON b.Id = ac.BookingId
        WHERE ac.BookingId = @TargetBookingId
          AND (b.IsDeleted = 1 OR b.BookingStatusId IN (3, 4, 6, 86));
    END;

    -- Update existing access cards with correct invoice rent period start/end dates and status
    UPDATE ac
    SET 
        ac.StartDate = ISNULL(inv.BillingPeriodStart, b.StartOn),
        ac.EndDate   = ISNULL(inv.BillingPeriodEnd, DATEADD(MONTH, ISNULL(NULLIF(b.AdvanceRentMonths, 0), 1), b.StartOn)),
        ac.Status    = CASE 
                        WHEN ISNULL(inv.BillingPeriodEnd, DATEADD(MONTH, ISNULL(NULLIF(b.AdvanceRentMonths, 0), 1), b.StartOn)) < CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2(0)) THEN 3 -- Inactive/Expired
                        ELSE 1 -- Active
                       END,
        ac.UpdatedOn = SYSUTCDATETIME()
    FROM dbo.WN_AccessCards ac
    JOIN dbo.WN_Bookings b ON b.Id = ac.BookingId
    OUTER APPLY (
        SELECT TOP 1 BillingPeriodStart, BillingPeriodEnd
        FROM dbo.WN_Invoices
        WHERE BookingId = b.Id AND IsDeleted = 0
        ORDER BY Id ASC
    ) inv
    WHERE (@TargetBookingId IS NULL OR b.Id = @TargetBookingId);

    -- Insert missing cards up to (Capacity + 1)
    WITH Numbers AS (
        SELECT TOP 500 ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS Seq
        FROM sys.all_objects a CROSS JOIN sys.all_objects b
    )
    INSERT INTO dbo.WN_AccessCards (
        IdGUID,
        LocationId,
        CustomerId,
        BookingId,
        SpaceId,
        CardNumber,
        StartDate,
        EndDate,
        Status,
        CreatedOn,
        UpdatedOn,
        CreatedById,
        UpdatedById
    )
    SELECT 
        NEWID() AS IdGUID,
        CASE 
            WHEN EXISTS (SELECT 1 FROM dbo.WN_Locations l WHERE l.Id = s.LocationId) THEN s.LocationId
            ELSE (SELECT TOP 1 Id FROM dbo.WN_Locations ORDER BY Id ASC)
        END AS LocationId,
        COALESCE(
            c_code.Id,
            c_user.Id,
            c_email.Id,
            (SELECT TOP 1 Id FROM dbo.WN_Customers ORDER BY Id ASC)
        ) AS CustomerId,
        b.Id AS BookingId,
        b.SpaceId AS SpaceId,
        'AC-' + CAST(b.Id AS NVARCHAR(20)) + '-' + RIGHT('00' + CAST(n.Seq AS NVARCHAR(10)), 2) AS CardNumber,
        ISNULL(inv.BillingPeriodStart, b.StartOn) AS StartDate,
        ISNULL(inv.BillingPeriodEnd, DATEADD(MONTH, ISNULL(NULLIF(b.AdvanceRentMonths, 0), 1), b.StartOn)) AS EndDate,
        CASE 
            WHEN ISNULL(inv.BillingPeriodEnd, DATEADD(MONTH, ISNULL(NULLIF(b.AdvanceRentMonths, 0), 1), b.StartOn)) < CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2(0)) THEN 3 -- Inactive/Expired
            ELSE 1 -- Active
        END AS Status,
        SYSUTCDATETIME() AS CreatedOn,
        NULL AS UpdatedOn,
        CASE 
            WHEN EXISTS (SELECT 1 FROM dbo.WN_Users u WHERE u.Id = b.CreatedById) THEN b.CreatedById
            WHEN EXISTS (SELECT 1 FROM dbo.WN_Users u WHERE u.Id = b.UserId) THEN b.UserId
            ELSE NULL
        END AS CreatedById,
        NULL AS UpdatedById
    FROM dbo.WN_Bookings b
    JOIN dbo.WN_Spaces s ON s.Id = b.SpaceId
    LEFT JOIN dbo.WN_Users u ON u.Id = b.UserId
    LEFT JOIN dbo.WN_Customers c_code ON c_code.Code = b.CustomerCode
    LEFT JOIN dbo.WN_Customers c_user ON c_user.UserId = b.UserId
    LEFT JOIN dbo.WN_Customers c_email ON c_email.Email = u.Email
    OUTER APPLY (
        SELECT TOP 1 BillingPeriodStart, BillingPeriodEnd
        FROM dbo.WN_Invoices
        WHERE BookingId = b.Id AND IsDeleted = 0
        ORDER BY Id ASC
    ) inv
    CROSS JOIN Numbers n
    WHERE b.IsDeleted = 0
      AND b.BookingStatusId NOT IN (3, 4, 6, 86) -- Exclude Cancelled (3) and Rejected (4)
      AND (@TargetBookingId IS NULL OR b.Id = @TargetBookingId)
      AND n.Seq <= (ISNULL(NULLIF(s.Capacity, 0), 1) + 1)
      AND NOT EXISTS (
          SELECT 1 FROM dbo.WN_AccessCards ac 
          WHERE ac.BookingId = b.Id AND ac.CardNumber = 'AC-' + CAST(b.Id AS NVARCHAR(20)) + '-' + RIGHT('00' + CAST(n.Seq AS NVARCHAR(10)), 2)
      )
    ORDER BY b.Id, n.Seq;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_AccessCards_Update]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- 4. WN_AccessCards_Update
CREATE   PROCEDURE [dbo].[WN_AccessCards_Update]
    @Id NVARCHAR(100),
    @LocationId INT = NULL,
    @CustomerId INT = NULL,
    @BookingId INT = NULL,
    @SpaceId INT = NULL,
    @CardNumber NVARCHAR(100) = NULL,
    @StartDate DATETIME = NULL,
    @EndDate DATETIME = NULL,
    @Status INT = NULL,
    @UpdatedById INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE dbo.WN_AccessCards
    SET 
        LocationId  = ISNULL(@LocationId, LocationId),
        CustomerId  = ISNULL(@CustomerId, CustomerId),
        BookingId   = ISNULL(@BookingId, BookingId),
        SpaceId     = ISNULL(@SpaceId, SpaceId),
        CardNumber  = ISNULL(@CardNumber, CardNumber),
        StartDate   = ISNULL(@StartDate, StartDate),
        EndDate     = ISNULL(@EndDate, EndDate),
        Status      = ISNULL(@Status, Status),
        UpdatedOn   = SYSUTCDATETIME(),
        UpdatedById = ISNULL(@UpdatedById, UpdatedById)
    WHERE (TRY_CAST(@Id AS INT) IS NOT NULL AND Id = TRY_CAST(@Id AS INT))
       OR (TRY_CAST(@Id AS UNIQUEIDENTIFIER) IS NOT NULL AND IdGUID = TRY_CAST(@Id AS UNIQUEIDENTIFIER))
       OR (CardNumber = @Id);
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_AccessOfficer_Lookup]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_AccessOfficer_Lookup]
    @Cnic            NVARCHAR(40)  = NULL,  -- CNIC / passport number; compared on letters and digits only (- space . / _ ignored)
    @PersonId        INT           = NULL,  -- or one person (the API's write calls); at least one of @Cnic / @PersonId
    @BookingDetailId INT           = NULL,  -- only this booked space; NULL = every booked space
    @LocationIds     NVARCHAR(MAX) = NULL   -- locations in scope, CSV (NULL = every location: super admin, write checks)
AS
BEGIN
    -- Access Officer page (read-only, AO_01). The people on a CONFIRMED booking (BookingStatusId 33) that has not ended,
    -- one row per booked space (WN_BookingDetails) and person:
    --   State assigned = on the space now (WN_BookingAttendants, AssignedTo empty or not passed);
    --   State pending  = added by the customer (WN_BookingEmployeeRequests, Pending), CNIC not checked, not on the space.
    --                    A request without a space counts for the booking's rent line (as dbo.WN_BookingEmployees_Get).
    -- AccessEnabled = WN_AccessStatus.IsEnabled of an assigned row (no row = on); 0 for pending.
    -- LocationId = WN_Spaces.LocationId of the booking (the location the API and the machines use for a booked space).
    -- Customer = the booking owner (WN_Customers by CustomerCode, else by UserId): company, else name, else email.
    -- MachineId = WN_HIK_PersonMap (NULL = never enrolled). ActiveCount / PendingCount = seats used on the space.
    -- Pending rows first, then the newest booking.
    SET NOCOUNT ON;
    DECLARE @Today DATE = CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE);
    DECLARE @Key NVARCHAR(40) = NULLIF(UPPER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(ISNULL(@Cnic, N''))),
                                N'-', N''), N' ', N''), N'.', N''), N'/', N''), N'_', N'')), N'');
    SET @LocationIds = NULLIF(LTRIM(RTRIM(@LocationIds)), N'');
    DECLARE @All BIT = CASE WHEN @LocationIds IS NULL THEN 1 ELSE 0 END;
    DECLARE @Scope TABLE (Id INT PRIMARY KEY);
    INSERT INTO @Scope (Id)
    SELECT DISTINCT TRY_CAST(value AS INT) FROM STRING_SPLIT(ISNULL(@LocationIds, N''), N',') WHERE TRY_CAST(value AS INT) > 0;
    -- The person(s): this CNIC / passport number and / or this person.
    DECLARE @P TABLE (PersonId INT PRIMARY KEY);
    INSERT INTO @P (PersonId)
    SELECT p.PersonId
      FROM dbo.WN_Persons p WITH (NOLOCK)
     WHERE (@Key IS NOT NULL OR @PersonId IS NOT NULL)
       AND (@PersonId IS NULL OR p.PersonId = @PersonId)
       AND (@Key IS NULL OR UPPER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(ISNULL(p.IdNumber, ''))),
                                 '-', ''), ' ', ''), '.', ''), '/', ''), '_', '')) = @Key);
    DECLARE @M TABLE (BookingDetailId INT NOT NULL, PersonId INT NOT NULL, State NVARCHAR(10) NOT NULL, CustomerId INT NULL,
                      PRIMARY KEY (BookingDetailId, PersonId));
    -- assigned: on the booked space now
    INSERT INTO @M (BookingDetailId, PersonId, State, CustomerId)
    SELECT ba.BookingDetailId, ba.PersonId, N'assigned', MAX(ba.CustomerId)
      FROM dbo.WN_BookingAttendants ba WITH (NOLOCK)
      JOIN @P p ON p.PersonId = ba.PersonId
     WHERE (ba.AssignedTo IS NULL OR ba.AssignedTo >= @Today)
       AND (@BookingDetailId IS NULL OR ba.BookingDetailId = @BookingDetailId)
     GROUP BY ba.BookingDetailId, ba.PersonId;
    -- pending: added by the customer, not on that space yet
    INSERT INTO @M (BookingDetailId, PersonId, State, CustomerId)
    SELECT x.BookingDetailId, x.PersonId, N'pending', MAX(x.CustomerId)
      FROM (SELECT COALESCE(r.BookingDetailId, rl.Id) AS BookingDetailId, r.PersonId, r.CustomerId
              FROM dbo.WN_BookingEmployeeRequests r WITH (NOLOCK)
              JOIN @P p ON p.PersonId = r.PersonId
              JOIN dbo.WN_Bookings b WITH (NOLOCK) ON b.Id = r.BookingId
             OUTER APPLY (SELECT TOP 1 d.Id
                            FROM dbo.WN_BookingDetails d WITH (NOLOCK)
                           WHERE d.BookingGuid = b.IdGUID AND ISNULL(d.IsDeleted, 0) = 0
                           ORDER BY CASE WHEN d.FeeType LIKE N'%Rent%' THEN 0 ELSE 1 END, d.Id DESC) rl
             WHERE r.Status = N'Pending') x
     WHERE x.BookingDetailId IS NOT NULL
       AND (@BookingDetailId IS NULL OR x.BookingDetailId = @BookingDetailId)
       AND NOT EXISTS (SELECT 1 FROM @M m WHERE m.BookingDetailId = x.BookingDetailId AND m.PersonId = x.PersonId)
     GROUP BY x.BookingDetailId, x.PersonId;
    SELECT m.BookingDetailId, b.Id AS BookingId, m.PersonId, m.State,
           p.Name, p.Email, p.Phone, p.IdType, p.IdNumber,
           COALESCE(NULLIF(LTRIM(RTRIM(s.Name)), N''), NULLIF(LTRIM(RTRIM(bd.SpaceName)), N''), bd.SpaceCode) AS Room,
           bd.SpaceCode, bd.SpaceName,
           s.LocationId, l.Name AS Location,
           COALESCE(cu.Customer, NULLIF(LTRIM(RTRIM(bd.CustomerName)), N''), bd.CustomerEmail) AS Customer,
           COALESCE(m.CustomerId, cu.Id) AS CustomerId,
           ISNULL(bs.Label, N'Confirmed') AS BookingStatus,
           COALESCE(bd.StartDateTime, b.StartOn) AS StartOn,
           COALESCE(bd.EndDateTime, b.EndOn) AS EndOn,
           CAST(CASE WHEN m.State = N'assigned' THEN ISNULL(acc.IsEnabled, 1) ELSE 0 END AS BIT) AS AccessEnabled,
           hpm.MachineID AS MachineId,
           (SELECT COUNT(DISTINCT ba2.PersonId)
              FROM dbo.WN_BookingAttendants ba2 WITH (NOLOCK)
             WHERE ba2.BookingDetailId = m.BookingDetailId
               AND (ba2.AssignedTo IS NULL OR ba2.AssignedTo >= @Today)) AS ActiveCount,
           (SELECT COUNT(DISTINCT r2.PersonId)
              FROM dbo.WN_BookingEmployeeRequests r2 WITH (NOLOCK)
             WHERE r2.BookingId = b.Id AND r2.Status = N'Pending'
               AND NOT EXISTS (SELECT 1 FROM dbo.WN_BookingAttendants ba3 WITH (NOLOCK)
                                WHERE ba3.BookingDetailId = m.BookingDetailId AND ba3.PersonId = r2.PersonId
                                  AND (ba3.AssignedTo IS NULL OR ba3.AssignedTo >= @Today))) AS PendingCount
      FROM @M m
      JOIN dbo.WN_BookingDetails bd WITH (NOLOCK) ON bd.Id = m.BookingDetailId
      JOIN dbo.WN_Bookings b WITH (NOLOCK) ON b.IdGUID = bd.BookingGuid
      JOIN dbo.WN_Persons p WITH (NOLOCK) ON p.PersonId = m.PersonId
      LEFT JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = b.SpaceId
      LEFT JOIN dbo.WN_Locations l WITH (NOLOCK) ON l.Id = s.LocationId
      LEFT JOIN dbo.WN_BookingStatuses bs WITH (NOLOCK) ON bs.Id = b.BookingStatusId
      LEFT JOIN dbo.WN_HIK_PersonMap hpm WITH (NOLOCK) ON hpm.PersonId = m.PersonId
     OUTER APPLY (SELECT TOP 1 a.IsEnabled
                    FROM dbo.WN_AccessStatus a WITH (NOLOCK)
                   WHERE a.BookingDetailId = m.BookingDetailId AND a.PersonId = m.PersonId
                   ORDER BY a.Id DESC) acc
     OUTER APPLY (SELECT TOP 1 c.Id,
                         COALESCE(NULLIF(LTRIM(RTRIM(c.Company)), N''),
                                  NULLIF(LTRIM(RTRIM(CONCAT(c.FirstName, N' ', c.LastName))), N''), c.Email) AS Customer
                    FROM dbo.WN_Customers c WITH (NOLOCK)
                   WHERE (NULLIF(b.CustomerCode, N'') IS NOT NULL AND c.Code = b.CustomerCode)
                      OR (NULLIF(b.CustomerCode, N'') IS NULL AND c.UserId = b.UserId)
                   ORDER BY c.Id) cu
     WHERE b.BookingStatusId = 33
       AND ISNULL(b.IsDeleted, 0) = 0
       AND ISNULL(bd.IsDeleted, 0) = 0
       AND COALESCE(bd.EndDateTime, b.EndOn) >= @Today
       AND (@All = 1 OR s.LocationId IN (SELECT Id FROM @Scope))
     ORDER BY CASE m.State WHEN N'pending' THEN 0 ELSE 1 END, COALESCE(bd.StartDateTime, b.StartOn) DESC, m.BookingDetailId DESC;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Account_Delete]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_Account_Delete]
    @UserId    INT,
    @CheckOnly BIT  = 0,     -- 1 = only say whether the account can be deleted (nothing is changed)
    @Today     DATE = NULL   -- the business date (Pakistan); NULL = today in Pakistan (UTC+5)
AS
BEGIN
    -- Self-service deletion of a customer account (QA_04). See the script header for what is removed and kept.
    -- ReasonCode: NULL (can be / was deleted), not_found, staff_account, active_booking, pending_booking, unpaid_invoice.
    -- The counts are always returned so the API can explain every reason at once.
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF @Today IS NULL SET @Today = CAST(SWITCHOFFSET(SYSDATETIMEOFFSET(), N'+05:00') AS DATE);
    DECLARE @GeneralRoleId INT = (SELECT TOP 1 r.Id FROM dbo.WN_Roles r WITH (NOLOCK) WHERE r.RoleName = N'general');
    IF @GeneralRoleId IS NULL SET @GeneralRoleId = 14;
    DECLARE @Exists BIT = 0, @IsActive BIT = 0, @RoleId INT = NULL, @OldEmail NVARCHAR(512) = NULL;
    DECLARE @Active INT = 0, @Pending INT = 0, @Unpaid INT = 0, @Balance DECIMAL(18, 2) = 0;
    DECLARE @Reason NVARCHAR(40) = NULL, @Placeholder NVARCHAR(256) = NULL, @Customers INT = 0;
    IF @CheckOnly = 0 BEGIN TRANSACTION;
    -- The user row is locked until the end, so two deletions (or a deletion and a booking) can't interleave.
    IF @CheckOnly = 0
        SELECT @Exists = 1, @IsActive = ISNULL(u.IsActive, 0), @RoleId = u.RoleId, @OldEmail = NULLIF(LTRIM(RTRIM(u.Email)), N'')
          FROM dbo.WN_Users u WITH (UPDLOCK, HOLDLOCK)
         WHERE u.Id = @UserId;
    ELSE
        SELECT @Exists = 1, @IsActive = ISNULL(u.IsActive, 0), @RoleId = u.RoleId, @OldEmail = NULLIF(LTRIM(RTRIM(u.Email)), N'')
          FROM dbo.WN_Users u WITH (NOLOCK)
         WHERE u.Id = @UserId;
    -- The customer profile: linked by UserId, or (older rows without a UserId) by the same email.
    DECLARE @CustomerIds TABLE (Id INT PRIMARY KEY, Code NVARCHAR(50) NULL);
    INSERT INTO @CustomerIds (Id, Code)
    SELECT c.Id, NULLIF(LTRIM(RTRIM(c.Code)), N'') FROM dbo.WN_Customers c
     WHERE @Exists = 1 AND (c.UserId = @UserId OR (c.UserId IS NULL AND @OldEmail IS NOT NULL AND c.Email = @OldEmail));
    -- Their bookings: made by staff for their customer code, or by the user in the app (as My Bookings finds them).
    DECLARE @BookingIds TABLE (Id INT PRIMARY KEY);
    INSERT INTO @BookingIds (Id)
    SELECT b.Id FROM dbo.WN_Bookings b
     WHERE @Exists = 1 AND ISNULL(b.IsDeleted, 0) = 0
       AND (b.UserId = @UserId OR b.CustomerCode IN (SELECT k.Code FROM @CustomerIds k WHERE k.Code IS NOT NULL));
    -- What stops a deletion. Read without NOLOCK on purpose: this decides whether personal data is removed.
    SELECT @Active  = ISNULL(SUM(CASE WHEN s.Code = N'Confirmed' THEN 1 ELSE 0 END), 0),
           @Pending = ISNULL(SUM(CASE WHEN s.Code = N'Pending'   THEN 1 ELSE 0 END), 0)
      FROM dbo.WN_Bookings b
      JOIN @BookingIds k ON k.Id = b.Id
      JOIN dbo.WN_BookingStatuses s ON s.Id = b.BookingStatusId
     WHERE s.Code IN (N'Confirmed', N'Pending')
       AND (b.EndOn IS NULL OR CAST(b.EndOn AS DATE) >= @Today);
    -- Money due: not Paid / Cancelled (legacy values 2 / 5, or the dbo.OrderStatus rows 'Paid' / 'Cancelled'),
    -- balance = grand total - WHT - paid (as the invoice lists show it).
    SELECT @Unpaid  = COUNT(*),
           @Balance = ISNULL(SUM(x.Balance), 0)
      FROM (SELECT ISNULL(i.GrandTotal, 0) - ISNULL(i.WHTAmount, 0) - ISNULL(i.PaidTotal, 0) AS Balance
              FROM dbo.WN_Invoices i
             WHERE (i.UserId = @UserId OR i.BookingId IN (SELECT k.Id FROM @BookingIds k))
               AND i.StatusId NOT IN (2, 5)
               AND NOT (i.StatusId > 5 AND EXISTS (SELECT 1 FROM dbo.OrderStatus os WITH (NOLOCK)
                                                    WHERE os.Id = i.StatusId
                                                      AND LTRIM(RTRIM(os.Description)) IN (N'Paid', N'Cancelled')))
               AND ISNULL(i.GrandTotal, 0) - ISNULL(i.WHTAmount, 0) - ISNULL(i.PaidTotal, 0) > 0) x;
    IF @Exists = 0 OR @IsActive = 0 SET @Reason = N'not_found';
    ELSE IF ISNULL(@RoleId, @GeneralRoleId) <> @GeneralRoleId SET @Reason = N'staff_account';
    ELSE IF @Active > 0 SET @Reason = N'active_booking';
    ELSE IF @Pending > 0 SET @Reason = N'pending_booking';
    ELSE IF @Unpaid > 0 SET @Reason = N'unpaid_invoice';
    IF @CheckOnly = 1 OR @Reason IS NOT NULL
    BEGIN
        IF @@TRANCOUNT > 0 AND @CheckOnly = 0 COMMIT TRANSACTION; -- nothing was changed
        SELECT @UserId AS UserId, CAST(CASE WHEN @Reason IS NULL THEN 1 ELSE 0 END AS BIT) AS CanDelete,
               CAST(0 AS BIT) AS Deleted, @Reason AS ReasonCode, @Active AS ActiveBookings, @Pending AS PendingBookings,
               @Unpaid AS UnpaidInvoices, @Balance AS BalanceDue;
        RETURN;
    END
    -- A unique address that can never receive mail (.invalid is reserved): the old email is free to sign up again.
    SET @Placeholder = N'deleted-' + CAST(@UserId AS NVARCHAR(12)) + N'-'
                     + LOWER(LEFT(REPLACE(CONVERT(NVARCHAR(36), NEWID()), N'-', N''), 10)) + N'@deleted.worknest.invalid';
    -- The audit triggers record who made the change: the user themselves, under the new address.
    EXEC sp_set_session_context @key = N'AppUserId', @value = @UserId;
    EXEC sp_set_session_context @key = N'AppUserEmail', @value = @Placeholder;
    EXEC sp_set_session_context @key = N'SourceApp', @value = N'AccountDelete';
    UPDATE dbo.WN_Users
       SET Name = N'Deleted user', UserName = N'Deleted user', Email = @Placeholder, PhoneNumber = NULL,
           Address = NULL, CnicOrPassport = NULL, AvatarUrl = NULL, PasswordHash = NULL, IsActive = 0, UpdatedOn = GETDATE()
     WHERE Id = @UserId;
    SET @Customers = (SELECT COUNT(*) FROM @CustomerIds);
    UPDATE c
       SET FirstName = N'Deleted user', LastName = NULL, Email = @Placeholder, PhoneNumber = NULL, CnicOrPassport = NULL,
           Address = NULL, IsActive = 0, UpdatedAt = GETDATE(), UpdatedById = @UserId
      FROM dbo.WN_Customers c
      JOIN @CustomerIds k ON k.Id = c.Id;
    UPDATE dbo.WN_DeviceToken SET IsActive = 0 WHERE UserId = @UserId AND IsActive = 1;
    UPDATE dbo.WN_RefreshTokens_Temp SET RevokedAt = SYSUTCDATETIME() WHERE UserId = @UserId AND RevokedAt IS NULL;
    -- The audit log keeps every change, but not the personal details of a deleted account.
    UPDATE a
       SET OldValues = CASE WHEN ISJSON(a.OldValues) = 1 THEN
               JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(a.OldValues,
               N'$.Name', NULL), N'$.UserName', NULL), N'$.Email', NULL), N'$.PhoneNumber', NULL), N'$.Address', NULL),
               N'$.CnicOrPassport', NULL), N'$.AvatarUrl', NULL), N'$.PasswordHash', NULL) ELSE a.OldValues END,
           NewValues = CASE WHEN ISJSON(a.NewValues) = 1 THEN
               JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(a.NewValues,
               N'$.Name', NULL), N'$.UserName', NULL), N'$.Email', NULL), N'$.PhoneNumber', NULL), N'$.Address', NULL),
               N'$.CnicOrPassport', NULL), N'$.AvatarUrl', NULL), N'$.PasswordHash', NULL) ELSE a.NewValues END
      FROM dbo.WN_AuditLog a
     WHERE a.EntityName = N'WN_Users' AND a.RecordId = CAST(@UserId AS NVARCHAR(64));
    UPDATE a
       SET OldValues = CASE WHEN ISJSON(a.OldValues) = 1 THEN
               JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(a.OldValues,
               N'$.FirstName', NULL), N'$.LastName', NULL), N'$.Email', NULL), N'$.PhoneNumber', NULL),
               N'$.CnicOrPassport', NULL), N'$.Address', NULL) ELSE a.OldValues END,
           NewValues = CASE WHEN ISJSON(a.NewValues) = 1 THEN
               JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(a.NewValues,
               N'$.FirstName', NULL), N'$.LastName', NULL), N'$.Email', NULL), N'$.PhoneNumber', NULL),
               N'$.CnicOrPassport', NULL), N'$.Address', NULL) ELSE a.NewValues END
      FROM dbo.WN_AuditLog a
      JOIN @CustomerIds k ON a.RecordId = CAST(k.Id AS NVARCHAR(64))
     WHERE a.EntityName = N'WN_Customers';
    UPDATE dbo.WN_AuditLog
       SET ChangedByUserEmail = @Placeholder
     WHERE ChangedByUserId = @UserId AND ChangedByUserEmail IS NOT NULL AND ChangedByUserEmail <> @Placeholder;
    INSERT INTO dbo.WN_AuditLog (EntityName, RecordId, Operation, OldValues, NewValues, ErrorMessage, ErrorSeverity,
                                 StackTrace, ChangedByUserId, ChangedByUserEmail, ChangedAt, SourceApp)
    VALUES (N'WN_Users', CAST(@UserId AS NVARCHAR(64)), 'D', NULL,
            (SELECT N'Account deleted by its owner' AS Action, @UserId AS UserId, @Customers AS CustomerProfiles,
                    N'Personal details removed; bookings, invoices, payments and agreements kept' AS Kept
               FOR JSON PATH, WITHOUT_ARRAY_WRAPPER),
            NULL, NULL, NULL, @UserId, @Placeholder, SYSUTCDATETIME(), N'AccountDelete');
    COMMIT TRANSACTION;
    SELECT @UserId AS UserId, CAST(1 AS BIT) AS CanDelete, CAST(1 AS BIT) AS Deleted, CAST(NULL AS NVARCHAR(40)) AS ReasonCode,
           @Active AS ActiveBookings, @Pending AS PendingBookings, @Unpaid AS UnpaidInvoices, @Balance AS BalanceDue;
END
GO
