-- 4. Get Agreement By ID with Quotation & Vendor Details
CREATE   PROCEDURE [dbo].[WN_Agreements_GetById]
    @AgreementId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT a.*, q.QuotationNumber, q.StartDateTime, q.EndDateTime,
           t.Name AS TemplateName, t.ContentHtml AS TemplateHtml,
           COALESCE(loc.Name, br.[Description], comp.CompanyName, '') AS CenterName,
           COALESCE(comp.CompanyName, br.[Description], loc.Name, 'WorkNest (Pvt) Ltd') AS VendorLegalName,
           COALESCE(NULLIF(LTRIM(RTRIM(ISNULL(comp.AddressLine1, '') + ' ' + ISNULL(comp.AddressLine2, ''))), ''), loc.Address, '') AS VendorAddress,
           COALESCE(comp.Contact, '') AS VendorPhone,
           COALESCE(comp.NTN, '') AS VendorNtn,
           ISNULL(ot.[Description], a.OperatingHours) AS OfferingTypeDescription
    FROM dbo.WN_Agreements a WITH (NOLOCK)
    JOIN dbo.WN_Quotations q WITH (NOLOCK) ON q.Id = a.QuotationId
    LEFT JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = q.SpaceId
    LEFT JOIN dbo.WN_Locations loc WITH (NOLOCK) ON loc.Id = s.LocationId
    LEFT JOIN dbo.Branches br WITH (NOLOCK) ON br.Id = loc.BranchId
    LEFT JOIN dbo.Company comp WITH (NOLOCK) ON comp.Id = COALESCE(loc.CompanyId, br.CompanyId)
    LEFT JOIN dbo.WN_LeaseTemplates t WITH (NOLOCK) ON t.Id = a.TemplateVersionId
    LEFT JOIN dbo.WN_OfferingType ot WITH (NOLOCK) ON (TRY_CAST(a.OperatingHours AS INT) = ot.Id OR TRY_CAST(q.OfferingType AS INT) = ot.Id OR ot.[Description] = a.OperatingHours)
    WHERE a.Id = @AgreementId;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Agreements_GetList]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_Agreements_GetList]
    @Page INT = 1,
    @Limit INT = 10,
    @Search NVARCHAR(200) = NULL,
    @Status NVARCHAR(50) = NULL,
    @LocationIds NVARCHAR(4000) = NULL
AS
BEGIN
    -- Paginated agreement list with search and status filter (QA_06: optional location filter).
    -- @LocationIds: comma-separated WN_Locations ids of a location-bound admin / sales executive; only agreements of
    -- those locations (the booked space's location, else the quoted space's) plus agreements without a location are
    -- listed. NULL (super admin) = every agreement, exactly as before.
    SET NOCOUNT ON;
    IF @Page < 1 SET @Page = 1;
    IF @Limit < 1 SET @Limit = 10;
    DECLARE @Offset INT = (@Page - 1) * @Limit;
    DECLARE @Locs NVARCHAR(MAX) = CASE WHEN @LocationIds IS NULL THEN NULL ELSE N',' + REPLACE(@LocationIds, N' ', N'') + N',' END;
    SELECT COUNT(1)
    FROM dbo.WN_Agreements a WITH (NOLOCK)
    JOIN dbo.WN_Quotations q WITH (NOLOCK) ON q.Id = a.QuotationId
    LEFT JOIN dbo.WN_Spaces sq WITH (NOLOCK) ON sq.Id = q.SpaceId
    LEFT JOIN dbo.WN_Bookings b WITH (NOLOCK) ON b.Id = a.BookingId
    LEFT JOIN dbo.WN_Spaces sb WITH (NOLOCK) ON sb.Id = b.SpaceId
    WHERE (@Status IS NULL OR a.Status = @Status)
      AND (@Search IS NULL OR
           a.CustomerName LIKE '%' + @Search + '%' OR
           a.CompanyName LIKE '%' + @Search + '%' OR
           q.QuotationNumber LIKE '%' + @Search + '%' OR
           a.CustomerCnic LIKE '%' + @Search + '%')
      AND (@Locs IS NULL OR COALESCE(sb.LocationId, sq.LocationId) IS NULL
           OR @Locs LIKE N'%,' + CAST(COALESCE(sb.LocationId, sq.LocationId) AS NVARCHAR(12)) + N',%');
    SELECT a.*, q.QuotationNumber, t.Name AS TemplateName
    FROM dbo.WN_Agreements a WITH (NOLOCK)
    JOIN dbo.WN_Quotations q WITH (NOLOCK) ON q.Id = a.QuotationId
    LEFT JOIN dbo.WN_LeaseTemplates t WITH (NOLOCK) ON t.Id = a.TemplateVersionId
    LEFT JOIN dbo.WN_Spaces sq WITH (NOLOCK) ON sq.Id = q.SpaceId
    LEFT JOIN dbo.WN_Bookings b WITH (NOLOCK) ON b.Id = a.BookingId
    LEFT JOIN dbo.WN_Spaces sb WITH (NOLOCK) ON sb.Id = b.SpaceId
    WHERE (@Status IS NULL OR a.Status = @Status)
      AND (@Search IS NULL OR
           a.CustomerName LIKE '%' + @Search + '%' OR
           a.CompanyName LIKE '%' + @Search + '%' OR
           q.QuotationNumber LIKE '%' + @Search + '%' OR
           a.CustomerCnic LIKE '%' + @Search + '%')
      AND (@Locs IS NULL OR COALESCE(sb.LocationId, sq.LocationId) IS NULL
           OR @Locs LIKE N'%,' + CAST(COALESCE(sb.LocationId, sq.LocationId) AS NVARCHAR(12)) + N',%')
    ORDER BY a.Id DESC
    OFFSET @Offset ROWS
    FETCH NEXT @Limit ROWS ONLY;
END;
GO
