CREATE   PROCEDURE [dbo].[WN_Agreements_Insert]
    @QuotationId INT,
    @CustomerId INT,
    @EntityType NVARCHAR(50),
    @RefundDays INT = 30,
    @FeeAmount DECIMAL(18,2) = 0,
    @SecurityDeposit DECIMAL(18,2) = 0,
    @OperatingHours NVARCHAR(200) = '24/7',
    @CustomerName NVARCHAR(250) = NULL,
    @CustomerCnic NVARCHAR(100) = NULL,
    @CustomerPhone NVARCHAR(100) = NULL,
    @CustomerAddress NVARCHAR(500) = NULL,
    @CompanyName NVARCHAR(250) = NULL,
    @Ntn NVARCHAR(100) = NULL,
    @SecpRegistrationNo NVARCHAR(100) = NULL,
    @CreatedById INT = NULL,
    @TemplateVersionId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO dbo.WN_Agreements (
        QuotationId, CustomerId, EntityType, Status, SentDate,
        RefundDays, FeeAmount, SecurityDeposit, OperatingHours,
        CustomerName, CustomerCnic, CustomerPhone, CustomerAddress,
        CompanyName, Ntn, SecpRegistrationNo, CreatedById, TemplateVersionId, CreatedOn
    )
    OUTPUT INSERTED.Id
    VALUES (
        @QuotationId, @CustomerId, @EntityType, 'AgreementSent', SYSUTCDATETIME(),
        ISNULL(NULLIF(@RefundDays, 0), 30), @FeeAmount, @SecurityDeposit, ISNULL(@OperatingHours, '24/7'),
        @CustomerName, @CustomerCnic, @CustomerPhone, @CustomerAddress,
        @CompanyName, @Ntn, @SecpRegistrationNo, @CreatedById, @TemplateVersionId, SYSUTCDATETIME()
    );
END;
