-- 2. Audit log detail by AuditId (on-demand modal inspection)
CREATE   PROCEDURE [dbo].[WN_AuditLog_GetById]
    @AuditId BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT a.AuditId,
           a.EntityName,
           a.RecordId,
           a.Operation,
           a.OldValues,
           a.NewValues,
           a.ErrorMessage,
           a.ErrorSeverity,
           a.StackTrace,
           a.ChangedByUserId,
           a.ChangedByUserEmail,
           a.ChangedAt,
           a.SourceApp,
           CASE WHEN a.ErrorMessage IS NOT NULL AND LEN(a.ErrorMessage) > 0 THEN 1 ELSE 0 END AS HasError
    FROM dbo.WN_AuditLog a WITH (NOLOCK)
    WHERE a.AuditId = @AuditId;
END;
