/****** Object:  StoredProcedure [dbo].[WN_AuditLog_GetPaged]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- 1. Paged audit logs with server-side pagination and filters
CREATE   PROCEDURE [dbo].[WN_AuditLog_GetPaged]
    @Page INT = 1,
    @PageSize INT = 50,
    @FromDate DATETIME2(3) = NULL,
    @ToDate DATETIME2(3) = NULL,
    @Operation CHAR(1) = NULL,
    @EntityName NVARCHAR(128) = NULL,
    @ChangedByUserEmail NVARCHAR(256) = NULL,
    @RecordId NVARCHAR(64) = NULL,
    @SourceApp NVARCHAR(50) = NULL,
    @ErrorsOnly BIT = 0
AS
BEGIN
    SET NOCOUNT ON;

    -- Clamping
    IF @Page < 1 SET @Page = 1;
    IF @PageSize < 1 SET @PageSize = 50;
    IF @PageSize > 200 SET @PageSize = 200;

    DECLARE @Offset INT = (@Page - 1) * @PageSize;
    DECLARE @ToDateExclusive DATETIME2(3) = NULL;
    IF @ToDate IS NOT NULL
        SET @ToDateExclusive = DATEADD(DAY, 1, CAST(@ToDate AS DATE));

    DECLARE @EmailLike NVARCHAR(258) = NULL;
    IF @ChangedByUserEmail IS NOT NULL AND LEN(LTRIM(RTRIM(@ChangedByUserEmail))) > 0
        SET @EmailLike = N'%' + LTRIM(RTRIM(@ChangedByUserEmail)) + N'%';

    -- Result Set 1: Total Count
    SELECT COUNT(1) AS TotalCount
    FROM dbo.WN_AuditLog a WITH (NOLOCK)
    WHERE (@FromDate IS NULL OR a.ChangedAt >= @FromDate)
      AND (@ToDateExclusive IS NULL OR a.ChangedAt < @ToDateExclusive)
      AND (@Operation IS NULL OR a.Operation = @Operation)
      AND (@EntityName IS NULL OR a.EntityName = @EntityName)
      AND (@EmailLike IS NULL OR a.ChangedByUserEmail LIKE @EmailLike)
      AND (@RecordId IS NULL OR a.RecordId = @RecordId)
      AND (@SourceApp IS NULL OR 
           (@SourceApp IN ('[None]', '[Empty]') AND (a.SourceApp IS NULL OR a.SourceApp = '')) OR 
           (a.SourceApp = @SourceApp))
      AND (@ErrorsOnly = 0 OR (a.ErrorMessage IS NOT NULL AND LEN(a.ErrorMessage) > 0));

    -- Result Set 2: Paged Records
    SELECT a.AuditId,
           a.EntityName,
           a.RecordId,
           a.Operation,
           a.ChangedByUserId,
           a.ChangedByUserEmail,
           a.ChangedAt,
           a.SourceApp,
           a.ErrorSeverity,
           CASE WHEN a.ErrorMessage IS NOT NULL AND LEN(a.ErrorMessage) > 0 THEN 1 ELSE 0 END AS HasError
    FROM dbo.WN_AuditLog a WITH (NOLOCK)
    WHERE (@FromDate IS NULL OR a.ChangedAt >= @FromDate)
      AND (@ToDateExclusive IS NULL OR a.ChangedAt < @ToDateExclusive)
      AND (@Operation IS NULL OR a.Operation = @Operation)
      AND (@EntityName IS NULL OR a.EntityName = @EntityName)
      AND (@EmailLike IS NULL OR a.ChangedByUserEmail LIKE @EmailLike)
      AND (@RecordId IS NULL OR a.RecordId = @RecordId)
      AND (@SourceApp IS NULL OR 
           (@SourceApp IN ('[None]', '[Empty]') AND (a.SourceApp IS NULL OR a.SourceApp = '')) OR 
           (a.SourceApp = @SourceApp))
      AND (@ErrorsOnly = 0 OR (a.ErrorMessage IS NOT NULL AND LEN(a.ErrorMessage) > 0))
    ORDER BY a.AuditId DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Billing_GetDueBookings]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- ==============================================================================
-- 3. ALTER PROCEDURE dbo.WN_Billing_GetDueBookings
-- Ensure deleted invoices (StatusId 40) are excluded from billing cycle checks
-- ==============================================================================
CREATE   PROCEDURE [dbo].[WN_Billing_GetDueBookings]
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Today DATE = CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE);
    DECLARE @EndOfCurrentMonth DATE = EOMONTH(@Today);
    DECLARE @DayOfMonth INT = DAY(@Today);

    DECLARE @GenerationDay INT = 15;
    SELECT TOP 1 @GenerationDay = TRY_CAST(SettingValue AS INT)
    FROM dbo.WN_BillingSettings WITH (NOLOCK)
    WHERE SettingKey = 'GenerationDayOfMonth';
    IF @GenerationDay IS NULL OR @GenerationDay < 1 OR @GenerationDay > 28 SET @GenerationDay = 15;

    -- Fetch active bookings due for next billing cycle (trigger on configured generation day)
    -- CI_01: custom invoices (InvoiceTypeId 7 / IsCustom = 1) never decide the billing cycle.
    SELECT
        b.Id AS BookingId,
        b.UserId,
        b.SpaceId,
        b.StartOn AS ContractStart,
        b.EndOn AS ContractEnd,
        ISNULL(b.MonthlyRent, CASE WHEN ISNULL(b.BillingPeriodMonths, 3) > 0 AND b.SubtotalAmount > 0 THEN b.SubtotalAmount / b.BillingPeriodMonths ELSE b.TotalAmount END) AS MonthlyRent,
        b.TotalAmount AS ContractTotalAmount,
        ISNULL(b.BillingPeriodMonths, 3) AS BillingPeriodMonths,
        ISNULL(b.SecurityDepositMonths, 2) AS SecurityDepositMonths,
        CAST(1 AS BIT) AS SecurityDepositCharged,
        latestInv.BillingPeriodStart AS CurrentPeriodStart,
        latestInv.BillingPeriodEnd AS CurrentPeriodEnd,
        DATEADD(day, 1, latestInv.BillingPeriodEnd) AS NextBillingDate
    FROM dbo.WN_Bookings b WITH (NOLOCK)
    CROSS APPLY (
        SELECT TOP 1
            i.BillingPeriodStart,
            i.BillingPeriodEnd
        FROM dbo.WN_Invoices i WITH (NOLOCK)
        WHERE i.BookingId = b.Id
          AND i.InvoiceTypeId <> 7 AND i.IsCustom = 0
          AND i.StatusId <> 40
          AND (i.StatusId NOT IN (5, ISNULL((SELECT TOP 1 Id FROM dbo.OrderStatus WITH (NOLOCK) WHERE LTRIM(RTRIM(Description)) = 'Cancelled' ORDER BY Id), 5))
               OR EXISTS (SELECT 1 FROM dbo.WN_CustomInvoices ci WITH (NOLOCK) WHERE ci.ReplacedInvoiceId = i.Id))
        ORDER BY i.BillingPeriodEnd DESC, i.Id DESC
    ) latestInv
    WHERE b.IsDeleted = 0
      AND b.BookingStatusId IN (1, 2, 5, 33)
      AND latestInv.BillingPeriodEnd IS NOT NULL
      AND latestInv.BillingPeriodEnd < b.EndOn
      AND (
          (@DayOfMonth >= @GenerationDay AND latestInv.BillingPeriodEnd <= @EndOfCurrentMonth)
          OR
          (latestInv.BillingPeriodEnd <= DATEADD(day, 14, @Today))
      )
      AND NOT EXISTS (
          SELECT 1
          FROM dbo.WN_Invoices nextInv WITH (NOLOCK)
          WHERE nextInv.BookingId = b.Id
            AND nextInv.BillingPeriodStart > latestInv.BillingPeriodEnd
            AND nextInv.InvoiceTypeId <> 7 AND nextInv.IsCustom = 0
            AND nextInv.StatusId <> 40
            AND (nextInv.StatusId NOT IN (5, ISNULL((SELECT TOP 1 Id FROM dbo.OrderStatus WITH (NOLOCK) WHERE LTRIM(RTRIM(Description)) = 'Cancelled' ORDER BY Id), 5))
                 OR EXISTS (SELECT 1 FROM dbo.WN_CustomInvoices ci WITH (NOLOCK) WHERE ci.ReplacedInvoiceId = nextInv.Id))
      );
END;
GO
