/****** Object:  StoredProcedure [dbo].[WN_BookingEmployees_AddRequest]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_BookingEmployees_AddRequest]
        @BookingId       INT,
        @BookingDetailId INT,
        @CustomerId      INT,
        @PersonId        INT,
        @AddedByUserId   INT,
        @Seats           INT
    AS
    BEGIN
        SET NOCOUNT ON;
        SET XACT_ABORT ON;
        DECLARE @LockResult INT;
        DECLARE @LockName NVARCHAR(255) = CONCAT(N'WN_BookingAttendants:', @BookingDetailId);
        DECLARE @Today DATE = CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE);
        DECLARE @Result NVARCHAR(20) = N'ok';
        DECLARE @RequestId INT = NULL;
        DECLARE @Used INT = 0;
        BEGIN TRANSACTION;
        BEGIN TRY
            EXEC @LockResult = sys.sp_getapplock @Resource = @LockName, @LockMode = N'Exclusive',
                                                 @LockOwner = N'Transaction', @LockTimeout = 15000;
            IF @LockResult < 0
                THROW 50000, N'This booking is being updated by someone else. Please try again.', 1;
            SELECT @Used = COUNT(*) FROM (
                SELECT r.PersonId FROM dbo.WN_BookingEmployeeRequests r
                 WHERE r.BookingId = @BookingId AND r.Status = N'Pending'
                UNION
                SELECT ba.PersonId FROM dbo.WN_BookingAttendants ba
                 WHERE ba.BookingDetailId = @BookingDetailId AND (ba.AssignedTo IS NULL OR ba.AssignedTo >= @Today)
            ) x;
            IF EXISTS (SELECT 1 FROM dbo.WN_BookingEmployeeRequests r
                        WHERE r.BookingId = @BookingId AND r.PersonId = @PersonId AND r.Status = N'Pending')
               OR EXISTS (SELECT 1 FROM dbo.WN_BookingAttendants ba
                           WHERE ba.BookingDetailId = @BookingDetailId AND ba.PersonId = @PersonId
                             AND (ba.AssignedTo IS NULL OR ba.AssignedTo >= @Today))
                SET @Result = N'duplicate';
            ELSE IF @Used >= @Seats
                SET @Result = N'full';
            ELSE
            BEGIN
                INSERT INTO dbo.WN_BookingEmployeeRequests (BookingId, BookingDetailId, CustomerId, PersonId, Status, AddedAt, AddedByUserId)
                VALUES (@BookingId, @BookingDetailId, @CustomerId, @PersonId, N'Pending', SYSUTCDATETIME(), @AddedByUserId);
                SET @RequestId = SCOPE_IDENTITY();
                SET @Used = @Used + 1;
            END
            COMMIT TRANSACTION;
            SELECT @Result AS Result, @RequestId AS RequestId, @Used AS Used;
        END TRY
        BEGIN CATCH
            IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
            THROW;
        END CATCH
    END
GO
/****** Object:  StoredProcedure [dbo].[WN_BookingEmployees_FindPendingByIdNumber]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_BookingEmployees_FindPendingByIdNumber]
        @BookingDetailId INT,
        @IdNumber        VARCHAR(30)
    AS
    BEGIN
        SET NOCOUNT ON;
        SELECT TOP 1 r.Id AS RequestId, r.BookingId, r.PersonId,
               COALESCE(r.CustomerId, cu.Id) AS CustomerId,
               p.Name, p.Email, p.Phone, p.IdType, p.IdNumber
          FROM dbo.WN_BookingDetails bd WITH (NOLOCK)
          JOIN dbo.WN_Bookings b WITH (NOLOCK) ON b.IdGUID = bd.BookingGuid
          JOIN dbo.WN_BookingEmployeeRequests r WITH (NOLOCK) ON r.BookingId = b.Id AND r.Status = N'Pending'
          JOIN dbo.WN_Persons p WITH (NOLOCK) ON p.PersonId = r.PersonId
          OUTER APPLY (SELECT TOP 1 c.Id
                         FROM dbo.WN_Customers c WITH (NOLOCK)
                        WHERE (NULLIF(b.CustomerCode, N'') IS NOT NULL AND c.Code = b.CustomerCode)
                           OR (NULLIF(b.CustomerCode, N'') IS NULL AND c.UserId = b.UserId)
                        ORDER BY c.Id) cu
         WHERE bd.Id = @BookingDetailId
           AND (r.BookingDetailId IS NULL OR r.BookingDetailId = @BookingDetailId)
           AND REPLACE(REPLACE(p.IdNumber, '-', ''), ' ', '') = @IdNumber
         ORDER BY r.Id DESC;
    END
GO
