CREATE   PROCEDURE [dbo].[WN_BookingEmployees_FindPerson]
        @IdType     VARCHAR(10),
        @IdNumber   VARCHAR(30),
        @CustomerId INT
    AS
    BEGIN
        SET NOCOUNT ON;
        SELECT TOP 1 p.PersonId, p.Name,
               CASE WHEN EXISTS (SELECT 1 FROM dbo.WN_CustomerAttendants ca WITH (NOLOCK)
                                  WHERE ca.PersonId = p.PersonId AND ca.CustomerId = @CustomerId)
                    THEN CAST(1 AS BIT) ELSE CAST(0 AS BIT) END AS LinkedToCustomer
          FROM dbo.WN_Persons p WITH (NOLOCK)
         WHERE p.IdType = @IdType AND p.IdNumber = @IdNumber
         ORDER BY p.PersonId;
    END
