/****** Object:  StoredProcedure [dbo].[WN_BookingEmployees_Get]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_BookingEmployees_Get]
        @BookingId INT,
        @UserId    INT
    AS
    BEGIN
        SET NOCOUNT ON;
        DECLARE @B TABLE (
            BookingId INT, BookingStatusId INT, StartOn DATETIME2 NULL, EndOn DATETIME2 NULL,
            BookingDetailId INT NULL, DetailEnd DATETIME NULL, SpaceName NVARCHAR(MAX) NULL,
            LocationName NVARCHAR(MAX) NULL, CustomerId INT NULL);
        INSERT INTO @B (BookingId, BookingStatusId, StartOn, EndOn, BookingDetailId, DetailEnd, SpaceName, LocationName, CustomerId)
        SELECT TOP 1
               b.Id, b.BookingStatusId, b.StartOn, b.EndOn,
               bd.Id, bd.EndDateTime,
               COALESCE(NULLIF(s.Name, N''), bd.SpaceName),
               l.Name,
               cu.Id
          FROM dbo.WN_Bookings b WITH (NOLOCK)
          LEFT JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = b.SpaceId
          LEFT JOIN dbo.WN_Locations l WITH (NOLOCK) ON l.Id = s.LocationId
          OUTER APPLY (SELECT TOP 1 d.Id, d.EndDateTime, d.SpaceName
                         FROM dbo.WN_BookingDetails d WITH (NOLOCK)
                        WHERE d.BookingGuid = b.IdGUID AND d.IsDeleted = 0
                        ORDER BY CASE WHEN d.FeeType LIKE N'%Rent%' THEN 0 ELSE 1 END, d.Id DESC) bd
          OUTER APPLY (SELECT TOP 1 c.Id
                         FROM dbo.WN_Customers c WITH (NOLOCK)
                        WHERE (NULLIF(b.CustomerCode, N'') IS NOT NULL AND c.Code = b.CustomerCode)
                           OR (NULLIF(b.CustomerCode, N'') IS NULL AND c.UserId = b.UserId)
                        ORDER BY c.Id) cu
         WHERE b.Id = @BookingId
           AND ISNULL(b.IsDeleted, 0) = 0
           AND @UserId > 0
           AND (b.UserId = @UserId
                OR (NULLIF(b.CustomerCode, N'') IS NOT NULL
                    AND EXISTS (SELECT 1 FROM dbo.WN_Customers c2 WITH (NOLOCK)
                                 WHERE c2.UserId = @UserId AND c2.Code = b.CustomerCode)));
        SELECT BookingId, BookingStatusId, StartOn, EndOn, BookingDetailId, DetailEnd, SpaceName, LocationName, CustomerId
          FROM @B;
        -- Pending = waiting for the CNIC check at the branch; Verified = added to the booking by sales.
        SELECT r.Id AS RequestId, r.PersonId, r.Status, r.AddedAt, r.BookingDetailId,
               p.Name, p.Email, p.Phone, p.IdType, p.IdNumber
          FROM dbo.WN_BookingEmployeeRequests r WITH (NOLOCK)
          JOIN dbo.WN_Persons p WITH (NOLOCK) ON p.PersonId = r.PersonId
         WHERE r.BookingId IN (SELECT BookingId FROM @B)
           AND r.Status IN (N'Pending', N'Verified')
         ORDER BY r.Id;
    END
GO
/****** Object:  StoredProcedure [dbo].[WN_BookingEmployees_PendingPersons]    Script Date: 28/10/2026 11:43:10 am ******/
