CREATE   PROCEDURE [dbo].[WN_BookingEmployees_PendingPersons]
    @CustomerId      INT = NULL,
    @BookingDetailId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Today DATE = CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE);
    SELECT r.PersonId, r.BookingDetailId,
           CASE WHEN EXISTS (SELECT 1 FROM dbo.WN_BookingAttendants ba WITH (NOLOCK)
                              WHERE ba.PersonId = r.PersonId
                                AND (ba.AssignedTo IS NULL OR ba.AssignedTo >= @Today))
                THEN 1 ELSE 0 END AS IsActiveSomewhere
      FROM dbo.WN_BookingEmployeeRequests r WITH (NOLOCK)
     WHERE r.Status = N'Pending'
       AND (@CustomerId IS NULL OR r.CustomerId = @CustomerId)
       AND (@BookingDetailId IS NULL OR r.BookingDetailId = @BookingDetailId);
END
GO
