CREATE   PROCEDURE [dbo].[WN_BookingEmployees_Verify]
        @RequestId       INT = NULL,
        @BookingDetailId INT = NULL,
        @PersonId        INT = NULL,
        @VerifiedById    INT = NULL
    AS
    BEGIN
        SET NOCOUNT ON;
        UPDATE r
           SET r.Status = N'Verified', r.VerifiedAt = SYSUTCDATETIME(), r.VerifiedById = @VerifiedById,
               r.BookingDetailId = COALESCE(r.BookingDetailId, @BookingDetailId)
          FROM dbo.WN_BookingEmployeeRequests r
         WHERE r.Status = N'Pending'
           AND ((@RequestId IS NOT NULL AND r.Id = @RequestId)
             OR (@RequestId IS NULL AND r.PersonId = @PersonId
                 AND r.BookingId IN (SELECT b.Id
                                       FROM dbo.WN_BookingDetails bd WITH (NOLOCK)
                                       JOIN dbo.WN_Bookings b WITH (NOLOCK) ON b.IdGUID = bd.BookingGuid
                                      WHERE bd.Id = @BookingDetailId)));
        SELECT @@ROWCOUNT AS Verified;
    END
