-- 14. WN_Bookings_GetListByUserId --
CREATE   PROCEDURE [dbo].[WN_Bookings_GetListByUserId]
    @UserId INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT b.IdGUID         AS IdGuid,
           b.Id             AS Id,
           s.Name           AS SpaceName,
           b.StartOn        AS StartDateTime,
           b.EndOn          AS EndDateTime,
           b.TotalAmount    AS TotalAmount,
           b.Notes          AS Notes,
           b.BookingDate    AS CreatedAt,
           CASE b.BookingStatusId
               WHEN 5 THEN 'Pending'
               WHEN 86 THEN 'Cancelled'
               WHEN 3 THEN 'Rejected'
               WHEN 33 THEN 'Confirmed'
               ELSE 'Confirmed'
           END AS BookingStatus
    FROM dbo.WN_Bookings b WITH (NOLOCK)
    LEFT JOIN dbo.WN_Spaces s WITH (NOLOCK) ON b.SpaceId = s.Id
    WHERE b.UserId = @UserId AND (b.IsDeleted = 0 OR b.IsDeleted IS NULL)
    ORDER BY b.BookingDate DESC;
END
GO
/****** Object:  StoredProcedure [dbo].[WN_Bookings_GetListFiltered]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[WN_Bookings_GetListFiltered]
    @Page        INT           = 1,
    @Limit       INT           = 20,
    @Search      NVARCHAR(255) = NULL,
    @LocationId  INT           = NULL,
    @StatusIds   NVARCHAR(400) = NULL,  -- CSV of WN_Bookings.BookingStatusId values (NULL = every status)
    @DateFrom    DATETIME2(0)  = NULL,  -- start date from (inclusive, business time)
    @DateTo      DATETIME2(0)  = NULL   -- start date before (exclusive, business time)
AS
BEGIN
    -- LST_01: the admin Bookings list with filters. Same columns, search and order as dbo.WN_Bookings_GetList;
    -- the API calls it only when a status or a start date range is chosen (otherwise WN_Bookings_GetList as before).
    SET NOCOUNT ON;
    IF @Page < 1 SET @Page = 1;
    IF @Limit < 1 SET @Limit = 20;
    DECLARE @Offset INT = (@Page - 1) * @Limit;
    SELECT
        v.*,
        fi.GrandTotal AS InitialPayable,
        COUNT(*) OVER () AS TotalCount
    FROM dbo.WN_vw_BookingSummary v WITH (NOLOCK)
    OUTER APPLY (
        SELECT TOP 1 ISNULL(i.GrandTotal, 0) AS GrandTotal
        FROM dbo.WN_Invoices i WITH (NOLOCK)
        WHERE i.BookingId = v.BookingId AND ISNULL(i.StatusId, 0) NOT IN (5, 40)
        ORDER BY i.Id ASC
    ) fi
    WHERE (@LocationId IS NULL OR v.LocationId = @LocationId)
      AND (@StatusIds IS NULL OR v.BookingStatusId IN (SELECT TRY_CAST(x.value AS INT) FROM STRING_SPLIT(@StatusIds, ',') x))
      AND (@DateFrom IS NULL OR v.StartOn >= @DateFrom)
      AND (@DateTo IS NULL OR v.StartOn < @DateTo)
      AND (@Search IS NULL OR @Search = ''
           OR v.UserName      LIKE '%' + @Search + '%'
           OR v.CustomerName  LIKE '%' + @Search + '%'
           OR v.UserEmail     LIKE '%' + @Search + '%'
           OR v.CustomerEmail LIKE '%' + @Search + '%'
           OR v.SpaceCode     LIKE '%' + @Search + '%'
           OR v.SpaceName     LIKE '%' + @Search + '%'
           OR v.ChallanNumber LIKE '%' + @Search + '%')
    ORDER BY v.BookedOn DESC
    OFFSET @Offset ROWS FETCH NEXT @Limit ROWS ONLY;
END;
GO
