/****** Object:  StoredProcedure [dbo].[WN_Challans_GetFullByBooking]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- ==============================================================================
-- 14. dbo.WN_Challans_GetFullByBooking (ALTERED)
-- Ensures CustomerEmail is sourced ONLY from dbo.WN_Customers (cust.Email).
-- ==============================================================================
CREATE   PROCEDURE [dbo].[WN_Challans_GetFullByBooking]
    @BookingId INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        c.Id              AS ChallanId,
        c.PublicId        AS ChallanPublicId,
        c.ChallanNumber,
        c.IssuedOn,
        ISNULL((SELECT CASE WHEN bx.ValidityDate > c.ValidUntil OR c.ValidUntil IS NULL THEN bx.ValidityDate ELSE c.ValidUntil END FROM dbo.WN_Bookings bx WITH (NOLOCK) WHERE bx.Id = c.BookingId), c.ValidUntil) AS ValidUntil,
        c.StatusId        AS ChallanStatusId,
        c.Notes           AS ChallanNotes,
        v.BookingId,
        v.BookingPublicId,
        v.StartOn,
        v.EndOn,
        v.ContractStartDate,
        v.ContractEndDate,
        v.BookingStatusCode,
        v.BookingStatusLabel,
        COALESCE(
            NULLIF(RTRIM(LTRIM(ISNULL(cust.FirstName, '') + ' ' + ISNULL(cust.LastName, ''))), ''),
            NULLIF(u.Name, ''),
            v.UserName
        )                 AS CustomerName,
        cust.Company      AS CustomerCompany,
        cust.Address      AS CustomerAddress,
        cust.Email        AS CustomerEmail,
        v.SpaceCode,
        v.SpaceNumber,
        v.SpaceName,
        v.SpaceCapacity,
        v.SpaceTypeName,
        v.LocationName,
        v.BranchName,
        v.CompanyName,
        v.BillingPeriodCode,
        v.BillingPeriodLabel,
        v.BillingPeriod,
        v.BillingPeriodMonths,
        v.NumberOfMonths,
        v.ContractDuration,
        v.MonthlyRent,
        v.CurrentCycleAmount,
        v.TotalContractAmount,
        v.TotalPaidAmount,
        v.BalanceLeft,
        v.NextBillDueDate,
        v.NextBillingDate,
        v.SeatPrice,
        v.RoomPrice,
        v.SecurityDeposit,
        v.BookedOn
    FROM dbo.WN_Challans          c    WITH (NOLOCK)
    JOIN dbo.WN_vw_BookingSummary v    ON v.BookingId = c.BookingId
    JOIN dbo.WN_Bookings          b    WITH (NOLOCK) ON b.Id = c.BookingId
    LEFT JOIN dbo.WN_Customers    cust WITH (NOLOCK) ON (cust.Code = b.CustomerCode OR (b.CustomerCode IS NULL AND cust.UserId = b.UserId))
    LEFT JOIN dbo.WN_Users        u    WITH (NOLOCK) ON u.Id = b.UserId
    WHERE c.BookingId = @BookingId
    ORDER BY c.CreatedOn DESC;

    SELECT
        bl.Id             AS LineId,
        bl.BookingId,
        ct.Code           AS ChargeTypeCode,
        ct.Label          AS ChargeTypeLabel,
        bl.Description,
        bl.Quantity,
        bl.UnitPrice,
        bl.DiscountAmount,
        bl.TaxRate,
        bl.TaxAmount,
        bl.LineTotal,
        bl.AccountId,
        a.Description     AS AccountName
    FROM dbo.WN_BookingLines bl WITH (NOLOCK)
    JOIN dbo.WN_ChargeTypes  ct WITH (NOLOCK) ON ct.Id = bl.ChargeTypeId
    LEFT JOIN dbo.AccountsCOA a WITH (NOLOCK) ON a.Id  = bl.AccountId
    WHERE bl.BookingId = @BookingId
      AND bl.IsDeleted = 0
    ORDER BY bl.Id;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Challans_Search]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[WN_Challans_Search]
    @Query NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT TOP 1
        c.Id, c.PublicId, c.ChallanNumber,
        c.IssuedOn, ISNULL((SELECT CASE WHEN bx.ValidityDate > c.ValidUntil OR c.ValidUntil IS NULL THEN bx.ValidityDate ELSE c.ValidUntil END FROM dbo.WN_Bookings bx WITH (NOLOCK) WHERE bx.Id = c.BookingId), c.ValidUntil) AS ValidUntil, c.StatusId,
        v.BookingId, v.BookingPublicId,
        v.UserName, v.UserEmail,
        v.SpaceName, v.SpaceCode,
        v.StartOn, v.EndOn,
        v.RoomPrice, v.BillingPeriodCode,
        v.BookingStatusCode
    FROM dbo.WN_Challans          c  WITH (NOLOCK)
    JOIN dbo.WN_vw_BookingSummary v  ON v.BookingId = c.BookingId
    WHERE c.ChallanNumber = @Query
       OR CAST(c.BookingId AS NVARCHAR(20)) = @Query
       OR c.ChallanNumber LIKE '%' + @Query + '%'
    ORDER BY c.CreatedOn DESC;
END
GO
