CREATE   PROCEDURE [dbo].[WN_Contacts_Insert]
    @ContactType   NVARCHAR(20)  = 'Contact',
    @UserId        INT           = NULL,
    @Name          NVARCHAR(200),
    @Email         NVARCHAR(256),
    @PhoneNumber   NVARCHAR(50)  = NULL,
    @Message       NVARCHAR(MAX) = NULL,
    @InquiryType   NVARCHAR(20)  = NULL,
    @ReferenceName NVARCHAR(200) = NULL,
    @LocationId    INT           = NULL    -- BR_01: the branch (dbo.WN_Locations.Id); NULL = no branch
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO dbo.WN_Contacts
        (ContactType, UserId, Name, Email, PhoneNumber, Message, StatusId, InquiryType, ReferenceName, LocationId)
    VALUES
        (@ContactType, @UserId, @Name, @Email, @PhoneNumber, @Message, 1,
         NULLIF(LTRIM(RTRIM(@InquiryType)), N''),
         CASE WHEN @InquiryType = N'Reference' THEN NULLIF(LTRIM(RTRIM(@ReferenceName)), N'') END,
         (SELECT l.Id FROM dbo.WN_Locations l WITH (NOLOCK) WHERE l.Id = @LocationId));
    SELECT Id, PublicId FROM dbo.WN_Contacts WHERE Id = SCOPE_IDENTITY();
END
GO
/****** Object:  StoredProcedure [dbo].[WN_Contacts_UpdateInquiryType]    Script Date: 28/10/2026 11:43:10 am ******/
