CREATE   PROCEDURE [dbo].[WN_Contacts_UpdateInquiryType]
    @PublicId      UNIQUEIDENTIFIER,
    @InquiryType   NVARCHAR(20),
    @ReferenceName NVARCHAR(200) = NULL,
    @UpdatedById   INT           = NULL
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE dbo.WN_Contacts SET
        InquiryType   = NULLIF(LTRIM(RTRIM(@InquiryType)), N''),
        ReferenceName = CASE WHEN @InquiryType = N'Reference' THEN NULLIF(LTRIM(RTRIM(@ReferenceName)), N'') END,
        UpdatedOn     = SYSUTCDATETIME(),
        UpdatedById   = @UpdatedById
    WHERE PublicId = @PublicId;

    -- 0 = not found (older website bookings in WN_BookTour cannot be changed).
    SELECT @@ROWCOUNT AS Updated;
END
GO
/****** Object:  StoredProcedure [dbo].[WN_Contacts_UpdateLocation]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_Contacts_UpdateLocation]
    @PublicId    UNIQUEIDENTIFIER,
    @LocationId  INT           = NULL,   -- the new branch (dbo.WN_Locations.Id); NULL = no branch
    @UpdatedById INT           = NULL,
    @LocationIds NVARCHAR(MAX) = NULL    -- location-bound staff: their locations (CSV); only inquiries without a branch
                                         -- or of these are changed. NULL = any inquiry
AS
BEGIN
    SET NOCOUNT ON;
    SET @LocationIds = NULLIF(REPLACE(LTRIM(RTRIM(@LocationIds)), N' ', N''), N'');
    UPDATE dbo.WN_Contacts SET
        LocationId  = @LocationId,
        UpdatedOn   = SYSUTCDATETIME(),
        UpdatedById = @UpdatedById
    WHERE PublicId = @PublicId
      AND (@LocationIds IS NULL OR LocationId IS NULL
           OR CHARINDEX(N',' + CAST(LocationId AS NVARCHAR(20)) + N',', N',' + @LocationIds + N',') > 0);
    -- 0 = not found, or a branch the caller does not see (older website bookings in WN_BookTour cannot be changed).
    SELECT @@ROWCOUNT AS Updated;
END
GO
/****** Object:  StoredProcedure [dbo].[WN_Contacts_UpdateStatus]    Script Date: 28/10/2026 11:43:10 am ******/
