CREATE   PROCEDURE [dbo].[WN_Contacts_UpdateStatus]
    @Id          INT,
    @StatusId    TINYINT,
    @UpdatedById INT = NULL,
    @Source      NVARCHAR(20) = NULL   -- QA_05: 'contact' = only dbo.WN_Contacts, 'booktour' = only dbo.WN_BookTour;
                                       -- NULL = the WN_Contacts row with this Id, else the WN_BookTour one (as before)
AS
BEGIN
    SET NOCOUNT ON;
    SET @Source = LOWER(NULLIF(LTRIM(RTRIM(@Source)), N''));
    IF @Source IS NULL OR @Source = N'contact'
    BEGIN
        UPDATE dbo.WN_Contacts SET
            StatusId    = @StatusId,
            UpdatedOn   = SYSUTCDATETIME(),
            UpdatedById = @UpdatedById
        WHERE Id = @Id;
        IF @@ROWCOUNT > 0 OR @Source = N'contact' RETURN;
    END
    UPDATE dbo.WN_BookTour SET
        Status    = @StatusId,
        UpdatedOn = GETDATE()
    WHERE Id = @Id;
END
