-- 6. Stored Procedure: WN_CustomerKYCDocuments_GetByCustomerId
CREATE   PROCEDURE [dbo].[WN_CustomerKYCDocuments_GetByCustomerId]
    @CustomerId INT,
    @IncludeInactive BIT = 0
AS
BEGIN
    SET NOCOUNT ON;

    SELECT 
        d.Id,
        d.CustomerId,
        d.FolderName,
        d.DocumentTypeId,
        dt.Code AS DocumentTypeCode,
        dt.Name AS DocumentTypeName,
        dt.GroupCode,
        dt.AlternativeCode,
        dt.AllowMultiple,
        dt.RequiresHolderName,
        dt.RequiresExpiry,
        dt.IndividualRequirement,
        dt.BusinessRequirement,
        d.SlotNo,
        d.HolderName,
        d.StoredPath,
        d.OriginalFileName,
        d.FileHash,
        d.ExpiryDate,
        d.VersionNo,
        d.IsActive,
        d.Status,
        d.Remarks,
        d.VerifiedBy,
        d.VerifiedOn,
        d.UploadedBy,
        d.UploadedOn,
        d.ReplacedBy,
        d.ReplacedOn,
        COALESCE(u.Name, u.Email, CAST(d.UploadedBy AS NVARCHAR(50))) AS UploadedByName,
        COALESCE(vu.Name, vu.Email, CAST(d.VerifiedBy AS NVARCHAR(50))) AS VerifiedByName
    FROM dbo.WN_CustomerKYCDocuments d WITH (NOLOCK)
    LEFT JOIN dbo.WN_KYCDocumentTypes dt WITH (NOLOCK) ON dt.Id = d.DocumentTypeId
    LEFT JOIN dbo.WN_Users u WITH (NOLOCK) ON u.Id = d.UploadedBy
    LEFT JOIN dbo.WN_Users vu WITH (NOLOCK) ON vu.Id = d.VerifiedBy
    WHERE d.CustomerId = @CustomerId
      AND (@IncludeInactive = 1 OR d.IsActive = 1)
    ORDER BY dt.SortOrder ASC, d.SlotNo ASC, d.VersionNo DESC;
END
GO
