-- 9. Stored Procedure: WN_CustomerKYCDocuments_GetById
CREATE   PROCEDURE [dbo].[WN_CustomerKYCDocuments_GetById]
    @Id INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT 
        d.Id,
        d.CustomerId,
        d.FolderName,
        d.DocumentTypeId,
        dt.Code AS DocumentTypeCode,
        dt.Name AS DocumentTypeName,
        dt.GroupCode,
        dt.AlternativeCode,
        dt.AllowMultiple,
        dt.RequiresHolderName,
        dt.RequiresExpiry,
        d.SlotNo,
        d.HolderName,
        d.StoredPath,
        d.OriginalFileName,
        d.FileHash,
        d.ExpiryDate,
        d.VersionNo,
        d.IsActive,
        d.Status,
        d.Remarks,
        d.VerifiedBy,
        d.VerifiedOn,
        d.UploadedBy,
        d.UploadedOn,
        d.ReplacedBy,
        d.ReplacedOn,
        c.Code AS CustomerCode,
        LTRIM(RTRIM(ISNULL(c.FirstName, '') + ' ' + ISNULL(c.LastName, ''))) AS CustomerName,
        c.Company AS CustomerCompany
    FROM dbo.WN_CustomerKYCDocuments d WITH (NOLOCK)
    LEFT JOIN dbo.WN_KYCDocumentTypes dt WITH (NOLOCK) ON dt.Id = d.DocumentTypeId
    LEFT JOIN dbo.WN_Customers c WITH (NOLOCK) ON c.Id = d.CustomerId
    WHERE d.Id = @Id;
END
GO
/****** Object:  StoredProcedure [dbo].[WN_CustomerKYCDocuments_InsertOrReplace]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- 7. Stored Procedure: WN_CustomerKYCDocuments_InsertOrReplace
CREATE   PROCEDURE [dbo].[WN_CustomerKYCDocuments_InsertOrReplace]
    @CustomerId       INT,
    @FolderName       NVARCHAR(100),
    @DocumentTypeId   INT,
    @SlotNo           TINYINT = 1,
    @HolderName       NVARCHAR(150) = NULL,
    @StoredPath       NVARCHAR(500),
    @OriginalFileName NVARCHAR(260),
    @FileHash         CHAR(64),
    @ExpiryDate       DATE = NULL,
    @UploadedBy       INT,
    @NewDocId         INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRANSACTION;

    DECLARE @ExistingDocId INT = NULL;
    DECLARE @ExistingVersion INT = 0;

    -- Check if active document exists for this slot
    SELECT TOP 1 
        @ExistingDocId = Id,
        @ExistingVersion = VersionNo
    FROM dbo.WN_CustomerKYCDocuments WITH (UPDLOCK, ROWLOCK)
    WHERE CustomerId = @CustomerId 
      AND DocumentTypeId = @DocumentTypeId 
      AND SlotNo = @SlotNo 
      AND IsActive = 1;

    -- If existing document found, deactivate it
    IF @ExistingDocId IS NOT NULL
    BEGIN
        UPDATE dbo.WN_CustomerKYCDocuments
        SET IsActive = 0,
            ReplacedBy = @UploadedBy,
            ReplacedOn = SYSDATETIME()
        WHERE Id = @ExistingDocId;
    END

    -- Insert new document version
    INSERT INTO dbo.WN_CustomerKYCDocuments (
        CustomerId,
        FolderName,
        DocumentTypeId,
        SlotNo,
        HolderName,
        StoredPath,
        OriginalFileName,
        FileHash,
        ExpiryDate,
        VersionNo,
        IsActive,
        Status,
        Remarks,
        UploadedBy,
        UploadedOn
    ) VALUES (
        @CustomerId,
        @FolderName,
        @DocumentTypeId,
        @SlotNo,
        @HolderName,
        @StoredPath,
        @OriginalFileName,
        @FileHash,
        @ExpiryDate,
        @ExistingVersion + 1,
        1,
        0, -- 0 Pending verification
        NULL,
        @UploadedBy,
        SYSDATETIME()
    );

    SET @NewDocId = SCOPE_IDENTITY();

    COMMIT TRANSACTION;
END
GO
