-- 10. Stored Procedure: WN_Customers_GetKycList
CREATE   PROCEDURE [dbo].[WN_Customers_GetKycList]
    @Page         INT           = 1,
    @Limit        INT           = 20,
    @Search       NVARCHAR(255) = NULL,
    @LocationId   INT           = NULL,
    @StatusFilter NVARCHAR(50)  = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @Page < 1 SET @Page = 1;
    IF @Limit < 1 SET @Limit = 20;
    DECLARE @Offset INT = (@Page - 1) * @Limit;

    -- CTE of distinct customers filtered by location scope
    WITH LocationCustomers AS (
        SELECT DISTINCT c.Id
        FROM dbo.WN_Customers c WITH (NOLOCK)
        LEFT JOIN dbo.WN_Users u WITH (NOLOCK) ON u.Id = c.UserId
        LEFT JOIN dbo.WN_Bookings b WITH (NOLOCK) ON b.CustomerCode = c.Code OR (c.UserId IS NOT NULL AND b.UserId = c.UserId)
        LEFT JOIN dbo.WN_Spaces sb WITH (NOLOCK) ON sb.Id = b.SpaceId
        WHERE (
            @LocationId IS NULL 
            OR sb.LocationId = @LocationId 
            OR u.LocationId = @LocationId
        )
    ),
    CustomerSummaries AS (
        SELECT 
            c.Id,
            c.IdGUID,
            c.Code,
            c.FirstName,
            c.LastName,
            LTRIM(RTRIM(ISNULL(c.FirstName, '') + ' ' + ISNULL(c.LastName, ''))) AS FullName,
            c.Company,
            c.Email,
            c.PhoneNumber,
            c.CnicOrPassport,
            c.IsActive,
            c.CreatedAt,
            -- Document stats
            ISNULL(docStats.TotalDocs, 0) AS TotalActiveDocs,
            ISNULL(docStats.VerifiedDocs, 0) AS VerifiedDocsCount,
            ISNULL(docStats.PendingDocs, 0) AS PendingDocsCount,
            ISNULL(docStats.RejectedDocs, 0) AS RejectedDocsCount,
            ISNULL(docStats.FolderName, '') AS FolderName
        FROM dbo.WN_Customers c WITH (NOLOCK)
        INNER JOIN LocationCustomers lc ON lc.Id = c.Id
        OUTER APPLY (
            SELECT 
                COUNT(1) AS TotalDocs,
                SUM(CASE WHEN d.Status = 1 THEN 1 ELSE 0 END) AS VerifiedDocs,
                SUM(CASE WHEN d.Status = 0 THEN 1 ELSE 0 END) AS PendingDocs,
                SUM(CASE WHEN d.Status = 2 THEN 1 ELSE 0 END) AS RejectedDocs,
                MAX(d.FolderName) AS FolderName
            FROM dbo.WN_CustomerKYCDocuments d WITH (NOLOCK)
            WHERE d.CustomerId = c.Id AND d.IsActive = 1
        ) docStats
        WHERE (
            @Search IS NULL OR @Search = ''
            OR c.Code LIKE '%' + @Search + '%'
            OR c.FirstName LIKE '%' + @Search + '%'
            OR c.LastName LIKE '%' + @Search + '%'
            OR c.Company LIKE '%' + @Search + '%'
            OR c.Email LIKE '%' + @Search + '%'
            OR c.PhoneNumber LIKE '%' + @Search + '%'
        )
    )
    SELECT 
        *,
        COUNT(1) OVER() AS TotalRecords
    FROM CustomerSummaries
    ORDER BY Id DESC
    OFFSET @Offset ROWS FETCH NEXT @Limit ROWS ONLY;
END
GO
/****** Object:  StoredProcedure [dbo].[WN_Customers_GetList]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
