CREATE   PROCEDURE [dbo].[WN_Customers_GetList]
    @Search NVARCHAR(255) = NULL,
    @Page   INT = 1,
    @Limit  INT = 20
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@Page - 1) * @Limit;
    SELECT c.Id, c.IdGUID, c.Code, c.FirstName, c.LastName, c.Company,
           LTRIM(RTRIM(ISNULL(c.FirstName,'') + ' ' + ISNULL(c.LastName,''))) AS FullName,
           c.Email, c.PhoneNumber, c.CnicOrPassport, c.Address,
           c.CityId, ci.Description AS CityName, c.IsActive, c.Notes, c.CreatedAt,
           c.NTN, c.SecpRegistrationNo
    FROM dbo.WN_Customers c
    LEFT JOIN dbo.City ci ON ci.Id = c.CityId
    WHERE (@Search IS NULL OR
           c.FirstName    LIKE '%' + @Search + '%' OR
           c.LastName     LIKE '%' + @Search + '%' OR
           c.Company      LIKE '%' + @Search + '%' OR
           c.Email        LIKE '%' + @Search + '%' OR
           c.Code         LIKE '%' + @Search + '%' OR
           c.PhoneNumber  LIKE '%' + @Search + '%' OR
           c.NTN          LIKE '%' + @Search + '%')
    ORDER BY c.Id DESC
    OFFSET @Offset ROWS FETCH NEXT @Limit ROWS ONLY;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Customers_GetListFiltered]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_Customers_GetListFiltered]
    @Search       NVARCHAR(255) = NULL,
    @Page         INT           = 1,
    @Limit        INT           = 20,
    @LocationIds  NVARCHAR(MAX) = NULL,  -- CSV of location ids (NULL = every customer)
    @IsActive     BIT           = NULL,  -- 1 = active, 0 = inactive (an empty IsActive counts as inactive), NULL = both
    @DateFrom     DATETIME2(0)  = NULL,  -- created (CreatedAt) from (inclusive)
    @DateTo       DATETIME2(0)  = NULL   -- created before (exclusive)
AS
BEGIN
    -- LST_01: the admin Customers list with filters. Same columns, search and order as dbo.WN_Customers_GetList, plus
    -- TotalCount. A customer belongs to the location of their user account and to the locations of their bookings
    -- (the same rule the API uses to scope one customer). Called only when a location, a status or a date range is chosen.
    SET NOCOUNT ON;
    IF @Page < 1 SET @Page = 1;
    IF @Limit < 1 SET @Limit = 20;
    DECLARE @Offset INT = (@Page - 1) * @Limit;
    SELECT c.Id, c.IdGUID, c.Code, c.FirstName, c.LastName, c.Company,
           LTRIM(RTRIM(ISNULL(c.FirstName,'') + ' ' + ISNULL(c.LastName,''))) AS FullName,
           c.Email, c.PhoneNumber, c.CnicOrPassport, c.Address,
           c.CityId, ci.Description AS CityName, c.IsActive, c.Notes, c.CreatedAt,
           c.NTN, c.SecpRegistrationNo,
           COUNT(*) OVER () AS TotalCount
    FROM dbo.WN_Customers c WITH (NOLOCK)
    LEFT JOIN dbo.City ci WITH (NOLOCK) ON ci.Id = c.CityId
    WHERE (@Search IS NULL OR
           c.FirstName    LIKE '%' + @Search + '%' OR
           c.LastName     LIKE '%' + @Search + '%' OR
           c.Company      LIKE '%' + @Search + '%' OR
           c.Email        LIKE '%' + @Search + '%' OR
           c.Code         LIKE '%' + @Search + '%' OR
           c.PhoneNumber  LIKE '%' + @Search + '%' OR
           c.NTN          LIKE '%' + @Search + '%')
      AND (@IsActive IS NULL OR ISNULL(c.IsActive, 0) = @IsActive)
      AND (@DateFrom IS NULL OR c.CreatedAt >= @DateFrom)
      AND (@DateTo IS NULL OR c.CreatedAt < @DateTo)
      AND (@LocationIds IS NULL
           OR EXISTS (SELECT 1 FROM dbo.WN_Users u WITH (NOLOCK)
                       WHERE u.Id = c.UserId
                         AND u.LocationId IN (SELECT TRY_CAST(x.value AS INT) FROM STRING_SPLIT(@LocationIds, ',') x))
           OR EXISTS (SELECT 1 FROM dbo.WN_Bookings b WITH (NOLOCK)
                        JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = b.SpaceId
                       WHERE (b.CustomerCode = c.Code OR (c.UserId IS NOT NULL AND b.UserId = c.UserId))
                         AND s.LocationId IN (SELECT TRY_CAST(x.value AS INT) FROM STRING_SPLIT(@LocationIds, ',') x)))
    ORDER BY c.Id DESC
    OFFSET @Offset ROWS FETCH NEXT @Limit ROWS ONLY;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Customers_GetOverview]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[WN_Customers_GetOverview]
    @CustomerId    INT,                    -- WN_Customers.Id
    @BizNow        DATETIME2(0) = NULL,    -- business (Pakistan) wall-clock time from the app clock
    @OpenStatusIds NVARCHAR(400) = NULL,   -- invoice StatusIds still owed (Unpaid / Partial / Challan Expire), CSV
    @PaidStatusIds NVARCHAR(400) = NULL,   -- invoice StatusIds paid, CSV
    @VoidStatusIds NVARCHAR(400) = NULL,   -- invoice StatusIds void / cancelled, CSV
    @Top           INT = 100               -- rows per list (1 to 500)
AS
BEGIN
    -- CD_01 customer detail page (CMS /admin/customers/:id), read-only. One customer with everything around them.
    -- A customer owns: bookings by CustomerCode or by their user account (same rule as the bookings list and the
    -- location check of the API); invoices by the same rule as GET api/customer/{id}/invoices (their user, their
    -- bookings, or a user with their email); quotations by WN_Quotations.CustomerId; agreements by CustomerId, by
    -- their quotations or their bookings; fee receipts by customer or by their invoices; payments by their bookings,
    -- invoices or user; security deposits as the security deposit report (CustomerId = code or id).
    -- Money uses the CEO dashboard rules: invoiced = GrandTotal of invoices not void; paid = GrandTotal of paid
    -- invoices plus PaidTotal of the others; outstanding = GrandTotal - WHT - PaidTotal of open invoices; overdue =
    -- open and past DueOn; active bookings = not deleted, BookingStatusId 1, 2, 5, 33, running now.
    -- Deleted bookings are left out of the bookings list and counts.
    -- Times: CreatedOn columns hold UTC instants (the API marks them UTC); EventDate / SignedDate / ReceiptDate are
    -- dates; StartOn / EndOn are Pakistan wall-clock.
    -- Result sets: [0] summary (no row = no such customer), [1] bookings, [2] fee receipts, [3] payments,
    -- [4] agreements, [5] security deposits, [6] activity timeline (newest first).
    SET NOCOUNT ON;
    IF @BizNow IS NULL SET @BizNow = CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2(0));
    IF @Top IS NULL OR @Top < 1 SET @Top = 100;
    IF @Top > 500 SET @Top = 500;
    DECLARE @Today DATE = CAST(@BizNow AS DATE);
    DECLARE @Open TABLE (Id INT PRIMARY KEY);
    DECLARE @Paid TABLE (Id INT PRIMARY KEY);
    DECLARE @Void TABLE (Id INT PRIMARY KEY);
    INSERT INTO @Open (Id) SELECT DISTINCT TRY_CAST(LTRIM(RTRIM(value)) AS INT) FROM STRING_SPLIT(ISNULL(@OpenStatusIds, ''), ',') WHERE TRY_CAST(LTRIM(RTRIM(value)) AS INT) > 0;
    INSERT INTO @Paid (Id) SELECT DISTINCT TRY_CAST(LTRIM(RTRIM(value)) AS INT) FROM STRING_SPLIT(ISNULL(@PaidStatusIds, ''), ',') WHERE TRY_CAST(LTRIM(RTRIM(value)) AS INT) > 0;
    INSERT INTO @Void (Id) SELECT DISTINCT TRY_CAST(LTRIM(RTRIM(value)) AS INT) FROM STRING_SPLIT(ISNULL(@VoidStatusIds, ''), ',') WHERE TRY_CAST(LTRIM(RTRIM(value)) AS INT) > 0;
    DECLARE @C TABLE (Id INT PRIMARY KEY, IdGUID UNIQUEIDENTIFIER NULL, Code NVARCHAR(50) NULL, UserId INT NULL,
                      Email NVARCHAR(400) NULL, CreatedAt DATETIME NULL, CreatedBy NVARCHAR(400) NULL);
    INSERT INTO @C (Id, IdGUID, Code, UserId, Email, CreatedAt, CreatedBy)
    SELECT c.Id, c.IdGUID, c.Code, c.UserId, c.Email, c.CreatedAt, c.CreatedBy
      FROM dbo.WN_Customers c WITH (NOLOCK)
     WHERE c.Id = @CustomerId;
    -- Bookings of the customer (deleted ones too: their invoices still belong to the customer).
    DECLARE @B TABLE (Id INT PRIMARY KEY, IsDeleted BIT NOT NULL, SpaceId INT NULL, StatusId INT NULL,
                      StartOn DATETIME2(0) NULL, EndOn DATETIME2(0) NULL, CreatedOn DATETIME NULL, CreatedById INT NULL);
    INSERT INTO @B (Id, IsDeleted, SpaceId, StatusId, StartOn, EndOn, CreatedOn, CreatedById)
    SELECT b.Id, ISNULL(b.IsDeleted, 0), b.SpaceId, b.BookingStatusId, b.StartOn, b.EndOn, b.CreatedOn, b.CreatedById
      FROM dbo.WN_Bookings b WITH (NOLOCK)
      JOIN @C c ON b.CustomerCode = c.Code OR (c.UserId IS NOT NULL AND b.UserId = c.UserId);
    -- Invoices of the customer (same rule as GET api/customer/{id}/invoices).
    DECLARE @I TABLE (Id INT PRIMARY KEY, PublicId UNIQUEIDENTIFIER NULL, InvoiceNumber NVARCHAR(100) NULL,
                      BookingId INT NULL, StatusId INT NULL, GrandTotal DECIMAL(18,2) NOT NULL, PaidTotal DECIMAL(18,2) NOT NULL,
                      WhtAmount DECIMAL(18,2) NOT NULL, IssuedOn DATE NULL, DueOn DATE NULL, CreatedOn DATETIME2 NULL,
                      CreatedById INT NULL, IsVoid BIT NOT NULL, IsOpen BIT NOT NULL, IsPaid BIT NOT NULL);
    INSERT INTO @I (Id, PublicId, InvoiceNumber, BookingId, StatusId, GrandTotal, PaidTotal, WhtAmount, IssuedOn, DueOn,
                    CreatedOn, CreatedById, IsVoid, IsOpen, IsPaid)
    SELECT i.Id, i.PublicId, i.InvoiceNumber, i.BookingId, i.StatusId, ISNULL(i.GrandTotal, 0), ISNULL(i.PaidTotal, 0),
           ISNULL(i.WHTAmount, 0), i.IssuedOn, i.DueOn, i.CreatedOn, i.CreatedById,
           CASE WHEN i.StatusId IN (5, 40) OR EXISTS (SELECT 1 FROM @Void v WHERE v.Id = i.StatusId) THEN 1 ELSE 0 END,
           CASE WHEN i.StatusId NOT IN (5, 40) AND EXISTS (SELECT 1 FROM @Open o WHERE o.Id = i.StatusId) THEN 1 ELSE 0 END,
           CASE WHEN i.StatusId NOT IN (5, 40) AND EXISTS (SELECT 1 FROM @Paid p WHERE p.Id = i.StatusId) THEN 1 ELSE 0 END
      FROM dbo.WN_Invoices i WITH (NOLOCK)
     WHERE (i.UserId IN (SELECT c.UserId FROM @C c WHERE c.UserId IS NOT NULL)
        OR i.BookingId IN (SELECT x.Id FROM @B x)
        OR i.UserId IN (SELECT u.Id FROM dbo.WN_Users u WITH (NOLOCK) JOIN @C c ON c.Email = u.Email
                         WHERE LTRIM(RTRIM(ISNULL(c.Email, ''))) <> ''))
       AND ISNULL(i.StatusId, 0) <> 40;
    DECLARE @Q TABLE (Id INT PRIMARY KEY);
    INSERT INTO @Q (Id) SELECT q.Id FROM dbo.WN_Quotations q WITH (NOLOCK) WHERE q.CustomerId = @CustomerId;
    -- [0] summary
    SELECT c.Id AS CustomerId,
           c.Code AS CustomerCode,
           (SELECT COUNT(*) FROM @B x WHERE x.IsDeleted = 0) AS TotalBookings,
           (SELECT COUNT(*) FROM @B x WHERE x.IsDeleted = 0 AND x.StatusId IN (1, 2, 5, 33)
                AND x.StartOn <= @BizNow AND x.EndOn >= @BizNow) AS ActiveBookings,
           (SELECT COUNT(*) FROM @I x WHERE x.IsVoid = 0) AS InvoiceCount,
           (SELECT ISNULL(SUM(x.GrandTotal), 0) FROM @I x WHERE x.IsVoid = 0) AS TotalInvoiced,
           (SELECT ISNULL(SUM(CASE WHEN x.IsPaid = 1 THEN x.GrandTotal ELSE x.PaidTotal END), 0) FROM @I x WHERE x.IsVoid = 0) AS TotalPaid,
           (SELECT ISNULL(SUM(CASE WHEN x.GrandTotal - x.WhtAmount - x.PaidTotal > 0 THEN x.GrandTotal - x.WhtAmount - x.PaidTotal ELSE 0 END), 0)
              FROM @I x WHERE x.IsVoid = 0 AND x.IsOpen = 1) AS Outstanding,
           (SELECT COUNT(*) FROM @I x WHERE x.IsVoid = 0 AND x.IsOpen = 1 AND x.GrandTotal - x.WhtAmount - x.PaidTotal > 0) AS OutstandingCount,
           (SELECT ISNULL(SUM(CASE WHEN x.GrandTotal - x.WhtAmount - x.PaidTotal > 0 THEN x.GrandTotal - x.WhtAmount - x.PaidTotal ELSE 0 END), 0)
              FROM @I x WHERE x.IsVoid = 0 AND x.IsOpen = 1 AND x.DueOn < @Today) AS Overdue,
           (SELECT COUNT(*) FROM @I x WHERE x.IsVoid = 0 AND x.IsOpen = 1 AND x.DueOn < @Today
                AND x.GrandTotal - x.WhtAmount - x.PaidTotal > 0) AS OverdueCount,
           (SELECT ISNULL(SUM(sd.Amount), 0) FROM dbo.WN_SecurityDeposits sd WITH (NOLOCK)
             WHERE (sd.CustomerId = c.Code OR sd.CustomerId = CAST(c.Id AS VARCHAR(50)))
               AND sd.ReleasedOn IS NULL AND sd.ForfeitedOn IS NULL) AS DepositHeld,
           (SELECT COUNT(*) FROM dbo.WN_SecurityDeposits sd WITH (NOLOCK)
             WHERE (sd.CustomerId = c.Code OR sd.CustomerId = CAST(c.Id AS VARCHAR(50)))
               AND sd.ReleasedOn IS NULL AND sd.ForfeitedOn IS NULL) AS DepositCount,
           (SELECT COUNT(*) FROM @Q) AS QuotationCount,
           (SELECT STRING_AGG(n.Name, ', ') WITHIN GROUP (ORDER BY n.Name)
              FROM (SELECT DISTINCT CAST(l.Name AS NVARCHAR(400)) AS Name
                      FROM dbo.WN_Locations l WITH (NOLOCK)
                     WHERE l.Id IN (SELECT s.LocationId FROM dbo.WN_Spaces s WITH (NOLOCK)
                                      JOIN @B x ON x.SpaceId = s.Id WHERE x.IsDeleted = 0)
                        OR l.Id IN (SELECT u.LocationId FROM dbo.WN_Users u WITH (NOLOCK)
                                      JOIN @C cc ON cc.UserId = u.Id)) n) AS Locations
      FROM @C c;
    -- [1] bookings (the bookings list view, so the figures match the Bookings page)
    SELECT TOP (@Top)
           v.BookingId,
           v.BookingStatusId,
           COALESCE(v.BookingStatusLabel,
                    (SELECT TOP 1 bs.Label FROM dbo.WN_BookingStatuses bs WITH (NOLOCK)
                      WHERE bs.Code = 'Pending' AND v.BookingStatusId = 1)) AS BookingStatusLabel,
           v.SpaceId, v.SpaceName, v.SpaceCode, v.SpaceTypeName, v.SpaceCapacity,
           v.LocationId, v.LocationName,
           v.StartOn, v.EndOn, x.CreatedOn,
           v.MonthlyRent, v.BillingPeriodLabel, v.TotalContractAmount, v.TotalPaidAmount, v.BalanceLeft,
           v.NextBillingDate, v.SecurityDeposit, v.ChallanNumber,
           CAST(CASE WHEN x.StatusId IN (1, 2, 5, 33) AND x.StartOn <= @BizNow AND x.EndOn >= @BizNow THEN 1 ELSE 0 END AS BIT) AS IsActive,
           u.Name AS CreatedByName
      FROM @B x
      JOIN dbo.WN_vw_BookingSummary v WITH (NOLOCK) ON v.BookingId = x.Id
      LEFT JOIN dbo.WN_Users u WITH (NOLOCK) ON u.Id = x.CreatedById
     WHERE x.IsDeleted = 0
     ORDER BY x.CreatedOn DESC, x.Id DESC;
    -- [2] fee receipts (status labels as dbo.WN_FeeReceipts_GetList)
    SELECT TOP (@Top)
           fr.Id, fr.IdGUID, fr.Code, fr.ReceiptDate, fr.TotalAmount, fr.WHTAmount, fr.SecurityDepositAmount,
           fr.PaymentType, fr.Status,
           CASE fr.Status WHEN 1 THEN 'Active' WHEN 0 THEN 'Void' ELSE 'Unknown' END AS StatusLabel,
           fr.VoidReason, fr.Remarks, fr.CreatedOn,
           creator.Name AS CreatedByName,
           i.Id AS InvoiceId, i.InvoiceNumber,
           coa.Description AS CashInHandAccountName,
           loc.Name AS LocationName
      FROM dbo.WN_FeeReceipts fr WITH (NOLOCK)
      LEFT JOIN dbo.WN_Invoices i WITH (NOLOCK) ON i.PublicId = fr.InvoiceIdGUID
      LEFT JOIN dbo.WN_Bookings b WITH (NOLOCK) ON b.Id = i.BookingId
      LEFT JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = b.SpaceId
      LEFT JOIN dbo.WN_Users iu WITH (NOLOCK) ON iu.Id = i.UserId
      LEFT JOIN dbo.WN_Locations loc WITH (NOLOCK) ON loc.Id = ISNULL(s.LocationId, iu.LocationId)
      LEFT JOIN dbo.AccountsCOA coa WITH (NOLOCK) ON coa.Id = fr.CashInHandAccountId
      LEFT JOIN dbo.WN_Users creator WITH (NOLOCK) ON creator.Id = fr.CreatedById
     WHERE fr.CustomerIdGUID IN (SELECT c.IdGUID FROM @C c WHERE c.IdGUID IS NOT NULL)
        OR fr.InvoiceIdGUID IN (SELECT x.PublicId FROM @I x WHERE x.PublicId IS NOT NULL)
     ORDER BY fr.Id DESC;
    -- [3] payments (method and status labels as dbo.WN_Payments_GetList)
    SELECT TOP (@Top)
           p.Id, p.IdGUID, p.Amount, ISNULL(p.CurrencyCode, 'PKR') AS CurrencyCode,
           p.PaymentMethodId, ISNULL(pm.Label, 'Bank Transfer / Challan') AS PaymentMethodLabel,
           ISNULL(p.StatusId, 1) AS StatusId,
           CASE WHEN ISNULL(p.StatusId, 1) = 2 THEN 'Paid' WHEN ISNULL(p.StatusId, 1) = 3 THEN 'Failed'
                WHEN ISNULL(p.StatusId, 1) = 4 THEN 'Refunded' WHEN ISNULL(p.StatusId, 1) = 5 THEN 'Cancelled'
                ELSE 'Pending' END AS PaymentStatus,
           p.PaidOn, p.CreatedOn, p.TransactionRef, p.InvoiceId, i.InvoiceNumber, p.BookingIdInt AS BookingId
      FROM dbo.WN_Payments p WITH (NOLOCK)
      LEFT JOIN dbo.WN_PaymentMethods pm WITH (NOLOCK) ON pm.Id = p.PaymentMethodId
      LEFT JOIN dbo.WN_Invoices i WITH (NOLOCK) ON i.Id = p.InvoiceId
     WHERE p.BookingIdInt IN (SELECT x.Id FROM @B x)
        OR p.InvoiceId IN (SELECT x.Id FROM @I x)
        OR p.UserIdInt IN (SELECT c.UserId FROM @C c WHERE c.UserId IS NOT NULL)
     ORDER BY COALESCE(p.PaidOn, p.CreatedOn) DESC, p.Id DESC;
    -- [4] agreements (location: the booking space, else the quoted space; the signed copy itself is not sent)
    SELECT TOP (@Top)
           a.Id, a.Status, a.SentDate AS SentAt, a.SignedDate, a.CreatedOn, a.FeeAmount, a.SecurityDeposit,
           a.QuotationId, q.QuotationNumber, q.Version AS QuotationVersion, a.BookingId,
           COALESCE(sb.Name, sq.Name) AS SpaceName,
           COALESCE(lb.Name, lq.Name) AS LocationName,
           CAST(CASE WHEN NULLIF(LTRIM(RTRIM(ISNULL(a.SignedPdfPath, ''))), '') IS NULL THEN 0 ELSE 1 END AS BIT) AS HasSignedPdf,
           creator.Name AS CreatedByName
      FROM dbo.WN_Agreements a WITH (NOLOCK)
      LEFT JOIN dbo.WN_Quotations q WITH (NOLOCK) ON q.Id = a.QuotationId
      LEFT JOIN dbo.WN_Spaces sq WITH (NOLOCK) ON sq.Id = q.SpaceId
      LEFT JOIN dbo.WN_Locations lq WITH (NOLOCK) ON lq.Id = sq.LocationId
      LEFT JOIN dbo.WN_Bookings b WITH (NOLOCK) ON b.Id = a.BookingId
      LEFT JOIN dbo.WN_Spaces sb WITH (NOLOCK) ON sb.Id = b.SpaceId
      LEFT JOIN dbo.WN_Locations lb WITH (NOLOCK) ON lb.Id = sb.LocationId
      LEFT JOIN dbo.WN_Users creator WITH (NOLOCK) ON creator.Id = a.CreatedById
     WHERE a.CustomerId = @CustomerId
        OR a.QuotationId IN (SELECT x.Id FROM @Q x)
        OR a.BookingId IN (SELECT x.Id FROM @B x)
     ORDER BY a.Id DESC;
    -- [5] security deposits (states as dbo.WN_SecurityDeposit_CustomerDetail)
    SELECT TOP (@Top)
           sd.Id, sd.BookingId, sd.RefNo, sd.Amount,
           CASE WHEN sd.ReleasedOn IS NOT NULL THEN 'Released' WHEN sd.ForfeitedOn IS NOT NULL THEN 'Forfeited' ELSE 'Held' END AS [State],
           COALESCE(sd.CreatedOn, sd.HeldOn) AS CreatedOn, sd.ReleasedOn, sd.ForfeitedOn, sd.ForfeitReason
      FROM dbo.WN_SecurityDeposits sd WITH (NOLOCK)
      JOIN @C c ON (sd.CustomerId = c.Code OR sd.CustomerId = CAST(c.Id AS VARCHAR(50)))
     ORDER BY sd.HeldOn DESC, sd.Id DESC;
    -- [6] activity timeline. Kind: customer, quotation, booking, invoice, receipt, payment, agreement, deposit.
    -- Title NULL = a quotation activity: the page words it from Action (WN_QuotationActivities.ActivityType).
    -- Agreements sent are not repeated here: the quotation activity AgreementSent records them.
    DECLARE @T TABLE (Kind NVARCHAR(20) NOT NULL, [Action] NVARCHAR(100) NULL, Title NVARCHAR(100) NULL,
                      Reference NVARCHAR(200) NULL, Detail NVARCHAR(2000) NULL, Note NVARCHAR(2000) NULL,
                      Amount DECIMAL(18,2) NULL, ActorName NVARCHAR(400) NULL, RefId INT NULL,
                      CreatedOn DATETIME2 NULL, EventDate DATE NULL, SortOn DATETIME2 NULL);
    INSERT INTO @T (Kind, [Action], Title, Reference, ActorName, RefId, CreatedOn, SortOn)
    SELECT 'customer', 'Created', 'Customer added', c.Code,
           (SELECT TOP 1 u.Name FROM dbo.WN_Users u WITH (NOLOCK) WHERE u.Email = c.CreatedBy AND NULLIF(LTRIM(RTRIM(c.CreatedBy)), '') IS NOT NULL),
           c.Id, c.CreatedAt, CAST(CAST(c.CreatedAt AS DATETIME2) AT TIME ZONE 'UTC' AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2)
      FROM @C c WHERE c.CreatedAt IS NOT NULL;
    INSERT INTO @T (Kind, [Action], Title, Reference, Detail, Amount, ActorName, RefId, CreatedOn, SortOn)
    SELECT 'quotation', 'Created', 'Quotation created', q.QuotationNumber, s.Name, q.TotalAmount, u.Name, q.Id, q.CreatedDate,
           CAST(q.CreatedDate AT TIME ZONE 'UTC' AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2)
      FROM dbo.WN_Quotations q WITH (NOLOCK)
      LEFT JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = q.SpaceId
      LEFT JOIN dbo.WN_Users u WITH (NOLOCK) ON u.Id = q.CreatedById
     WHERE q.Id IN (SELECT x.Id FROM @Q x) AND ISNULL(q.Version, 1) = 1 AND q.CreatedDate IS NOT NULL;
    INSERT INTO @T (Kind, [Action], Reference, Detail, Note, ActorName, RefId, CreatedOn, SortOn)
    SELECT 'quotation', qa.ActivityType,
           CASE WHEN qa.Version IS NULL THEN q.QuotationNumber ELSE CONCAT(q.QuotationNumber, ' v', qa.Version) END,
           qa.Message, NULLIF(LTRIM(RTRIM(qa.CustomerNote)), ''), u.Name, q.Id, qa.CreatedDate,
           CAST(qa.CreatedDate AT TIME ZONE 'UTC' AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2)
      FROM dbo.WN_QuotationActivities qa WITH (NOLOCK)
      JOIN dbo.WN_Quotations q WITH (NOLOCK) ON q.Id = qa.QuotationId
      LEFT JOIN dbo.WN_Users u WITH (NOLOCK) ON u.Id = qa.CreatedByUserId
     WHERE qa.QuotationId IN (SELECT x.Id FROM @Q x) AND qa.CreatedDate IS NOT NULL;
    INSERT INTO @T (Kind, [Action], Title, Reference, Detail, ActorName, RefId, CreatedOn, SortOn)
    SELECT 'booking', 'Created', 'Booking created', s.Name, l.Name, u.Name, x.Id, x.CreatedOn,
           CAST(CAST(x.CreatedOn AS DATETIME2) AT TIME ZONE 'UTC' AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2)
      FROM @B x
      LEFT JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = x.SpaceId
      LEFT JOIN dbo.WN_Locations l WITH (NOLOCK) ON l.Id = s.LocationId
      LEFT JOIN dbo.WN_Users u WITH (NOLOCK) ON u.Id = x.CreatedById
     WHERE x.IsDeleted = 0 AND x.CreatedOn IS NOT NULL;
    INSERT INTO @T (Kind, [Action], Title, Reference, Amount, ActorName, RefId, CreatedOn, EventDate, SortOn)
    SELECT 'invoice', 'Issued', 'Invoice issued', x.InvoiceNumber, x.GrandTotal, u.Name, x.Id, x.CreatedOn,
           CASE WHEN x.CreatedOn IS NULL THEN x.IssuedOn END,
           COALESCE(CAST(x.CreatedOn AT TIME ZONE 'UTC' AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2), CAST(x.IssuedOn AS DATETIME2))
      FROM @I x
      LEFT JOIN dbo.WN_Users u WITH (NOLOCK) ON u.Id = x.CreatedById
     WHERE x.IsVoid = 0 AND (x.CreatedOn IS NOT NULL OR x.IssuedOn IS NOT NULL);
    INSERT INTO @T (Kind, [Action], Title, Reference, Detail, Amount, ActorName, RefId, CreatedOn, EventDate, SortOn)
    SELECT 'receipt', 'Recorded', 'Receipt recorded', fr.Code,
           CASE WHEN i.InvoiceNumber IS NOT NULL THEN CONCAT('For invoice ', i.InvoiceNumber) END, fr.TotalAmount, u.Name, fr.Id, fr.CreatedOn,
           CASE WHEN fr.CreatedOn IS NULL THEN fr.ReceiptDate END,
           COALESCE(CAST(fr.CreatedOn AT TIME ZONE 'UTC' AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2), CAST(fr.ReceiptDate AS DATETIME2))
      FROM dbo.WN_FeeReceipts fr WITH (NOLOCK)
      LEFT JOIN dbo.WN_Invoices i WITH (NOLOCK) ON i.PublicId = fr.InvoiceIdGUID
      LEFT JOIN dbo.WN_Users u WITH (NOLOCK) ON u.Id = fr.CreatedById
     WHERE (fr.CustomerIdGUID IN (SELECT c.IdGUID FROM @C c WHERE c.IdGUID IS NOT NULL)
            OR fr.InvoiceIdGUID IN (SELECT x.PublicId FROM @I x WHERE x.PublicId IS NOT NULL))
       AND (fr.CreatedOn IS NOT NULL OR fr.ReceiptDate IS NOT NULL);
    INSERT INTO @T (Kind, [Action], Title, Reference, Detail, Amount, ActorName, RefId, CreatedOn, SortOn)
    SELECT 'receipt', 'Voided', 'Receipt voided', fr.Code, fr.VoidReason, fr.TotalAmount, u.Name, fr.Id, fr.UpdatedOn,
           CAST(fr.UpdatedOn AT TIME ZONE 'UTC' AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2)
      FROM dbo.WN_FeeReceipts fr WITH (NOLOCK)
      LEFT JOIN dbo.WN_Users u WITH (NOLOCK) ON u.Id = fr.UpdatedById
     WHERE (fr.CustomerIdGUID IN (SELECT c.IdGUID FROM @C c WHERE c.IdGUID IS NOT NULL)
            OR fr.InvoiceIdGUID IN (SELECT x.PublicId FROM @I x WHERE x.PublicId IS NOT NULL))
       AND fr.Status = 0 AND fr.UpdatedOn IS NOT NULL;
    -- Payments that happened (pending ones are only in the payments list).
    INSERT INTO @T (Kind, [Action], Title, Reference, Detail, Amount, ActorName, RefId, CreatedOn, SortOn)
    SELECT 'payment',
           CASE WHEN ISNULL(p.StatusId, 1) = 2 THEN 'Paid' WHEN ISNULL(p.StatusId, 1) = 3 THEN 'Failed'
                WHEN ISNULL(p.StatusId, 1) = 4 THEN 'Refunded' ELSE 'Cancelled' END,
           CASE WHEN ISNULL(p.StatusId, 1) = 2 THEN 'Payment received' WHEN ISNULL(p.StatusId, 1) = 3 THEN 'Payment failed'
                WHEN ISNULL(p.StatusId, 1) = 4 THEN 'Payment refunded' ELSE 'Payment cancelled' END,
           i.InvoiceNumber, ISNULL(pm.Label, 'Bank Transfer / Challan'), p.Amount, u.Name, p.Id,
           COALESCE(p.PaidOn, p.UpdatedOn, p.CreatedOn),
           CAST(COALESCE(p.PaidOn, p.UpdatedOn, p.CreatedOn) AT TIME ZONE 'UTC' AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2)
      FROM dbo.WN_Payments p WITH (NOLOCK)
      LEFT JOIN dbo.WN_PaymentMethods pm WITH (NOLOCK) ON pm.Id = p.PaymentMethodId
      LEFT JOIN dbo.WN_Invoices i WITH (NOLOCK) ON i.Id = p.InvoiceId
      LEFT JOIN dbo.WN_Users u WITH (NOLOCK) ON u.Id = p.CreatedById
     WHERE (p.BookingIdInt IN (SELECT x.Id FROM @B x)
            OR p.InvoiceId IN (SELECT x.Id FROM @I x)
            OR p.UserIdInt IN (SELECT c.UserId FROM @C c WHERE c.UserId IS NOT NULL))
       AND ISNULL(p.StatusId, 1) <> 1
       AND COALESCE(p.PaidOn, p.UpdatedOn, p.CreatedOn) IS NOT NULL;
    INSERT INTO @T (Kind, [Action], Title, Reference, Detail, Amount, RefId, EventDate, SortOn)
    SELECT 'agreement', 'Signed', 'Agreement signed', q.QuotationNumber, COALESCE(sb.Name, sq.Name), a.FeeAmount, a.Id,
           CAST(a.SignedDate AS DATE), CAST(a.SignedDate AS DATETIME2)
      FROM dbo.WN_Agreements a WITH (NOLOCK)
      LEFT JOIN dbo.WN_Quotations q WITH (NOLOCK) ON q.Id = a.QuotationId
      LEFT JOIN dbo.WN_Spaces sq WITH (NOLOCK) ON sq.Id = q.SpaceId
      LEFT JOIN dbo.WN_Bookings b WITH (NOLOCK) ON b.Id = a.BookingId
      LEFT JOIN dbo.WN_Spaces sb WITH (NOLOCK) ON sb.Id = b.SpaceId
     WHERE (a.CustomerId = @CustomerId OR a.QuotationId IN (SELECT x.Id FROM @Q x) OR a.BookingId IN (SELECT x.Id FROM @B x))
       AND a.SignedDate IS NOT NULL;
    INSERT INTO @T (Kind, [Action], Title, Reference, Amount, RefId, CreatedOn, SortOn)
    SELECT 'deposit', 'Held', 'Security deposit held', sd.RefNo, sd.Amount, sd.Id, COALESCE(sd.CreatedOn, sd.HeldOn),
           CAST(COALESCE(sd.CreatedOn, sd.HeldOn) AT TIME ZONE 'UTC' AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2)
      FROM dbo.WN_SecurityDeposits sd WITH (NOLOCK)
      JOIN @C c ON (sd.CustomerId = c.Code OR sd.CustomerId = CAST(c.Id AS VARCHAR(50)))
     WHERE COALESCE(sd.CreatedOn, sd.HeldOn) IS NOT NULL;
    INSERT INTO @T (Kind, [Action], Title, Reference, Detail, Amount, RefId, CreatedOn, SortOn)
    SELECT 'deposit', CASE WHEN sd.ReleasedOn IS NOT NULL THEN 'Released' ELSE 'Forfeited' END,
           CASE WHEN sd.ReleasedOn IS NOT NULL THEN 'Security deposit released' ELSE 'Security deposit forfeited' END,
           sd.RefNo, CASE WHEN sd.ReleasedOn IS NULL THEN sd.ForfeitReason END, sd.Amount, sd.Id,
           COALESCE(sd.ReleasedOn, sd.ForfeitedOn),
           CAST(COALESCE(sd.ReleasedOn, sd.ForfeitedOn) AT TIME ZONE 'UTC' AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2)
      FROM dbo.WN_SecurityDeposits sd WITH (NOLOCK)
      JOIN @C c ON (sd.CustomerId = c.Code OR sd.CustomerId = CAST(c.Id AS VARCHAR(50)))
     WHERE sd.ReleasedOn IS NOT NULL OR sd.ForfeitedOn IS NOT NULL;
    SELECT TOP (@Top) t.Kind, t.[Action], t.Title, t.Reference, t.Detail, t.Note, t.Amount, t.ActorName, t.RefId,
           t.CreatedOn, t.EventDate
      FROM @T t
     ORDER BY t.SortOn DESC;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Customers_Insert]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[WN_Customers_Insert]
    @FirstName                   NVARCHAR(100),
    @LastName                    NVARCHAR(100)  = NULL,
    @Email                       NVARCHAR(255),
    @PhoneNumber                 NVARCHAR(50)   = NULL,
    @CnicOrPassport              NVARCHAR(50)   = NULL,
    @Address                     NVARCHAR(500)  = NULL,
    @CityId                      INT            = NULL,
    @Notes                       NVARCHAR(1000) = NULL,
    @CreatedBy                   NVARCHAR(255)  = NULL,
    @UserId                      INT            = NULL,
    @Company                     NVARCHAR(255)  = NULL,
    @NTN                         NVARCHAR(100)  = NULL,
    @SecpRegistrationNo          NVARCHAR(100)  = NULL,
    @CustomerTypeId              NVARCHAR(225)  = NULL,
    @CountryId                   INT            = NULL,
    @IdentificationDocumentTypeId NVARCHAR(225) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET QUOTED_IDENTIFIER ON;

    -- Treat 0 or negative foreign keys / IDs as NULL
    IF @CountryId IS NULL OR @CountryId <= 0 SET @CountryId = NULL;
    IF @CityId IS NULL OR @CityId <= 0 SET @CityId = NULL;
    IF @UserId IS NULL OR @UserId <= 0 SET @UserId = NULL;

    IF @UserId IS NULL AND @Email IS NOT NULL AND LTRIM(RTRIM(@Email)) <> ''
    BEGIN
        SELECT TOP 1 @UserId = u.Id
        FROM dbo.WN_Users u WITH (NOLOCK)
        WHERE LOWER(LTRIM(RTRIM(u.Email))) = LOWER(LTRIM(RTRIM(@Email)))
          AND NOT EXISTS (SELECT 1 FROM dbo.WN_Customers c WITH (NOLOCK) WHERE c.UserId = u.Id)
        ORDER BY u.IsActive DESC, u.Id ASC;
    END

    -- Treat empty strings and '0' as NULL for string / optional fields
    IF @CustomerTypeId IS NULL OR LTRIM(RTRIM(@CustomerTypeId)) IN ('', '0') SET @CustomerTypeId = NULL;
    IF @IdentificationDocumentTypeId IS NULL OR LTRIM(RTRIM(@IdentificationDocumentTypeId)) IN ('', '0') SET @IdentificationDocumentTypeId = NULL;
    IF LTRIM(RTRIM(@Company)) = '' SET @Company = NULL;
    IF LTRIM(RTRIM(@LastName)) = '' SET @LastName = NULL;
    IF LTRIM(RTRIM(@PhoneNumber)) = '' SET @PhoneNumber = NULL;
    IF LTRIM(RTRIM(@CnicOrPassport)) = '' SET @CnicOrPassport = NULL;
    IF LTRIM(RTRIM(@Address)) = '' SET @Address = NULL;
    IF LTRIM(RTRIM(@Notes)) = '' SET @Notes = NULL;
    IF LTRIM(RTRIM(@CreatedBy)) = '' SET @CreatedBy = NULL;
    IF LTRIM(RTRIM(@NTN)) = '' SET @NTN = NULL;
    IF LTRIM(RTRIM(@SecpRegistrationNo)) = '' SET @SecpRegistrationNo = NULL;

    INSERT INTO dbo.WN_Customers
    (
        FirstName,
        LastName,
        Company,
        Email, 
        PhoneNumber,
        CnicOrPassport,
        Address, 
        CityId, 
        Notes, 
        CreatedBy, 
        UserId, 
        NTN, 
        SecpRegistrationNo,
        CustomerTypeId,
        CountryId,
        IdentificationDocumentTypeId
    )
    VALUES
    (
        @FirstName, 
        @LastName,
        @Company,
        @Email,
        @PhoneNumber,
        @CnicOrPassport, 
        @Address, 
        @CityId, 
        @Notes, 
        @CreatedBy,
        @UserId,
        @NTN,
        @SecpRegistrationNo,
        TRY_CAST(@CustomerTypeId AS INT),
        @CountryId,
        TRY_CAST(@IdentificationDocumentTypeId AS INT)
    ); 

    SELECT SCOPE_IDENTITY() AS ID;
END;

GO
/****** Object:  StoredProcedure [dbo].[WN_Customers_Search]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_Customers_Search]
    @Query NVARCHAR(255)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT TOP 20
           c.Id, c.IdGUID, c.Code, c.FirstName, c.LastName, c.Company,
           LTRIM(RTRIM(ISNULL(c.FirstName,'') + ' ' + ISNULL(c.LastName,''))) AS FullName,
           c.Email, c.PhoneNumber, c.CnicOrPassport, c.Address,
           c.CityId, ci.Description AS CityName, c.IsActive, c.Notes, c.CreatedAt,
           c.NTN, c.SecpRegistrationNo
    FROM dbo.WN_Customers c
    LEFT JOIN dbo.City ci ON ci.Id = c.CityId
    WHERE c.IsActive = 1 AND (
           c.FirstName   LIKE '%' + @Query + '%' OR
           c.LastName    LIKE '%' + @Query + '%' OR
           c.Company     LIKE '%' + @Query + '%' OR
           c.Email       LIKE '%' + @Query + '%' OR
           c.Code        LIKE '%' + @Query + '%' OR
           c.PhoneNumber LIKE '%' + @Query + '%' OR
           c.NTN         LIKE '%' + @Query + '%')
    ORDER BY c.FirstName;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Customers_Update]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_Customers_Update]
    @IdGUID             UNIQUEIDENTIFIER = NULL,
    @Id                 INT              = NULL,
    @FirstName          NVARCHAR(100)  = NULL,
    @LastName           NVARCHAR(100)  = NULL,
    @Email              NVARCHAR(255)  = NULL,
    @PhoneNumber        NVARCHAR(50)   = NULL,
    @CnicOrPassport     NVARCHAR(50)   = NULL,
    @Address            NVARCHAR(500)  = NULL,
    @CityId             INT            = NULL,
    @Notes              NVARCHAR(1000) = NULL,
    @IsActive           BIT            = NULL,
    @Company            NVARCHAR(255)  = NULL,
    @NTN                NVARCHAR(100)  = NULL,
    @SecpRegistrationNo NVARCHAR(100)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET QUOTED_IDENTIFIER ON;

    DECLARE @UserId INT = NULL;
    SELECT TOP 1 @UserId = UserId
    FROM dbo.WN_Customers
    WHERE (@IdGUID IS NOT NULL AND IdGUID = @IdGUID)
       OR (@Id IS NOT NULL AND Id = @Id);

    -- If customer didn't have a linked UserId, find existing user by email and link it
    IF @UserId IS NULL
    BEGIN
        SELECT TOP 1 @UserId = u.Id
        FROM dbo.WN_Users u
        INNER JOIN dbo.WN_Customers c ON LOWER(LTRIM(RTRIM(c.Email))) = LOWER(LTRIM(RTRIM(u.Email)))
        WHERE (@IdGUID IS NOT NULL AND c.IdGUID = @IdGUID)
           OR (@Id IS NOT NULL AND c.Id = @Id);

        IF @UserId IS NOT NULL
        BEGIN
            UPDATE dbo.WN_Customers
            SET UserId = @UserId
            WHERE (@IdGUID IS NOT NULL AND IdGUID = @IdGUID)
               OR (@Id IS NOT NULL AND Id = @Id);
        END
    END

    UPDATE dbo.WN_Customers SET
        FirstName          = ISNULL(@FirstName,          FirstName),
        LastName           = ISNULL(@LastName,           LastName),
        Company            = ISNULL(@Company,            Company),
        Email              = ISNULL(@Email,              Email),
        PhoneNumber        = ISNULL(@PhoneNumber,        PhoneNumber),
        CnicOrPassport     = ISNULL(@CnicOrPassport,     CnicOrPassport),
        Address            = ISNULL(@Address,            Address),
        CityId             = ISNULL(@CityId,             CityId),
        Notes              = ISNULL(@Notes,              Notes),
        IsActive           = ISNULL(@IsActive,           IsActive),
        NTN                = ISNULL(@NTN,                NTN),
        SecpRegistrationNo = ISNULL(@SecpRegistrationNo, SecpRegistrationNo),
        UpdatedAt          = GETDATE()
    WHERE (@IdGUID IS NOT NULL AND IdGUID = @IdGUID)
       OR (@Id IS NOT NULL AND Id = @Id);

    IF @UserId IS NOT NULL AND @UserId > 0
    BEGIN
        DECLARE @FullName NVARCHAR(200) = LTRIM(RTRIM(ISNULL(@FirstName, '') + ' ' + ISNULL(@LastName, '')));
        UPDATE dbo.WN_Users SET
            Email          = ISNULL(@Email,          Email),
            UserName       = ISNULL(@Email,          UserName),
            PhoneNumber    = ISNULL(@PhoneNumber,    PhoneNumber),
            Name           = CASE WHEN @FullName <> '' THEN @FullName ELSE Name END,
            Address        = ISNULL(@Address,        Address),
            CityId         = ISNULL(@CityId,         CityId),
            CnicOrPassport = ISNULL(@CnicOrPassport, CnicOrPassport)
        WHERE Id = @UserId;
    END;

    SELECT c.Id, c.IdGUID, c.Code, c.FirstName, c.LastName, c.Company,
           LTRIM(RTRIM(ISNULL(c.FirstName,'') + ' ' + ISNULL(c.LastName,''))) AS FullName,
           c.Email, c.PhoneNumber, c.CnicOrPassport, c.Address,
           c.CityId, ci.Description AS CityName, c.IsActive, c.Notes, c.CreatedAt,
           c.NTN, c.SecpRegistrationNo, c.UserId
    FROM dbo.WN_Customers c
    LEFT JOIN dbo.City ci ON ci.Id = c.CityId
    WHERE (@IdGUID IS NOT NULL AND c.IdGUID = @IdGUID)
       OR (@Id IS NOT NULL AND c.Id = @Id);
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Customers_UpdateAgreementDetails]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_Customers_UpdateAgreementDetails]
    @CustomerId         INT,
    @FirstName          NVARCHAR(250) = NULL,
    @LastName           NVARCHAR(250) = NULL,
    @PhoneNumber        NVARCHAR(100) = NULL,
    @Cnic               NVARCHAR(100) = NULL,
    @Address            NVARCHAR(500) = NULL,
    @CompanyName        NVARCHAR(250) = NULL,
    @NTN                NVARCHAR(100) = NULL,
    @SecpRegistrationNo NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- If @LastName is not provided but @FirstName contains a space, split cleanly
    IF @LastName IS NULL AND @FirstName IS NOT NULL AND CHARINDEX(' ', LTRIM(RTRIM(@FirstName))) > 0
    BEGIN
        DECLARE @TrimmedName NVARCHAR(250) = LTRIM(RTRIM(@FirstName));
        DECLARE @SpacePos INT = CHARINDEX(' ', @TrimmedName);
        SET @FirstName = SUBSTRING(@TrimmedName, 1, @SpacePos - 1);
        SET @LastName = LTRIM(SUBSTRING(@TrimmedName, @SpacePos + 1, LEN(@TrimmedName)));
    END

    UPDATE dbo.WN_Customers
    SET FirstName          = ISNULL(@FirstName, FirstName),
        LastName           = ISNULL(@LastName, LastName),
        PhoneNumber        = ISNULL(@PhoneNumber, PhoneNumber),
        CnicOrPassport     = ISNULL(@Cnic, CnicOrPassport),
        Address            = ISNULL(@Address, Address),
        Company            = ISNULL(@CompanyName, Company),
        NTN                = ISNULL(@NTN, NTN),
        SecpRegistrationNo = ISNULL(@SecpRegistrationNo, SecpRegistrationNo),
        UpdatedAt          = SYSUTCDATETIME()
    WHERE Id = @CustomerId;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_CustomersTemp_Insert]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[WN_CustomersTemp_Insert]
@FirstName          NVARCHAR(100),
    @LastName           NVARCHAR(100)  = NULL,
    @Email              NVARCHAR(255),
    @PhoneNumber        NVARCHAR(50)   = NULL,
    @CnicOrPassport     NVARCHAR(50)   = NULL,
    @Address            NVARCHAR(500)  = NULL,
    @CityId             INT            = NULL,
    @Notes              NVARCHAR(1000) = NULL,
    @CreatedBy          NVARCHAR(255)  = NULL,
    @UserId             INT            = NULL,
    @Company            NVARCHAR(255)  = NULL,
    @NTN                NVARCHAR(100)  = NULL,
    @SecpRegistrationNo NVARCHAR(100)  = NULL,
	@CustomerTypeId     nvarchar(225)  = NULL,
	@CountryId           INT           = NULL,
	@IdentificationDocumentTypeId    nvarchar(225) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET QUOTED_IDENTIFIER ON;
    INSERT INTO dbo.WN_Customers
     (FirstName,
	  LastName,
	  Company,
	  Email, 
	  PhoneNumber,
	  CnicOrPassport,
	  Address, 
	  CityId, 
	  Notes, 
	  CreatedBy, 
	  UserId, 
	  NTN, 
	  SecpRegistrationNo,
	  CustomerTypeId,
	  CountryId,
	  IdentificationDocumentTypeId
	   )
    VALUES
      (@FirstName, 
	  @LastName,
	  @Company,
	  @Email,
	  @PhoneNumber,
	  @CnicOrPassport, 
	  @Address, 
	  @CityId, 
	  @Notes, 
	  @CreatedBy,
	  @UserId,
	  @NTN,
	  @SecpRegistrationNo,
	  @CustomerTypeId,
	  @CountryId,
	  @IdentificationDocumentTypeId); 
	  SELECT SCOPE_IDENTITY() ID
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_CustomersVendors_SyncOnInvoice]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- Enhanced Helper Procedure: WN_CustomersVendors_SyncOnInvoice
CREATE   PROCEDURE [dbo].[WN_CustomersVendors_SyncOnInvoice]
    @CustomerId  INT = NULL,
    @UserId      INT = NULL,
    @BookingId   INT = NULL,
    @CreatedById INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @TargetEmail NVARCHAR(255) = NULL;

    IF @UserId IS NOT NULL AND @UserId > 0
    BEGIN
        SELECT TOP 1 @TargetEmail = Email FROM dbo.WN_Users WITH (NOLOCK) WHERE Id = @UserId;
    END

    -- Resolve Customer details from WN_Customers with multi-attribute fallback
    DECLARE @CustUserId INT = NULL;
    DECLARE @CustomerCode NVARCHAR(50) = NULL;
    DECLARE @FirstName NVARCHAR(100) = NULL;
    DECLARE @LastName NVARCHAR(100) = NULL;
    DECLARE @Company NVARCHAR(255) = NULL;
    DECLARE @Email NVARCHAR(255) = NULL;
    DECLARE @PhoneNumber NVARCHAR(50) = NULL;
    DECLARE @CnicOrPassport NVARCHAR(50) = NULL;
    DECLARE @Address NVARCHAR(500) = NULL;
    DECLARE @CustCityId INT = NULL;

    SELECT TOP 1
        @CustUserId     = c.UserId,
        @CustomerCode   = c.Code,
        @FirstName      = c.FirstName,
        @LastName       = c.LastName,
        @Company        = c.Company,
        @Email          = c.Email,
        @PhoneNumber    = c.PhoneNumber,
        @CnicOrPassport = c.CnicOrPassport,
        @Address        = c.Address,
        @CustCityId     = c.CityId
    FROM dbo.WN_Customers c WITH (NOLOCK)
    WHERE c.Id = @CustomerId 
       OR (c.UserId IS NOT NULL AND c.UserId = @UserId)
       OR (@TargetEmail IS NOT NULL AND c.Email = @TargetEmail)
       OR (c.Code IS NOT NULL AND c.Code = (SELECT TOP 1 CustomerCode FROM dbo.WN_Bookings WITH (NOLOCK) WHERE Id = @BookingId));

    IF @CustomerId IS NULL AND @CustUserId IS NOT NULL
        SET @CustomerId = @CustUserId;

    -- Fallback missing fields from WN_Users
    IF @UserId IS NOT NULL AND @UserId > 0
    BEGIN
        SELECT TOP 1
            @Email          = ISNULL(NULLIF(@Email, ''), u.Email),
            @FirstName      = CASE WHEN @FirstName IS NULL OR @FirstName = '' THEN u.Name ELSE @FirstName END,
            @Address        = ISNULL(NULLIF(@Address, ''), u.Address),
            @CnicOrPassport = ISNULL(NULLIF(@CnicOrPassport, ''), u.CnicOrPassport),
            @CustCityId     = ISNULL(@CustCityId, u.CityId)
        FROM dbo.WN_Users u WITH (NOLOCK)
        WHERE u.Id = @UserId;
    END

    -- Fallback missing fields from WN_BookingDetails & WN_Bookings
    IF @BookingId IS NOT NULL
    BEGIN
        SELECT TOP 1
            @CustomerCode   = ISNULL(NULLIF(@CustomerCode, ''), bd.CustomerCode),
            @Email          = ISNULL(NULLIF(@Email, ''), bd.CustomerEmail),
            @FirstName      = CASE WHEN @FirstName IS NULL OR @FirstName = '' THEN bd.CustomerName ELSE @FirstName END
        FROM dbo.WN_BookingDetails bd WITH (NOLOCK)
        JOIN dbo.WN_Bookings b WITH (NOLOCK) ON b.IdGUID = bd.BookingGuid
        WHERE b.Id = @BookingId;

        IF @CustomerCode IS NULL OR @CustomerCode = ''
        BEGIN
            SELECT TOP 1 @CustomerCode = CustomerCode
            FROM dbo.WN_Bookings WITH (NOLOCK)
            WHERE Id = @BookingId;
        END
    END

    -- Fallback Company Name from dbo.Company if WN_Customers.Company is missing
    IF (@Company IS NULL OR LTRIM(RTRIM(@Company)) = '') AND @UserId IS NOT NULL
    BEGIN
        SELECT TOP 1 @Company = comp.CompanyName
        FROM dbo.WN_Users u WITH (NOLOCK)
        JOIN dbo.Company comp WITH (NOLOCK) ON comp.Id = u.CompanyId
        WHERE u.Id = @UserId AND comp.CompanyName NOT LIKE '%WorkNest%';
    END

    -- Exit if no email or customer code available
    IF (@Email IS NULL OR LTRIM(RTRIM(@Email)) = '') AND (@CustomerCode IS NULL OR LTRIM(RTRIM(@CustomerCode)) = '')
        RETURN;

    -- Duplicate Check: If matching customer already exists in dbo.CustomersVendors, skip insertion
    IF EXISTS (
        SELECT 1 
        FROM dbo.CustomersVendors WITH (UPDLOCK, HOLDLOCK)
        WHERE (Email IS NOT NULL AND Email <> '' AND LOWER(RTRIM(LTRIM(Email))) = LOWER(RTRIM(LTRIM(@Email))))
           OR (Code IS NOT NULL AND Code <> '' AND Code = @CustomerCode)
    )
    BEGIN
        RETURN;
    END

    -- Resolve Name Rule: When WN_Customers Company is not NULL/empty, Name MUST be the Company name
    DECLARE @TargetName NVARCHAR(250) = NULL;
    IF @Company IS NOT NULL AND LTRIM(RTRIM(@Company)) <> ''
        SET @TargetName = LTRIM(RTRIM(@Company));
    ELSE
        SET @TargetName = LTRIM(RTRIM(ISNULL(@FirstName, '') + ' ' + ISNULL(@LastName, '')));

    IF @TargetName IS NULL OR @TargetName = ''
        SET @TargetName = 'Valued Customer';

    -- Parse CNIC vs Passport
    DECLARE @CleanCnicPass NVARCHAR(50) = REPLACE(REPLACE(REPLACE(ISNULL(@CnicOrPassport, ''), '-', ''), ' ', ''), '/', '');
    DECLARE @CNIC NVARCHAR(50) = NULL;
    DECLARE @Passport NVARCHAR(50) = NULL;

    IF @CleanCnicPass <> ''
    BEGIN
        IF LEN(@CleanCnicPass) = 13 AND ISNUMERIC(@CleanCnicPass) = 1
            SET @CNIC = @CnicOrPassport;
        ELSE
            SET @Passport = @CnicOrPassport;
    END

    -- Normalize Phone to Pakistani international format (+923xxxxxxxxx)
    -- Handles raw, +9203..., 00923..., 923..., 03..., 3... formats cleanly
    DECLARE @Phone NVARCHAR(50) = NULL;
    IF @PhoneNumber IS NOT NULL AND LTRIM(RTRIM(@PhoneNumber)) <> ''
    BEGIN
        DECLARE @CleanPhone NVARCHAR(50) = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(@PhoneNumber)), ' ', ''), '-', ''), '(', ''), ')', ''), '+', '');
        IF @CleanPhone LIKE '9203%'
            SET @Phone = '+92' + SUBSTRING(@CleanPhone, 4, LEN(@CleanPhone) - 3);
        ELSE IF @CleanPhone LIKE '00923%'
            SET @Phone = '+' + RIGHT(@CleanPhone, LEN(@CleanPhone) - 2);
        ELSE IF @CleanPhone LIKE '923%'
            SET @Phone = '+' + @CleanPhone;
        ELSE IF @CleanPhone LIKE '03%'
            SET @Phone = '+92' + SUBSTRING(@CleanPhone, 2, LEN(@CleanPhone) - 1);
        ELSE IF @CleanPhone LIKE '3%' AND LEN(@CleanPhone) = 10
            SET @Phone = '+92' + @CleanPhone;
        ELSE
            SET @Phone = LTRIM(RTRIM(@PhoneNumber));
    END

    -- Location / Company / Branch / Province / City Resolution
    DECLARE @CompanyId INT = NULL;
    DECLARE @BranchId INT = NULL;
    DECLARE @ProvinceId INT = NULL;
    DECLARE @LocationCityId INT = NULL;

    IF @BookingId IS NOT NULL
    BEGIN
        SELECT TOP 1
            @CompanyId  = l.CompanyId,
            @BranchId   = l.BranchId,
            @ProvinceId = l.ProvinceId,
            @LocationCityId = l.CityId
        FROM dbo.WN_Bookings b WITH (NOLOCK)
        JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = b.SpaceId
        JOIN dbo.WN_Locations l WITH (NOLOCK) ON l.Id = s.LocationId
        WHERE b.Id = @BookingId;
    END

    IF @CompanyId IS NULL
        SET @CompanyId = 486;

    DECLARE @ResolvedCityId INT = ISNULL(@CustCityId, @LocationCityId);
    DECLARE @CountryId INT = NULL;

    IF @ResolvedCityId IS NOT NULL
    BEGIN
        SELECT TOP 1 @CountryId = CountryId
        FROM dbo.City WITH (NOLOCK)
        WHERE Id = @ResolvedCityId AND CountryId IS NOT NULL;

        IF @CountryId IS NULL
            SET @CountryId = 168; -- Pakistan SAC400 CountryId default
    END
    ELSE
    BEGIN
        SET @CountryId = 168;
    END

    -- GUID / HashGUID generation
    DECLARE @ShortGUID VARCHAR(10);

SET @ShortGUID = CONVERT(VARCHAR(50), NEWID());

SELECT @ShortGUID;

    DECLARE @HashGUID VARBINARY(50) = CAST(NEWID() AS VARBINARY(50));

    -- Insert single record into dbo.CustomersVendors
    INSERT INTO dbo.CustomersVendors (
        Name, Code, Type, AddressLine1,
        CNIC, Passport, CityId, CountryId, Phone, Email,
        CompanyId, CreatedById, CreatedTime, ShortGUID, HashGUID,
        BranchId, ProvinceId
    )
    VALUES (
        @TargetName, @CustomerCode, 1, @Address,
        @CNIC, @Passport, @ResolvedCityId, @CountryId, @Phone, @Email,
        @CompanyId, @CreatedById, SYSUTCDATETIME(), @ShortGUID, @HashGUID,
        @BranchId, @ProvinceId
    );
END
GO
/****** Object:  StoredProcedure [dbo].[WN_CustomInvoice_GetBookings]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_CustomInvoice_GetBookings]
    @UserId INT
AS
BEGIN
    -- CI_01: the customer bookings (WN_Bookings.UserId, or the customer code of the user), most recent first.
    -- Label: #id space (start to end).
    SET NOCOUNT ON;
    SELECT TOP 100
           b.Id AS BookingId,
           CONCAT(N'#', b.Id, N' ', COALESCE(NULLIF(LTRIM(RTRIM(s.Name)), N''), s.Code, N'Booking'), N' (',
                  CONVERT(NVARCHAR(11), b.StartOn, 106), N' to ', CONVERT(NVARCHAR(11), b.EndOn, 106), N')') AS Label,
           COALESCE(NULLIF(LTRIM(RTRIM(s.Name)), N''), s.Code) AS SpaceName,
           s.LocationId,
           l.Name AS LocationName,
           b.StartOn,
           b.EndOn,
           COALESCE(bs.Label, bs.Code) AS Status
      FROM dbo.WN_Bookings b WITH (NOLOCK)
      LEFT JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = b.SpaceId
      LEFT JOIN dbo.WN_Locations l WITH (NOLOCK) ON l.Id = s.LocationId
      LEFT JOIN dbo.WN_BookingStatuses bs WITH (NOLOCK) ON bs.Id = b.BookingStatusId
     WHERE ISNULL(b.IsDeleted, 0) = 0
       AND (b.UserId = @UserId
            OR b.CustomerCode IN (SELECT c.Code FROM dbo.WN_Customers c WITH (NOLOCK) WHERE c.UserId = @UserId AND c.Code IS NOT NULL AND c.Code <> ''))
     ORDER BY b.StartOn DESC, b.Id DESC;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_CustomInvoice_GetLedgerDefaults]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_CustomInvoice_GetLedgerDefaults]
    @LocationId INT,
    @Date       DATE
AS
BEGIN
    -- CI_01: the default GL accounts of a location on a date from dbo.WN_ChargeTypeAccountMapping (effective that day;
    -- ChargeTypeId 1 = receivable + rent, 2 = security received, 3 = sales tax, 4 = services income). One row; an account
    -- with no mapping (or mapped to 0) is NULL. Code = AccountsCOA.ShortDesc, name = AccountsCOA.Description.
    SET NOCOUNT ON;
    DECLARE @OnDate DATE = ISNULL(@Date, CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE));
    DECLARE @DefAr INT = NULL, @DefRent INT = NULL, @DefServ INT = NULL, @DefTax INT = NULL, @DefSec INT = NULL;
    SELECT @DefAr   = COALESCE(@DefAr,   MAX(CASE WHEN m.ChargeTypeId = 1 THEN NULLIF(m.AccountReceivableId, 0) END)),
           @DefRent = COALESCE(@DefRent, MAX(CASE WHEN m.ChargeTypeId = 1 THEN NULLIF(m.RentAccountId, 0) END)),
           @DefSec  = COALESCE(@DefSec,  MAX(CASE WHEN m.ChargeTypeId = 2 THEN NULLIF(m.SecurityReceivedId, 0) END)),
           @DefTax  = COALESCE(@DefTax,  MAX(CASE WHEN m.ChargeTypeId = 3 THEN NULLIF(m.SalesTaxId, 0) END)),
           @DefServ = COALESCE(@DefServ, MAX(CASE WHEN m.ChargeTypeId = 4 THEN NULLIF(m.ServicesIncomeId, 0) END))
      FROM dbo.WN_ChargeTypeAccountMapping m WITH (NOLOCK)
     WHERE m.LocationId = @LocationId
       AND m.EffectiveFrom <= @OnDate
       AND (m.EffectiveTo IS NULL OR m.EffectiveTo >= @OnDate);
    SELECT ar.Id AS AccountReceivableId, ar.ShortDesc AS AccountReceivableCode, LTRIM(RTRIM(ar.Description)) AS AccountReceivableName,
           rn.Id AS RentAccountId, rn.ShortDesc AS RentCode, LTRIM(RTRIM(rn.Description)) AS RentName,
           sv.Id AS ServicesIncomeId, sv.ShortDesc AS ServicesIncomeCode, LTRIM(RTRIM(sv.Description)) AS ServicesIncomeName,
           tx.Id AS SalesTaxId, tx.ShortDesc AS SalesTaxCode, LTRIM(RTRIM(tx.Description)) AS SalesTaxName,
           sc.Id AS SecurityReceivedId, sc.ShortDesc AS SecurityReceivedCode, LTRIM(RTRIM(sc.Description)) AS SecurityReceivedName
      FROM (SELECT 1 AS One) x
      LEFT JOIN dbo.AccountsCOA ar WITH (NOLOCK) ON ar.Id = @DefAr
      LEFT JOIN dbo.AccountsCOA rn WITH (NOLOCK) ON rn.Id = @DefRent
      LEFT JOIN dbo.AccountsCOA sv WITH (NOLOCK) ON sv.Id = @DefServ
      LEFT JOIN dbo.AccountsCOA tx WITH (NOLOCK) ON tx.Id = @DefTax
      LEFT JOIN dbo.AccountsCOA sc WITH (NOLOCK) ON sc.Id = @DefSec;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_CustomInvoice_GetList]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_CustomInvoice_GetList]
    @Search   NVARCHAR(200) = NULL,
    @Page     INT           = 1,
    @PageSize INT           = 20
AS
BEGIN
    -- CI_01: custom invoices (InvoiceTypeId 7 / IsCustom = 1), newest first, one page; TotalCount (all matches) on every row.
    SET NOCOUNT ON;
    IF @Page IS NULL OR @Page < 1 SET @Page = 1;
    IF @PageSize IS NULL OR @PageSize < 1 OR @PageSize > 100 SET @PageSize = 20;
    SET @Search = NULLIF(LTRIM(RTRIM(@Search)), N'');
    SELECT i.Id AS InvoiceId,
           i.InvoiceNumber,
           COALESCE(NULLIF(LTRIM(RTRIM(c.Company)), N''), NULLIF(LTRIM(RTRIM(ISNULL(c.FirstName, N'') + N' ' + ISNULL(c.LastName, N''))), N''), u.Name, u.Email) AS CustomerName,
           CASE WHEN b.Id IS NULL THEN NULL ELSE CONCAT(N'#', b.Id, N' ', COALESCE(NULLIF(LTRIM(RTRIM(s.Name)), N''), s.Code, N'Booking'), N' (',
                  CONVERT(NVARCHAR(11), b.StartOn, 106), N' to ', CONVERT(NVARCHAR(11), b.EndOn, 106), N')') END AS BookingLabel,
           i.GrandTotal,
           i.IssuedOn,
           COALESCE(CASE i.StatusId WHEN 1 THEN 'Unpaid' WHEN 2 THEN 'Paid' WHEN 3 THEN 'Partial' WHEN 4 THEN 'Overdue' WHEN 5 THEN 'Cancelled' END,
                    CASE LTRIM(RTRIM(os.Description)) WHEN 'Un Paid' THEN 'Unpaid' WHEN 'Challan Expire' THEN 'Overdue' ELSE LTRIM(RTRIM(os.Description)) END,
                    'Unknown') AS StatusLabel,
           i.CustomReason AS Reason,
           COALESCE(NULLIF(LTRIM(RTRIM(cb.Name)), N''), cb.Email) AS CreatedBy,
           v.Code AS VoucherCode,
           ri.InvoiceNumber AS ReplacedInvoiceNumber,
           COUNT(*) OVER () AS TotalCount
      FROM dbo.WN_Invoices i WITH (NOLOCK)
      LEFT JOIN dbo.WN_CustomInvoices ci WITH (NOLOCK) ON ci.InvoiceId = i.Id
      LEFT JOIN dbo.WN_Bookings b WITH (NOLOCK) ON b.Id = i.BookingId
      LEFT JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = b.SpaceId
      LEFT JOIN dbo.WN_Users u WITH (NOLOCK) ON u.Id = i.UserId
      LEFT JOIN dbo.WN_Users cb WITH (NOLOCK) ON cb.Id = i.CreatedById
      LEFT JOIN dbo.OrderStatus os WITH (NOLOCK) ON os.Id = i.StatusId
      LEFT JOIN dbo.Vouchers v WITH (NOLOCK) ON v.Id = i.VoucherId
      LEFT JOIN dbo.WN_Invoices ri WITH (NOLOCK) ON ri.Id = ci.ReplacedInvoiceId
      OUTER APPLY (SELECT TOP 1 cu.Code, cu.FirstName, cu.LastName, cu.Company
                     FROM dbo.WN_Customers cu WITH (NOLOCK)
                    WHERE cu.UserId = i.UserId
                    ORDER BY cu.Id) c
     WHERE (i.InvoiceTypeId = 7 OR i.IsCustom = 1)
       AND (@Search IS NULL
            OR i.InvoiceNumber LIKE N'%' + @Search + N'%'
            OR i.CustomReason LIKE N'%' + @Search + N'%'
            OR c.Code LIKE N'%' + @Search + N'%'
            OR c.FirstName LIKE N'%' + @Search + N'%'
            OR c.LastName LIKE N'%' + @Search + N'%'
            OR c.Company LIKE N'%' + @Search + N'%'
            OR u.Name LIKE N'%' + @Search + N'%'
            OR u.Email LIKE N'%' + @Search + N'%')
     ORDER BY i.Id DESC
     OFFSET (@Page - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_CustomInvoice_GetReplaceable]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_CustomInvoice_GetReplaceable]
    @BookingId INT
AS
BEGIN
    -- CI_01: the booking invoices a custom invoice may replace: unpaid (Un Paid / Challan Expire, nothing paid, no
    -- active fee receipt) and not cancelled; newest first, at most 10. Same rules as dbo.WN_CustomInvoice_Insert.
    SET NOCOUNT ON;
    DECLARE @UnPaidId    INT = ISNULL((SELECT TOP 1 Id FROM dbo.OrderStatus WITH (NOLOCK) WHERE LTRIM(RTRIM(Description)) = 'Un Paid' ORDER BY Id), 1);
    DECLARE @OverdueId   INT = ISNULL((SELECT TOP 1 Id FROM dbo.OrderStatus WITH (NOLOCK) WHERE LTRIM(RTRIM(Description)) = 'Challan Expire' ORDER BY Id), 4);
    DECLARE @CancelledId INT = ISNULL((SELECT TOP 1 Id FROM dbo.OrderStatus WITH (NOLOCK) WHERE LTRIM(RTRIM(Description)) = 'Cancelled' ORDER BY Id), 5);
    SELECT TOP 10
           i.Id AS InvoiceId,
           i.InvoiceNumber,
           i.IssuedOn,
           i.BillingPeriodStart AS PeriodStart,
           i.BillingPeriodEnd AS PeriodEnd,
           i.GrandTotal,
           i.InvoiceTypeId
      FROM dbo.WN_Invoices i WITH (NOLOCK)
     WHERE i.BookingId = @BookingId
       AND i.StatusId IN (1, 4, @UnPaidId, @OverdueId)
       AND i.StatusId NOT IN (5, @CancelledId)
       AND ISNULL(i.PaidTotal, 0) = 0
       AND NOT EXISTS (SELECT 1 FROM dbo.WN_FeeReceipts fr WITH (NOLOCK) WHERE fr.InvoiceIdGUID = i.PublicId AND fr.Status = 1)
     ORDER BY i.Id DESC;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_CustomInvoice_Insert]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_CustomInvoice_Insert]
    @UserId                  INT,
    @BookingId               INT = NULL,
    @LocationId              INT,
    @IssuedOn                DATE,
    @DueOn                   DATE,
    @PeriodFrom              DATE,
    @PeriodTo                DATE,
    @RoomRentExclTax         DECIMAL(18,4),
    @ServiceCharges          DECIMAL(18,4),
    @TaxPercent              DECIMAL(9,4),
    @TaxOnServiceCharges     DECIMAL(18,4),
    @SecurityDepositAmount   DECIMAL(18,4),
    @GrandTotal              DECIMAL(18,4),
    @CustomReason            NVARCHAR(500),
    @CreatedById             INT,
    @VoucherDate             DATE,
    @VoucherDescription      NVARCHAR(500),
    @CustomerLedgerDebit     DECIMAL(18,4),
    @CustomerLedgerNarration NVARCHAR(500),
    @ReplaceInvoiceId        INT = NULL,
    @Lines                   dbo.TT_WN_CustomInvoiceLedgerLine READONLY
AS
BEGIN
    -- CI_01: a custom invoice (InvoiceTypeId 7, IsCustom = 1) with its own GL voucher. In ONE transaction: the invoice
    -- (number INV-<year>-<MAX(Id)+1> as WN_Invoices_Insert, status Un Paid) and its lines (dbo.WN_InvoiceLines, for the
    -- PDF), a JV (dbo.Vouchers_Insert, RefNo = invoice number) with one dbo.Ledgers_Insert per posted line, the customer
    -- ledger debit (dbo.CustomerLedger_Insert), WN_Invoices.VoucherId, dbo.WN_CustomInvoices and one dbo.WN_AuditLog row
    -- (EntityName WN_CustomInvoice). With @ReplaceInvoiceId: that unpaid invoice of the same booking is cancelled (row
    -- kept) and its JV and customer ledger debit are reversed. Any error rolls everything back. Business rules: error
    -- 51000 with a message for the screen. Returns one row.
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @Msg NVARCHAR(2048);
    DECLARE @UnPaidId    INT = ISNULL((SELECT TOP 1 Id FROM dbo.OrderStatus WITH (NOLOCK) WHERE LTRIM(RTRIM(Description)) = 'Un Paid' ORDER BY Id), 1);
    DECLARE @OverdueId   INT = ISNULL((SELECT TOP 1 Id FROM dbo.OrderStatus WITH (NOLOCK) WHERE LTRIM(RTRIM(Description)) = 'Challan Expire' ORDER BY Id), 4);
    DECLARE @CancelledId INT = ISNULL((SELECT TOP 1 Id FROM dbo.OrderStatus WITH (NOLOCK) WHERE LTRIM(RTRIM(Description)) = 'Cancelled' ORDER BY Id), 5);
    SET @CustomReason = NULLIF(LTRIM(RTRIM(@CustomReason)), N'');
    SET @VoucherDescription = NULLIF(LTRIM(RTRIM(@VoucherDescription)), N'');
    SET @CustomerLedgerNarration = NULLIF(LTRIM(RTRIM(@CustomerLedgerNarration)), N'');
    SET @RoomRentExclTax = ISNULL(@RoomRentExclTax, 0);
    SET @ServiceCharges = ISNULL(@ServiceCharges, 0);
    SET @TaxOnServiceCharges = ISNULL(@TaxOnServiceCharges, 0);
    SET @SecurityDepositAmount = ISNULL(@SecurityDepositAmount, 0);
    -- The posted lines in order (Seq 1..n is the line number in messages).
    DECLARE @L TABLE (Seq INT IDENTITY(1,1) PRIMARY KEY, [LineNo] INT NULL, AccountId INT NULL, Debit DECIMAL(18,4) NOT NULL, Credit DECIMAL(18,4) NOT NULL, Narration NVARCHAR(500) NULL);
    INSERT INTO @L ([LineNo], AccountId, Debit, Credit, Narration)
    SELECT [LineNo], AccountId, ISNULL(Debit, 0), ISNULL(Credit, 0), NULLIF(LTRIM(RTRIM(Narration)), N'')
      FROM @Lines
     ORDER BY [LineNo];
    -- 1. Rules (the API checks the same ones first)
    IF @CustomReason IS NULL
        BEGIN SET @Msg = N'Enter the reason for this custom invoice.'; THROW 51000, @Msg, 1; END
    IF @UserId IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.WN_Users WITH (NOLOCK) WHERE Id = @UserId)
        BEGIN SET @Msg = N'The customer was not found.'; THROW 51000, @Msg, 1; END
    IF @IssuedOn IS NULL OR @DueOn IS NULL
        BEGIN SET @Msg = N'Enter the issue date and the due date.'; THROW 51000, @Msg, 1; END
    IF @DueOn < @IssuedOn
        BEGIN SET @Msg = N'The due date cannot be before the issue date.'; THROW 51000, @Msg, 1; END
    IF (@PeriodFrom IS NULL AND @PeriodTo IS NOT NULL) OR (@PeriodFrom IS NOT NULL AND @PeriodTo IS NULL)
        BEGIN SET @Msg = N'Enter both period dates, or leave both empty.'; THROW 51000, @Msg, 1; END
    IF @PeriodFrom > @PeriodTo
        BEGIN SET @Msg = N'The period start cannot be after the period end.'; THROW 51000, @Msg, 1; END
    IF @RoomRentExclTax < 0 OR @ServiceCharges < 0 OR @TaxOnServiceCharges < 0 OR @SecurityDepositAmount < 0
        BEGIN SET @Msg = N'The invoice amounts cannot be negative.'; THROW 51000, @Msg, 1; END
    IF @SecurityDepositAmount <> ROUND(@SecurityDepositAmount, 2)
        BEGIN SET @Msg = N'The security deposit can have at most 2 decimals.'; THROW 51000, @Msg, 1; END
    IF @GrandTotal IS NULL OR @GrandTotal <= 0
        BEGIN SET @Msg = N'The invoice total must be more than zero.'; THROW 51000, @Msg, 1; END
    IF @GrandTotal <> @RoomRentExclTax + @ServiceCharges + @TaxOnServiceCharges + @SecurityDepositAmount
        BEGIN SET @Msg = CONCAT(N'The invoice total (', FORMAT(@GrandTotal, 'N2', 'en-US'), N') must equal rent + service charges + tax + security deposit (', FORMAT(@RoomRentExclTax + @ServiceCharges + @TaxOnServiceCharges + @SecurityDepositAmount, 'N2', 'en-US'), N').'); THROW 51000, @Msg, 1; END
    IF @TaxOnServiceCharges > 0 AND @ServiceCharges = 0 AND @RoomRentExclTax = 0
        BEGIN SET @Msg = N'Tax needs a service charge or rent amount to be charged on.'; THROW 51000, @Msg, 1; END
    IF @TaxOnServiceCharges > CASE WHEN @ServiceCharges > 0 THEN @ServiceCharges ELSE @RoomRentExclTax END
        BEGIN SET @Msg = N'The tax cannot be more than the amount it is charged on.'; THROW 51000, @Msg, 1; END
    IF @TaxPercent IS NOT NULL AND (@TaxPercent < 0 OR @TaxPercent > 100)
        BEGIN SET @Msg = N'The tax percentage must be between 0 and 100.'; THROW 51000, @Msg, 1; END
    IF @VoucherDate IS NULL
        BEGIN SET @Msg = N'Enter the voucher date.'; THROW 51000, @Msg, 1; END
    IF @CustomerLedgerDebit IS NULL OR @CustomerLedgerDebit <= 0
        BEGIN SET @Msg = N'The customer ledger debit must be more than zero.'; THROW 51000, @Msg, 1; END
    DECLARE @LineCount INT, @TotalDebit DECIMAL(18,4), @TotalCredit DECIMAL(18,4), @BadLine INT = NULL;
    SELECT @LineCount = COUNT(*), @TotalDebit = ISNULL(SUM(Debit), 0), @TotalCredit = ISNULL(SUM(Credit), 0) FROM @L;
    IF @LineCount < 2 OR @LineCount > 5
        BEGIN SET @Msg = N'The voucher needs 2 to 5 ledger lines.'; THROW 51000, @Msg, 1; END
    SELECT TOP 1 @BadLine = Seq FROM @L WHERE AccountId IS NULL OR AccountId <= 0 ORDER BY Seq;
    IF @BadLine IS NOT NULL
        BEGIN SET @Msg = CONCAT(N'Ledger line ', @BadLine, N': choose a GL account.'); THROW 51000, @Msg, 1; END
    SELECT TOP 1 @BadLine = Seq FROM @L WHERE Debit < 0 OR Credit < 0 OR (Debit > 0 AND Credit > 0) OR (Debit = 0 AND Credit = 0) ORDER BY Seq;
    IF @BadLine IS NOT NULL
        BEGIN SET @Msg = CONCAT(N'Ledger line ', @BadLine, N' must have either a debit or a credit (one of them, more than zero).'); THROW 51000, @Msg, 1; END
    IF @TotalDebit <> @TotalCredit
        BEGIN SET @Msg = CONCAT(N'Total debits (', FORMAT(@TotalDebit, 'N2', 'en-US'), N') must equal total credits (', FORMAT(@TotalCredit, 'N2', 'en-US'), N').'); THROW 51000, @Msg, 1; END
    SELECT TOP 1 @BadLine = l.Seq FROM @L l WHERE NOT EXISTS (SELECT 1 FROM dbo.AccountsCOA a WITH (NOLOCK) WHERE a.Id = l.AccountId) ORDER BY l.Seq;
    IF @BadLine IS NOT NULL
        BEGIN SET @Msg = CONCAT(N'Ledger line ', @BadLine, N': the GL account was not found.'); THROW 51000, @Msg, 1; END
    -- 2. Booking, location, company / branch
    IF @ReplaceInvoiceId IS NOT NULL AND @BookingId IS NULL
        BEGIN SET @Msg = N'Choose the booking of the invoice to replace.'; THROW 51000, @Msg, 1; END
    IF @BookingId IS NOT NULL
    BEGIN
        DECLARE @BkFound BIT = 0, @BkUserId INT = NULL, @BkCode NVARCHAR(50) = NULL, @BkLocationId INT = NULL;
        SELECT TOP 1 @BkFound = 1, @BkUserId = b.UserId, @BkCode = NULLIF(LTRIM(RTRIM(b.CustomerCode)), N''), @BkLocationId = s.LocationId
          FROM dbo.WN_Bookings b WITH (NOLOCK)
          LEFT JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = b.SpaceId
         WHERE b.Id = @BookingId AND ISNULL(b.IsDeleted, 0) = 0;
        IF @BkFound = 0
            BEGIN SET @Msg = N'The booking was not found.'; THROW 51000, @Msg, 1; END
        IF NOT (ISNULL(@BkUserId, 0) = @UserId
                OR (@BkCode IS NOT NULL AND @BkCode IN (SELECT c.Code FROM dbo.WN_Customers c WITH (NOLOCK) WHERE c.UserId = @UserId)))
            BEGIN SET @Msg = N'The booking does not belong to this customer.'; THROW 51000, @Msg, 1; END
        IF @LocationId IS NULL SET @LocationId = @BkLocationId;
        ELSE IF @BkLocationId IS NOT NULL AND @LocationId <> @BkLocationId
            BEGIN SET @Msg = N'The location must be the location of the booking.'; THROW 51000, @Msg, 1; END
    END
    IF @LocationId IS NULL
        BEGIN SET @Msg = N'Choose the location.'; THROW 51000, @Msg, 1; END
    DECLARE @CompanyId INT = NULL, @BranchId INT = NULL;
    SELECT TOP 1 @CompanyId = CompanyId, @BranchId = BranchId FROM dbo.WN_Locations WITH (NOLOCK) WHERE Id = @LocationId;
    IF @CompanyId IS NULL OR @BranchId IS NULL
        BEGIN SET @Msg = N'The location was not found, or it has no company or branch for the accounts.'; THROW 51000, @Msg, 1; END
    -- 3. Header accounts from the posted lines where they map naturally: the default account of that kind (space type ->
    --    space -> WN_ChargeTypeAccountMapping, as in WN_Invoices_Insert) when a line uses it, else the line with that amount.
    DECLARE @OnDate DATE = @IssuedOn;
    DECLARE @DefAr INT = NULL, @DefRent INT = NULL, @DefServ INT = NULL, @DefTax INT = NULL, @DefSec INT = NULL;
    IF @BookingId IS NOT NULL
        SELECT TOP 1
               @DefAr   = COALESCE(NULLIF(st.AccountReceivableId, 0), NULLIF(s.AccountReceivableId, 0)),
               @DefRent = COALESCE(NULLIF(st.RentAccountId, 0), NULLIF(s.RentAccountId, 0)),
               @DefServ = COALESCE(NULLIF(st.ServicesIncomeId, 0), NULLIF(s.ServicesIncomeId, 0)),
               @DefTax  = COALESCE(NULLIF(st.SalesTaxId, 0), NULLIF(s.SalesTaxId, 0)),
               @DefSec  = COALESCE(NULLIF(st.SecurityReceivedId, 0), NULLIF(s.SecurityReceivedId, 0))
          FROM dbo.WN_Bookings b WITH (NOLOCK)
          LEFT JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = b.SpaceId
          LEFT JOIN dbo.WN_SpaceTypes st WITH (NOLOCK) ON st.Id = s.SpaceTypeId
         WHERE b.Id = @BookingId;
    SELECT @DefAr   = COALESCE(@DefAr,   MAX(CASE WHEN m.ChargeTypeId = 1 THEN NULLIF(m.AccountReceivableId, 0) END)),
           @DefRent = COALESCE(@DefRent, MAX(CASE WHEN m.ChargeTypeId = 1 THEN NULLIF(m.RentAccountId, 0) END)),
           @DefSec  = COALESCE(@DefSec,  MAX(CASE WHEN m.ChargeTypeId = 2 THEN NULLIF(m.SecurityReceivedId, 0) END)),
           @DefTax  = COALESCE(@DefTax,  MAX(CASE WHEN m.ChargeTypeId = 3 THEN NULLIF(m.SalesTaxId, 0) END)),
           @DefServ = COALESCE(@DefServ, MAX(CASE WHEN m.ChargeTypeId = 4 THEN NULLIF(m.ServicesIncomeId, 0) END))
      FROM dbo.WN_ChargeTypeAccountMapping m WITH (NOLOCK)
     WHERE m.LocationId = @LocationId
       AND m.EffectiveFrom <= @OnDate
       AND (m.EffectiveTo IS NULL OR m.EffectiveTo >= @OnDate);
    DECLARE @ArLine INT = NULL, @RentLine INT = NULL, @ServLine INT = NULL, @TaxLine INT = NULL, @SecLine INT = NULL;
    SELECT TOP 1 @ArLine = Seq FROM @L WHERE Debit > 0 AND AccountId = @DefAr ORDER BY Seq;
    IF @ArLine IS NULL SELECT TOP 1 @ArLine = Seq FROM @L WHERE Debit > 0 AND Debit = @CustomerLedgerDebit ORDER BY Seq;
    IF @ArLine IS NULL SELECT TOP 1 @ArLine = Seq FROM @L WHERE Debit > 0 AND Debit = @GrandTotal ORDER BY Seq;
    IF @ArLine IS NULL SELECT TOP 1 @ArLine = Seq FROM @L WHERE Debit > 0 ORDER BY Debit DESC, Seq;
    SELECT TOP 1 @RentLine = Seq FROM @L WHERE Credit > 0 AND AccountId = @DefRent ORDER BY Seq;
    IF @RentLine IS NULL AND @RoomRentExclTax > 0 SELECT TOP 1 @RentLine = Seq FROM @L WHERE Credit = @RoomRentExclTax ORDER BY Seq;
    SELECT TOP 1 @ServLine = Seq FROM @L WHERE Credit > 0 AND AccountId = @DefServ AND Seq <> ISNULL(@RentLine, 0) ORDER BY Seq;
    IF @ServLine IS NULL AND @ServiceCharges > 0 SELECT TOP 1 @ServLine = Seq FROM @L WHERE Credit = @ServiceCharges AND Seq <> ISNULL(@RentLine, 0) ORDER BY Seq;
    SELECT TOP 1 @TaxLine = Seq FROM @L WHERE Credit > 0 AND AccountId = @DefTax AND Seq NOT IN (ISNULL(@RentLine, 0), ISNULL(@ServLine, 0)) ORDER BY Seq;
    IF @TaxLine IS NULL AND @TaxOnServiceCharges > 0 SELECT TOP 1 @TaxLine = Seq FROM @L WHERE Credit = @TaxOnServiceCharges AND Seq NOT IN (ISNULL(@RentLine, 0), ISNULL(@ServLine, 0)) ORDER BY Seq;
    SELECT TOP 1 @SecLine = Seq FROM @L WHERE Credit > 0 AND AccountId = @DefSec AND Seq NOT IN (ISNULL(@RentLine, 0), ISNULL(@ServLine, 0), ISNULL(@TaxLine, 0)) ORDER BY Seq;
    IF @SecLine IS NULL AND @SecurityDepositAmount > 0 SELECT TOP 1 @SecLine = Seq FROM @L WHERE Credit = @SecurityDepositAmount AND Seq NOT IN (ISNULL(@RentLine, 0), ISNULL(@ServLine, 0), ISNULL(@TaxLine, 0)) ORDER BY Seq;
    DECLARE @ArAcc INT = (SELECT AccountId FROM @L WHERE Seq = @ArLine);
    DECLARE @RentAcc INT = (SELECT AccountId FROM @L WHERE Seq = @RentLine);
    DECLARE @ServAcc INT = (SELECT AccountId FROM @L WHERE Seq = @ServLine);
    DECLARE @TaxAcc INT = (SELECT AccountId FROM @L WHERE Seq = @TaxLine);
    DECLARE @SecAcc INT = (SELECT AccountId FROM @L WHERE Seq = @SecLine);
    -- 4. Post
    DECLARE @InvoiceId INT = NULL, @InvoiceNumber NVARCHAR(50) = NULL, @PublicId UNIQUEIDENTIFIER = NEWID();
    DECLARE @VoucherId INT = NULL, @VoucherCode VARCHAR(50) = NULL, @CustomerVendorId INT = NULL, @CustomerCode NVARCHAR(50) = NULL;
    DECLARE @OldNumber NVARCHAR(50) = NULL, @OldBookingId INT = NULL, @OldPublicId UNIQUEIDENTIFIER = NULL, @OldStatusId INT = NULL,
            @OldPaid DECIMAL(18,4) = NULL, @OldVoucherId INT = NULL, @RevVoucherId INT = NULL, @RevVoucherCode VARCHAR(50) = NULL,
            @OldClNet DECIMAL(18,4) = NULL, @OldClVendorId INT = NULL, @OldClAccountId INT = NULL, @OldClCompanyId INT = NULL, @OldClBranchId INT = NULL;
    DECLARE @CustomerLedgerText NVARCHAR(500) = NULL, @ReversalText NVARCHAR(500) = NULL;
    BEGIN TRY
        BEGIN TRANSACTION;
        -- (a) The invoice to replace: locked, same booking, not cancelled and unpaid.
        IF @ReplaceInvoiceId IS NOT NULL
        BEGIN
            SELECT @OldNumber = InvoiceNumber, @OldBookingId = BookingId, @OldPublicId = PublicId, @OldStatusId = StatusId,
                   @OldPaid = PaidTotal, @OldVoucherId = VoucherId
              FROM dbo.WN_Invoices WITH (UPDLOCK, HOLDLOCK)
             WHERE Id = @ReplaceInvoiceId;
            IF @OldNumber IS NULL
                BEGIN SET @Msg = N'The invoice to replace was not found.'; THROW 51000, @Msg, 1; END
            IF @OldBookingId IS NULL OR @OldBookingId <> @BookingId
                BEGIN SET @Msg = CONCAT(N'Invoice ', @OldNumber, N' does not belong to this booking, so it cannot be replaced.'); THROW 51000, @Msg, 1; END
            IF @OldStatusId IN (5, @CancelledId)
                BEGIN SET @Msg = CONCAT(N'Invoice ', @OldNumber, N' is already cancelled.'); THROW 51000, @Msg, 1; END
            IF ISNULL(@OldPaid, 0) > 0
               OR @OldStatusId NOT IN (1, 4, @UnPaidId, @OverdueId)
               OR EXISTS (SELECT 1 FROM dbo.WN_FeeReceipts fr WITH (NOLOCK) WHERE fr.InvoiceIdGUID = @OldPublicId AND fr.Status = 1)
                BEGIN SET @Msg = CONCAT(N'Invoice ', @OldNumber, N' is not unpaid (it has a payment or a fee receipt), so it cannot be replaced.'); THROW 51000, @Msg, 1; END
        END
        -- (b) The invoice: same number rule as WN_Invoices_Insert.
        DECLARE @NextId INT;
        SELECT @NextId = ISNULL(MAX(Id), 0) + 1 FROM dbo.WN_Invoices WITH (UPDLOCK, HOLDLOCK);
        SET @InvoiceNumber = 'INV-' + CAST(YEAR(CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2(0))) AS VARCHAR(4)) + '-' + RIGHT('00000' + CAST(@NextId AS VARCHAR(10)), 5);
        DECLARE @Notes NVARCHAR(MAX) = CONCAT(N'Custom invoice: ', @CustomReason,
            CASE WHEN @TaxPercent IS NOT NULL THEN CONCAT(N' | Tax rate: ', CONVERT(NVARCHAR(20), CAST(@TaxPercent AS DECIMAL(9,2))), N' percent') ELSE N'' END,
            CASE WHEN @ReplaceInvoiceId IS NOT NULL THEN CONCAT(N' | Replaces ', @OldNumber) ELSE N'' END);
        INSERT INTO dbo.WN_Invoices (
            PublicId, InvoiceNumber, UserId, BookingId, IssuedOn, DueOn,
            SubTotal, DiscountTotal, TaxTotal, GrandTotal, PaidTotal, CurrencyCode, StatusId, Notes, CreatedOn, CreatedById,
            InvoiceTypeId, SecurityDepositAmount, AccountsCoaId, BillingPeriodStart, BillingPeriodEnd,
            AccountReceivableId, RentAccountId, ServicesIncomeId, SalesTaxId, SecurityReceivedId,
            RoomRentExclTax, ServiceCharges, TaxOnServiceCharges, WHTRate, WHTAmount, VoucherId, IsCustom, CustomReason
        )
        VALUES (
            @PublicId, @InvoiceNumber, @UserId, @BookingId, @IssuedOn, @DueOn,
            @RoomRentExclTax + @ServiceCharges, 0, @TaxOnServiceCharges, @GrandTotal, 0, N'PKR', @UnPaidId, @Notes, SYSUTCDATETIME(), @CreatedById,
            7, @SecurityDepositAmount, @RentAcc, @PeriodFrom, @PeriodTo,
            @ArAcc, @RentAcc, @ServAcc, @TaxAcc, @SecAcc,
            @RoomRentExclTax, @ServiceCharges, @TaxOnServiceCharges, 0, 0, NULL, 1, @CustomReason
        );
        SET @InvoiceId = SCOPE_IDENTITY();

        DECLARE @AutoApprove NVARCHAR(50) = (SELECT TOP 1 SettingValue FROM dbo.WN_BillingSettings WITH (NOLOCK) WHERE SettingKey = 'CustomInvoiceAutoApprove');
        DECLARE @ApprovalStatus NVARCHAR(50) = CASE WHEN LOWER(ISNULL(@AutoApprove, 'false')) = 'true' THEN 'Approved' ELSE 'PendingApproval' END;

        UPDATE dbo.WN_Invoices
        SET ApprovalStatus = @ApprovalStatus
        WHERE Id = @InvoiceId;
        -- Lines for the invoice PDF / statement (the tax sits on the service line, else on the rent line).
        IF @RoomRentExclTax > 0
            INSERT INTO dbo.WN_InvoiceLines (InvoiceId, ChargeTypeId, Description, Quantity, UnitPrice, DiscountAmount, TaxRate, AccountId, SortOrder)
            VALUES (@InvoiceId, 1, N'Rent', 1, @RoomRentExclTax, 0,
                    CASE WHEN @ServiceCharges = 0 AND @TaxOnServiceCharges > 0 THEN ROUND(@TaxOnServiceCharges / @RoomRentExclTax, 4) ELSE 0 END,
                    @RentAcc, 1);
        IF @ServiceCharges > 0
            INSERT INTO dbo.WN_InvoiceLines (InvoiceId, ChargeTypeId, Description, Quantity, UnitPrice, DiscountAmount, TaxRate, AccountId, SortOrder)
            VALUES (@InvoiceId, 4, N'Service charges', 1, @ServiceCharges, 0,
                    CASE WHEN @TaxOnServiceCharges > 0 THEN ROUND(@TaxOnServiceCharges / @ServiceCharges, 4) ELSE 0 END,
                    @ServAcc, 2);
        IF @SecurityDepositAmount > 0
            INSERT INTO dbo.WN_InvoiceLines (InvoiceId, ChargeTypeId, Description, Quantity, UnitPrice, DiscountAmount, TaxRate, AccountId, SortOrder)
            VALUES (@InvoiceId, 2, N'Security Deposit (Refundable)', 1, @SecurityDepositAmount, 0, 0, @SecAcc, 3);
        -- (c) Customer / vendor record, then its id (same lookups as WN_Invoices_Insert).
        IF OBJECT_ID('dbo.WN_CustomersVendors_SyncOnInvoice', 'P') IS NOT NULL
            EXEC dbo.WN_CustomersVendors_SyncOnInvoice
                @CustomerId  = NULL,
                @UserId      = @UserId,
                @BookingId   = @BookingId,
                @CreatedById = @CreatedById;
        IF @BookingId IS NOT NULL
            SELECT TOP 1 @CustomerCode = NULLIF(LTRIM(RTRIM(CustomerCode)), N'') FROM dbo.WN_Bookings WITH (NOLOCK) WHERE Id = @BookingId;
        IF @CustomerCode IS NULL
            SELECT TOP 1 @CustomerCode = NULLIF(LTRIM(RTRIM(Code)), N'') FROM dbo.WN_Customers WITH (NOLOCK)
             WHERE UserId = @UserId AND NULLIF(LTRIM(RTRIM(Code)), N'') IS NOT NULL ORDER BY Id;
        IF @CustomerCode IS NOT NULL
            SELECT TOP 1 @CustomerVendorId = Id FROM dbo.CustomersVendors WITH (NOLOCK) WHERE Code = @CustomerCode ORDER BY Id DESC;
        IF @CustomerVendorId IS NULL
            SELECT TOP 1 @CustomerVendorId = cv.Id
              FROM dbo.CustomersVendors cv WITH (NOLOCK)
              JOIN dbo.WN_Users u WITH (NOLOCK) ON cv.Email = u.Email
             WHERE u.Id = @UserId AND cv.Email IS NOT NULL AND cv.Email <> ''
             ORDER BY cv.Id DESC;
        IF @CustomerVendorId IS NULL
            BEGIN SET @Msg = N'This customer has no customer account in the accounts system (it needs an e-mail address or a customer code).'; THROW 51000, @Msg, 1; END
        -- (d) The JV: dbo.Vouchers_Insert as WN_Invoices_Insert calls it, then one dbo.Ledgers_Insert per posted line.
        DECLARE @VoucherTable TABLE (Id INT, Code VARCHAR(50));
        DECLARE @VoucherShortGUID VARCHAR(50) = CONVERT(VARCHAR(50), NEWID());
        INSERT INTO @VoucherTable (Id, Code)
        EXEC dbo.Vouchers_Insert
            @TypeId              = 1,
            @TransDate           = @VoucherDate,
            @TotalAmount         = @TotalDebit,
            @CompanyId           = @CompanyId,
            @CreatedById         = @CreatedById,
            @ShortGUID           = @VoucherShortGUID,
            @RefNo               = @InvoiceNumber,
            @RefId               = @InvoiceId,
            @BranchId            = @BranchId,
            @FundMangId          = NULL,
            @CreatedByBranchId   = @BranchId,
            @CreatedByCompanyId  = @CompanyId;
        SELECT TOP 1 @VoucherId = Id, @VoucherCode = Code FROM @VoucherTable;
        IF @VoucherId IS NULL OR @VoucherId <= 0
            BEGIN SET @Msg = CONCAT(N'The voucher could not be created for invoice ', @InvoiceNumber, N'.'); THROW 51000, @Msg, 1; END
        UPDATE dbo.Vouchers SET Status = 1 WHERE Id = @VoucherId;
        UPDATE dbo.WN_Invoices SET VoucherId = @VoucherId WHERE Id = @InvoiceId;
        DECLARE @Seq INT = (SELECT MIN(Seq) FROM @L);
        DECLARE @LAccountId INT, @LDebit DECIMAL(18,4), @LCredit DECIMAL(18,4), @LText VARCHAR(500);
        WHILE @Seq IS NOT NULL
        BEGIN
            SELECT @LAccountId = AccountId, @LDebit = Debit, @LCredit = Credit,
                   @LText = LEFT(COALESCE(Narration, @VoucherDescription, CONCAT(N'Custom invoice ', @InvoiceNumber)), 500)
              FROM @L WHERE Seq = @Seq;
            EXEC dbo.Ledgers_Insert
                @VoucherId                   = @VoucherId,
                @AccountId                   = @LAccountId,
                @Description                 = @LText,
                @ProjectId                   = NULL,
                @Debit                       = @LDebit,
                @Credit                      = @LCredit,
                @VehicleId                   = NULL,
                @ConstructionProjectActiveId = NULL;
            SET @Seq = (SELECT MIN(Seq) FROM @L WHERE Seq > @Seq);
        END
        -- (e) Customer ledger debit, on the receivable account of the posted lines.
        SET @CustomerLedgerText = LEFT(COALESCE(@CustomerLedgerNarration, CONCAT(N'Accounts Receivable - ', @InvoiceNumber)), 500);
        DECLARE @CustLedgerShortGUID VARCHAR(50) = CONVERT(VARCHAR(50), NEWID());
        EXEC dbo.CustomerLedger_Insert
            @Description         = @CustomerLedgerText,
            @Debit               = @CustomerLedgerDebit,
            @Credit              = 0.0000,
            @LedgerDate          = @VoucherDate,
            @CustomerVendorId    = @CustomerVendorId,
            @AccountId           = @ArAcc,
            @Status              = 1,
            @CreatedById         = @CreatedById,
            @ShortGUID           = @CustLedgerShortGUID,
            @CompanyId           = @CompanyId,
            @RefNo               = @InvoiceNumber,
            @RefId               = @InvoiceId,
            @TypeId              = 1,
            @CreatedByBranchId   = @BranchId,
            @CreatedByCompanyId  = @CompanyId,
            @BranchId            = @BranchId;
        UPDATE dbo.CustomerLedger SET Status = 1 WHERE ShortGUID = @CustLedgerShortGUID;
        -- (f) Replace: cancel the old invoice (row kept) and reverse its JV and customer ledger debit.
        IF @ReplaceInvoiceId IS NOT NULL
        BEGIN
            UPDATE dbo.WN_Invoices
               SET StatusId = @CancelledId,
                   Notes = CONCAT(Notes, CASE WHEN NULLIF(Notes, N'') IS NULL THEN N'' ELSE N' | ' END, N'Cancelled: replaced by custom invoice ', @InvoiceNumber)
             WHERE Id = @ReplaceInvoiceId;
            SET @ReversalText = CONCAT(N'Reversal of ', @OldNumber, N', replaced by ', @InvoiceNumber);
            -- The old voucher: WN_Invoices.VoucherId, else the invoice JV by RefNo / RefId (older invoices have no VoucherId).
            IF @OldVoucherId IS NULL
                SELECT TOP 1 @OldVoucherId = v.Id FROM dbo.Vouchers v WITH (NOLOCK)
                 WHERE v.RefId = @ReplaceInvoiceId AND v.RefNo = @OldNumber AND v.TypeId IN (1, 2)
                 ORDER BY v.Id;
            IF @OldVoucherId IS NOT NULL AND EXISTS (SELECT 1 FROM dbo.Ledgers WITH (NOLOCK) WHERE VoucherId = @OldVoucherId)
            BEGIN
                DECLARE @RevTotal DECIMAL(18,4), @RevCompanyId INT = NULL, @RevBranchId INT = NULL;
                SELECT @RevTotal = SUM(ISNULL(Debit, 0)) FROM dbo.Ledgers WITH (NOLOCK) WHERE VoucherId = @OldVoucherId;
                SELECT @RevCompanyId = CompanyId, @RevBranchId = BranchId FROM dbo.Vouchers WITH (NOLOCK) WHERE Id = @OldVoucherId;
                SET @RevCompanyId = ISNULL(@RevCompanyId, @CompanyId);
                SET @RevBranchId = ISNULL(@RevBranchId, @BranchId);
                DELETE FROM @VoucherTable;
                DECLARE @RevShortGUID VARCHAR(50) = CONVERT(VARCHAR(50), NEWID());
                INSERT INTO @VoucherTable (Id, Code)
                EXEC dbo.Vouchers_Insert
                    @TypeId              = 1,
                    @TransDate           = @VoucherDate,
                    @TotalAmount         = @RevTotal,
                    @CompanyId           = @RevCompanyId,
                    @CreatedById         = @CreatedById,
                    @ShortGUID           = @RevShortGUID,
                    @RefNo               = @OldNumber,
                    @RefId               = @ReplaceInvoiceId,
                    @BranchId            = @RevBranchId,
                    @FundMangId          = NULL,
                    @CreatedByBranchId   = @RevBranchId,
                    @CreatedByCompanyId  = @RevCompanyId;
                SELECT TOP 1 @RevVoucherId = Id, @RevVoucherCode = Code FROM @VoucherTable;
                IF @RevVoucherId IS NULL OR @RevVoucherId <= 0
                    BEGIN SET @Msg = CONCAT(N'The reversal voucher could not be created for invoice ', @OldNumber, N'.'); THROW 51000, @Msg, 1; END
                UPDATE dbo.Vouchers SET Status = 1 WHERE Id = @RevVoucherId;
                DECLARE @OldLedgerId INT = (SELECT MIN(Id) FROM dbo.Ledgers WITH (NOLOCK) WHERE VoucherId = @OldVoucherId);
                DECLARE @OAccountId INT, @OProjectId INT, @ODebit DECIMAL(18,4), @OCredit DECIMAL(18,4), @OVehicleId INT, @OConstructionId INT, @OText VARCHAR(500);
                WHILE @OldLedgerId IS NOT NULL
                BEGIN
                    SELECT @OAccountId = AccountId, @OProjectId = ProjectId, @ODebit = ISNULL(Debit, 0), @OCredit = ISNULL(Credit, 0),
                           @OVehicleId = VehicleId, @OConstructionId = ConstructionProjectActiveId,
                           @OText = LEFT(CONCAT(@ReversalText, N' - ', Description), 500)
                      FROM dbo.Ledgers WITH (NOLOCK) WHERE Id = @OldLedgerId;
                    EXEC dbo.Ledgers_Insert
                        @VoucherId                   = @RevVoucherId,
                        @AccountId                   = @OAccountId,
                        @Description                 = @OText,
                        @ProjectId                   = @OProjectId,
                        @Debit                       = @OCredit,
                        @Credit                      = @ODebit,
                        @VehicleId                   = @OVehicleId,
                        @ConstructionProjectActiveId = @OConstructionId;
                    SET @OldLedgerId = (SELECT MIN(Id) FROM dbo.Ledgers WITH (NOLOCK) WHERE VoucherId = @OldVoucherId AND Id > @OldLedgerId);
                END
            END
            -- Customer ledger: credit what the old invoice still has as debit (its rows by RefId / RefNo).
            SELECT @OldClNet = SUM(ISNULL(Debit, 0)) - SUM(ISNULL(Credit, 0))
              FROM dbo.CustomerLedger WITH (NOLOCK)
             WHERE RefId = @ReplaceInvoiceId AND RefNo = @OldNumber;
            SELECT TOP 1 @OldClVendorId = CustomerVendorId, @OldClAccountId = AccountId, @OldClCompanyId = CompanyId, @OldClBranchId = BranchId
              FROM dbo.CustomerLedger WITH (NOLOCK)
             WHERE RefId = @ReplaceInvoiceId AND RefNo = @OldNumber AND ISNULL(Debit, 0) > 0
             ORDER BY Id;
            IF @OldClNet > 0
            BEGIN
                DECLARE @RevClShortGUID VARCHAR(50) = CONVERT(VARCHAR(50), NEWID());
                SET @OldClCompanyId = ISNULL(@OldClCompanyId, @CompanyId);
                SET @OldClBranchId = ISNULL(@OldClBranchId, @BranchId);
                SET @OldClVendorId = ISNULL(@OldClVendorId, @CustomerVendorId);
                EXEC dbo.CustomerLedger_Insert
                    @Description         = @ReversalText,
                    @Debit               = 0.0000,
                    @Credit              = @OldClNet,
                    @LedgerDate          = @VoucherDate,
                    @CustomerVendorId    = @OldClVendorId,
                    @AccountId           = @OldClAccountId,
                    @Status              = 1,
                    @CreatedById         = @CreatedById,
                    @ShortGUID           = @RevClShortGUID,
                    @CompanyId           = @OldClCompanyId,
                    @RefNo               = @OldNumber,
                    @RefId               = @ReplaceInvoiceId,
                    @TypeId              = 1,
                    @CreatedByBranchId   = @OldClBranchId,
                    @CreatedByCompanyId  = @OldClCompanyId,
                    @BranchId            = @OldClBranchId;
                UPDATE dbo.CustomerLedger SET Status = 1 WHERE ShortGUID = @RevClShortGUID;
            END
        END
        -- (g) Custom invoice details (replaced invoice, reversal voucher, voucher description, tax rate, chosen location).
        INSERT INTO dbo.WN_CustomInvoices (InvoiceId, LocationId, ReplacedInvoiceId, ReversalVoucherId, VoucherDescription, TaxPercent, CreatedOn)
        VALUES (@InvoiceId, @LocationId, @ReplaceInvoiceId, @RevVoucherId, @VoucherDescription, @TaxPercent, SYSUTCDATETIME());
        -- (h) One audit row with everything that was posted (the table triggers also record each row change).
        DECLARE @AuditUserId INT = COALESCE(CAST(SESSION_CONTEXT(N'AppUserId') AS INT), @CreatedById, -1);
        DECLARE @AuditEmail NVARCHAR(256) = CAST(SESSION_CONTEXT(N'AppUserEmail') AS NVARCHAR(256));
        DECLARE @AuditSource NVARCHAR(50) = CAST(SESSION_CONTEXT(N'SourceApp') AS NVARCHAR(50));
        DECLARE @AuditJson NVARCHAR(MAX) = (
            SELECT
                JSON_QUERY((SELECT i.Id AS invoiceId, i.InvoiceNumber AS invoiceNumber, i.PublicId AS publicId, i.UserId AS userId,
                                   i.BookingId AS bookingId, @LocationId AS locationId, i.IssuedOn AS issuedOn, i.DueOn AS dueOn,
                                   i.BillingPeriodStart AS periodFrom, i.BillingPeriodEnd AS periodTo, i.RoomRentExclTax AS rent,
                                   i.ServiceCharges AS serviceCharges, i.TaxOnServiceCharges AS tax, @TaxPercent AS taxPercent,
                                   i.SecurityDepositAmount AS securityDeposit, i.GrandTotal AS grandTotal, i.StatusId AS statusId,
                                   i.InvoiceTypeId AS invoiceTypeId, i.IsCustom AS isCustom, i.CustomReason AS reason, i.CreatedById AS createdById,
                                   i.AccountReceivableId AS accountReceivableId, i.RentAccountId AS rentAccountId, i.ServicesIncomeId AS servicesIncomeId,
                                   i.SalesTaxId AS salesTaxId, i.SecurityReceivedId AS securityReceivedId
                              FROM dbo.WN_Invoices i WITH (NOLOCK) WHERE i.Id = @InvoiceId
                               FOR JSON PATH, WITHOUT_ARRAY_WRAPPER)) AS invoice,
                JSON_QUERY((SELECT @VoucherId AS voucherId, @VoucherCode AS voucherCode, @VoucherDate AS [date], @VoucherDescription AS [description],
                                   @TotalDebit AS totalAmount,
                                   JSON_QUERY((SELECT l.Seq AS [lineNo], l.AccountId AS accountId, a.ShortDesc AS accountCode,
                                                      LTRIM(RTRIM(a.Description)) AS accountName, l.Debit AS debit, l.Credit AS credit, l.Narration AS narration
                                                 FROM @L l LEFT JOIN dbo.AccountsCOA a WITH (NOLOCK) ON a.Id = l.AccountId
                                                ORDER BY l.Seq
                                                  FOR JSON PATH)) AS lines
                               FOR JSON PATH, WITHOUT_ARRAY_WRAPPER)) AS voucher,
                JSON_QUERY((SELECT @CustomerVendorId AS customerVendorId, @ArAcc AS accountId, @CustomerLedgerDebit AS debit,
                                   @CustomerLedgerText AS narration, @VoucherDate AS [date]
                               FOR JSON PATH, WITHOUT_ARRAY_WRAPPER)) AS customerLedger,
                JSON_QUERY(CASE WHEN @ReplaceInvoiceId IS NULL THEN NULL ELSE
                           (SELECT @ReplaceInvoiceId AS invoiceId, @OldNumber AS invoiceNumber, @CancelledId AS statusId,
                                   @OldVoucherId AS originalVoucherId, @RevVoucherId AS reversalVoucherId, @RevVoucherCode AS reversalVoucherCode,
                                   @OldClNet AS customerLedgerCredit, @ReversalText AS narration
                               FOR JSON PATH, WITHOUT_ARRAY_WRAPPER) END) AS replaced
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER);
        INSERT INTO dbo.WN_AuditLog (
            EntityName, RecordId, Operation, OldValues, NewValues,
            ErrorMessage, ErrorSeverity, StackTrace, ChangedByUserId, ChangedByUserEmail, ChangedAt, SourceApp
        )
        VALUES (
            N'WN_CustomInvoice', CAST(@InvoiceId AS NVARCHAR(64)), 'I', NULL, @AuditJson,
            NULL, NULL, NULL, @AuditUserId, @AuditEmail, SYSUTCDATETIME(), @AuditSource
        );
        COMMIT TRANSACTION;
        SELECT @InvoiceId AS InvoiceId, @InvoiceNumber AS InvoiceNumber, @PublicId AS PublicId,
               @VoucherId AS VoucherId, @VoucherCode AS VoucherCode,
               @OldNumber AS ReplacedInvoiceNumber, @RevVoucherCode AS ReversalVoucherCode;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        -- One invoice per booking and period (unique index UQ_WN_Invoice_Booking_BillingPeriod): say which invoice has it.
        IF ERROR_NUMBER() IN (2601, 2627) AND ERROR_MESSAGE() LIKE N'%UQ[_]WN[_]Invoice[_]Booking[_]BillingPeriod%'
        BEGIN
            DECLARE @Clash NVARCHAR(50) = (SELECT TOP 1 InvoiceNumber FROM dbo.WN_Invoices WITH (NOLOCK)
                                            WHERE BookingId = @BookingId AND BillingPeriodStart = @PeriodFrom AND BillingPeriodEnd = @PeriodTo ORDER BY Id);
            SET @Msg = CONCAT(ISNULL(N'Invoice ' + @Clash, N'Another invoice'), N' already has this booking period (',
                              CONVERT(NVARCHAR(10), @PeriodFrom, 23), N' to ', CONVERT(NVARCHAR(10), @PeriodTo, 23),
                              N'), and only one invoice per booking and period is allowed. Change the period dates or leave them empty.');
            THROW 51000, @Msg, 1;
        END;
        THROW;
    END CATCH
END;
GO
