CREATE   PROCEDURE [dbo].[WN_CustomInvoice_SearchAccounts]
    @Search NVARCHAR(200) = NULL,
    @Top    INT           = 30
AS
BEGIN
    -- CI_01: GL accounts of the chart of accounts that dbo.Ledgers posts to (dbo.AccountsCOA): code = ShortDesc,
    -- name = Description; active accounts only; by name, code or exact id.
    SET NOCOUNT ON;
    IF @Top IS NULL OR @Top <= 0 OR @Top > 100 SET @Top = 30;
    SET @Search = NULLIF(LTRIM(RTRIM(@Search)), N'');
    SELECT TOP (@Top) a.Id AS AccountId, a.ShortDesc AS Code, LTRIM(RTRIM(a.Description)) AS Name
      FROM dbo.AccountsCOA a WITH (NOLOCK)
     WHERE ISNULL(a.Status, 1) = 1
       AND ISNULL(a.ActiveStatus, 1) = 1
       AND (@Search IS NULL
            OR a.Description LIKE N'%' + @Search + N'%'
            OR a.ShortDesc LIKE N'%' + @Search + N'%'
            OR CAST(a.Id AS NVARCHAR(12)) = @Search)
     ORDER BY LTRIM(RTRIM(a.Description)), a.Id;
END;
GO
