CREATE   PROCEDURE [dbo].[WN_CustomInvoice_SearchCustomers]
    @Search NVARCHAR(200) = NULL,
    @Top    INT           = 20
AS
BEGIN
    -- CI_01: active customers (dbo.WN_Customers) that have a WorkNest user (WN_Customers.UserId, else the user with the
    -- same e-mail), because an invoice needs WN_Invoices.UserId. Name: first + last name, else company, else user name.
    SET NOCOUNT ON;
    IF @Top IS NULL OR @Top <= 0 OR @Top > 50 SET @Top = 20;
    SET @Search = NULLIF(LTRIM(RTRIM(@Search)), N'');
    SELECT TOP (@Top)
           u.Id AS UserId,
           c.Id AS CustomerId,
           COALESCE(NULLIF(LTRIM(RTRIM(ISNULL(c.FirstName, N'') + N' ' + ISNULL(c.LastName, N''))), N''), NULLIF(LTRIM(RTRIM(c.Company)), N''), u.Name, u.Email) AS Name,
           COALESCE(NULLIF(c.Email, N''), u.Email) AS Email,
           c.Code,
           c.PhoneNumber AS Phone
      FROM dbo.WN_Customers c WITH (NOLOCK)
     CROSS APPLY (SELECT TOP 1 uu.Id, uu.Name, uu.Email
                    FROM dbo.WN_Users uu WITH (NOLOCK)
                   WHERE (c.UserId IS NOT NULL AND uu.Id = c.UserId)
                      OR (c.UserId IS NULL AND NULLIF(LTRIM(RTRIM(c.Email)), N'') IS NOT NULL AND uu.Email = c.Email)
                   ORDER BY CASE WHEN uu.Id = c.UserId THEN 0 ELSE 1 END, uu.Id) u
     WHERE ISNULL(c.IsActive, 1) = 1
       AND (@Search IS NULL
            OR c.FirstName LIKE N'%' + @Search + N'%'
            OR c.LastName LIKE N'%' + @Search + N'%'
            OR (ISNULL(c.FirstName, N'') + N' ' + ISNULL(c.LastName, N'')) LIKE N'%' + @Search + N'%'
            OR c.Company LIKE N'%' + @Search + N'%'
            OR c.Email LIKE N'%' + @Search + N'%'
            OR c.Code LIKE N'%' + @Search + N'%'
            OR c.PhoneNumber LIKE N'%' + @Search + N'%'
            OR u.Name LIKE N'%' + @Search + N'%'
            OR u.Email LIKE N'%' + @Search + N'%')
     ORDER BY Name, c.Id;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Dash_OverviewBookings]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_Dash_OverviewBookings]
    @LocationIds NVARCHAR(MAX) = NULL,   -- comma-separated location ids; NULL = every location (as api/dashboard/overview)
    @BizNow      DATETIME2(0) = NULL,    -- business (Pakistan) wall-clock time from the app clock
    @List        NVARCHAR(20) = N'new',  -- new: bookings made in @MonthStart | ending: live bookings ending in @MonthStart, from now on
    @MonthStart  DATE = NULL,            -- the month (first day)
    @Top         INT = 200
AS
BEGIN
    -- DASH_02. Main admin dashboard (/admin/dashboard) chart drill-down, read-only: the bookings behind one month of
    -- Occupancy and new bookings (the bars, @List = new) or of Leases expiring (@List = ending).
    -- Which bookings count is exactly api/dashboard/overview (DbRepository.GetDashboardOverviewDbAsync):
    --   on an active space (WN_Spaces.Status = 1) of the locations, not deleted;
    --   new: CreatedOn in the month and a status other than 3, 4, 6, 86 (rejected, cancelled, no show);
    --   ending: a live booking (status 1, 2, 5, 33: old pending / confirmed, Pending, Confirmed) whose end (to the
    --   second, as the overview stores it) is in the month and not before now. Amount = WN_Bookings.TotalAmount.
    -- Result sets: [0] Total and Amount of every matching booking; [1] the first @Top of them (new: newest first;
    -- ending: soonest end first).
    SET NOCOUNT ON;
    IF @Top IS NULL OR @Top < 1 SET @Top = 200;
    SET @List = LOWER(LTRIM(RTRIM(ISNULL(@List, N''))));
    DECLARE @Now DATETIME2(0) = ISNULL(@BizNow, SYSDATETIME());
    DECLARE @MonthEnd DATE = DATEADD(MONTH, 1, @MonthStart);
    DECLARE @Loc TABLE (Id INT PRIMARY KEY);
    INSERT INTO @Loc (Id) SELECT DISTINCT TRY_CAST(value AS INT) FROM STRING_SPLIT(ISNULL(@LocationIds, N''), N',') WHERE TRY_CAST(value AS INT) IS NOT NULL;
    DECLARE @Spaces TABLE (Id INT PRIMARY KEY);
    INSERT INTO @Spaces (Id)
    SELECT s.Id FROM dbo.WN_Spaces s WITH (NOLOCK)
     WHERE s.Status = 1 AND (@LocationIds IS NULL OR s.LocationId IN (SELECT l.Id FROM @Loc l));
    DECLARE @B TABLE (Id INT PRIMARY KEY, EndOn DATETIME2(0) NULL);
    INSERT INTO @B (Id, EndOn)
    SELECT b.Id, CAST(b.EndOn AS DATETIME2(0))
      FROM dbo.WN_Bookings b WITH (NOLOCK)
     WHERE ISNULL(b.IsDeleted, 0) = 0
       AND b.SpaceId IN (SELECT sp.Id FROM @Spaces sp)
       AND ((@List = N'new' AND b.CreatedOn >= @MonthStart AND b.CreatedOn < @MonthEnd AND b.BookingStatusId NOT IN (3, 4, 6, 86))
         OR (@List = N'ending' AND b.BookingStatusId IN (1, 2, 5, 33)
             AND CAST(b.EndOn AS DATETIME2(0)) >= @MonthStart AND CAST(b.EndOn AS DATETIME2(0)) < @MonthEnd
             AND CAST(b.EndOn AS DATETIME2(0)) >= @Now));
    SELECT COUNT(*) AS Total, ISNULL(SUM(b.TotalAmount), 0) AS Amount
      FROM @B x
      JOIN dbo.WN_Bookings b WITH (NOLOCK) ON b.Id = x.Id;
    SELECT TOP (@Top)
           b.Id AS BookingId,
           COALESCE(NULLIF(cust.Name, N''), NULLIF(u.Name, N''), NULLIF(u.UserName, N''), NULLIF(u.Email, N''), N'Customer') AS Customer,
           COALESCE(NULLIF(s.Name, N''), s.Code) AS Space,
           COALESCE(NULLIF(st.Description, N''), N'Other') AS SpaceType,
           s.LocationId, CAST(loc.Name AS NVARCHAR(200)) AS Location,
           b.CreatedOn, b.StartOn, b.EndOn,
           b.BookingStatusId AS StatusId,
           COALESCE(NULLIF(bs.Label, N''),
                    CASE b.BookingStatusId WHEN 1 THEN N'Pending' WHEN 2 THEN N'Confirmed' END,
                    CONCAT(N'Status ', b.BookingStatusId)) AS Status,
           ISNULL(b.TotalAmount, 0) AS TotalAmount,
           NULLIF(b.Capacity, 0) AS Seats
      FROM @B x
      JOIN dbo.WN_Bookings b WITH (NOLOCK) ON b.Id = x.Id
      JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = b.SpaceId
      LEFT JOIN dbo.WN_Locations loc WITH (NOLOCK) ON loc.Id = s.LocationId
      LEFT JOIN dbo.WN_SpaceTypes st WITH (NOLOCK) ON st.Id = s.SpaceTypeId
      LEFT JOIN dbo.WN_BookingStatuses bs WITH (NOLOCK) ON bs.Id = b.BookingStatusId
      LEFT JOIN dbo.WN_Users u WITH (NOLOCK) ON u.Id = b.UserId
     OUTER APPLY (SELECT TOP 1 COALESCE(NULLIF(cu.Company, N''), NULLIF(LTRIM(RTRIM(CONCAT(cu.FirstName, N' ', cu.LastName))), N''), cu.Email) AS Name
                    FROM dbo.WN_Customers cu WITH (NOLOCK)
                   WHERE (b.CustomerCode IS NOT NULL AND cu.Code = b.CustomerCode)
                      OR (b.UserId IS NOT NULL AND cu.UserId = b.UserId)
                      OR (u.Email IS NOT NULL AND cu.Email = u.Email)
                   ORDER BY CASE WHEN cu.Code = b.CustomerCode THEN 0 WHEN cu.UserId = b.UserId THEN 1 ELSE 2 END, cu.Id) cust
     ORDER BY CASE WHEN @List = N'ending' THEN x.EndOn END, b.CreatedOn DESC, b.Id DESC;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Dash_OverviewInvoices]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[WN_Dash_OverviewInvoices]
    @LocationIds   NVARCHAR(MAX) = NULL,   -- comma-separated location ids; NULL = every location (as api/dashboard/overview)
    @BizNow        DATETIME2(0) = NULL,    -- business (Pakistan) wall-clock time from the app clock
    @OpenStatusIds NVARCHAR(400) = NULL,   -- invoice StatusIds still owed: Unpaid / Partial / Challan Expire (legacy + OrderStatus)
    @PaidStatusIds NVARCHAR(400) = NULL,   -- Paid (legacy + OrderStatus)
    @VoidStatusIds NVARCHAR(400) = NULL,   -- Cancelled (legacy 5 + OrderStatus)
    @MonthStart    DATE = NULL,            -- Revenue and collections: the invoices issued in this month
    @Bucket        NVARCHAR(20) = NULL,    -- Receivables aging: the open invoices of this bucket (not_due, 1_30, 31_60, 61_90, 90_plus)
    @Customer      NVARCHAR(400) = NULL,   -- Top customers: this customer (the name as the chart shows it), issued from @From
    @From          DATE = NULL,            -- with @Customer: first issue date (start of the period, or of the custom range)
    @To            DATE = NULL,            -- with @Customer: last issue date (end of the custom range); NULL = no end, as the chart
    @Top           INT = 200
AS
BEGIN
    -- DASH_02. Main admin dashboard (/admin/dashboard) chart drill-down, read-only: the invoices behind one month of
    -- Revenue and collections, one bucket of Receivables aging or one bar of Top customers.
    -- Which invoices count is exactly api/dashboard/overview (DbRepository.GetDashboardOverviewDbAsync):
    --   not void (a status, not one of @VoidStatusIds); with locations, only invoices whose booking is on an active
    --   space (WN_Spaces.Status = 1) of those locations; without locations, every invoice.
    --   Invoiced = GrandTotal by IssuedOn; Paid = GrandTotal of the invoices with a paid status;
    --   owed (balance) = GrandTotal - WHTAmount - PaidTotal of the open invoices; aging by DueOn against today.
    --   Customer = the Top customers name: the customer record (booking customer code, else the user, else the e-mail):
    --   company, else first + last name, else e-mail; else the user name; else Customer #user id.
    -- Result sets: [0] Total, Amount (GrandTotal), PaidAmount (GrandTotal of the paid ones) and Balance (owed) of every
    -- matching invoice; [1] the first @Top of them (aging: oldest due date first; else newest issue date first).
    SET NOCOUNT ON;
    IF @Top IS NULL OR @Top < 1 SET @Top = 200;
    SET @Bucket = NULLIF(LOWER(LTRIM(RTRIM(@Bucket))), N'');
    DECLARE @Now DATETIME2(0) = ISNULL(@BizNow, SYSDATETIME());
    DECLARE @Today DATE = CAST(@Now AS DATE);
    DECLARE @BucketNo INT = CASE @Bucket WHEN N'not_due' THEN 0 WHEN N'1_30' THEN 1 WHEN N'31_60' THEN 2
                                         WHEN N'61_90' THEN 3 WHEN N'90_plus' THEN 4 ELSE -1 END;
    DECLARE @Open TABLE (Id INT PRIMARY KEY);
    DECLARE @Paid TABLE (Id INT PRIMARY KEY);
    DECLARE @Void TABLE (Id INT PRIMARY KEY);
    INSERT INTO @Open (Id) SELECT DISTINCT TRY_CAST(value AS INT) FROM STRING_SPLIT(ISNULL(@OpenStatusIds, N''), N',') WHERE TRY_CAST(value AS INT) IS NOT NULL;
    INSERT INTO @Paid (Id) SELECT DISTINCT TRY_CAST(value AS INT) FROM STRING_SPLIT(ISNULL(@PaidStatusIds, N''), N',') WHERE TRY_CAST(value AS INT) IS NOT NULL;
    INSERT INTO @Void (Id) SELECT DISTINCT TRY_CAST(value AS INT) FROM STRING_SPLIT(ISNULL(@VoidStatusIds, N''), N',') WHERE TRY_CAST(value AS INT) IS NOT NULL;
    DECLARE @Loc TABLE (Id INT PRIMARY KEY);
    INSERT INTO @Loc (Id) SELECT DISTINCT TRY_CAST(value AS INT) FROM STRING_SPLIT(ISNULL(@LocationIds, N''), N',') WHERE TRY_CAST(value AS INT) IS NOT NULL;
    DECLARE @Spaces TABLE (Id INT PRIMARY KEY);
    INSERT INTO @Spaces (Id)
    SELECT s.Id FROM dbo.WN_Spaces s WITH (NOLOCK)
     WHERE s.Status = 1 AND (@LocationIds IS NULL OR s.LocationId IN (SELECT l.Id FROM @Loc l));
    DECLARE @Inv TABLE (Id INT PRIMARY KEY, BookingId INT NULL, SpaceId INT NULL, IssuedOn DATE NULL, DueOn DATE NULL,
                        GrandTotal DECIMAL(18,4), PaidTotal DECIMAL(18,4), Wht DECIMAL(18,4), IsOpen BIT, IsPaid BIT, Customer NVARCHAR(400) NULL);
    INSERT INTO @Inv (Id, BookingId, SpaceId, IssuedOn, DueOn, GrandTotal, PaidTotal, Wht, IsOpen, IsPaid, Customer)
    SELECT i.Id, i.BookingId, b.SpaceId, i.IssuedOn, i.DueOn, ISNULL(i.GrandTotal, 0), ISNULL(i.PaidTotal, 0), ISNULL(i.WHTAmount, 0),
           CASE WHEN o.Id IS NULL THEN 0 ELSE 1 END, CASE WHEN p.Id IS NULL THEN 0 ELSE 1 END, cn.Customer
      FROM dbo.WN_Invoices i WITH (NOLOCK)
      LEFT JOIN dbo.WN_Bookings b WITH (NOLOCK) ON b.Id = i.BookingId
      LEFT JOIN @Open o ON o.Id = i.StatusId
      LEFT JOIN @Paid p ON p.Id = i.StatusId
      LEFT JOIN dbo.WN_Users u WITH (NOLOCK) ON u.Id = ISNULL(b.UserId, i.UserId)
     OUTER APPLY (SELECT TOP 1 COALESCE(NULLIF(cu.Company, N''), NULLIF(LTRIM(RTRIM(CONCAT(cu.FirstName, N' ', cu.LastName))), N''), cu.Email) AS Name
                    FROM dbo.WN_Customers cu WITH (NOLOCK)
                   WHERE (b.CustomerCode IS NOT NULL AND cu.Code = b.CustomerCode)
                      OR (ISNULL(b.UserId, i.UserId) IS NOT NULL AND cu.UserId = ISNULL(b.UserId, i.UserId))
                      OR (u.Email IS NOT NULL AND cu.Email = u.Email)
                   ORDER BY cu.Id) cust
     CROSS APPLY (SELECT COALESCE(NULLIF(cust.Name, N''), NULLIF(u.Name, N''), NULLIF(u.UserName, N''), CONCAT(N'Customer #', ISNULL(b.UserId, i.UserId))) AS Customer) cn
     CROSS APPLY (SELECT CASE WHEN i.DueOn IS NULL OR i.DueOn >= @Today THEN 0
                              WHEN DATEDIFF(DAY, i.DueOn, @Today) <= 30 THEN 1
                              WHEN DATEDIFF(DAY, i.DueOn, @Today) <= 60 THEN 2
                              WHEN DATEDIFF(DAY, i.DueOn, @Today) <= 90 THEN 3
                              ELSE 4 END AS AgeBucket) ab
     WHERE i.StatusId IS NOT NULL AND NOT EXISTS (SELECT 1 FROM @Void v WHERE v.Id = i.StatusId) AND ISNULL(i.StatusId, 0) <> 40
       AND (@LocationIds IS NULL OR b.SpaceId IN (SELECT sp.Id FROM @Spaces sp))
       AND (@MonthStart IS NULL OR (i.IssuedOn >= @MonthStart AND i.IssuedOn < DATEADD(MONTH, 1, @MonthStart)))
       AND (@Bucket IS NULL OR (o.Id IS NOT NULL AND ab.AgeBucket = @BucketNo))
       AND (@Customer IS NULL OR (cn.Customer = @Customer AND i.IssuedOn >= @From AND (@To IS NULL OR i.IssuedOn < DATEADD(DAY, 1, @To))));
    SELECT COUNT(*) AS Total,
           ISNULL(SUM(x.GrandTotal), 0) AS Amount,
           ISNULL(SUM(CASE WHEN x.IsPaid = 1 THEN x.GrandTotal ELSE 0 END), 0) AS PaidAmount,
           ISNULL(SUM(CASE WHEN x.IsOpen = 1 THEN x.GrandTotal - x.Wht - x.PaidTotal ELSE 0 END), 0) AS Balance
      FROM @Inv x;
    SELECT TOP (@Top)
           x.Id AS InvoiceId, i.InvoiceNumber, x.BookingId, x.Customer,
           COALESCE(NULLIF(s.Name, N''), s.Code) AS Space,
           CAST(loc.Name AS NVARCHAR(200)) AS Location,
           x.IssuedOn, x.DueOn,
           x.GrandTotal AS Total, x.PaidTotal AS Paid, x.Wht,
           CASE WHEN x.IsOpen = 1 THEN x.GrandTotal - x.Wht - x.PaidTotal ELSE 0 END AS Balance,
           x.IsOpen, x.IsPaid,
           CASE WHEN x.IsOpen = 1 AND x.DueOn < @Today THEN DATEDIFF(DAY, x.DueOn, @Today) ELSE 0 END AS DaysOverdue,
           COALESCE(
               CASE i.StatusId WHEN 1 THEN N'Unpaid' WHEN 2 THEN N'Paid' WHEN 3 THEN N'Partial' WHEN 4 THEN N'Overdue' WHEN 5 THEN N'Cancelled' END,
               (SELECT CASE LTRIM(RTRIM(os.Description)) WHEN N'Un Paid' THEN N'Unpaid' WHEN N'Challan Expire' THEN N'Overdue' ELSE LTRIM(RTRIM(os.Description)) END
                  FROM dbo.OrderStatus os WITH (NOLOCK) WHERE os.Id = i.StatusId),
               N'Unknown') AS Status
      FROM @Inv x
      JOIN dbo.WN_Invoices i WITH (NOLOCK) ON i.Id = x.Id
      LEFT JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = x.SpaceId
      LEFT JOIN dbo.WN_Locations loc WITH (NOLOCK) ON loc.Id = s.LocationId
     ORDER BY CASE WHEN @Bucket IS NOT NULL THEN x.DueOn END, x.IssuedOn DESC, x.Id DESC;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Dash_OverviewSpaces]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_Dash_OverviewSpaces]
    @LocationIds NVARCHAR(MAX) = NULL,    -- comma-separated location ids; NULL = every location (as api/dashboard/overview)
    @BizNow      DATETIME2(0) = NULL,     -- business (Pakistan) wall-clock time from the app clock
    @List        NVARCHAR(20) = N'type',  -- type: every active space of @SpaceType, in use now or not | occupied: the spaces in use in @MonthStart
    @SpaceType   NVARCHAR(MAX) = NULL,    -- with type: the space type as the chart names it (WN_SpaceTypes.Description, else Other)
    @MonthStart  DATE = NULL,             -- with occupied: the month (first day); this month = now, an earlier month = its last second
    @Top         INT = 500
AS
BEGIN
    -- DASH_02. Main admin dashboard (/admin/dashboard) chart drill-down, read-only: the spaces behind one bar of
    -- Occupancy by space type (@List = type) or one point of the Occupancy line (@List = occupied).
    -- Which spaces count is exactly api/dashboard/overview (DbRepository.GetDashboardOverviewDbAsync):
    --   active spaces (WN_Spaces.Status = 1) of the locations; in use = a live booking on it (not deleted, status 1, 2,
    --   5, 33) with StartOn <= the moment <= EndOn, both to the second as the overview stores them; the moment is now
    --   (space types, and this month on the line) or the last second of an earlier month.
    -- The booking shown for a space in use: a confirmed one before a pending one, then the earliest start (as the
    -- Occupancy card list, api/dashboard/occupied-spaces); BookingCount = live bookings on it at that moment.
    -- Result sets: [0] Total (spaces listed), Occupied (of them in use) and TotalSpaces (active spaces of the locations);
    -- [1] the first @Top spaces, by location and name.
    SET NOCOUNT ON;
    IF @Top IS NULL OR @Top < 1 SET @Top = 500;
    SET @List = LOWER(LTRIM(RTRIM(ISNULL(@List, N''))));
    DECLARE @Now DATETIME2(0) = ISNULL(@BizNow, SYSDATETIME());
    DECLARE @Today DATE = CAST(@Now AS DATE);
    DECLARE @ThisMonth DATE = DATEFROMPARTS(YEAR(@Today), MONTH(@Today), 1);
    DECLARE @At DATETIME2(0) = CASE WHEN @List = N'occupied' AND @MonthStart IS NOT NULL AND @MonthStart < @ThisMonth
                                    THEN DATEADD(SECOND, -1, CAST(DATEADD(MONTH, 1, @MonthStart) AS DATETIME2(0)))
                                    ELSE @Now END;
    DECLARE @Loc TABLE (Id INT PRIMARY KEY);
    INSERT INTO @Loc (Id) SELECT DISTINCT TRY_CAST(value AS INT) FROM STRING_SPLIT(ISNULL(@LocationIds, N''), N',') WHERE TRY_CAST(value AS INT) IS NOT NULL;
    DECLARE @Spaces TABLE (Id INT PRIMARY KEY);
    INSERT INTO @Spaces (Id)
    SELECT s.Id FROM dbo.WN_Spaces s WITH (NOLOCK)
     WHERE s.Status = 1 AND (@LocationIds IS NULL OR s.LocationId IN (SELECT l.Id FROM @Loc l));
    DECLARE @Live TABLE (Id INT PRIMARY KEY, SpaceId INT, StartOn DATETIME2(0), EndOn DATETIME2(0), StatusId INT, UserId INT NULL, CustomerCode NVARCHAR(50) NULL);
    INSERT INTO @Live (Id, SpaceId, StartOn, EndOn, StatusId, UserId, CustomerCode)
    SELECT b.Id, b.SpaceId, b.StartOn, b.EndOn, b.BookingStatusId, b.UserId, b.CustomerCode
      FROM dbo.WN_Bookings b WITH (NOLOCK)
      JOIN @Spaces sp ON sp.Id = b.SpaceId
     WHERE ISNULL(b.IsDeleted, 0) = 0 AND b.BookingStatusId IN (1, 2, 5, 33);
    DECLARE @Rows TABLE (SpaceId INT PRIMARY KEY, Occupied BIT);
    INSERT INTO @Rows (SpaceId, Occupied)
    SELECT s.Id, CASE WHEN EXISTS (SELECT 1 FROM @Live l WHERE l.SpaceId = s.Id AND l.StartOn <= @At AND l.EndOn >= @At) THEN 1 ELSE 0 END
      FROM dbo.WN_Spaces s WITH (NOLOCK)
      JOIN @Spaces sp ON sp.Id = s.Id
      LEFT JOIN dbo.WN_SpaceTypes st WITH (NOLOCK) ON st.Id = s.SpaceTypeId
     WHERE (@List = N'type' AND COALESCE(NULLIF(st.Description, N''), N'Other') = @SpaceType)
        OR (@List = N'occupied' AND EXISTS (SELECT 1 FROM @Live l WHERE l.SpaceId = s.Id AND l.StartOn <= @At AND l.EndOn >= @At));
    SELECT COUNT(*) AS Total,
           ISNULL(SUM(CAST(r.Occupied AS INT)), 0) AS Occupied,
           (SELECT COUNT(*) FROM @Spaces) AS TotalSpaces
      FROM @Rows r;
    WITH pick AS (
        SELECT l.Id, l.SpaceId, l.StartOn, l.EndOn, l.StatusId, l.UserId, l.CustomerCode,
               ROW_NUMBER() OVER (PARTITION BY l.SpaceId ORDER BY CASE WHEN l.StatusId IN (2, 33) THEN 0 ELSE 1 END, l.StartOn, l.Id) AS rn,
               COUNT(*) OVER (PARTITION BY l.SpaceId) AS BookingCount
          FROM @Live l
         WHERE l.StartOn <= @At AND l.EndOn >= @At
    )
    SELECT TOP (@Top)
           s.Id AS SpaceId, COALESCE(NULLIF(s.Name, N''), s.Code) AS Room, s.Code AS SpaceCode,
           COALESCE(NULLIF(st.Description, N''), N'Other') AS SpaceType,
           s.LocationId, CAST(loc.Name AS NVARCHAR(200)) AS Location,
           s.Capacity AS Seats, r.Occupied,
           p.Id AS BookingId, p.StartOn, p.EndOn, p.StatusId,
           CASE WHEN p.Id IS NULL THEN NULL
                ELSE COALESCE(NULLIF(bs.Label, N''), CASE p.StatusId WHEN 1 THEN N'Pending' WHEN 2 THEN N'Confirmed' END, CONCAT(N'Status ', p.StatusId)) END AS Status,
           ISNULL(p.BookingCount, 0) AS BookingCount,
           CASE WHEN p.Id IS NULL THEN NULL
                ELSE COALESCE(NULLIF(cust.Name, N''), NULLIF(u.Name, N''), NULLIF(u.UserName, N''), NULLIF(u.Email, N''), N'Customer') END AS Customer
      FROM @Rows r
      JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = r.SpaceId
      LEFT JOIN dbo.WN_Locations loc WITH (NOLOCK) ON loc.Id = s.LocationId
      LEFT JOIN dbo.WN_SpaceTypes st WITH (NOLOCK) ON st.Id = s.SpaceTypeId
      LEFT JOIN pick p ON p.SpaceId = s.Id AND p.rn = 1
      LEFT JOIN dbo.WN_BookingStatuses bs WITH (NOLOCK) ON bs.Id = p.StatusId
      LEFT JOIN dbo.WN_Users u WITH (NOLOCK) ON u.Id = p.UserId
     OUTER APPLY (SELECT TOP 1 COALESCE(NULLIF(cu.Company, N''), NULLIF(LTRIM(RTRIM(CONCAT(cu.FirstName, N' ', cu.LastName))), N''), cu.Email) AS Name
                    FROM dbo.WN_Customers cu WITH (NOLOCK)
                   WHERE p.Id IS NOT NULL
                     AND ((p.CustomerCode IS NOT NULL AND cu.Code = p.CustomerCode)
                       OR (p.UserId IS NOT NULL AND cu.UserId = p.UserId)
                       OR (u.Email IS NOT NULL AND cu.Email = u.Email))
                   ORDER BY CASE WHEN cu.Code = p.CustomerCode THEN 0 WHEN cu.UserId = p.UserId THEN 1 ELSE 2 END, cu.Id) cust
     ORDER BY CAST(loc.Name AS NVARCHAR(200)), COALESCE(NULLIF(s.Name, N''), s.Code), s.Code, s.Id;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Dash_SpaceInventory]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_Dash_SpaceInventory]
    @LocationIds  NVARCHAR(MAX) = NULL,   -- comma-separated location ids in scope; NULL = every location
    @LocationId   INT = NULL,             -- the table Location filter (within the scope); NULL = all
    @Search       NVARCHAR(200) = NULL,   -- space code or name contains
    @Customer     NVARCHAR(200) = NULL,   -- customer or company contains
    @SpaceType    NVARCHAR(200) = NULL,   -- space type name (as on the cards)
    @Status       NVARCHAR(20) = NULL,    -- Booked | Quoted | Available; NULL = all
    @PrivateOnly  BIT = 0,
    @ExpiringDays INT = 30,               -- the Expiring Soon window in days (1 to 365)
    @SortBy       NVARCHAR(20) = N'urgency', -- urgency | spaceCode | customer | bookingStart | bookingEnd | remainingTime | status
    @SortDesc     BIT = 0,
    @Page         INT = 1,
    @PageSize     INT = 10,               -- 1 to 200
    @BizNow       DATETIME2(0) = NULL     -- business (Pakistan) wall-clock time from the app clock
AS
BEGIN
    -- DASH_01. Space Operations and Inventory table of the main admin dashboard (GET api/dashboard/inventory): every
    -- space in scope with its state (dbo.WN_Dash_SpaceStates), filtered, sorted and paged here instead of in the browser.
    -- The customer of a Booked space is its booking customer; of a Quoted space its quotation customer; the quotation
    -- columns are filled for Quoted spaces only (as the page showed them). Sort urgency (the page default, ascending
    -- only): booked and expiring soon (fewest days first), booked, quoted, available, then natural code order. Ties keep
    -- the newest space first. [0] Total (all matching rows), [1] the rows of the page.
    SET NOCOUNT ON;
    IF @ExpiringDays IS NULL OR @ExpiringDays < 1 SET @ExpiringDays = 30;
    IF @ExpiringDays > 365 SET @ExpiringDays = 365;
    IF @Page IS NULL OR @Page < 1 SET @Page = 1;
    IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
    IF @PageSize > 200 SET @PageSize = 200;
    IF @LocationId <= 0 SET @LocationId = NULL;
    SET @SortBy = ISNULL(NULLIF(LTRIM(RTRIM(@SortBy)), N''), N'urgency');
    SET @SortDesc = ISNULL(@SortDesc, 0);
    SET @PrivateOnly = ISNULL(@PrivateOnly, 0);
    SET @Status = NULLIF(LTRIM(RTRIM(@Status)), N'');
    SET @SpaceType = NULLIF(LTRIM(RTRIM(@SpaceType)), N'');
    -- LIKE patterns: the typed text as it is (wildcards [ % _ taken literally).
    DECLARE @SearchLike NVARCHAR(700) = CASE WHEN NULLIF(LTRIM(RTRIM(@Search)), N'') IS NULL THEN NULL
        ELSE N'%' + REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(@Search)), N'[', N'[[]'), N'%', N'[%]'), N'_', N'[_]') + N'%' END;
    DECLARE @CustomerLike NVARCHAR(700) = CASE WHEN NULLIF(LTRIM(RTRIM(@Customer)), N'') IS NULL THEN NULL
        ELSE N'%' + REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(@Customer)), N'[', N'[[]'), N'%', N'[%]'), N'_', N'[_]') + N'%' END;
    DECLARE @Now DATETIME2(0) = ISNULL(@BizNow, CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2(0)));
    DECLARE @Skip INT = (@Page - 1) * @PageSize;
    SELECT x.SpaceId, x.SpaceCode, x.SpaceName, x.Capacity, x.SpaceTypeId, x.SpaceTypeName, x.LocationId, x.LocationName, x.Status,
           x.BookingId, x.BookingCustomer AS CustomerName, x.BookingCompany AS CompanyName, x.BookingStart, x.BookingEnd,
           x.BookingStatus, x.ShiftType, q.QuotationId, q.QuotationNumber, q.QuotationCustomer AS QuotationCustomerName,
           q.QuotationDate, q.QuotationExpiry AS QuotationExpiryDate, q.QuotationAmount, q.QuotationStatus,
           x.DaysRemaining, x.IsExpiringSoon, x.IsPrivate, x.CodePrefix, x.CodeNumber,
           CASE WHEN x.Status = N'Booked' AND x.IsExpiringSoon = 1 THEN 1 WHEN x.Status = N'Booked' THEN 2
                WHEN x.Status = N'Quoted' THEN 3 ELSE 4 END AS Urgency,
           COALESCE(x.BookingCustomer, q.QuotationCustomer) AS CustomerSort
      INTO #Rows
      FROM dbo.WN_Dash_SpaceStates(@LocationIds, @Now, @ExpiringDays) x
     CROSS APPLY (SELECT CASE WHEN x.Status = N'Quoted' THEN x.QuotationId END AS QuotationId,
                         CASE WHEN x.Status = N'Quoted' THEN x.QuotationNumber END AS QuotationNumber,
                         CASE WHEN x.Status = N'Quoted' THEN x.QuotationCustomer END AS QuotationCustomer,
                         CASE WHEN x.Status = N'Quoted' THEN x.QuotationDate END AS QuotationDate,
                         CASE WHEN x.Status = N'Quoted' THEN x.QuotationExpiry END AS QuotationExpiry,
                         CASE WHEN x.Status = N'Quoted' THEN x.QuotationAmount END AS QuotationAmount,
                         CASE WHEN x.Status = N'Quoted' THEN x.QuotationStatus END AS QuotationStatus) q
     WHERE (@LocationId IS NULL OR x.LocationId = @LocationId)
       AND (@SearchLike IS NULL OR x.SpaceCode LIKE @SearchLike OR x.SpaceName LIKE @SearchLike)
       AND (@CustomerLike IS NULL OR ISNULL(COALESCE(x.BookingCustomer, q.QuotationCustomer), N'') LIKE @CustomerLike
            OR ISNULL(x.BookingCompany, N'') LIKE @CustomerLike)
       AND (@SpaceType IS NULL OR x.SpaceTypeName = @SpaceType)
       AND (@Status IS NULL OR x.Status = @Status)
       AND (@PrivateOnly = 0 OR x.IsPrivate = 1);
    SELECT COUNT(*) AS Total FROM #Rows;
    SELECT SpaceId, SpaceCode, SpaceName, Capacity, SpaceTypeId, SpaceTypeName, LocationId, LocationName, Status,
           BookingId, CustomerName, CompanyName, BookingStart, BookingEnd, BookingStatus, ShiftType,
           QuotationId, QuotationNumber, QuotationCustomerName, QuotationDate, QuotationExpiryDate, QuotationAmount, QuotationStatus,
           DaysRemaining, IsExpiringSoon, IsPrivate
      FROM #Rows
     ORDER BY
           CASE WHEN @SortBy = N'urgency' THEN Urgency END,
           CASE WHEN @SortBy = N'urgency' AND Urgency = 1 THEN DaysRemaining END,
           CASE WHEN @SortBy = N'customer' AND @SortDesc = 0 THEN CASE WHEN CustomerSort IS NULL THEN 1 ELSE 0 END END,
           CASE WHEN @SortBy = N'customer' AND @SortDesc = 0 THEN CustomerSort END,
           CASE WHEN @SortBy = N'customer' AND @SortDesc = 1 THEN CASE WHEN CustomerSort IS NULL THEN 1 ELSE 0 END END DESC,
           CASE WHEN @SortBy = N'customer' AND @SortDesc = 1 THEN CustomerSort END DESC,
           CASE WHEN @SortBy = N'bookingStart' AND @SortDesc = 0 THEN ISNULL(BookingStart, '19000101') END,
           CASE WHEN @SortBy = N'bookingStart' AND @SortDesc = 1 THEN ISNULL(BookingStart, '19000101') END DESC,
           CASE WHEN @SortBy = N'bookingEnd' AND @SortDesc = 0 THEN ISNULL(BookingEnd, '19000101') END,
           CASE WHEN @SortBy = N'bookingEnd' AND @SortDesc = 1 THEN ISNULL(BookingEnd, '19000101') END DESC,
           CASE WHEN @SortBy = N'remainingTime' AND @SortDesc = 0 THEN DaysRemaining END,
           CASE WHEN @SortBy = N'remainingTime' AND @SortDesc = 1 THEN DaysRemaining END DESC,
           CASE WHEN @SortBy = N'status' AND @SortDesc = 0 THEN Status END,
           CASE WHEN @SortBy = N'status' AND @SortDesc = 1 THEN Status END DESC,
           CASE WHEN @SortBy IN (N'urgency', N'spaceCode') AND (@SortBy = N'urgency' OR @SortDesc = 0) THEN CodePrefix END,
           CASE WHEN @SortBy IN (N'urgency', N'spaceCode') AND (@SortBy = N'urgency' OR @SortDesc = 0) THEN CodeNumber END,
           CASE WHEN @SortBy IN (N'urgency', N'spaceCode') AND (@SortBy = N'urgency' OR @SortDesc = 0) THEN SpaceCode END,
           CASE WHEN @SortBy = N'spaceCode' AND @SortDesc = 1 THEN CodePrefix END DESC,
           CASE WHEN @SortBy = N'spaceCode' AND @SortDesc = 1 THEN CodeNumber END DESC,
           CASE WHEN @SortBy = N'spaceCode' AND @SortDesc = 1 THEN SpaceCode END DESC,
           SpaceId DESC
    OFFSET @Skip ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Dash_SpaceTypeDetails]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_Dash_SpaceTypeDetails]
    @LocationIds  NVARCHAR(MAX) = NULL,   -- comma-separated location ids; NULL = every location
    @SpaceTypeId  INT,                    -- the card
    @Tag          NVARCHAR(20) = N'booked', -- booked | vacant | quoted | expiring
    @ExpiringDays INT = 30,               -- the Expiring Soon window in days (1 to 365)
    @BizNow       DATETIME2(0) = NULL,    -- business (Pakistan) wall-clock time from the app clock
    @Page         INT = 1,
    @PageSize     INT = 25                -- 1 to 200
AS
BEGIN
    -- DASH_01. The list behind one tag of a space type card (GET api/dashboard/main-summary/details), one page at a time.
    -- booked: the booked spaces (the booking shown, its customer, and which shifts the live bookings now take).
    -- vacant: the spaces with no live booking now, with the next live booking that starts later.
    -- quoted: the spaces with an active quotation (also when booked). expiring: every live booking now that ends within
    -- @ExpiringDays days (soonest first), each with its own customer. Spaces in natural code order.
    -- [0] Total (all rows of the tag), [1] the rows of the page.
    SET NOCOUNT ON;
    IF @ExpiringDays IS NULL OR @ExpiringDays < 1 SET @ExpiringDays = 30;
    IF @ExpiringDays > 365 SET @ExpiringDays = 365;
    IF @Page IS NULL OR @Page < 1 SET @Page = 1;
    IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 25;
    IF @PageSize > 200 SET @PageSize = 200;
    SET @Tag = LOWER(LTRIM(RTRIM(ISNULL(@Tag, N'booked'))));
    DECLARE @Now DATETIME2(0) = ISNULL(@BizNow, CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2(0)));
    DECLARE @Skip INT = (@Page - 1) * @PageSize;
    IF @Tag = N'expiring'
    BEGIN
        SELECT COUNT(*) AS Total
          FROM dbo.WN_Dash_SpaceStates(@LocationIds, @Now, @ExpiringDays) x
          JOIN dbo.WN_Dash_LiveBookings() lb ON lb.SpaceId = x.SpaceId
         WHERE x.SpaceTypeId = @SpaceTypeId
           AND lb.EndOn > @Now AND lb.EndOn <= DATEADD(DAY, @ExpiringDays, @Now)
           AND (lb.StartOn IS NULL OR lb.StartOn <= @Now);
        SELECT x.SpaceId, x.SpaceCode, x.SpaceName, x.Capacity, x.LocationName,
               lb.BookingId, lb.StartOn AS BookingStart, lb.EndOn AS BookingEnd, lb.StatusLabel AS BookingStatus,
               lb.Customer AS CustomerName, lb.Company AS CompanyName,
               CAST(CEILING(DATEDIFF_BIG(SECOND, @Now, lb.EndOn) / 86400.0) AS INT) AS DaysRemaining
          FROM dbo.WN_Dash_SpaceStates(@LocationIds, @Now, @ExpiringDays) x
          JOIN dbo.WN_Dash_LiveBookings() lb ON lb.SpaceId = x.SpaceId
         WHERE x.SpaceTypeId = @SpaceTypeId
           AND lb.EndOn > @Now AND lb.EndOn <= DATEADD(DAY, @ExpiringDays, @Now)
           AND (lb.StartOn IS NULL OR lb.StartOn <= @Now)
         ORDER BY lb.EndOn, x.CodePrefix, x.CodeNumber, x.SpaceCode, lb.BookingId
        OFFSET @Skip ROWS FETCH NEXT @PageSize ROWS ONLY;
        RETURN;
    END;
    SELECT COUNT(*) AS Total
      FROM dbo.WN_Dash_SpaceStates(@LocationIds, @Now, @ExpiringDays) x
     WHERE x.SpaceTypeId = @SpaceTypeId
       AND (   (@Tag = N'booked' AND x.Status = N'Booked')
            OR (@Tag = N'vacant' AND x.Status <> N'Booked')
            OR (@Tag = N'quoted' AND x.QuotationId IS NOT NULL));
    SELECT x.SpaceId, x.SpaceCode, x.SpaceName, x.Capacity, x.LocationName, x.Status,
           x.BookingId, x.BookingStart, x.BookingEnd, x.BookingStatus,
           x.BookingCustomer AS CustomerName, x.BookingCompany AS CompanyName,
           x.Has247, x.HasMorning, x.HasEvening,
           x.NextBookingStart, x.NextBookingCustomer,
           x.QuotationId, x.QuotationNumber, x.QuotationStatus, x.QuotationDate, x.QuotationExpiry, x.QuotationAmount,
           x.QuotationCustomer, x.QuotationCompany,
           CAST(CASE WHEN x.Status = N'Booked' THEN 1 ELSE 0 END AS BIT) AS IsBooked
      FROM dbo.WN_Dash_SpaceStates(@LocationIds, @Now, @ExpiringDays) x
     WHERE x.SpaceTypeId = @SpaceTypeId
       AND (   (@Tag = N'booked' AND x.Status = N'Booked')
            OR (@Tag = N'vacant' AND x.Status <> N'Booked')
            OR (@Tag = N'quoted' AND x.QuotationId IS NOT NULL))
     ORDER BY x.CodePrefix, x.CodeNumber, x.SpaceCode, x.SpaceId
    OFFSET @Skip ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Dash_SpaceTypeSummary]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_Dash_SpaceTypeSummary]
    @LocationIds  NVARCHAR(MAX) = NULL,   -- comma-separated location ids; NULL = every location
    @ExpiringDays INT = 30,               -- the Expiring Soon window in days (1 to 365)
    @BizNow       DATETIME2(0) = NULL     -- business (Pakistan) wall-clock time from the app clock
AS
BEGIN
    -- DASH_01. Main admin dashboard, Space Types Capacity and Occupancy cards (GET api/dashboard/main-summary).
    -- One row per space type: the active types of the locations in scope (a type without a location counts everywhere)
    -- and every type with a space there; a type named Other only when it has spaces. Counts from dbo.WN_Dash_SpaceStates:
    -- TotalSpaces, BookedCount (a live booking now), VacantCount (the rest), QuotedCount (an active quotation, booked or
    -- not), ExpiringCount (live bookings now that end within @ExpiringDays days). Biggest types first.
    SET NOCOUNT ON;
    IF @ExpiringDays IS NULL OR @ExpiringDays < 1 SET @ExpiringDays = 30;
    IF @ExpiringDays > 365 SET @ExpiringDays = 365;
    DECLARE @Now DATETIME2(0) = ISNULL(@BizNow, CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2(0)));
    ;WITH agg AS (
        SELECT x.SpaceTypeId, COUNT(*) AS TotalSpaces,
               SUM(CASE WHEN x.Status = N'Booked' THEN 1 ELSE 0 END) AS BookedCount,
               SUM(CASE WHEN x.Status = N'Booked' THEN 0 ELSE 1 END) AS VacantCount,
               SUM(CASE WHEN x.QuotationId IS NOT NULL THEN 1 ELSE 0 END) AS QuotedCount,
               SUM(x.ExpiringBookings) AS ExpiringCount
          FROM dbo.WN_Dash_SpaceStates(@LocationIds, @Now, @ExpiringDays) x
         GROUP BY x.SpaceTypeId
    )
    SELECT t.Id AS SpaceTypeId, tn.SpaceType, t.LocationId, l.Name AS LocationName,
           ISNULL(a.TotalSpaces, 0) AS TotalSpaces, ISNULL(a.BookedCount, 0) AS BookedCount,
           ISNULL(a.VacantCount, 0) AS VacantCount, ISNULL(a.QuotedCount, 0) AS QuotedCount,
           ISNULL(a.ExpiringCount, 0) AS ExpiringCount
      FROM dbo.WN_SpaceTypes t WITH (NOLOCK)
      LEFT JOIN agg a ON a.SpaceTypeId = t.Id
      LEFT JOIN dbo.WN_Locations l WITH (NOLOCK) ON l.Id = t.LocationId
      LEFT JOIN dbo.WN_SpaceCategories sc WITH (NOLOCK) ON sc.Id = t.CategoryId
     CROSS APPLY (SELECT COALESCE(NULLIF(t.Name, N''), NULLIF(t.Description, N''), N'Other') AS SpaceType) tn
     WHERE a.SpaceTypeId IS NOT NULL
        OR (t.IsActive = 1 AND tn.SpaceType <> N'Other'
            AND (@LocationIds IS NULL OR t.LocationId IS NULL
                 OR t.LocationId IN (SELECT TRY_CAST(LTRIM(RTRIM(v.value)) AS INT) FROM STRING_SPLIT(@LocationIds, N',') v)))
     ORDER BY ISNULL(a.TotalSpaces, 0) DESC, l.Name, sc.Label, tn.SpaceType, t.Id;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Dashboard_GetSummary]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[WN_Dashboard_GetSummary]
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @TotalSpaces      INT;
    DECLARE @OccupiedNow      INT;
    DECLARE @AvailableNow     INT;
    DECLARE @TotalUsers       INT;
    DECLARE @ActiveMembers    INT;
    DECLARE @RevenueThisMonth DECIMAL(18,4);
    DECLARE @BookingsToday    INT;

    SELECT @TotalSpaces = COUNT(*) FROM dbo.WN_Spaces WHERE IsActive = 1;

    SELECT @OccupiedNow = COUNT(DISTINCT SpaceId)
    FROM dbo.WN_Bookings
    WHERE IsDeleted       = 0
      AND BookingStatusId IN (1, 2, 5, 33)
      AND StartOn         <= SYSUTCDATETIME()
      AND EndOn           >= SYSUTCDATETIME();

    SET @AvailableNow = @TotalSpaces - ISNULL(@OccupiedNow, 0);

    SELECT @TotalUsers = COUNT(*) FROM dbo.WN_Users WHERE IsActive = 1;

    -- Active members: check new table first, fall back to old
    IF EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('dbo.WN_Memberships') AND name = 'StatusId')
    BEGIN
        DECLARE @sqlM NVARCHAR(MAX) = N'SELECT @cnt = COUNT(*) FROM dbo.WN_Memberships WHERE StatusId = 1 AND StartOn <= SYSUTCDATETIME() AND (EndOn IS NULL OR EndOn >= SYSUTCDATETIME());';
        EXEC sp_executesql @sqlM, N'@cnt INT OUTPUT', @ActiveMembers OUTPUT;
    END
    ELSE
        SELECT @ActiveMembers = COUNT(*)
        FROM dbo.WN_MemberShips_Temp
        WHERE Status   = 'Active'
          AND IsActive = 1;

    SELECT @RevenueThisMonth = ISNULL(SUM(Amount), 0)
    FROM dbo.WN_Payments
    WHERE StatusId    = 2
      AND YEAR(PaidOn)  = YEAR(SYSUTCDATETIME())
      AND MONTH(PaidOn) = MONTH(SYSUTCDATETIME());

    SELECT @BookingsToday = COUNT(*)
    FROM dbo.WN_Bookings
    WHERE IsDeleted = 0
      AND CAST(CreatedOn AS DATE) = CAST(SYSUTCDATETIME() AS DATE);

    -- Summary row
    SELECT
        @TotalSpaces      AS TotalSpaces,
        @OccupiedNow      AS OccupiedNow,
        @AvailableNow     AS AvailableNow,
        @TotalUsers       AS TotalUsers,
        @ActiveMembers    AS ActiveMembers,
        @RevenueThisMonth AS RevenueThisMonth,
        @BookingsToday    AS BookingsToday;

    -- Booking counts by status
    SELECT
        bs.Code  AS StatusCode,
        bs.Label AS StatusLabel,
        COUNT(b.Id) AS BookingCount
    FROM dbo.WN_BookingStatuses bs
    LEFT JOIN dbo.WN_Bookings   b ON b.BookingStatusId = bs.Id AND b.IsDeleted = 0
    GROUP BY bs.Id, bs.Code, bs.Label
    ORDER BY bs.Id;

    -- Recent 5 bookings
    SELECT TOP 5
        v.BookingId, v.BookingPublicId,
        v.UserName, v.UserEmail,
        v.SpaceCode, v.SpaceName,
        v.StartOn, v.EndOn,
        v.BookingStatusCode, v.BookingStatusLabel,
        v.RoomPrice, v.BookedOn
    FROM dbo.WN_vw_BookingSummary v
    ORDER BY v.BookedOn DESC;
END
GO
