/****** Object:  StoredProcedure [dbo].[WN_DeviceTokens_Upsert]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_DeviceTokens_Upsert]
    @UserId   INT,
    @Token    NVARCHAR(500),
    @Platform NVARCHAR(10)
AS
BEGIN
    SET NOCOUNT ON;
    -- QA_01: the same token registered earlier by another user (e.g. a sign-out that could not unregister it) stops
    -- receiving that user's notifications: one phone, one account.
    UPDATE dbo.WN_DeviceToken
    SET IsActive = 0
    WHERE Token = @Token AND UserId <> @UserId AND IsActive = 1;
    IF EXISTS (SELECT 1 FROM dbo.WN_DeviceToken WHERE UserId = @UserId AND Token = @Token)
    BEGIN
        UPDATE dbo.WN_DeviceToken
        SET Platform = @Platform,
            IsActive = 1
        WHERE UserId = @UserId AND Token = @Token;
    END
    ELSE
    BEGIN
        INSERT INTO dbo.WN_DeviceToken (UserId, Token, Platform, CreatedAt, IsActive)
        VALUES (@UserId, @Token, @Platform, SYSUTCDATETIME(), 1);
    END
    SELECT 1 AS Success;
END
GO
