CREATE   PROCEDURE [dbo].[WN_EmailOtps_GetActive]
    @Email   NVARCHAR(256),
    @Purpose NVARCHAR(60)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT TOP 1 Id, Email, Purpose, CodeHash, CreatedOn, ExpiresOn, IdentityToken
    FROM dbo.WN_EmailOtps WITH (NOLOCK)
    WHERE Email     = @Email
      AND Purpose   = @Purpose
      AND UsedOn    IS NULL
      AND ExpiresOn > SYSUTCDATETIME()
    ORDER BY CreatedOn DESC;
END
