    @PublicId UNIQUEIDENTIFIER = NULL,
    @STInvoiceNumber NVARCHAR(50),
    @RoomRentAmount DECIMAL(18,2),
    @ServiceChargeAmount DECIMAL(18,2),
    @STTaxRate DECIMAL(5,2),
