/****** Object:  StoredProcedure [dbo].[WN_GetAvailableSpaces]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[WN_GetAvailableSpaces] 
    @SpaceType NVARCHAR(100), 
    @StartDateTime DATETIME, 
    @EndDateTime DATETIME 
AS 
BEGIN
    SET NOCOUNT ON;
    DECLARE @STId INT;
    SELECT @STId = Id FROM dbo.WN_SpaceTypes WITH(NOLOCK) WHERE (Name = @SpaceType OR Description = @SpaceType) AND (IsActive = 1 OR Status = 1);
    IF @STId IS NULL BEGIN RAISERROR('Invalid space type', 16, 1); RETURN; END

    SELECT s.Id, s.IdGUID, s.Name, s.Code, NULL AS PricePerDay, NULL AS PricePerHour,
        st.Description AS SpaceType, l.Name AS LocationName,
        CASE WHEN @SpaceType LIKE '%Private%' AND s.Code LIKE '30%' THEN 1 WHEN @SpaceType LIKE '%Shared%' AND s.Code LIKE '31%' THEN 1 WHEN @SpaceType LIKE '%Meeting%' AND s.Code LIKE '32%' THEN 1 ELSE 2 END AS Priority,
        CASE WHEN ISNUMERIC(SUBSTRING(s.Code,3,LEN(s.Code)-2))=1 THEN CAST(SUBSTRING(s.Code,3,LEN(s.Code)-2) AS INT) ELSE 999 END AS CodeNumber
    FROM dbo.WN_Spaces s WITH(NOLOCK) 
    INNER JOIN dbo.WN_SpaceTypes st WITH(NOLOCK) ON s.SpaceTypeId = st.Id 
    INNER JOIN dbo.WN_Locations l WITH(NOLOCK) ON s.LocationId = l.Id
    WHERE s.SpaceTypeId = @STId AND s.Status = 1 AND s.Id NOT IN (
        SELECT DISTINCT b.SpaceId FROM dbo.WN_Bookings b WITH(NOLOCK) 
        WHERE b.BookingStatusId IN (1, 2, 5, 33) 
          AND ((@StartDateTime >= b.StartOn AND @StartDateTime < b.EndOn) 
            OR (@EndDateTime > b.StartOn AND @EndDateTime <= b.EndOn) 
            OR (@StartDateTime <= b.StartOn AND @EndDateTime >= b.EndOn))
    )
    ORDER BY Priority ASC, CodeNumber ASC;
END
GO
/****** Object:  StoredProcedure [dbo].[WN_GetBookingBillingSummary]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[WN_GetBookingBillingSummary]
    @BookingId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT 
        b.Id AS BookingId,
        ISNULL(b.SubtotalAmount, 420000.00) AS TotalContractRent,
        ISNULL((SELECT SUM(GrandTotal) FROM dbo.WN_Invoices WHERE BookingId = b.Id AND InvoiceTypeId IN (1,2,6) AND ISNULL(StatusId, 0) NOT IN (5, 40)), 0.00) AS RentInvoiced,
        ISNULL((SELECT SUM(PaidTotal) FROM dbo.WN_Invoices WHERE BookingId = b.Id AND InvoiceTypeId IN (1,2,6) AND ISNULL(StatusId, 0) NOT IN (5, 40)), 0.00) AS RentPaid,
        ISNULL((SELECT SUM(PaidTotal) FROM dbo.WN_Invoices WHERE BookingId = b.Id AND InvoiceTypeId = 2 AND ISNULL(StatusId, 0) NOT IN (5, 40)), 0.00) AS AdvanceRentPaid,
        ISNULL(b.SecurityDepositRequired, 0.00) AS SecurityDepositRequired,
        ISNULL((SELECT SUM(SecurityDepositAmount) FROM dbo.WN_Invoices WHERE BookingId = b.Id AND ISNULL(StatusId, 0) NOT IN (5, 40)), 0.00) AS SecurityDepositInvoiced,
        ISNULL(b.SecurityDepositPaid, 0.00) AS SecurityDepositPaid,
        (ISNULL(b.SecurityDepositRequired, 0.00) - ISNULL(b.SecurityDepositPaid, 0.00)) AS SecurityDepositOutstanding
    FROM dbo.WN_Bookings b
    WHERE b.Id = @BookingId;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_GetBookingInvoiceDetails]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- ==============================================================================
-- 8. dbo.WN_GetBookingInvoiceDetails (ALTERED)
-- Ensures CustomerEmail is sourced ONLY from dbo.WN_Customers (c.Email).
-- ==============================================================================
CREATE   PROCEDURE [dbo].[WN_GetBookingInvoiceDetails]
    @BookingId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT TOP 1
        b.Id AS BookingId, b.UserId, b.StartOn, b.EndOn,
        mr.MonthlyRent AS MonthlyRent,
        COALESCE(NULLIF(b.SubtotalAmount, 0), NULLIF(q.SubtotalAmount, 0), 0) AS SubtotalAmount,
        b.TotalAmount,
        COALESCE(NULLIF(b.BillingPeriodMonths, 0), NULLIF(q.BillingPeriodMonths, 0), 3) AS BillingPeriodMonths,
        COALESCE(b.SecurityDepositMonths, q.SecurityDepositMonths, 0) AS SecurityDepositMonths,
        COALESCE(NULLIF(b.DiscountAmount, 0), NULLIF(q.DiscountAmount, 0), 0) AS DiscountAmount,
        COALESCE(NULLIF(b.DiscountPercentage, 0), NULLIF(q.DiscountPercentage, 0), 0) AS DiscountPercentage,
        COALESCE(NULLIF(b.DiscountType, ''), NULLIF(q.DiscountType, ''), 'Percentage') AS DiscountType,
        dep.Amount AS SecurityDepositRequired,
        dep.Amount AS ResolvedSecurityDeposit,
        c.Email AS CustomerEmail,
        ISNULL(NULLIF(c.Company, ''), ISNULL(NULLIF(LTRIM(RTRIM(ISNULL(c.FirstName, '') + ' ' + ISNULL(c.LastName, ''))), ''), ISNULL(NULLIF(u.Name, ''), 'Valued Customer'))) AS CustomerName,
        s.Name AS SpaceName, ISNULL(st.Name, '') AS SpaceTypeName, ISNULL(st.Description, '') AS CategoryCode,
        COALESCE(NULLIF(q.Capacity, 0), NULLIF(s.Capacity, 0), 1) AS SpaceCapacity,
        CASE WHEN ISNULL(ptax.TaxApplicable, 0) = 0 THEN 0.00 ELSE ISNULL(bd.AppliedTaxPercentage, 16.00) END AS AppliedTaxPercentage,
        ISNULL(bd.AppliedChargePercentage, 10.00) AS AppliedChargePercentage,
        COALESCE(bd.PerSeatSupportRate, (SELECT TOP 1 FixedAmount FROM dbo.WN_ChargeTypeRate WITH (NOLOCK) WHERE ChargeTypeId = 4 AND (StartDate IS NULL OR StartDate <= b.StartOn) AND (EndDate IS NULL OR EndDate >= b.StartOn) ORDER BY StartDate DESC), (SELECT TOP 1 FixedAmount FROM dbo.WN_ChargeTypeRate WITH (NOLOCK) WHERE ChargeTypeId = 4 ORDER BY StartDate DESC), 2000.00) AS PerSeatSupportRate,
        COALESCE(b.RentAccountId, bd.RentAccountId, 2852) AS RentAccountId,
        COALESCE(b.SecurityReceivedId, bd.SecurityReceivedId, 76) AS SecurityReceivedId,
        COALESCE(b.ServicesIncomeId, bd.ServicesIncomeId, 2853) AS ServicesIncomeId,
        COALESCE(b.SalesTaxId, bd.SalesTaxId, 2854) AS SalesTaxId,
        COALESCE(b.AccountReceivableId, bd.AccountReceivableId, 2855) AS AccountReceivableId,
        COALESCE(dbo.WN_WHTaxRate_Resolve(q.WHTaxId), 15.00) AS WithholdingTaxRate
    FROM dbo.WN_Bookings b WITH (NOLOCK)
    LEFT JOIN dbo.WN_BookingDetails bd WITH (NOLOCK) ON bd.BookingGuid = b.IdGUID
    LEFT JOIN dbo.WN_Quotations q WITH (NOLOCK) ON q.BookingId = b.Id
    OUTER APPLY (
        SELECT TOP 1 cu.Email, cu.Company, cu.FirstName, cu.LastName
        FROM dbo.WN_Customers cu WITH (NOLOCK)
        WHERE (b.CustomerCode IS NOT NULL AND b.CustomerCode <> '' AND cu.Code = b.CustomerCode)
           OR cu.UserId = b.UserId
        ORDER BY CASE WHEN b.CustomerCode IS NOT NULL AND cu.Code = b.CustomerCode THEN 0 ELSE 1 END, cu.Id
    ) c
    LEFT JOIN dbo.WN_Users u WITH (NOLOCK) ON u.Id = b.UserId
    LEFT JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = b.SpaceId
    LEFT JOIN dbo.WN_SpaceTypes st WITH (NOLOCK) ON st.Id = s.SpaceTypeId
    LEFT JOIN dbo.WN_SpaceCategories sc WITH (NOLOCK) ON sc.Id = st.CategoryId
    LEFT JOIN dbo.WN_Locations ploc WITH (NOLOCK) ON ploc.Id = s.LocationId
    OUTER APPLY (
        SELECT TOP 1 pct.TaxApplicable
        FROM dbo.WN_ProvinceChargeTypeTax pct WITH (NOLOCK)
        WHERE pct.ProvinceId = ploc.ProvinceId AND pct.ChargeTypeId = 4
    ) ptax
    OUTER APPLY (
        SELECT TOP 1
            sp.SeatPrice,
            sp.SeatPrice * ISNULL(NULLIF(s.Capacity, 0), 1) AS RoomPrice,
            sp.SecurityDeposit
        FROM dbo.WN_SpacePricing sp WITH (NOLOCK)
        WHERE sp.SpaceId = s.Id AND sp.IsActive = 1
        ORDER BY sp.EffectiveFrom DESC
    ) sp
    CROSS APPLY (SELECT COALESCE(
                NULLIF(q.MonthlyBasePrice, 0),
                (CASE WHEN q.PerSeatBasePrice > 0 THEN q.PerSeatBasePrice * ISNULL(COALESCE(NULLIF(q.Capacity, 0), NULLIF(s.Capacity, 0), 1), 1) ELSE NULL END),
                (CASE WHEN q.BookingId IS NULL AND ISNULL(s.Price, 0) > 0
                       AND b.MonthlyRent > s.Price * (CASE WHEN sc.Code IN ('PrivateOffice', 'Private') THEN ISNULL(NULLIF(s.Capacity, 0), 1) ELSE 1 END)
                      THEN b.MonthlyRent ELSE NULL END),
                NULLIF(sp.RoomPrice, 0),
                (CASE WHEN sp.SeatPrice > 0 THEN sp.SeatPrice * ISNULL(COALESCE(NULLIF(q.Capacity, 0), NULLIF(s.Capacity, 0), 1), 1) ELSE NULL END),
                NULLIF(b.SubtotalAmount, 0),
                0
            ) AS MonthlyRent) mr
    CROSS APPLY (
        SELECT CASE WHEN x.Pct > 0 THEN CASE WHEN x.Pct >= 100 THEN 1.0 ELSE x.Pct / 100.0 END
                    WHEN x.Amt > 0 AND mr.MonthlyRent > 0 THEN CASE WHEN x.Amt >= mr.MonthlyRent THEN 1.0 ELSE x.Amt / mr.MonthlyRent END
                    ELSE 0.0 END AS Fraction
        FROM (SELECT COALESCE(NULLIF(b.DiscountPercentage, 0), NULLIF(q.DiscountPercentage, 0), 0) AS Pct,
                     COALESCE(NULLIF(b.DiscountAmount, 0), NULLIF(q.DiscountAmount, 0), 0) AS Amt) x
    ) dz
    CROSS APPLY (
        SELECT CAST(CASE
            WHEN b.SecurityDepositRequired > 0 THEN b.SecurityDepositRequired
            WHEN q.SecurityDeposit > 0 AND q.SecurityDepositMonths = b.SecurityDepositMonths THEN q.SecurityDeposit
            WHEN bd.SecurityDeposit > 0 THEN bd.SecurityDeposit
            WHEN b.SecurityDepositMonths > 0 AND sc.Code IN ('PrivateOffice', 'Private')
            THEN ROUND(b.SecurityDepositMonths * mr.MonthlyRent * (1.0 - dz.Fraction), 2)
            ELSE 0 END AS DECIMAL(18,2)) AS Amount
    ) dep
    WHERE b.Id = @BookingId;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_GetBookingLastInvoicePeriodEnd]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_GetBookingLastInvoicePeriodEnd]
    @BookingId INT
AS
BEGIN
    SET NOCOUNT ON;
    -- CI_01: custom invoices (InvoiceTypeId 7 / IsCustom = 1) never decide the next billing period.
    SELECT TOP 1 BillingPeriodEnd
    FROM dbo.WN_Invoices WITH (NOLOCK)
    WHERE BookingId = @BookingId
      AND InvoiceTypeId <> 7 AND IsCustom = 0
    ORDER BY Id DESC;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_GetCustomerArrears]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- ==============================================================================
-- 8. UPDATE dbo.WN_GetCustomerArrears
-- Exclude PendingApproval invoices
-- ==============================================================================
CREATE   PROCEDURE [dbo].[WN_GetCustomerArrears]
    @UserId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT ISNULL(SUM(GrandTotal - PaidTotal), 0) AS Arrears
    FROM dbo.WN_Invoices WITH (NOLOCK)
    WHERE UserId = @UserId AND StatusId NOT IN (2, 5, 40)
      AND StatusId NOT IN (SELECT Id FROM dbo.OrderStatus WITH (NOLOCK) WHERE LTRIM(RTRIM(Description)) IN ('Paid', 'Cancelled', 'Delete', 'Deleted'))
      AND (ApprovalStatus IS NULL OR ApprovalStatus <> 'PendingApproval');
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_GetCustomerSTInvoiceByPublicId]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[WN_GetCustomerSTInvoiceByPublicId]
    @PublicId UNIQUEIDENTIFIER
AS
BEGIN
    SET NOCOUNT ON;

    SELECT TOP 1
        st.Id AS STInvoiceId,
        st.PublicId AS STPublicId,
        st.CustomerInvoiceId,
        st.STInvoiceNumber,
        st.TariffHeading,
        st.TariffLabel,
        st.RoomRentDescription,
        st.RoomRentAmount,
        st.RoomRentTaxRate,
        st.RoomRentTaxAmount,
        st.ServiceChargeDescription,
        COALESCE(
            NULLIF(st.ServiceChargeAmount, 0),
            NULLIF(bd.SupportChargeAmount, 0),
            CASE WHEN i.TaxTotal > 0 THEN ROUND(i.TaxTotal / (ISNULL(NULLIF(bd.AppliedTaxPercentage, 0), 16.00) / 100.0), 2) ELSE 0 END
        ) AS ServiceChargeAmount,
        ISNULL(NULLIF(st.ServiceChargeTaxRate, 0), ISNULL(NULLIF(bd.AppliedTaxPercentage, 0), 16.00)) AS ServiceChargeTaxRate,
        COALESCE(
            NULLIF(st.ServiceChargeTaxAmount, 0),
            NULLIF(i.TaxTotal, 0),
            NULLIF(bd.TaxAmount, 0),
            ROUND(ISNULL(bd.SupportChargeAmount, 0) * (ISNULL(NULLIF(bd.AppliedTaxPercentage, 0), 16.00) / 100.0), 2)
        ) AS ServiceChargeTaxAmount,
        st.SecurityDepositDescription,
        st.SecurityDepositAmount,
        st.SecurityDepositTaxRate,
        st.SecurityDepositTaxAmount,
        COALESCE(
            NULLIF(st.ServiceChargeAmount, 0),
            NULLIF(bd.SupportChargeAmount, 0),
            CASE WHEN i.TaxTotal > 0 THEN ROUND(i.TaxTotal / (ISNULL(NULLIF(bd.AppliedTaxPercentage, 0), 16.00) / 100.0), 2) ELSE 0 END
        ) AS SubTotal,
        COALESCE(
            NULLIF(st.ServiceChargeTaxAmount, 0),
            NULLIF(i.TaxTotal, 0),
            NULLIF(bd.TaxAmount, 0),
            ROUND(ISNULL(bd.SupportChargeAmount, 0) * (ISNULL(NULLIF(bd.AppliedTaxPercentage, 0), 16.00) / 100.0), 2)
        ) AS TaxTotal,
        (
            COALESCE(
                NULLIF(st.ServiceChargeAmount, 0),
                NULLIF(bd.SupportChargeAmount, 0),
                CASE WHEN i.TaxTotal > 0 THEN ROUND(i.TaxTotal / (ISNULL(NULLIF(bd.AppliedTaxPercentage, 0), 16.00) / 100.0), 2) ELSE 0 END
            ) +
            COALESCE(
                NULLIF(st.ServiceChargeTaxAmount, 0),
                NULLIF(i.TaxTotal, 0),
                NULLIF(bd.TaxAmount, 0),
                ROUND(ISNULL(bd.SupportChargeAmount, 0) * (ISNULL(NULLIF(bd.AppliedTaxPercentage, 0), 16.00) / 100.0), 2)
            )
        ) AS GrandTotal,
        st.CreatedOn,
        i.InvoiceNumber AS ParentInvoiceNumber,
        i.IssuedOn,
        i.DueOn,
        ISNULL(i.CurrencyCode, 'PKR') AS CurrencyCode,
        COALESCE(NULLIF(LTRIM(RTRIM(c.Company)), ''), NULLIF(LTRIM(RTRIM(ISNULL(c.FirstName, '') + ' ' + ISNULL(c.LastName, ''))), ''), NULLIF(LTRIM(RTRIM(bd.CustomerName)), ''), u.Name, '') AS CustomerName,
        COALESCE(NULLIF(LTRIM(RTRIM(c.Address)), ''), NULLIF(LTRIM(RTRIM(u.Address)), ''), '') AS CustomerAddress,
        COALESCE(NULLIF(LTRIM(RTRIM(c.Code)), ''), NULLIF(LTRIM(RTRIM(b.CustomerCode)), ''), NULLIF(LTRIM(RTRIM(bd.CustomerCode)), ''), '') AS CustomerCode,
        COALESCE(NULLIF(LTRIM(RTRIM(c.CnicOrPassport)), ''), NULLIF(LTRIM(RTRIM(c.NTN)), ''), NULLIF(LTRIM(RTRIM(u.CnicOrPassport)), ''), '') AS SntnNtnNic,
        COALESCE(loc.Name, br.[Description], comp.CompanyName, '') AS CenterName,
        COALESCE(comp.CompanyName, br.[Description], loc.Name, '') AS VendorLegalName,
        COALESCE(NULLIF(LTRIM(RTRIM(ISNULL(comp.AddressLine1, '') + ' ' + ISNULL(comp.AddressLine2, ''))), ''), loc.Address, '') AS VendorAddress,
        COALESCE(comp.Contact, '') AS VendorPhone,
        COALESCE(comp.Fax, '') AS VendorFax,
        COALESCE(comp.NTN, '') AS VendorNtn,
        i.OneBillNumber,
        COALESCE(loc.Id, s.LocationId, u.LocationId) AS LocationId
    FROM dbo.WN_CustomerSTInvoice st WITH (NOLOCK)
    JOIN dbo.WN_Invoices i WITH (NOLOCK) ON i.Id = st.CustomerInvoiceId
    LEFT JOIN dbo.WN_Bookings b WITH (NOLOCK) ON b.Id = i.BookingId
    LEFT JOIN dbo.WN_BookingDetails bd WITH (NOLOCK) ON bd.BookingGuid = b.IdGUID
    LEFT JOIN dbo.WN_Users u WITH (NOLOCK) ON u.Id = i.UserId
    LEFT JOIN dbo.WN_Customers c WITH (NOLOCK) ON (
        (b.CustomerCode IS NOT NULL AND b.CustomerCode <> '' AND c.Code = b.CustomerCode)
        OR (bd.CustomerCode IS NOT NULL AND bd.CustomerCode <> '' AND c.Code = bd.CustomerCode)
        OR (i.UserId IS NOT NULL AND i.UserId > 0 AND c.UserId = i.UserId)
        OR (u.Email IS NOT NULL AND u.Email <> '' AND c.Email = u.Email)
    ) AND (c.IsActive = 1 OR c.IsActive IS NULL)
    LEFT JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = b.SpaceId
    LEFT JOIN dbo.WN_Locations loc WITH (NOLOCK) ON loc.Id = s.LocationId
    LEFT JOIN dbo.Branches br WITH (NOLOCK) ON br.Id = loc.BranchId
    LEFT JOIN dbo.Company comp WITH (NOLOCK) ON comp.Id = COALESCE(loc.CompanyId, br.CompanyId, u.CompanyId)
    WHERE st.PublicId = @PublicId;
END;
GO
