CREATE   PROCEDURE [dbo].[WN_GetInvoiceByBookingId]
    @BookingId INT
AS
BEGIN
    SET NOCOUNT ON;
    -- CI_01: the booking’s first invoice for "Send initial invoice"; a custom invoice (InvoiceTypeId 7 / IsCustom = 1)
    -- is never the first billing period.
    SELECT TOP 1 Id, InvoiceNumber, StatusId, GrandTotal
    FROM dbo.WN_Invoices WITH (NOLOCK)
    WHERE BookingId = @BookingId
      AND InvoiceTypeId <> 7 AND IsCustom = 0
    ORDER BY Id ASC;
END;
