CREATE   PROCEDURE [dbo].[WN_HIK_Settings_Set] @key NVARCHAR(64), @value NVARCHAR(256) AS
BEGIN
  SET NOCOUNT ON;
  MERGE dbo.WN_HIK_Settings WITH (HOLDLOCK) AS t USING (SELECT @key AS k) s ON t.[key] = s.k
