/****** Object:  StoredProcedure [dbo].[WN_Invoice_ApplyWhtToLines]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_Invoice_ApplyWhtToLines]
    @InvoiceId INT
AS
BEGIN
    -- Grosses up the room rent lines (ChargeTypeId 1, which carry rent + support) of a WHT invoice (InvoiceTypeId 6)
    -- the same way WN_Invoices_Insert grossed up its header: UnitPrice and DiscountAmount / (1 - WhtRate/100), rounded
    -- to 2 dp. Security deposit (2), sales tax (3) and support/services (4) lines are not grossed up.
    -- Does nothing for normal invoices. Call ONCE, after the lines are inserted.
    SET NOCOUNT ON;
    DECLARE @WhtRate DECIMAL(9,4) = NULL;
    SELECT @WhtRate = WHTRate FROM dbo.WN_Invoices WITH (NOLOCK) WHERE Id = @InvoiceId AND InvoiceTypeId = 6;
    IF @WhtRate IS NULL OR @WhtRate <= 0 OR @WhtRate >= 100 RETURN 0;

    DECLARE @WhtDivisor DECIMAL(18,10) = 1.0 - (@WhtRate / 100.0);
    UPDATE dbo.WN_InvoiceLines
       SET UnitPrice      = ROUND(UnitPrice / @WhtDivisor, 2),
           DiscountAmount = ROUND(ISNULL(DiscountAmount, 0) / @WhtDivisor, 2)
     WHERE InvoiceId = @InvoiceId
       AND ChargeTypeId = 1;
    RETURN 0;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Invoice_CheckExistingBillingPeriod]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_Invoice_CheckExistingBillingPeriod]
    @BookingId INT,
    @BillingPeriodStart DATETIME,
    @BillingPeriodEnd DATETIME
AS
BEGIN
    SET NOCOUNT ON;
    -- CI_01: a custom invoice (InvoiceTypeId 7 / IsCustom = 1) for the same period does not count as the period billed;
    -- an invoice that a custom invoice replaced (cancelled) still does.
    IF EXISTS (
        SELECT 1
        FROM dbo.WN_Invoices i WITH (NOLOCK)
        WHERE i.BookingId = @BookingId
          AND i.BillingPeriodStart = @BillingPeriodStart
          AND i.BillingPeriodEnd = @BillingPeriodEnd
          AND i.InvoiceTypeId <> 7 AND i.IsCustom = 0
          AND (i.StatusId NOT IN (5, ISNULL((SELECT TOP 1 Id FROM dbo.OrderStatus WITH (NOLOCK) WHERE LTRIM(RTRIM(Description)) = 'Cancelled' ORDER BY Id), 5)) -- was != 3 (Partial) by mistake; void = old 5 / ’Cancelled’
               OR EXISTS (SELECT 1 FROM dbo.WN_CustomInvoices ci WITH (NOLOCK) WHERE ci.ReplacedInvoiceId = i.Id))
    )
        SELECT 1 AS AlreadyExists;
    ELSE
        SELECT 0 AS AlreadyExists;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Invoice_CreateRecurring]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_Invoice_CreateRecurring]
    @BookingId INT,
    @BillingPeriodStart DATETIME,
    @BillingPeriodEnd DATETIME
AS
BEGIN
    SET NOCOUNT ON;
    -- New invoices use dbo.OrderStatus IDs (looked up by description, not hard-coded).
    DECLARE @UnPaidStatusId TINYINT = (SELECT TOP 1 Id FROM dbo.OrderStatus WITH (NOLOCK) WHERE LTRIM(RTRIM(Description)) = 'Un Paid' ORDER BY Id);
    SET XACT_ABORT ON;
    BEGIN TRANSACTION;
    BEGIN TRY
        DECLARE @UserId INT;
        DECLARE @MonthlyRent DECIMAL(18,2);
        DECLARE @DiscountAmt DECIMAL(18,2);
        DECLARE @BillingPeriodMonths INT;
        DECLARE @SpaceId INT;
        DECLARE @BookingGuid UNIQUEIDENTIFIER;
        DECLARE @RentAccountId INT;
        SELECT TOP 1 
            @UserId = b.UserId,
            @MonthlyRent = COALESCE(NULLIF(b.MonthlyRent, 0), NULLIF(b.MonthlyBasePrice, 0), CASE WHEN ISNULL(b.BillingPeriodMonths, 0) > 0 THEN b.SubtotalAmount / b.BillingPeriodMonths ELSE b.SubtotalAmount END),
            @DiscountAmt = ISNULL(b.DiscountAmount, 0.00),
            @BillingPeriodMonths = ISNULL(b.BillingPeriodMonths, 1),
            @SpaceId = b.SpaceId,
            @BookingGuid = b.IdGUID,
            @RentAccountId = ISNULL(b.RentAccountId, 2852)
        FROM dbo.WN_Bookings b WITH (NOLOCK)
        WHERE b.Id = @BookingId AND b.BookingStatusId IN (1, 2, 5, 33); -- Active
        IF @UserId IS NULL
        BEGIN
            ROLLBACK TRANSACTION;
            SELECT NULL AS InvoiceId, NULL AS InvoiceNumber, 0 AS TotalAmount;
            RETURN;
        END

        -- All subsequent recurring invoices after initial advance rent are billed monthly (1 month)
        SET @BillingPeriodMonths = 1;
        DECLARE @RentAmount DECIMAL(18,2) = @MonthlyRent * @BillingPeriodMonths;
        DECLARE @DiscountedRent DECIMAL(18,2) = @RentAmount - @DiscountAmt;
        IF @DiscountedRent < 0 SET @DiscountedRent = 0;

        -- Attendant Surcharges for this cycle
        DECLARE @AttendantSurchargeSubtotal DECIMAL(18,2) = 0.00;
        SELECT @AttendantSurchargeSubtotal = ISNULL(SUM(ba.SurchargeApplied * @BillingPeriodMonths), 0.00)
        FROM dbo.WN_BookingAttendants ba WITH (NOLOCK)
        JOIN dbo.WN_BookingDetails bd WITH (NOLOCK) ON bd.Id = ba.BookingDetailId
        WHERE (bd.BookingGuid = @BookingGuid OR bd.CustomerCode IN (SELECT Code FROM dbo.WN_Customers WHERE UserId = @UserId))
          AND ba.IsOverCapacity = 1
          AND (ba.AssignedTo IS NULL OR ba.AssignedTo >= CAST(@BillingPeriodStart AS DATE))
          AND ba.AssignedFrom <= CAST(@BillingPeriodEnd AS DATE);

        DECLARE @TotalBaseAmount DECIMAL(18,2) = @DiscountedRent + @AttendantSurchargeSubtotal;

        -- Determine Taxes and Support Charges
        DECLARE @AppliedChargePercentage DECIMAL(5,2) = 10.00;
        DECLARE @AppliedTaxPercentage DECIMAL(5,2) = 16.00;
        DECLARE @ProvinceId INT = NULL;
        SELECT TOP 1 
            @AppliedChargePercentage = ISNULL(bd.AppliedChargePercentage, 10.00),
            @AppliedTaxPercentage = ISNULL(bd.AppliedTaxPercentage, 16.00)
        FROM dbo.WN_BookingDetails bd WITH (NOLOCK)
        WHERE bd.BookingGuid = @BookingGuid;

        IF @AppliedChargePercentage IS NULL OR @AppliedChargePercentage <= 0
        BEGIN
            SELECT TOP 1 @AppliedChargePercentage = ISNULL(ChargePercentage, 10.00)
            FROM dbo.WN_ChargeTypeRate WITH (NOLOCK)
            WHERE ChargeTypeId = 4
              AND (StartDate IS NULL OR StartDate <= CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE))
              AND (EndDate IS NULL OR EndDate > CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE))
            ORDER BY StartDate DESC;

            IF @AppliedChargePercentage IS NULL OR @AppliedChargePercentage <= 0
                SET @AppliedChargePercentage = 10.00;
        END

        IF @AppliedTaxPercentage IS NULL OR @AppliedTaxPercentage <= 0
        BEGIN
            SELECT TOP 1 @ProvinceId = l.ProvinceId
            FROM dbo.WN_Spaces s WITH (NOLOCK)
            JOIN dbo.WN_Locations l WITH (NOLOCK) ON l.Id = s.LocationId
            WHERE s.Id = @SpaceId;
            IF @ProvinceId IS NOT NULL
            BEGIN
                SELECT TOP 1 @AppliedTaxPercentage = ISNULL(TaxPercentage, 16.00)
                FROM dbo.WN_Tax WITH (NOLOCK)
                WHERE ProvinceId = @ProvinceId
                  AND StartDate <= CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2(0))
                  AND (EndDate IS NULL OR EndDate > CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2(0)))
                ORDER BY StartDate DESC;
            END
        END

        DECLARE @SupportChargeAmount DECIMAL(18,2) = ROUND(@TotalBaseAmount * (@AppliedChargePercentage / 100.0), 2);
        DECLARE @TaxAmount DECIMAL(18,2) = ROUND(@SupportChargeAmount * (@AppliedTaxPercentage / 100.0), 2);
        DECLARE @GrandTotal DECIMAL(18,2) = @TotalBaseAmount + @TaxAmount;
        DECLARE @Today DATE = CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE);
        DECLARE @DueDate DATE = EOMONTH(@Today);
        DECLARE @InvNum NVARCHAR(50) = 'INV-REC-' + CAST(@BookingId AS NVARCHAR(10)) + '-' + CONVERT(NVARCHAR(8), @BillingPeriodStart, 112);
        DECLARE @SubTotalAmount DECIMAL(18,2) = @RentAmount + @AttendantSurchargeSubtotal;
        DECLARE @InvoiceNotes NVARCHAR(MAX) = 'Recurring Invoice for Period ' + CONVERT(NVARCHAR(10), @BillingPeriodStart, 120) + ' to ' + CONVERT(NVARCHAR(10), @BillingPeriodEnd, 120);

        DECLARE @RoomRentAmount DECIMAL(18,2) = @TotalBaseAmount - @SupportChargeAmount;
        IF @RoomRentAmount < 0 SET @RoomRentAmount = 0;

        -- Call Centralized SP to insert invoice header (GL posting handled untouched within WN_Invoices_Insert)
        DECLARE @InvoiceId INT;
        EXEC dbo.WN_Invoices_Insert
            @UserId                 = @UserId,
            @BookingId              = @BookingId,
            @InvoiceNumber          = @InvNum,
            @IssuedOn               = @Today,
            @DueOn                  = @DueDate,
            @SubTotal               = @SubTotalAmount,
            @DiscountTotal          = @DiscountAmt,
            @TaxTotal               = @TaxAmount,
            @GrandTotal             = @GrandTotal,
            @PaidTotal              = 0.00,
            @CurrencyCode           = 'PKR',
            @StatusId               = @UnPaidStatusId, -- OrderStatus 'Un Paid'
            @Notes                  = @InvoiceNotes,
            @InvoiceTypeId          = 2, -- Recurring/Advance
            @AdvanceRentMonths      = @BillingPeriodMonths,
            @SecurityDepositMonths  = 0,
            @SecurityDepositAmount  = 0.00,
            @AccountsCoaId          = @RentAccountId,
            @BillingPeriodMonths    = @BillingPeriodMonths,
            @BillingPeriodStart     = @BillingPeriodStart,
            @BillingPeriodEnd       = @BillingPeriodEnd,
            @SyncCustomerVendor     = 1,
            @RoomRentExclTax        = @RoomRentAmount,
            @ServiceCharges         = @SupportChargeAmount,
            @TaxOnServiceCharges    = @TaxAmount,
            @InvoiceId              = @InvoiceId OUTPUT,
            @GeneratedInvoiceNumber = @InvNum OUTPUT;

        -- Set ApprovalStatus to PendingApproval
        UPDATE dbo.WN_Invoices
        SET ApprovalStatus = 'PendingApproval'
        WHERE Id = @InvoiceId;

        DECLARE @LineTaxRate DECIMAL(6,4) = CASE WHEN @TotalBaseAmount > 0 THEN CAST(ROUND(@TaxAmount / @TotalBaseAmount, 4) AS DECIMAL(6,4)) ELSE 0 END;

        -- Line Item 1: Recurring Room Rent
        INSERT INTO dbo.WN_InvoiceLines (
            InvoiceId, ChargeTypeId, Description, Quantity, UnitPrice, DiscountAmount, TaxRate, AccountId, SortOrder
        )
        VALUES (
            @InvoiceId, 1, 'Recurring Room Rent', @BillingPeriodMonths, @MonthlyRent, @DiscountAmt, @LineTaxRate, @RentAccountId, 1
        );

        -- Line Items for Active Attendant Surcharges
        INSERT INTO dbo.WN_InvoiceLines (
            InvoiceId, ChargeTypeId, Description, Quantity, UnitPrice, DiscountAmount, TaxRate, AccountId, SortOrder
        )
        SELECT 
            @InvoiceId,
            1,
            'Capacity Overage Surcharge for Attendant: ' + p.Name + ' (' + ISNULL(p.IdNumber, '') + ') in ' + ISNULL(bd.SpaceName, 'Workspace'),
            ISNULL(ba.ExcessSeatCount, 1),
            ba.SurchargeApplied * @BillingPeriodMonths / CASE WHEN ISNULL(ba.ExcessSeatCount, 1) > 0 THEN ba.ExcessSeatCount ELSE 1 END,
            0,
            @LineTaxRate,
            @RentAccountId,
            2
        FROM dbo.WN_BookingAttendants ba WITH (NOLOCK)
        JOIN dbo.WN_BookingDetails bd WITH (NOLOCK) ON bd.Id = ba.BookingDetailId
        JOIN dbo.WN_Persons p WITH (NOLOCK) ON p.PersonId = ba.PersonId
        WHERE (bd.BookingGuid = @BookingGuid OR bd.CustomerCode IN (SELECT Code FROM dbo.WN_Customers WHERE UserId = @UserId))
          AND ba.IsOverCapacity = 1
          AND (ba.AssignedTo IS NULL OR ba.AssignedTo >= CAST(@BillingPeriodStart AS DATE))
          AND ba.AssignedFrom <= CAST(@BillingPeriodEnd AS DATE);

        -- If taxes apply, ensure customer ST invoice is created specifically for this cycle
        IF @TaxAmount > 0
        BEGIN
            DECLARE @STInvNum NVARCHAR(50) = REPLACE(@InvNum, 'INV-', 'ST-INV-');
            DECLARE @STGrandTotal DECIMAL(18,2) = @SupportChargeAmount + @TaxAmount;

            EXEC dbo.WN_EnsureCustomerSTInvoice
                @InvoiceId           = @InvoiceId,
                @PublicId            = NULL,
                @STInvoiceNumber     = @STInvNum,
                @RoomRentAmount      = @RoomRentAmount,
                @ServiceChargeAmount = @SupportChargeAmount,
                @STTaxRate           = @AppliedTaxPercentage,
                @SubTotal            = @SupportChargeAmount,
                @TaxAmount           = @TaxAmount,
                @GrandTotal          = @STGrandTotal;
        END

        COMMIT TRANSACTION;
        SELECT @InvoiceId AS InvoiceId, @InvNum AS InvoiceNumber, @GrandTotal AS TotalAmount;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        SELECT NULL AS InvoiceId, NULL AS InvoiceNumber, 0 AS TotalAmount;
    END CATCH;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Invoice_CreateRecurring_Test]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_Invoice_CreateRecurring_Test]
    @BookingId INT,
    @BillingPeriodStart DATETIME,
    @BillingPeriodEnd DATETIME
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @UnPaidStatusId TINYINT = (SELECT TOP 1 Id FROM dbo.OrderStatus WITH (NOLOCK) WHERE LTRIM(RTRIM(Description)) = 'Un Paid' ORDER BY Id);
    SET XACT_ABORT ON;
    BEGIN TRANSACTION;
    BEGIN TRY
        DECLARE @UserId INT;
        DECLARE @MonthlyRent DECIMAL(18,2);
        DECLARE @DiscountAmt DECIMAL(18,2);
        DECLARE @BillingPeriodMonths INT;
        DECLARE @SpaceId INT;
        DECLARE @BookingGuid UNIQUEIDENTIFIER;
        DECLARE @RentAccountId INT;
        SELECT TOP 1 
            @UserId = b.UserId,
            @MonthlyRent = COALESCE(NULLIF(b.MonthlyRent, 0), NULLIF(b.MonthlyBasePrice, 0), CASE WHEN ISNULL(b.BillingPeriodMonths, 0) > 0 THEN b.SubtotalAmount / b.BillingPeriodMonths ELSE b.SubtotalAmount END),
            @DiscountAmt = ISNULL(b.DiscountAmount, 0.00),
            @BillingPeriodMonths = ISNULL(b.BillingPeriodMonths, 1),
            @SpaceId = b.SpaceId,
            @BookingGuid = b.IdGUID,
            @RentAccountId = ISNULL(b.RentAccountId, 2852)
        FROM dbo.WN_Bookings b WITH (NOLOCK)
        WHERE b.Id = @BookingId AND b.BookingStatusId IN (1, 2, 5, 33);

        IF @UserId IS NULL
        BEGIN
            RAISERROR('UserId is NULL or Booking not active', 16, 1);
        END

        SET @BillingPeriodMonths = 1;
        DECLARE @RentAmount DECIMAL(18,2) = @MonthlyRent * @BillingPeriodMonths;
        DECLARE @DiscountedRent DECIMAL(18,2) = @RentAmount - @DiscountAmt;
        IF @DiscountedRent < 0 SET @DiscountedRent = 0;

        DECLARE @AttendantSurchargeSubtotal DECIMAL(18,2) = 0.00;
        SELECT @AttendantSurchargeSubtotal = ISNULL(SUM(ba.SurchargeApplied * @BillingPeriodMonths), 0.00)
        FROM dbo.WN_BookingAttendants ba WITH (NOLOCK)
        JOIN dbo.WN_BookingDetails bd WITH (NOLOCK) ON bd.Id = ba.BookingDetailId
        WHERE (bd.BookingGuid = @BookingGuid OR bd.CustomerCode IN (SELECT Code FROM dbo.WN_Customers WHERE UserId = @UserId))
          AND ba.IsOverCapacity = 1
          AND (ba.AssignedTo IS NULL OR ba.AssignedTo >= CAST(@BillingPeriodStart AS DATE))
          AND ba.AssignedFrom <= CAST(@BillingPeriodEnd AS DATE);

        DECLARE @TotalBaseAmount DECIMAL(18,2) = @DiscountedRent + @AttendantSurchargeSubtotal;

        DECLARE @AppliedChargePercentage DECIMAL(5,2) = 10.00;
        DECLARE @AppliedTaxPercentage DECIMAL(5,2) = 16.00;
        DECLARE @ProvinceId INT = NULL;
        SELECT TOP 1 
            @AppliedChargePercentage = ISNULL(bd.AppliedChargePercentage, 10.00),
            @AppliedTaxPercentage = ISNULL(bd.AppliedTaxPercentage, 16.00)
        FROM dbo.WN_BookingDetails bd WITH (NOLOCK)
        WHERE bd.BookingGuid = @BookingGuid;

        IF @AppliedChargePercentage IS NULL OR @AppliedChargePercentage <= 0
        BEGIN
            SELECT TOP 1 @AppliedChargePercentage = ISNULL(ChargePercentage, 10.00)
            FROM dbo.WN_ChargeTypeRate WITH (NOLOCK)
            WHERE ChargeTypeId = 4
              AND (StartDate IS NULL OR StartDate <= CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE))
              AND (EndDate IS NULL OR EndDate > CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE))
            ORDER BY StartDate DESC;

            IF @AppliedChargePercentage IS NULL OR @AppliedChargePercentage <= 0
                SET @AppliedChargePercentage = 10.00;
        END

        IF @AppliedTaxPercentage IS NULL OR @AppliedTaxPercentage <= 0
        BEGIN
            SELECT TOP 1 @ProvinceId = l.ProvinceId
            FROM dbo.WN_Spaces s WITH (NOLOCK)
            JOIN dbo.WN_Locations l WITH (NOLOCK) ON l.Id = s.LocationId
            WHERE s.Id = @SpaceId;
            IF @ProvinceId IS NOT NULL
            BEGIN
                SELECT TOP 1 @AppliedTaxPercentage = ISNULL(TaxPercentage, 16.00)
                FROM dbo.WN_Tax WITH (NOLOCK)
                WHERE ProvinceId = @ProvinceId
                  AND StartDate <= CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2(0))
                  AND (EndDate IS NULL OR EndDate > CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2(0)))
                ORDER BY StartDate DESC;
            END
        END

        DECLARE @SupportChargeAmount DECIMAL(18,2) = ROUND(@TotalBaseAmount * (@AppliedChargePercentage / 100.0), 2);
        DECLARE @TaxAmount DECIMAL(18,2) = ROUND(@SupportChargeAmount * (@AppliedTaxPercentage / 100.0), 2);
        DECLARE @GrandTotal DECIMAL(18,2) = @TotalBaseAmount + @TaxAmount;
        DECLARE @Today DATE = CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE);
        DECLARE @DueDate DATE = EOMONTH(@Today);
        DECLARE @InvNum NVARCHAR(50) = 'INV-REC-' + CAST(@BookingId AS NVARCHAR(10)) + '-' + CONVERT(NVARCHAR(8), @BillingPeriodStart, 112);
        DECLARE @SubTotalAmount DECIMAL(18,2) = @RentAmount + @AttendantSurchargeSubtotal;
        DECLARE @InvoiceNotes NVARCHAR(MAX) = 'Recurring Invoice for Period ' + CONVERT(NVARCHAR(10), @BillingPeriodStart, 120) + ' to ' + CONVERT(NVARCHAR(10), @BillingPeriodEnd, 120);

        DECLARE @RoomRentAmount DECIMAL(18,2) = @TotalBaseAmount - @SupportChargeAmount;
        IF @RoomRentAmount < 0 SET @RoomRentAmount = 0;

        DECLARE @InvoiceId INT;
        EXEC dbo.WN_Invoices_Insert
            @UserId                 = @UserId,
            @BookingId              = @BookingId,
            @InvoiceNumber          = @InvNum,
            @IssuedOn               = @Today,
            @DueOn                  = @DueDate,
            @SubTotal               = @SubTotalAmount,
            @DiscountTotal          = @DiscountAmt,
            @TaxTotal               = @TaxAmount,
            @GrandTotal             = @GrandTotal,
            @PaidTotal              = 0.00,
            @CurrencyCode           = 'PKR',
            @StatusId               = @UnPaidStatusId,
            @Notes                  = @InvoiceNotes,
            @InvoiceTypeId          = 2,
            @AdvanceRentMonths      = @BillingPeriodMonths,
            @SecurityDepositMonths  = 0,
            @SecurityDepositAmount  = 0.00,
            @AccountsCoaId          = @RentAccountId,
            @BillingPeriodMonths    = @BillingPeriodMonths,
            @BillingPeriodStart     = @BillingPeriodStart,
            @BillingPeriodEnd       = @BillingPeriodEnd,
            @SyncCustomerVendor     = 1,
            @RoomRentExclTax        = @RoomRentAmount,
            @ServiceCharges         = @SupportChargeAmount,
            @TaxOnServiceCharges    = @TaxAmount,
            @InvoiceId              = @InvoiceId OUTPUT,
            @GeneratedInvoiceNumber = @InvNum OUTPUT;

        UPDATE dbo.WN_Invoices
        SET ApprovalStatus = 'PendingApproval'
        WHERE Id = @InvoiceId;

        DECLARE @LineTaxRate DECIMAL(6,4) = CASE WHEN @TotalBaseAmount > 0 THEN CAST(ROUND(@TaxAmount / @TotalBaseAmount, 4) AS DECIMAL(6,4)) ELSE 0 END;

        INSERT INTO dbo.WN_InvoiceLines (
            InvoiceId, ChargeTypeId, Description, Quantity, UnitPrice, DiscountAmount, TaxRate, AccountId, SortOrder
        )
        VALUES (
            @InvoiceId, 1, 'Recurring Room Rent', @BillingPeriodMonths, @MonthlyRent, @DiscountAmt, @LineTaxRate, @RentAccountId, 1
        );

        INSERT INTO dbo.WN_InvoiceLines (
            InvoiceId, ChargeTypeId, Description, Quantity, UnitPrice, DiscountAmount, TaxRate, AccountId, SortOrder
        )
        SELECT 
            @InvoiceId,
            1,
            'Capacity Overage Surcharge for Attendant: ' + p.Name + ' (' + ISNULL(p.IdNumber, '') + ') in ' + ISNULL(bd.SpaceName, 'Workspace'),
            ISNULL(ba.ExcessSeatCount, 1),
            ba.SurchargeApplied * @BillingPeriodMonths / CASE WHEN ISNULL(ba.ExcessSeatCount, 1) > 0 THEN ba.ExcessSeatCount ELSE 1 END,
            0,
            @LineTaxRate,
            @RentAccountId,
            2
        FROM dbo.WN_BookingAttendants ba WITH (NOLOCK)
        JOIN dbo.WN_BookingDetails bd WITH (NOLOCK) ON bd.Id = ba.BookingDetailId
        JOIN dbo.WN_Persons p WITH (NOLOCK) ON p.PersonId = ba.PersonId
        WHERE (bd.BookingGuid = @BookingGuid OR bd.CustomerCode IN (SELECT Code FROM dbo.WN_Customers WHERE UserId = @UserId))
          AND ba.IsOverCapacity = 1
          AND (ba.AssignedTo IS NULL OR ba.AssignedTo >= CAST(@BillingPeriodStart AS DATE))
          AND ba.AssignedFrom <= CAST(@BillingPeriodEnd AS DATE);

        IF @TaxAmount > 0
        BEGIN
            DECLARE @STInvNum NVARCHAR(50) = REPLACE(@InvNum, 'INV-', 'ST-INV-');
            DECLARE @STGrandTotal DECIMAL(18,2) = @SupportChargeAmount + @TaxAmount;

            EXEC dbo.WN_EnsureCustomerSTInvoice
                @InvoiceId           = @InvoiceId,
                @PublicId            = NULL,
                @STInvoiceNumber     = @STInvNum,
                @RoomRentAmount      = @RoomRentAmount,
                @ServiceChargeAmount = @SupportChargeAmount,
                @STTaxRate           = @AppliedTaxPercentage,
                @SubTotal            = @SupportChargeAmount,
                @TaxAmount           = @TaxAmount,
                @GrandTotal          = @STGrandTotal;
        END

        COMMIT TRANSACTION;
        SELECT @InvoiceId AS InvoiceId, @InvNum AS InvoiceNumber, @GrandTotal AS TotalAmount;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        DECLARE @Msg NVARCHAR(MAX) = ERROR_MESSAGE();
        DECLARE @Line INT = ERROR_LINE();
        DECLARE @Proc NVARCHAR(200) = ERROR_PROCEDURE();
        RAISERROR('Error in %s line %d: %s', 16, 1, @Proc, @Line, @Msg);
    END CATCH;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Invoices_ApproveSingle]    Script Date: 28/10/2026 11:43:10 am ******/
