-- ==============================================================================
-- 12. NEW PROC: dbo.WN_Invoices_ApproveSingle
-- Exactly one conditional UPDATE ... WHERE Id = @InvoiceId AND ApprovalStatus = 'PendingApproval' AND ViewedAt IS NOT NULL AND ViewedBy = @UserId
-- ==============================================================================
CREATE   PROCEDURE [dbo].[WN_Invoices_ApproveSingle]
    @InvoiceId INT,
    @UserId    INT
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE dbo.WN_Invoices
       SET ApprovalStatus = 'Approved',
           ApprovedAt     = SYSUTCDATETIME(),
           ApprovedBy     = @UserId,
           UpdatedOn      = SYSUTCDATETIME()
     WHERE Id = @InvoiceId
       AND ApprovalStatus = 'PendingApproval'
       AND ViewedAt IS NOT NULL
       AND ViewedBy = @UserId;

    SELECT @@ROWCOUNT AS RowsAffected;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Invoices_DeleteUnapproved]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- ==============================================================================
-- 2. CREATE OR ALTER PROCEDURE dbo.WN_Invoices_DeleteUnapproved
-- Deletes / rejects an unapproved invoice (PendingApproval)
-- ==============================================================================
CREATE   PROCEDURE [dbo].[WN_Invoices_DeleteUnapproved]
    @InvoiceId INT,
    @UserId    INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        IF NOT EXISTS (SELECT 1 FROM dbo.WN_Invoices WITH (UPDLOCK, HOLDLOCK) WHERE Id = @InvoiceId)
        BEGIN
            RAISERROR('Invoice not found.', 16, 2);
            RETURN;
        END;

        DECLARE @ApprovalStatus NVARCHAR(50);
        DECLARE @PaidTotal      DECIMAL(18,4);
        DECLARE @PublicId       UNIQUEIDENTIFIER;

        SELECT @ApprovalStatus = ApprovalStatus,
               @PaidTotal      = ISNULL(PaidTotal, 0),
               @PublicId       = PublicId
        FROM dbo.WN_Invoices WITH (UPDLOCK, HOLDLOCK)
        WHERE Id = @InvoiceId;

        IF ISNULL(@ApprovalStatus, '') <> 'PendingApproval'
        BEGIN
            RAISERROR('Only unapproved (PendingApproval) invoices can be deleted.', 16, 1);
            RETURN;
        END;

        IF @PaidTotal > 0 OR EXISTS (SELECT 1 FROM dbo.WN_FeeReceipts WITH (NOLOCK) WHERE InvoiceIdGUID = @PublicId AND Status = 1)
        BEGIN
            RAISERROR('Invoice has payment or fee receipt records and cannot be deleted.', 16, 1);
            RETURN;
        END;

        -- Soft delete the unapproved invoice: StatusId = 40 (Deleted), ApprovalStatus = 'Rejected'
        UPDATE dbo.WN_Invoices
           SET StatusId       = 40,
               ApprovalStatus = 'Rejected',
               UpdatedOn      = SYSUTCDATETIME()
         WHERE Id = @InvoiceId
           AND ApprovalStatus = 'PendingApproval';

        -- Cancel any queued delivery emails for this invoice
        IF OBJECT_ID(N'dbo.WN_InvoiceDeliveryQueue', N'U') IS NOT NULL
        BEGIN
            UPDATE dbo.WN_InvoiceDeliveryQueue
               SET Status        = 'Cancelled',
                   LastAttemptAt = SYSUTCDATETIME()
             WHERE InvoiceId = @InvoiceId
               AND Status IN ('Pending', 'Failed');
        END;

        COMMIT TRANSACTION;

        SELECT @@ROWCOUNT AS RowsAffected;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Invoices_GetApprovalQueue]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- ==============================================================================
-- 7. dbo.WN_Invoices_GetApprovalQueue (ALTERED)
-- Ensures CustomerEmail is sourced ONLY from dbo.WN_Customers (c.Email).
-- ==============================================================================
CREATE   PROCEDURE [dbo].[WN_Invoices_GetApprovalQueue]
    @LocationId INT = NULL,
    @UserId     INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT 
        i.Id,
        i.PublicId,
        i.InvoiceNumber,
        i.UserId,
        i.BookingId,
        i.IssuedOn,
        i.DueOn,
        COALESCE(i.BillingPeriodStart, b.StartOn) AS BillingPeriodStart,
        COALESCE(i.BillingPeriodEnd, b.EndOn)     AS BillingPeriodEnd,
        ISNULL(i.SubTotal, 0)                     AS SubTotal,
        ISNULL(i.DiscountTotal, 0)                AS DiscountTotal,
        ISNULL(i.TaxTotal, 0)                     AS TaxTotal,
        ISNULL(i.GrandTotal, 0)                   AS GrandTotal,
        ISNULL(i.PaidTotal, 0)                    AS PaidTotal,
        i.CurrencyCode,
        i.StatusId,
        i.InvoiceTypeId,
        i.ApprovalStatus,
        i.ViewedAt,
        i.ViewedBy,
        vu.Email                                  AS ViewedByEmail,
        vu.Name                                   AS ViewedByName,
        i.ApprovedAt,
        i.ApprovedBy,
        i.CreatedOn,
        COALESCE(ci.LocationId, s.LocationId, u.LocationId) AS LocationId,
        loc.Name                                  AS LocationName,
        ISNULL(NULLIF(LTRIM(RTRIM(ISNULL(c.FirstName, '') + ' ' + ISNULL(c.LastName, ''))), ''), ISNULL(u.Name, 'Customer')) AS CustomerName,
        c.Email                                   AS CustomerEmail,
        COALESCE(NULLIF(LTRIM(RTRIM(c.Company)), ''), '-') AS CompanyName,
        s.Name                                    AS SpaceName,
        s.Code                                    AS SpaceCode,
        ISNULL(b.MonthlyRent, 0)                  AS MonthlyRent,
        ISNULL(b.BillingPeriodMonths, 1)          AS BillingPeriodMonths
    FROM dbo.WN_Invoices i WITH (NOLOCK)
    LEFT JOIN dbo.WN_CustomInvoices ci WITH (NOLOCK) ON ci.InvoiceId = i.Id
    LEFT JOIN dbo.WN_Bookings b WITH (NOLOCK) ON b.Id = i.BookingId
    OUTER APPLY (
        SELECT TOP 1 cu.Code, cu.FirstName, cu.LastName, cu.Email, cu.Company
        FROM dbo.WN_Customers cu WITH (NOLOCK)
        WHERE (b.CustomerCode IS NOT NULL AND b.CustomerCode <> '' AND cu.Code = b.CustomerCode)
           OR cu.UserId = i.UserId
        ORDER BY CASE WHEN b.CustomerCode IS NOT NULL AND cu.Code = b.CustomerCode THEN 0 ELSE 1 END, cu.Id
    ) c
    LEFT JOIN dbo.WN_Users u WITH (NOLOCK) ON u.Id = i.UserId
    LEFT JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = b.SpaceId
    LEFT JOIN dbo.WN_Locations loc WITH (NOLOCK) ON loc.Id = COALESCE(ci.LocationId, s.LocationId, u.LocationId)
    LEFT JOIN dbo.WN_Users vu WITH (NOLOCK) ON vu.Id = i.ViewedBy
    WHERE i.ApprovalStatus = 'PendingApproval'
      AND i.StatusId <> 40
      AND (@LocationId IS NULL OR ci.LocationId = @LocationId OR s.LocationId = @LocationId OR u.LocationId = @LocationId)
    ORDER BY i.DueOn ASC, i.Id ASC;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Invoices_GetList]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[WN_Invoices_GetList]
    @Page   INT           = 1,
    @Limit  INT           = 20,
    @Search NVARCHAR(255) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@Page - 1) * @Limit;
    SELECT
        i.Id, i.PublicId, i.InvoiceNumber,
        i.UserId, u.Name AS UserName, u.Email AS UserEmail,
        i.BookingId, i.MembershipId,
        i.IssuedOn, i.DueOn,
        i.SubTotal, i.DiscountTotal, i.TaxTotal,
        i.GrandTotal, i.PaidTotal, i.BalanceDue,
        i.CurrencyCode, i.StatusId, i.Notes, i.CreatedOn,
        COUNT(*) OVER () AS TotalCount
    FROM dbo.WN_Invoices i WITH (NOLOCK)
    JOIN dbo.WN_Users    u WITH (NOLOCK) ON u.Id = i.UserId
    WHERE ISNULL(i.StatusId, 0) <> 40
      AND (@Search IS NULL OR @Search = ''
           OR u.Name          LIKE '%' + @Search + '%'
           OR u.Email         LIKE '%' + @Search + '%'
           OR i.InvoiceNumber LIKE '%' + @Search + '%')
    ORDER BY i.CreatedOn DESC
    OFFSET @Offset ROWS FETCH NEXT @Limit ROWS ONLY;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Invoices_GetSummary]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_Invoices_GetSummary]
    @Id INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        i.Id, i.PublicId, i.InvoiceNumber,
        i.UserId, u.Name AS UserName, u.Email AS UserEmail,
        i.BookingId, i.MembershipId,
        i.IssuedOn, i.DueOn,
        i.SubTotal, i.DiscountTotal, i.TaxTotal,
        i.GrandTotal, i.PaidTotal, i.BalanceDue,
        i.CurrencyCode, i.StatusId, i.Notes, i.CreatedOn,
        (SELECT il.Id, ct.Code AS ChargeTypeCode, ct.Label AS ChargeTypeLabel,
                il.Description, il.Quantity, il.UnitPrice,
                il.DiscountAmount, il.TaxRate, il.TaxAmount, il.LineTotal
         FROM dbo.WN_InvoiceLines il
         JOIN dbo.WN_ChargeTypes  ct ON ct.Id = il.ChargeTypeId
         WHERE il.InvoiceId = i.Id
         ORDER BY il.SortOrder
         FOR JSON PATH) AS InvoiceLines
    FROM dbo.WN_Invoices i WITH (NOLOCK)
    JOIN dbo.WN_Users    u WITH (NOLOCK) ON u.Id = i.UserId
    WHERE i.Id = @Id;
END
GO
/****** Object:  StoredProcedure [dbo].[WN_Invoices_Insert]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_Invoices_Insert]
(
    -- Core & Existing Parameters (100% Backward Compatible)
    @UserId                 INT,
    @BookingId              INT                 = NULL,
    @MembershipId           INT                 = NULL,
    @InvoiceNumber          NVARCHAR(50)        = NULL,
    @PublicId               UNIQUEIDENTIFIER    = NULL,
    @IssuedOn               DATETIME            = NULL,
    @DueOn                  DATE                = NULL,
    @SubTotal               DECIMAL(18, 4)      = 0.0000,
    @DiscountTotal          DECIMAL(18, 4)      = 0.0000,
    @TaxTotal               DECIMAL(18, 4)      = 0.0000,
    @GrandTotal             DECIMAL(18, 4)      = NULL,
    @PaidTotal              DECIMAL(18, 4)      = 0.0000,
    @CurrencyCode           NVARCHAR(10)        = 'PKR',
    @StatusId               TINYINT             = NULL, -- NULL = OrderStatus ’Un Paid’ (looked up below)
    @Notes                  NVARCHAR(MAX)       = NULL,
    @InvoiceTypeId          INT                 = 1, -- 1: Standard, 2: Advance, 3: Recurring, 4: Custom, 5: Surcharge, 6: WHT (set here for WHT bookings)
    @AdvanceRentMonths      INT                 = NULL,
    @SecurityDepositMonths  INT                 = NULL,
    @SecurityDepositAmount  DECIMAL(18, 2)      = 0.00,
    @AccountsCoaId          INT                 = NULL,
    @BillingPeriodMonths    INT                 = NULL,
    @BillingPeriodStart     DATETIME            = NULL,
    @BillingPeriodEnd       DATETIME            = NULL,
    @AccountReceivableId    INT                 = NULL,
    @RentAccountId          INT                 = NULL,
    @ServicesIncomeId       INT                 = NULL,
    @SalesTaxId             INT                 = NULL,
    @SecurityReceivedId     INT                 = NULL,
    @CreatedById            INT                 = NULL,
    @SyncCustomerVendor     BIT                 = 1,
    -- Optional GL Posting & Breakdown Parameters
    @RoomRentExclTax        DECIMAL(18, 4)      = NULL,
    @ServiceCharges         DECIMAL(18, 4)      = NULL,
    @TaxOnServiceCharges    DECIMAL(18, 4)      = NULL,
    @WHTRate                DECIMAL(9, 4)       = 0.0000,
    @WHTAmount              DECIMAL(18, 4)      = 0.0000,
    @LocationId             INT                 = NULL,
    @VoucherTypeId          TINYINT             = 1,    -- Default Voucher Type: 1 (JV)
    @CustomerVendorId       INT                 = NULL,
    @PostToLedger           BIT                 = 1,
    -- Output Parameters
    @InvoiceId              INT                 = NULL OUTPUT,
    @GeneratedInvoiceNumber NVARCHAR(50)        = NULL OUTPUT,
    @GeneratedPublicId      UNIQUEIDENTIFIER    = NULL OUTPUT,
    @VoucherId              INT                 = NULL OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
    -- New invoices use dbo.OrderStatus IDs (looked up by description, not hard-coded).
    IF @StatusId IS NULL SET @StatusId = (SELECT TOP 1 Id FROM dbo.OrderStatus WITH (NOLOCK) WHERE LTRIM(RTRIM(Description)) = 'Un Paid' ORDER BY Id);
    -- 1. Default PublicId
    IF @PublicId IS NULL
    BEGIN
        SET @PublicId = NEWID();
    END
    -- 2. Default IssuedOn (Exact to the second) & DueOn
    DECLARE @NowPST DATETIME = CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2(0));
    IF @IssuedOn IS NULL
    BEGIN
        SET @IssuedOn = @NowPST;
    END
    ELSE IF CAST(@IssuedOn AS TIME) = '00:00:00'
    BEGIN
        -- If only a date portion was passed, preserve the date and append current time down to the second
        SET @IssuedOn = DATEADD(SECOND, DATEDIFF(SECOND, '00:00:00', CAST(@NowPST AS TIME)), CAST(CAST(@IssuedOn AS DATE) AS DATETIME));
    END
    IF @DueOn IS NULL
    BEGIN
        SET @DueOn = CAST(DATEADD(DAY, 7, @IssuedOn) AS DATE);
    END
    -- 3. Resolve CustomerCode across all available sources early
    DECLARE @CustomerCode NVARCHAR(50) = NULL;
    -- (a) From WN_Bookings
    IF @BookingId IS NOT NULL
    BEGIN
        SELECT TOP 1 @CustomerCode = CustomerCode 
        FROM dbo.WN_Bookings WITH (NOLOCK) 
        WHERE Id = @BookingId AND CustomerCode IS NOT NULL AND LTRIM(RTRIM(CustomerCode)) <> '';
    END
    -- (b) From WN_BookingDetails
    IF (@CustomerCode IS NULL OR @CustomerCode = '') AND @BookingId IS NOT NULL
    BEGIN
        SELECT TOP 1 @CustomerCode = bd.CustomerCode
        FROM dbo.WN_BookingDetails bd WITH (NOLOCK)
        JOIN dbo.WN_Bookings b WITH (NOLOCK) ON b.IdGUID = bd.BookingGuid
        WHERE b.Id = @BookingId AND bd.CustomerCode IS NOT NULL AND LTRIM(RTRIM(bd.CustomerCode)) <> '';
    END
    -- (c) From WN_Customers via UserId
    IF (@CustomerCode IS NULL OR @CustomerCode = '') AND @UserId IS NOT NULL
    BEGIN
        SELECT TOP 1 @CustomerCode = Code 
        FROM dbo.WN_Customers WITH (NOLOCK) 
        WHERE UserId = @UserId AND Code IS NOT NULL AND LTRIM(RTRIM(Code)) <> '';
    END
    -- (d) From WN_Customers via Email matching WN_Users
    IF (@CustomerCode IS NULL OR @CustomerCode = '') AND @UserId IS NOT NULL
    BEGIN
        SELECT TOP 1 @CustomerCode = c.Code
        FROM dbo.WN_Customers c WITH (NOLOCK)
        JOIN dbo.WN_Users u WITH (NOLOCK) ON u.Email = c.Email
        WHERE u.Id = @UserId AND c.Code IS NOT NULL AND LTRIM(RTRIM(c.Code)) <> '';
    END
    -- (e) From CustomersVendors via CustomerVendorId
    IF (@CustomerCode IS NULL OR @CustomerCode = '') AND @CustomerVendorId IS NOT NULL
    BEGIN
        SELECT TOP 1 @CustomerCode = Code
        FROM dbo.CustomersVendors WITH (NOLOCK)
        WHERE Id = @CustomerVendorId AND Code IS NOT NULL AND LTRIM(RTRIM(Code)) <> '';
    END
    -- (f) From CustomersVendors via Email matching WN_Users
    IF (@CustomerCode IS NULL OR @CustomerCode = '') AND @UserId IS NOT NULL
    BEGIN
        SELECT TOP 1 @CustomerCode = cv.Code
        FROM dbo.CustomersVendors cv WITH (NOLOCK)
        JOIN dbo.WN_Users u WITH (NOLOCK) ON cv.Email = u.Email
        WHERE u.Id = @UserId AND cv.Code IS NOT NULL AND LTRIM(RTRIM(cv.Code)) <> '';
    END
    -- 4. Fallback / resolution for booking-related metadata (SecurityDepositAmount, Months)
    IF @BookingId IS NOT NULL
    BEGIN
        IF @SecurityDepositMonths IS NULL
        BEGIN
            SELECT @SecurityDepositMonths = SecurityDepositMonths 
            FROM dbo.WN_Bookings WITH (NOLOCK) 
            WHERE Id = @BookingId;
        END
        IF @AdvanceRentMonths IS NULL
        BEGIN
            SELECT @AdvanceRentMonths = AdvanceRentMonths 
            FROM dbo.WN_Bookings WITH (NOLOCK) 
            WHERE Id = @BookingId;
        END
        -- Resolve total required security deposit from Booking or SecurityDeposits table
        DECLARE @BookingSecReq DECIMAL(18, 4) = 0.0000;
        SELECT @BookingSecReq = ISNULL(SecurityDepositRequired, 0.0000)
        FROM dbo.WN_Bookings WITH (NOLOCK)
        WHERE Id = @BookingId;
        IF @BookingSecReq = 0.0000
        BEGIN
            SELECT TOP 1 @BookingSecReq = ISNULL(Amount, 0.0000)
            FROM dbo.WN_SecurityDeposits WITH (NOLOCK)
            WHERE BookingId = @BookingId;
        END
        -- The booking’s security deposit belongs on its FIRST invoice only. Later invoices (next / recurring / custom /
        -- surcharge) used to get the full deposit forced on too, so they failed the breakdown check or booked it again.
        IF NOT EXISTS (SELECT 1 FROM dbo.WN_Invoices WITH (NOLOCK) WHERE BookingId = @BookingId AND InvoiceTypeId <> 7 AND IsCustom = 0) -- CI_03: a custom invoice is never the first invoice
        BEGIN
            -- If @SecurityDepositAmount was omitted or is smaller than the full required deposit, adopt the full booking deposit
            IF (@SecurityDepositAmount IS NULL OR @SecurityDepositAmount = 0.00) AND @BookingSecReq > 0
            BEGIN
                SET @SecurityDepositAmount = @BookingSecReq;
            END
            ELSE IF @BookingSecReq > 0 AND @SecurityDepositAmount < @BookingSecReq
            BEGIN
                -- If caller passed single-seat/monthly rate (e.g. 70,000) instead of total deposit (e.g. 490,000)
                SET @SecurityDepositAmount = @BookingSecReq;
            END
        END
    END
    -- 5. Default GrandTotal calculation if omitted
    IF @GrandTotal IS NULL
    BEGIN
        SET @GrandTotal = (@SubTotal - @DiscountTotal) + @TaxTotal + ISNULL(@SecurityDepositAmount, 0.0000);
    END
    -- 6. Default Currency
    IF @CurrencyCode IS NULL OR LTRIM(RTRIM(@CurrencyCode)) = ''
    BEGIN
        SET @CurrencyCode = 'PKR';
    END
    -- 7. Auto-generate InvoiceNumber if omitted
    IF @InvoiceNumber IS NULL OR LTRIM(RTRIM(@InvoiceNumber)) = ''
    BEGIN
        DECLARE @NextId INT;
        SELECT @NextId = ISNULL(MAX(Id), 0) + 1 FROM dbo.WN_Invoices;
        SET @InvoiceNumber = 'INV-' + CAST(YEAR(CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2(0))) AS VARCHAR(4)) + '-' + RIGHT('00000' + CAST(@NextId AS VARCHAR(10)), 5);
    END
    -- 8. Resolve CreatedById from Booking, User, or WN_Users table
    IF @CreatedById IS NULL AND @BookingId IS NOT NULL
    BEGIN
        SELECT TOP 1 @CreatedById = CreatedById 
        FROM dbo.WN_Bookings WITH (NOLOCK) 
        WHERE Id = @BookingId AND CreatedById IS NOT NULL;
    END
    IF @CreatedById IS NULL AND @UserId IS NOT NULL
    BEGIN
        SET @CreatedById = @UserId;
    END
    IF @CreatedById IS NULL
    BEGIN
        SELECT TOP 1 @CreatedById = Id 
        FROM dbo.WN_Users WITH (NOLOCK) 
        ORDER BY Id ASC;
    END
    -- 9. Location Resolution (LocationId -> CompanyId & BranchId)
    IF @LocationId IS NULL AND @BookingId IS NOT NULL
    BEGIN
        SELECT TOP 1 @LocationId = s.LocationId
        FROM dbo.WN_Bookings b WITH (NOLOCK)
        JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = b.SpaceId
        WHERE b.Id = @BookingId;
    END
    -- Fallback: lookup via User’s latest booking if not provided
    IF @LocationId IS NULL AND @UserId IS NOT NULL
    BEGIN
        SELECT TOP 1 @LocationId = s.LocationId
        FROM dbo.WN_Bookings b WITH (NOLOCK)
        JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = b.SpaceId
        WHERE b.UserId = @UserId
        ORDER BY b.Id DESC;
    END
    -- Resolve CompanyId and BranchId from WN_Locations
    DECLARE @CompanyId INT = NULL;
    DECLARE @BranchId  INT = NULL;
    IF @LocationId IS NOT NULL
    BEGIN
        SELECT TOP 1 
            @CompanyId = CompanyId, 
            @BranchId  = BranchId
        FROM dbo.WN_Locations WITH (NOLOCK)
        WHERE Id = @LocationId;
    END
    IF @PostToLedger = 1 AND (@LocationId IS NULL OR @CompanyId IS NULL OR @BranchId IS NULL)
    BEGIN
        RAISERROR('Unable to resolve LocationId, CompanyId, or BranchId for invoice ledger posting.', 16, 1);
        RETURN -1;
    END
    -- 10. Breakdown Derivation
    DECLARE @NetBase DECIMAL(18, 4) = 0.0000;
    DECLARE @SecAmt  DECIMAL(18, 4) = ISNULL(@SecurityDepositAmount, 0.0000);
    IF @GrandTotal IS NOT NULL AND @GrandTotal > 0
    BEGIN
        SET @NetBase = @GrandTotal - @SecAmt - @TaxTotal;
    END
    ELSE
    BEGIN
        SET @NetBase = (@SubTotal - @DiscountTotal);
        IF @NetBase < 0 SET @NetBase = 0.0000;
        SET @GrandTotal = @NetBase + @TaxTotal + @SecAmt;
    END
    IF @NetBase < 0 SET @NetBase = 0.0000;
    IF (@RoomRentExclTax IS NULL AND @ServiceCharges IS NULL AND @TaxOnServiceCharges IS NULL)
       OR (ISNULL(@RoomRentExclTax, 0) = 0 AND ISNULL(@ServiceCharges, 0) = 0 AND ISNULL(@TaxOnServiceCharges, 0) = 0 AND @GrandTotal > 0)
    BEGIN
        IF @TaxTotal > 0
        BEGIN
            -- Custom / Surcharge invoices: entire taxable base is treated as Service Fee
            IF @InvoiceTypeId IN (4, 5) OR @BookingId IS NULL
            BEGIN
                SET @TaxOnServiceCharges = @TaxTotal;
                SET @ServiceCharges      = @NetBase;
                SET @RoomRentExclTax     = 0.0000;
            END
            ELSE
            BEGIN
                -- Standard / Advance / Recurring booking invoices
                DECLARE @AppliedChargePct DECIMAL(5,2) = 10.00;
                IF @BookingId IS NOT NULL
                BEGIN
                    SELECT TOP 1 @AppliedChargePct = ISNULL(AppliedChargePercentage, 10.00)
                    FROM dbo.WN_BookingDetails WITH (NOLOCK)
                    WHERE BookingGuid = (SELECT TOP 1 IdGUID FROM dbo.WN_Bookings WITH (NOLOCK) WHERE Id = @BookingId);
                END
                SET @TaxOnServiceCharges = @TaxTotal;
                SET @ServiceCharges      = ROUND(@NetBase * (@AppliedChargePct / 100.0), 4);
                SET @RoomRentExclTax     = @NetBase - @ServiceCharges;
            END
        END
        ELSE
        BEGIN
            -- Zero tax invoices
            SET @RoomRentExclTax     = @NetBase;
            SET @ServiceCharges      = 0.0000;
            SET @TaxOnServiceCharges = 0.0000;
        END
    END
    ELSE
    BEGIN
        SET @RoomRentExclTax     = ISNULL(@RoomRentExclTax, 0.0000);
        SET @ServiceCharges      = ISNULL(@ServiceCharges, 0.0000);
        SET @TaxOnServiceCharges = ISNULL(@TaxOnServiceCharges, 0.0000);
    END
    -- 11. Balance & Fractional Rounding Alignment (Absorb sub-rupee rounding delta)
    DECLARE @CalculatedTotal DECIMAL(18, 4) = @RoomRentExclTax + @ServiceCharges + @TaxOnServiceCharges + @SecAmt;
    DECLARE @RoundingDiff    DECIMAL(18, 4) = @GrandTotal - @CalculatedTotal;
    IF ABS(@RoundingDiff) > 1.00
    BEGIN
        DECLARE @CalcTotalStr VARCHAR(30) = CAST(@CalculatedTotal AS VARCHAR(30));
        DECLARE @GrandTotalStr VARCHAR(30) = CAST(@GrandTotal AS VARCHAR(30));
        RAISERROR('Invoice breakdown amounts sum (%s) does not match GrandTotal (%s).', 16, 1, @CalcTotalStr, @GrandTotalStr);
        RETURN -1;
    END
    ELSE IF @RoundingDiff <> 0.0000
    BEGIN
        IF @RoomRentExclTax > 0
            SET @RoomRentExclTax = @RoomRentExclTax + @RoundingDiff;
        ELSE IF @ServiceCharges > 0
            SET @ServiceCharges = @ServiceCharges + @RoundingDiff;
        ELSE
            SET @RoomRentExclTax = @RoomRentExclTax + @RoundingDiff;
    END
    -- 11b. Withholding tax (WHT) invoice: the booking has SendWhtInvoice = 1 (rate snapshotted on the booking).
    --      Room rent (rent + support) is grossed up as ONE amount so that, after the customer withholds WhtRate%,
    --      the net received is unchanged: GrossRoomRent = ROUND(RoomRentNet / (1 - WhtRate/100), 2).
    --      The rent line absorbs the whole increase: RentLine = GrossRoomRent - SupportCharge. Support charges (fixed
    --      in the DB), the tax on them and the security deposit are NOT grossed up. WhtAmount = GrossRoomRent - RoomRentNet.
    --      Bookings without the flag skip this block entirely.
    DECLARE @IsWhtInvoice BIT = 0;
    DECLARE @WhtNetAmount DECIMAL(18, 4) = 0.0000;
    IF @BookingId IS NOT NULL
    BEGIN
        DECLARE @BkSendWht BIT = 0;
        DECLARE @BkWhtRate DECIMAL(9, 4) = NULL;
        SELECT @BkSendWht = ISNULL(SendWhtInvoice, 0), @BkWhtRate = dbo.WN_WHTaxRate_Resolve(WHTaxId)
        FROM dbo.WN_Bookings WITH (NOLOCK)
        WHERE Id = @BookingId;
        IF @BkSendWht = 1 AND @BkWhtRate > 0 AND @BkWhtRate < 100
        BEGIN
            DECLARE @WhtDivisor DECIMAL(18, 10) = 1.0 - (@BkWhtRate / 100.0);
            SET @IsWhtInvoice        = 1;
            SET @WhtNetAmount        = @RoomRentExclTax + @ServiceCharges;                         -- RoomRentNet
            SET @RoomRentExclTax     = ROUND(@WhtNetAmount / @WhtDivisor, 2) - @ServiceCharges;    -- RentLine = GrossRoomRent - Support
            SET @WHTRate             = @BkWhtRate;
            SET @WHTAmount           = (@RoomRentExclTax + @ServiceCharges) - @WhtNetAmount;       -- GrossRoomRent - RoomRentNet
            SET @TaxTotal            = @TaxOnServiceCharges;
            SET @SubTotal            = @RoomRentExclTax + @ServiceCharges + @DiscountTotal;   -- discount is applied before the gross-up
            SET @GrandTotal          = @RoomRentExclTax + @ServiceCharges + @TaxOnServiceCharges + @SecAmt;
            SET @InvoiceTypeId       = 6;
        END
    END
    -- 12. GL Accounts Resolution (SpaceType -> Spaces -> Parameters -> ChargeTypeMapping)
    DECLARE @ARAccountId            INT = NULL;
    DECLARE @RentAccountId_Loc      INT = NULL;
    DECLARE @SecurityReceivedId_Loc INT = NULL;
    DECLARE @SalesTaxId_Loc         INT = NULL;
    DECLARE @ServicesIncomeId_Loc   INT = NULL;
    DECLARE @WhtAccountId_Loc       INT = NULL;
    DECLARE @ResolvedSpaceId        INT = NULL;
    DECLARE @ResolvedSpaceTypeId    INT = NULL;
    DECLARE @ResolvedWHTaxId        INT = NULL;
    -- (a) Resolve Space, SpaceType, and WHTaxId from Booking
    IF @BookingId IS NOT NULL
    BEGIN
        SELECT TOP 1 
            @ResolvedSpaceId     = b.SpaceId,
            @ResolvedSpaceTypeId = COALESCE(s.SpaceTypeId, (SELECT TOP 1 SpaceTypeId FROM dbo.WN_Spaces WITH (NOLOCK) WHERE Id = b.SpaceId)),
            @ResolvedWHTaxId     = CAST(b.WHTaxId AS INT),
            @LocationId          = COALESCE(@LocationId, s.LocationId)
        FROM dbo.WN_Bookings b WITH (NOLOCK)
        LEFT JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = b.SpaceId
        WHERE b.Id = @BookingId;
    END
    -- (b) Fallback from User’s latest booking if not provided
    IF @ResolvedSpaceId IS NULL AND @UserId IS NOT NULL
    BEGIN
        SELECT TOP 1 
            @ResolvedSpaceId     = b.SpaceId,
            @ResolvedSpaceTypeId = COALESCE(s.SpaceTypeId, (SELECT TOP 1 SpaceTypeId FROM dbo.WN_Spaces WITH (NOLOCK) WHERE Id = b.SpaceId)),
            @ResolvedWHTaxId     = CAST(b.WHTaxId AS INT),
            @LocationId          = COALESCE(@LocationId, s.LocationId)
        FROM dbo.WN_Bookings b WITH (NOLOCK)
        LEFT JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = b.SpaceId
        WHERE b.UserId = @UserId
        ORDER BY b.Id DESC;
    END
    -- (c) If SpaceId is known but SpaceTypeId not yet resolved
    IF @ResolvedSpaceTypeId IS NULL AND @ResolvedSpaceId IS NOT NULL
    BEGIN
        SELECT TOP 1 
            @ResolvedSpaceTypeId = SpaceTypeId,
            @LocationId          = COALESCE(@LocationId, LocationId)
        FROM dbo.WN_Spaces WITH (NOLOCK)
        WHERE Id = @ResolvedSpaceId;
    END
    -- (d) Lookup from WN_SpaceTypes (Space Type accounts)
    DECLARE @StARId   INT = NULL;
    DECLARE @StRentId INT = NULL;
    DECLARE @StSecId  INT = NULL;
    DECLARE @StTaxId  INT = NULL;
    DECLARE @StServId INT = NULL;
    IF @ResolvedSpaceTypeId IS NOT NULL
    BEGIN
        SELECT TOP 1
            @StARId   = NULLIF(AccountReceivableId, 0),
            @StRentId = NULLIF(RentAccountId, 0),
            @StSecId  = NULLIF(SecurityReceivedId, 0),
            @StTaxId  = NULLIF(SalesTaxId, 0),
            @StServId = NULLIF(ServicesIncomeId, 0)
        FROM dbo.WN_SpaceTypes WITH (NOLOCK)
        WHERE Id = @ResolvedSpaceTypeId;
    END
    -- (e) Lookup from WN_Spaces (Space accounts fallback)
    DECLARE @SpARId   INT = NULL;
    DECLARE @SpRentId INT = NULL;
    DECLARE @SpSecId  INT = NULL;
    DECLARE @SpTaxId  INT = NULL;
    DECLARE @SpServId INT = NULL;
    IF @ResolvedSpaceId IS NOT NULL
    BEGIN
        SELECT TOP 1
            @SpARId   = NULLIF(AccountReceivableId, 0),
            @SpRentId = NULLIF(RentAccountId, 0),
            @SpSecId  = COALESCE(NULLIF(SecurityReceivedId, 0), NULLIF(SecurityRecivedId, 0)),
            @SpTaxId  = NULLIF(SalesTaxId, 0),
            @SpServId = NULLIF(ServicesIncomeId, 0)
        FROM dbo.WN_Spaces s WITH (NOLOCK)
        WHERE s.Id = @ResolvedSpaceId;
    END
    -- (f) Lookup WHAccountId from WN_WHTaxRate
    DECLARE @WhtRateAccountId INT = NULL;
    IF @ResolvedWHTaxId IS NOT NULL
    BEGIN
        SELECT TOP 1 @WhtRateAccountId = NULLIF(WHAccountId, 0)
        FROM dbo.WN_WHTaxRate WITH (NOLOCK)
        WHERE Id = @ResolvedWHTaxId;
    END
    IF (@WhtRateAccountId IS NULL OR @WhtRateAccountId = 0) AND @WHTRate > 0
    BEGIN
        SELECT TOP 1 @WhtRateAccountId = NULLIF(WHAccountId, 0)
        FROM dbo.WN_WHTaxRate WITH (NOLOCK)
        WHERE WHRate = @WHTRate
        ORDER BY Id ASC;
    END
    IF (@WhtRateAccountId IS NULL OR @WhtRateAccountId = 0)
    BEGIN
        SELECT TOP 1 @WhtRateAccountId = NULLIF(WHAccountId, 0)
        FROM dbo.WN_WHTaxRate WITH (NOLOCK)
        WHERE WHAccountId IS NOT NULL AND WHAccountId > 0
        ORDER BY Id ASC;
    END
    -- (g) Fallback lookup from WN_ChargeTypeAccountMapping
    DECLARE @MapARId   INT = NULL;
    DECLARE @MapRentId INT = NULL;
    DECLARE @MapSecId  INT = NULL;
    DECLARE @MapTaxId  INT = NULL;
    DECLARE @MapServId INT = NULL;
    DECLARE @MapWhtId  INT = NULL;
    IF @LocationId IS NOT NULL
    BEGIN
        SELECT 
            @MapARId   = MAX(CASE WHEN ChargeTypeId = 1 THEN NULLIF(AccountReceivableId, 0) END),
            @MapRentId = MAX(CASE WHEN ChargeTypeId = 1 THEN NULLIF(RentAccountId, 0) END),
            @MapSecId  = MAX(CASE WHEN ChargeTypeId = 2 THEN NULLIF(SecurityReceivedId, 0) END),
            @MapTaxId  = MAX(CASE WHEN ChargeTypeId = 3 THEN NULLIF(SalesTaxId, 0) END),
            @MapServId = MAX(CASE WHEN ChargeTypeId = 4 THEN NULLIF(ServicesIncomeId, 0) END),
            @MapWhtId  = MAX(NULLIF(WhtAccountId, 0))
        FROM dbo.WN_ChargeTypeAccountMapping WITH (NOLOCK)
        WHERE LocationId = @LocationId
          AND EffectiveFrom <= @IssuedOn
          AND (EffectiveTo IS NULL OR EffectiveTo >= @IssuedOn);
    END
    IF (@MapWhtId IS NULL OR @MapWhtId = 0)
    BEGIN
        SELECT TOP 1 @MapWhtId = NULLIF(WhtAccountId, 0)
        FROM dbo.WN_ChargeTypeAccountMapping WITH (NOLOCK)
        WHERE WhtAccountId IS NOT NULL AND WhtAccountId > 0;
    END
    -- (h) Combine with priority: SpaceType -> Space -> Parameter -> ChargeTypeMapping
    SET @ARAccountId            = COALESCE(@StARId,   @SpARId,   NULLIF(@AccountReceivableId, 0), @MapARId);
    SET @RentAccountId_Loc      = COALESCE(@StRentId, @SpRentId, NULLIF(@RentAccountId, 0),       @MapRentId);
    SET @SecurityReceivedId_Loc = COALESCE(@StSecId,  @SpSecId,  NULLIF(@SecurityReceivedId, 0),  @MapSecId);
    SET @SalesTaxId_Loc         = COALESCE(@StTaxId,  @SpTaxId,  NULLIF(@SalesTaxId, 0),          @MapTaxId);
    SET @ServicesIncomeId_Loc   = COALESCE(@StServId, @SpServId, NULLIF(@ServicesIncomeId, 0),    @MapServId);
    SET @WhtAccountId_Loc       = COALESCE(@WhtRateAccountId, @MapWhtId);
    -- WHT invoices (InvoiceTypeId 6): the five accounts come ONLY from the booked space’s type (WN_SpaceTypes),
    -- each falling back to the booked space (WN_Spaces) when NULL there. No parameter / WN_ChargeTypeAccountMapping
    -- fallback, and no WHT account: WN_WHTaxRate.WHAccountId is not posted.
    IF @IsWhtInvoice = 1
    BEGIN
        SET @ARAccountId            = COALESCE(@StARId,   @SpARId);
        SET @RentAccountId_Loc      = COALESCE(@StRentId, @SpRentId);
        SET @SecurityReceivedId_Loc = COALESCE(@StSecId,  @SpSecId);
        SET @SalesTaxId_Loc         = COALESCE(@StTaxId,  @SpTaxId);
        SET @ServicesIncomeId_Loc   = COALESCE(@StServId, @SpServId);
        SET @WhtAccountId_Loc       = NULL;
    END
    -- Validate required GL account mappings
    IF @PostToLedger = 1
    BEGIN
        DECLARE @IssuedOnStr VARCHAR(30) = CONVERT(VARCHAR(30), @IssuedOn, 120);
        IF @ARAccountId IS NULL
        BEGIN
            RAISERROR('No Accounts Receivable GL account mapped for SpaceType/Space on %s', 16, 1, @IssuedOnStr);
            RETURN -1;
        END
        IF @RoomRentExclTax > 0 AND @RentAccountId_Loc IS NULL
        BEGIN
            RAISERROR('No Room Rent GL account mapped for SpaceType/Space on %s', 16, 1, @IssuedOnStr);
            RETURN -1;
        END
        IF @SecAmt > 0 AND @SecurityReceivedId_Loc IS NULL
        BEGIN
            RAISERROR('No Security Received GL account mapped for SpaceType/Space on %s', 16, 1, @IssuedOnStr);
            RETURN -1;
        END
        IF @TaxOnServiceCharges > 0 AND @SalesTaxId_Loc IS NULL
        BEGIN
            RAISERROR('No Sales Tax GL account mapped for SpaceType/Space on %s', 16, 1, @IssuedOnStr);
            RETURN -1;
        END
        IF @ServiceCharges > 0 AND @ServicesIncomeId_Loc IS NULL
        BEGIN
            RAISERROR('No Services Income GL account mapped for SpaceType/Space on %s', 16, 1, @IssuedOnStr);
            RETURN -1;
        END
    END
    -- Map resolved accounts to invoice header columns
    SET @AccountReceivableId = @ARAccountId;
    SET @RentAccountId       = @RentAccountId_Loc;
    SET @SecurityReceivedId  = @SecurityReceivedId_Loc;
    SET @SalesTaxId          = @SalesTaxId_Loc;
    SET @ServicesIncomeId    = @ServicesIncomeId_Loc;
    IF @AccountsCoaId IS NULL SET @AccountsCoaId = @RentAccountId;
    -- 13. Atomic Transaction & Posting Pipeline
    SET XACT_ABORT ON;
    BEGIN TRY
        BEGIN TRANSACTION;
        -- Step A: Insert into dbo.WN_Invoices
        INSERT INTO dbo.WN_Invoices (
            PublicId,
            InvoiceNumber,
            UserId,
            BookingId,
            MembershipId,
            IssuedOn,
            DueOn,
            SubTotal,
            DiscountTotal,
            TaxTotal,
            GrandTotal,
            PaidTotal,
            CurrencyCode,
            StatusId,
            Notes,
            CreatedOn,
            CreatedById,
            InvoiceTypeId,
            AdvanceRentMonths,
            SecurityDepositMonths,
            SecurityDepositAmount,
            AccountsCoaId,
            BillingPeriodMonths,
            BillingPeriodStart,
            BillingPeriodEnd,
            AccountReceivableId,
            RentAccountId,
            ServicesIncomeId,
            SalesTaxId,
            SecurityReceivedId,
            RoomRentExclTax,
            ServiceCharges,
            TaxOnServiceCharges,
            WHTRate,
            WHTAmount,
            VoucherId
        )
        VALUES (
            @PublicId,
            @InvoiceNumber,
            @UserId,
            @BookingId,
            @MembershipId,
            @IssuedOn,
            @DueOn,
            @SubTotal,
            @DiscountTotal,
            @TaxTotal,
            @GrandTotal,
            @PaidTotal,
            @CurrencyCode,
            @StatusId,
            @Notes,
            SYSUTCDATETIME(),
            @CreatedById,
            @InvoiceTypeId,
            @AdvanceRentMonths,
            @SecurityDepositMonths,
            @SecurityDepositAmount,
            @AccountsCoaId,
            @BillingPeriodMonths,
            @BillingPeriodStart,
            @BillingPeriodEnd,
            @AccountReceivableId,
            @RentAccountId,
            @ServicesIncomeId,
            @SalesTaxId,
            @SecurityReceivedId,
            @RoomRentExclTax,
            @ServiceCharges,
            @TaxOnServiceCharges,
            ISNULL(@WHTRate, 0.0000),
            ISNULL(@WHTAmount, 0.0000),
            @VoucherId
        );
        SET @InvoiceId = SCOPE_IDENTITY();
        SET @GeneratedInvoiceNumber = @InvoiceNumber;
        SET @GeneratedPublicId = @PublicId;
        -- Step B: Update or Insert dbo.WN_SecurityDeposits (RefId = Invoice.Id, RefNo = Invoice.InvoiceNumber, CustomerId = CustomerCode)
        -- Only invoices that carry the deposit point the deposit record at themselves (later rent invoices used to
        -- re-point it, so the deposit report showed the latest rent invoice).
        IF @BookingId IS NOT NULL AND @SecAmt > 0
        BEGIN
            UPDATE dbo.WN_SecurityDeposits
            SET RefId      = @InvoiceId,
                RefNo      = @InvoiceNumber,
                CustomerId = COALESCE(CustomerId, @CustomerCode),
                Amount     = CASE 
                                WHEN (Amount IS NULL OR Amount = 0) AND @SecAmt > 0 THEN @SecAmt 
                                WHEN Amount > 0 AND @SecAmt > Amount THEN @SecAmt
                                ELSE Amount 
                             END
            WHERE BookingId = @BookingId;
            -- If no record existed yet for this booking and security deposit amount > 0, insert it
            IF @SecAmt > 0 AND NOT EXISTS (SELECT 1 FROM dbo.WN_SecurityDeposits WITH (NOLOCK) WHERE BookingId = @BookingId)
            BEGIN
                INSERT INTO dbo.WN_SecurityDeposits
                    (BookingId, UserId, Amount, AccountId, StatusId, Notes, UpdatedById, SecurityReceivedId,
                     AccountReceivableId, RentAccountId, ServicesIncomeId, SalesTaxId, CustomerId, RefId, RefNo)
                VALUES
                    (@BookingId, @UserId, @SecAmt, @SecurityReceivedId, 1, 'Security deposit for invoice ' + @InvoiceNumber, @CreatedById, @SecurityReceivedId,
                     @AccountReceivableId, @RentAccountId, @ServicesIncomeId, @SalesTaxId, @CustomerCode, @InvoiceId, @InvoiceNumber);
            END
        END
        ELSE IF @SecAmt > 0
        BEGIN
            INSERT INTO dbo.WN_SecurityDeposits
                (BookingId, UserId, Amount, AccountId, StatusId, Notes, UpdatedById, SecurityReceivedId,
                 AccountReceivableId, RentAccountId, ServicesIncomeId, SalesTaxId, CustomerId, RefId, RefNo)
            VALUES
                (NULL, @UserId, @SecAmt, @SecurityReceivedId, 1, 'Security deposit for invoice ' + @InvoiceNumber, @CreatedById, @SecurityReceivedId,
                 @AccountReceivableId, @RentAccountId, @ServicesIncomeId, @SalesTaxId, @CustomerCode, @InvoiceId, @InvoiceNumber);
        END
        -- Step C: Customer/Vendor Sync
        IF @SyncCustomerVendor = 1
        BEGIN
            IF OBJECT_ID('dbo.WN_CustomersVendors_SyncOnInvoice', 'P') IS NOT NULL
            BEGIN
                EXEC dbo.WN_CustomersVendors_SyncOnInvoice
                    @CustomerId  = NULL,
                    @UserId      = @UserId,
                    @BookingId   = @BookingId,
                    @CreatedById = @CreatedById;
            END
        END
        -- Step D: Accounting Postings (when @PostToLedger = 1 and @GrandTotal > 0)
        IF @PostToLedger = 1 AND @GrandTotal > 0
        BEGIN
            -- Derive CustomerVendorId if not supplied
            IF @CustomerVendorId IS NULL
            BEGIN
                IF @CustomerCode IS NOT NULL AND @CustomerCode <> ''
                BEGIN
                    SELECT TOP 1 @CustomerVendorId = Id 
                    FROM dbo.CustomersVendors WITH (NOLOCK) 
                    WHERE Code = @CustomerCode 
                    ORDER BY Id DESC;
                END
                IF @CustomerVendorId IS NULL AND @UserId IS NOT NULL
                BEGIN
                    SELECT TOP 1 @CustomerVendorId = cv.Id
                    FROM dbo.CustomersVendors cv WITH (NOLOCK)
                    JOIN dbo.WN_Users u WITH (NOLOCK) ON cv.Email = u.Email
                    WHERE u.Id = @UserId AND cv.Email IS NOT NULL AND cv.Email <> ''
                    ORDER BY cv.Id DESC;
                END
            END
            -- Resolve customer code and display name once at the top of the GL section
            DECLARE @GL_CustomerCode NVARCHAR(50)  = NULLIF(LTRIM(RTRIM(@CustomerCode)), '');
            DECLARE @GL_CustomerName NVARCHAR(255) = NULL;
            IF @GL_CustomerCode IS NOT NULL
            BEGIN
                SELECT TOP 1 
                    @GL_CustomerName = CASE 
                        WHEN c.Company IS NOT NULL AND LTRIM(RTRIM(c.Company)) <> '' THEN LTRIM(RTRIM(c.Company))
                        ELSE NULLIF(LTRIM(RTRIM(CONCAT_WS(' ', NULLIF(LTRIM(RTRIM(c.FirstName)), ''), NULLIF(LTRIM(RTRIM(c.LastName)), '')))), '')
                    END
                FROM dbo.WN_Customers c WITH (NOLOCK)
                WHERE c.Code = @GL_CustomerCode;
            END
            IF (@GL_CustomerName IS NULL OR @GL_CustomerCode IS NULL) AND @BookingId IS NOT NULL
            BEGIN
                SELECT TOP 1 
                    @GL_CustomerCode = COALESCE(@GL_CustomerCode, NULLIF(LTRIM(RTRIM(c.Code)), ''), NULLIF(LTRIM(RTRIM(b.CustomerCode)), '')),
                    @GL_CustomerName = COALESCE(@GL_CustomerName, 
                        CASE 
                            WHEN c.Company IS NOT NULL AND LTRIM(RTRIM(c.Company)) <> '' THEN LTRIM(RTRIM(c.Company))
                            ELSE NULLIF(LTRIM(RTRIM(CONCAT_WS(' ', NULLIF(LTRIM(RTRIM(c.FirstName)), ''), NULLIF(LTRIM(RTRIM(c.LastName)), '')))), '')
                        END)
                FROM dbo.WN_Bookings b WITH (NOLOCK)
                LEFT JOIN dbo.WN_Customers c WITH (NOLOCK) ON (c.Code = b.CustomerCode OR (b.CustomerCode IS NULL AND c.UserId = b.UserId))
                WHERE b.Id = @BookingId;
            END
            IF (@GL_CustomerName IS NULL OR @GL_CustomerCode IS NULL) AND @UserId IS NOT NULL
            BEGIN
                SELECT TOP 1 
                    @GL_CustomerCode = COALESCE(@GL_CustomerCode, NULLIF(LTRIM(RTRIM(c.Code)), '')),
                    @GL_CustomerName = COALESCE(@GL_CustomerName, 
                        CASE 
                            WHEN c.Company IS NOT NULL AND LTRIM(RTRIM(c.Company)) <> '' THEN LTRIM(RTRIM(c.Company))
                            ELSE NULLIF(LTRIM(RTRIM(CONCAT_WS(' ', NULLIF(LTRIM(RTRIM(c.FirstName)), ''), NULLIF(LTRIM(RTRIM(c.LastName)), '')))), '')
                        END)
                FROM dbo.WN_Customers c WITH (NOLOCK)
                WHERE c.UserId = @UserId;
            END
            IF (@GL_CustomerName IS NULL OR @GL_CustomerCode IS NULL) AND @CustomerVendorId IS NOT NULL
            BEGIN
                SELECT TOP 1 
                    @GL_CustomerCode = COALESCE(@GL_CustomerCode, NULLIF(LTRIM(RTRIM(Code)), '')),
                    @GL_CustomerName = COALESCE(@GL_CustomerName, NULLIF(LTRIM(RTRIM(Name)), ''))
                FROM dbo.CustomersVendors WITH (NOLOCK)
                WHERE Id = @CustomerVendorId;
            END
            IF @GL_CustomerName IS NULL AND @UserId IS NOT NULL
            BEGIN
                SELECT TOP 1 
                    @GL_CustomerName = NULLIF(LTRIM(RTRIM(Name)), '')
                FROM dbo.WN_Users WITH (NOLOCK)
                WHERE Id = @UserId;
            END
            -- AR is debited with the invoice total. For a WHT invoice that is G + security deposit, where
            -- G = gross room rent (rounded once in step 11b) + tax: exactly 5 lines, no WHT line.
            DECLARE @ARDebitAmount DECIMAL(18, 4) = @GrandTotal;
            -- WHT invoices post under voucher type 2; every other invoice keeps @VoucherTypeId.
            DECLARE @PostVoucherTypeId TINYINT = CASE WHEN @IsWhtInvoice = 1 THEN 2 ELSE @VoucherTypeId END;
            -- Balance guard (WHT invoices): debits must equal credits, or the whole invoice is rolled back.
            IF @IsWhtInvoice = 1
            BEGIN
                DECLARE @TotalDebits  DECIMAL(18, 4) = @ARDebitAmount;
                DECLARE @TotalCredits DECIMAL(18, 4) =
                      CASE WHEN @RoomRentExclTax > 0 THEN @RoomRentExclTax ELSE 0 END
                    + CASE WHEN @ServiceCharges > 0 THEN @ServiceCharges ELSE 0 END
                    + CASE WHEN @TaxOnServiceCharges > 0 THEN @TaxOnServiceCharges ELSE 0 END
                    + CASE WHEN @SecAmt > 0 THEN @SecAmt ELSE 0 END;
                IF ABS(@TotalDebits - @TotalCredits) > 0.005
                BEGIN
                    DECLARE @DebitsStr VARCHAR(30) = CAST(@TotalDebits AS VARCHAR(30));
                    DECLARE @CreditsStr VARCHAR(30) = CAST(@TotalCredits AS VARCHAR(30));
                    RAISERROR('WHT invoice voucher does not balance: debits %s, credits %s.', 16, 1, @DebitsStr, @CreditsStr);
                END
            END
            -- 1. Create Voucher via dbo.Vouchers_Insert
            DECLARE @VoucherTable TABLE (Id INT, Code VARCHAR(50));
            DECLARE @VoucherShortGUID VARCHAR(50) = CONVERT(VARCHAR(50), NEWID());
            INSERT INTO @VoucherTable (Id, Code)
            EXEC dbo.Vouchers_Insert
                @TypeId              = @PostVoucherTypeId,
                @TransDate           = @IssuedOn,
                @TotalAmount         = @GrandTotal,
                @CompanyId           = @CompanyId,
                @CreatedById         = @CreatedById,
                @ShortGUID           = @VoucherShortGUID,
                @RefNo               = @InvoiceNumber,
                @RefId               = @InvoiceId,
                @BranchId            = @BranchId,
                @FundMangId          = NULL,
                @CreatedByBranchId   = @BranchId,
                @CreatedByCompanyId  = @CompanyId;
            SELECT TOP 1 @VoucherId = Id FROM @VoucherTable;
            IF @VoucherId IS NULL OR @VoucherId <= 0
            BEGIN
                RAISERROR('Failed to create Voucher record for invoice %s', 16, 1, @InvoiceNumber);
            END
            UPDATE dbo.Vouchers
            SET Status = 1
            WHERE Id = @VoucherId;
            UPDATE dbo.WN_Invoices
            SET VoucherId = @VoucherId
            WHERE Id = @InvoiceId;
            -- 2. Create Ledger Entries via dbo.Ledgers_Insert
            -- Resolve Account Titles from AccountsCOA (match on Id)
            DECLARE @TitleAR       NVARCHAR(150) = NULL;
            DECLARE @TitleRent     NVARCHAR(150) = NULL;
            DECLARE @TitleService  NVARCHAR(150) = NULL;
            DECLARE @TitleTax      NVARCHAR(150) = NULL;
            DECLARE @TitleSecurity NVARCHAR(150) = NULL;
            SELECT 
                @TitleAR       = MAX(CASE WHEN Id = @ARAccountId            THEN NULLIF(LTRIM(RTRIM(Description)), '') END),
                @TitleRent     = MAX(CASE WHEN Id = @RentAccountId_Loc      THEN NULLIF(LTRIM(RTRIM(Description)), '') END),
                @TitleService  = MAX(CASE WHEN Id = @ServicesIncomeId_Loc   THEN NULLIF(LTRIM(RTRIM(Description)), '') END),
                @TitleTax      = MAX(CASE WHEN Id = @SalesTaxId_Loc         THEN NULLIF(LTRIM(RTRIM(Description)), '') END),
                @TitleSecurity = MAX(CASE WHEN Id = @SecurityReceivedId_Loc THEN NULLIF(LTRIM(RTRIM(Description)), '') END)
            FROM dbo.AccountsCOA WITH (NOLOCK)
            WHERE Id IN (@ARAccountId, @RentAccountId_Loc, @ServicesIncomeId_Loc, @SalesTaxId_Loc, @SecurityReceivedId_Loc);
            -- Ledger Description format: {AccountsCOA.Title} - {head label} - {InvoiceNo} - {CustomerCode} - {CustomerName}
            DECLARE @DescAR       VARCHAR(500) = LEFT(CONCAT_WS(' - ', @TitleAR, 'Accounts Receivable', @InvoiceNumber, @GL_CustomerName, @GL_CustomerCode), 500);
            DECLARE @DescRent     VARCHAR(500) = LEFT(CONCAT_WS(' - ', @TitleRent, 'Rent', @InvoiceNumber, @GL_CustomerName, @GL_CustomerCode), 500);
            DECLARE @DescService  VARCHAR(500) = LEFT(CONCAT_WS(' - ', @TitleService, 'Services Income', @InvoiceNumber, @GL_CustomerName, @GL_CustomerCode), 500);
            DECLARE @DescTax      VARCHAR(500) = LEFT(CONCAT_WS(' - ', @TitleTax, 'Sales Tax', @InvoiceNumber, @GL_CustomerName, @GL_CustomerCode), 500);
            DECLARE @DescSecurity VARCHAR(500) = LEFT(CONCAT_WS(' - ', @TitleSecurity, 'Security Received', @InvoiceNumber, @GL_CustomerName, @GL_CustomerCode), 500);
            -- CustomerLedger Description format: {AccountsCOA.Title} - {head label} - {InvoiceNo}
            DECLARE @DescCustLedger VARCHAR(500) = LEFT(CONCAT_WS(' - ', @TitleAR, 'Accounts Receivable', @InvoiceNumber), 500);
            -- (a) Accounts Receivable (DEBIT)
            EXEC dbo.Ledgers_Insert
                @VoucherId                   = @VoucherId,
                @AccountId                   = @ARAccountId,
                @Description                 = @DescAR,
                @ProjectId                   = NULL,
                @Debit                       = @ARDebitAmount,
                @Credit                      = 0.0000,
                @VehicleId                   = NULL,
                @ConstructionProjectActiveId = NULL;
            -- (b) Room Rent (CREDIT)
            IF @RoomRentExclTax > 0
            BEGIN
                EXEC dbo.Ledgers_Insert
                    @VoucherId                   = @VoucherId,
                    @AccountId                   = @RentAccountId_Loc,
                    @Description                 = @DescRent,
                    @ProjectId                   = NULL,
                    @Debit                       = 0.0000,
                    @Credit                      = @RoomRentExclTax,
                    @VehicleId                   = NULL,
                    @ConstructionProjectActiveId = NULL;
            END
            -- (c) Services Income (CREDIT)
            IF @ServiceCharges > 0
            BEGIN
                EXEC dbo.Ledgers_Insert
                    @VoucherId                   = @VoucherId,
                    @AccountId                   = @ServicesIncomeId_Loc,
                    @Description                 = @DescService,
                    @ProjectId                   = NULL,
                    @Debit                       = 0.0000,
                    @Credit                      = @ServiceCharges,
                    @VehicleId                   = NULL,
                    @ConstructionProjectActiveId = NULL;
            END
            -- (d) Sales Tax (CREDIT)
            IF @TaxOnServiceCharges > 0
            BEGIN
                EXEC dbo.Ledgers_Insert
                    @VoucherId                   = @VoucherId,
                    @AccountId                   = @SalesTaxId_Loc,
                    @Description                 = @DescTax,
                    @ProjectId                   = NULL,
                    @Debit                       = 0.0000,
                    @Credit                      = @TaxOnServiceCharges,
                    @VehicleId                   = NULL,
                    @ConstructionProjectActiveId = NULL;
            END
            -- (e) Security Deposit Received (CREDIT)
            IF @SecAmt > 0
            BEGIN
                EXEC dbo.Ledgers_Insert
                    @VoucherId                   = @VoucherId,
                    @AccountId                   = @SecurityReceivedId_Loc,
                    @Description                 = @DescSecurity,
                    @ProjectId                   = NULL,
                    @Debit                       = 0.0000,
                    @Credit                      = @SecAmt,
                    @VehicleId                   = NULL,
                    @ConstructionProjectActiveId = NULL;
            END
            -- 3. Create CustomerLedger Entry via dbo.CustomerLedger_Insert (AR DEBIT)
            DECLARE @CustLedgerShortGUID VARCHAR(50) = CONVERT(VARCHAR(50), NEWID());
            EXEC dbo.CustomerLedger_Insert
                @Description         = @DescCustLedger,
                @Debit               = @ARDebitAmount,
                @Credit              = 0.0000,
                @LedgerDate          = @IssuedOn,
                @CustomerVendorId    = @CustomerVendorId,
                @AccountId           = @ARAccountId,
                @Status              = 1,
                @CreatedById         = @CreatedById,
                @ShortGUID           = @CustLedgerShortGUID,
                @CompanyId           = @CompanyId,
                @RefNo               = @InvoiceNumber,
                @RefId               = @InvoiceId,
                @TypeId              = @PostVoucherTypeId,
                @CreatedByBranchId   = @BranchId,
                @CreatedByCompanyId  = @CompanyId,
                @BranchId            = @BranchId;
            UPDATE dbo.CustomerLedger
            SET Status = 1
            WHERE ShortGUID = @CustLedgerShortGUID;
        END
        COMMIT TRANSACTION;
                -- Return output resultset for top-level callers only
        IF @@NESTLEVEL <= 1
        BEGIN
            SELECT 
                @InvoiceId              AS InvoiceId,
                @GeneratedInvoiceNumber AS InvoiceNumber,
                @GeneratedPublicId      AS PublicId,
                @VoucherId              AS VoucherId,
                @GrandTotal             AS TotalAmount;
        END;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();
        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
        RETURN -1;
    END CATCH
END
GO
