-- 5. Stored Procedure: WN_KYCDocumentTypes_GetActive
CREATE   PROCEDURE [dbo].[WN_KYCDocumentTypes_GetActive]
    @Category NVARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT 
        Id,
        Code,
        Name,
        IndividualRequirement,
        BusinessRequirement,
        GroupCode,
        AlternativeCode,
        AllowMultiple,
        RequiresHolderName,
        RequiresExpiry,
        SortOrder,
        IsActive
    FROM dbo.WN_KYCDocumentTypes WITH (NOLOCK)
    WHERE IsActive = 1
      AND (
          @Category IS NULL 
