          OR (@Category = 'Business' AND BusinessRequirement > 0)
          OR (@Category NOT IN ('Individual', 'Business') AND (IndividualRequirement > 0 OR BusinessRequirement > 0))
      )
    ORDER BY SortOrder ASC, Id ASC;
END
