    @Name NVARCHAR(100) = 'StandardLeaseAgreement'
AS
BEGIN
    SET NOCOUNT ON;

    SELECT TOP 1 
        t.Id,
        t.Name,
        t.ContentHtml,
        t.IsActive,
        t.CreatedAt,
        t.CreatedBy,
        u.Email AS CreatedByName
    FROM dbo.WN_LeaseTemplates t WITH (NOLOCK)
