-- 6. Stored Procedure: WN_LeaseTemplates_Publish
CREATE   PROCEDURE [dbo].[WN_LeaseTemplates_Publish]
    @Name NVARCHAR(100),
    @ContentHtml NVARCHAR(MAX),
    @CreatedBy INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;

    BEGIN TRY
        -- Deactivate existing active versions for this template name
        UPDATE dbo.WN_LeaseTemplates
        SET IsActive = 0
        WHERE Name = @Name AND IsActive = 1;

        -- Insert new active version
        INSERT INTO dbo.WN_LeaseTemplates (
            Name,
            ContentHtml,
            IsActive,
            CreatedAt,
            CreatedBy
        )
        OUTPUT 
            INSERTED.Id,
            INSERTED.Name,
            INSERTED.ContentHtml,
            INSERTED.IsActive,
            INSERTED.CreatedAt,
            INSERTED.CreatedBy
        VALUES (
            @Name,
            @ContentHtml,
            1,
            SYSUTCDATETIME(),
            @CreatedBy
        );

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[WN_ListStatusOptions_Get]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[WN_ListStatusOptions_Get]
    @List   NVARCHAR(20),
    @Today  DATE         = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @Today IS NULL SET @Today = CAST(GETDATE() AS DATE);
    IF @List = 'bookings'
        SELECT CAST(bs.Id AS NVARCHAR(50)) AS Value, LTRIM(RTRIM(bs.Label)) AS Label
        FROM dbo.WN_BookingStatuses bs WITH (NOLOCK)
        WHERE NULLIF(LTRIM(RTRIM(bs.Label)), '') IS NOT NULL
        ORDER BY Label;
    ELSE IF @List = 'quotations'
        SELECT DISTINCT CAST(LTRIM(RTRIM(q.Status)) AS NVARCHAR(50)) AS Value, CAST(LTRIM(RTRIM(q.Status)) AS NVARCHAR(100)) AS Label
        FROM dbo.WN_Quotations q WITH (NOLOCK)
        WHERE NULLIF(LTRIM(RTRIM(q.Status)), '') IS NOT NULL
        ORDER BY Value;
    ELSE IF @List = 'invoices'
        SELECT DISTINCT CAST(ls.ListStatus AS NVARCHAR(50)) AS Value, CAST(ls.ListStatus AS NVARCHAR(100)) AS Label
        FROM dbo.WN_Invoices i WITH (NOLOCK)
        CROSS APPLY (
            SELECT COALESCE(
                CASE i.StatusId WHEN 1 THEN 'Unpaid' WHEN 2 THEN 'Paid' WHEN 3 THEN 'Partial' WHEN 4 THEN 'Overdue' WHEN 5 THEN 'Cancelled' END,
                (SELECT CASE LTRIM(RTRIM(os.Description)) WHEN 'Un Paid' THEN 'Unpaid' WHEN 'Challan Expire' THEN 'Overdue' ELSE LTRIM(RTRIM(os.Description)) END
                 FROM dbo.OrderStatus os WITH (NOLOCK) WHERE os.Id = i.StatusId),
                'Unknown') AS StatusLabel
        ) sl
        CROSS APPLY (
            SELECT CASE
                WHEN sl.StatusLabel IN ('Unpaid', 'Paid', 'Partial', 'Overdue', 'Cancelled') THEN sl.StatusLabel
                WHEN ISNULL(i.GrandTotal, 0) > 0 AND ISNULL(i.PaidTotal, 0) >= ISNULL(i.GrandTotal, 0) THEN 'Paid'
                WHEN ISNULL(i.PaidTotal, 0) > 0 THEN 'Partial'
                ELSE 'Unpaid' END AS BaseStatus
        ) bst
        CROSS APPLY (
            SELECT CASE WHEN bst.BaseStatus IN ('Unpaid', 'Partial') AND i.DueOn < @Today THEN 'Overdue' ELSE bst.BaseStatus END AS ListStatus
        ) ls
        WHERE i.StatusId <> 40
        ORDER BY Value;
    ELSE IF @List = 'payments'
        SELECT DISTINCT CAST(ISNULL(p.StatusId, 1) AS NVARCHAR(50)) AS Value,
               CAST(CASE WHEN ISNULL(p.StatusId, 1) = 2 THEN 'Paid' WHEN ISNULL(p.StatusId, 1) = 3 THEN 'Failed' WHEN ISNULL(p.StatusId, 1) = 4 THEN 'Refunded' WHEN ISNULL(p.StatusId, 1) = 5 THEN 'Cancelled' ELSE 'Pending' END AS NVARCHAR(100)) AS Label
        FROM dbo.WN_Payments p WITH (NOLOCK)
        ORDER BY Label;
    ELSE IF @List = 'customers'
        SELECT DISTINCT CAST(CASE WHEN ISNULL(c.IsActive, 0) = 1 THEN '1' ELSE '0' END AS NVARCHAR(50)) AS Value,
               CAST(CASE WHEN ISNULL(c.IsActive, 0) = 1 THEN 'Active' ELSE 'Inactive' END AS NVARCHAR(100)) AS Label
        FROM dbo.WN_Customers c WITH (NOLOCK)
        ORDER BY Label;
    ELSE
        SELECT CAST(NULL AS NVARCHAR(50)) AS Value, CAST(NULL AS NVARCHAR(100)) AS Label WHERE 1 = 0;
END;
GO
