CREATE   PROCEDURE [dbo].[WN_Locations_Insert]
    @BranchId    INT,
    @Name        NVARCHAR(MAX),
    @Address     NVARCHAR(MAX) = NULL,
    @CityId      INT,
    @OpeningTime NVARCHAR(10)  = NULL,
