-- 3. Procedure: Record a Login/Logout/Failed event
CREATE   PROCEDURE [dbo].[WN_LoginHistory_Insert]
    @UserId INT = NULL,
    @Email NVARCHAR(256) = NULL,
    @EventType VARCHAR(10),
    @FailureReason NVARCHAR(100) = NULL,
    @IpAddress VARCHAR(45) = NULL,
    @UserAgent NVARCHAR(400) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    INSERT INTO dbo.WN_LoginHistory (
        UserId,
        Email,
        EventType,
        FailureReason,
        IpAddress,
        UserAgent,
        EventAt
    )
    VALUES (
        @UserId,
        @Email,
        @EventType,
        @FailureReason,
        @IpAddress,
        @UserAgent,
        SYSUTCDATETIME()
    );

    SELECT SCOPE_IDENTITY() AS LoginId;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_MeetingRooms_BookFree]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_MeetingRooms_BookFree]
    @UserId        INT,
    @SpaceId       INT,
    @StartOn       DATETIME2,            -- Pakistan wall-clock time, as every booking StartOn
    @DurationHours INT,
    @Notes         NVARCHAR(MAX) = NULL,
    @CreatedById   INT           = NULL
AS
BEGIN
    -- MR_01: book a meeting room with free hours. Checks what dbo.WN_Bookings_InsertFreeMeetingRoom does not: the start
    -- is in the future (Pakistan time) and the room is at the location of the private office booking whose hours are
    -- charged (the one that procedure takes: own, Confirmed, PrivateOffice, covering the day, earliest start first; the
    -- same as dbo.WN_MeetingRooms_GetEntitlement and dbo.WN_MeetingRooms_GetRooms). Makes sure the month allowance row exists (dbo.WN_BookingMeetingRoomEntitlements_Generate,
    -- for the private office booking the insert procedure uses), then runs dbo.WN_Bookings_InsertFreeMeetingRoom, which
    -- checks 1-3 hours, the remaining hours and overlapping bookings in one transaction (no transaction here: that
    -- procedure commits or rolls back its own). Result columns as that procedure: BookingId, BookingPublicId,
    -- ChallanNumber, ChallanValidUntil, ErrorMessage (NULL = booked).
    SET NOCOUNT ON;
    DECLARE @Now DATETIME2 = CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2);
    DECLARE @UsageDate DATE = CAST(@StartOn AS DATE);
    DECLARE @MonthStart DATE = DATEFROMPARTS(YEAR(@UsageDate), MONTH(@UsageDate), 1);
    DECLARE @PrivateBookingId INT = NULL;
    DECLARE @PrivateLocationId INT = NULL;
    DECLARE @PrivateLocationName NVARCHAR(255) = NULL;
    DECLARE @Error NVARCHAR(4000) = NULL;
    IF @StartOn IS NULL OR @StartOn <= @Now
        SET @Error = N'The start time must be in the future.';
    IF @Error IS NULL
    BEGIN
        -- the private office booking dbo.WN_Bookings_InsertFreeMeetingRoom takes (same rules)
        SELECT TOP 1 @PrivateBookingId = b.Id, @PrivateLocationId = s.LocationId, @PrivateLocationName = l.Name
          FROM dbo.WN_Bookings b WITH (NOLOCK)
          JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = b.SpaceId
          JOIN dbo.WN_SpaceTypes st WITH (NOLOCK) ON st.Id = s.SpaceTypeId
          LEFT JOIN dbo.WN_Locations l WITH (NOLOCK) ON l.Id = s.LocationId
         WHERE b.UserId = @UserId
           AND b.BookingStatusId = 33
           AND b.IsDeleted = 0
           AND st.CategoryId = 1
           AND @UsageDate >= CAST(b.StartOn AS DATE)
           AND @UsageDate <= CAST(b.EndOn AS DATE)
         ORDER BY b.StartOn ASC;
        IF @PrivateBookingId IS NULL
            SET @Error = N'No active private-space booking covers the requested date.';
    END
    IF @Error IS NULL AND NOT EXISTS (SELECT 1
                                        FROM dbo.WN_Spaces s WITH (NOLOCK)
                                        JOIN dbo.WN_SpaceTypes st WITH (NOLOCK) ON st.Id = s.SpaceTypeId
                                       WHERE s.Id = @SpaceId AND s.IsActive = 1 AND st.CategoryId = 2)
        SET @Error = N'Selected space is not an active meeting room.';
    IF @Error IS NULL AND NOT EXISTS (SELECT 1
                                        FROM dbo.WN_Spaces m WITH (NOLOCK)
                                       WHERE m.Id = @SpaceId
                                         AND m.LocationId = @PrivateLocationId)
        SET @Error = CASE WHEN @PrivateLocationName IS NULL
                          THEN N'Your free hours for this date can only be used for a meeting room at the location of your private office.'
                          ELSE N'Your free hours for this date can only be used for a meeting room at ' + @PrivateLocationName + N' (the location of your private office).' END;
    IF @Error IS NOT NULL
    BEGIN
        SELECT CAST(NULL AS INT)              AS BookingId,
               CAST(NULL AS UNIQUEIDENTIFIER) AS BookingPublicId,
               CAST(NULL AS NVARCHAR(50))     AS ChallanNumber,
               CAST(NULL AS DATE)             AS ChallanValidUntil,
               @Error                         AS ErrorMessage;
        RETURN;
    END
    IF NOT EXISTS (SELECT 1 FROM dbo.WN_BookingMeetingRoomEntitlements WITH (NOLOCK)
                    WHERE BookingId = @PrivateBookingId AND MonthStartDate = @MonthStart)
    BEGIN
        BEGIN TRY
            EXEC dbo.WN_BookingMeetingRoomEntitlements_Generate @BookingId = @PrivateBookingId, @UserId = @UserId, @StartOn = @UsageDate, @EndOn = @UsageDate;
        END TRY
        BEGIN CATCH
            -- 2601 / 2627: a request at the same moment created the same row (UQ_Booking_Month)
            IF ERROR_NUMBER() NOT IN (2601, 2627) THROW;
        END CATCH
    END
    EXEC dbo.WN_Bookings_InsertFreeMeetingRoom @UserId = @UserId, @SpaceId = @SpaceId, @StartOn = @StartOn,
         @DurationHours = @DurationHours, @Notes = @Notes, @CreatedById = @CreatedById;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_MeetingRooms_CancelFree]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_MeetingRooms_CancelFree]
    @BookingId    INT,
    @UserId       INT,
    @CancelReason NVARCHAR(400) = NULL,  -- fits WN_MeetingRoomUsageLogs.Remarks (500) with the space added before it
    @UpdatedById  INT           = NULL
AS
BEGIN
    -- MR_01: a customer cancels their own free meeting-room booking. It must be theirs (WN_Bookings.UserId), free
    -- (IsFree = 1), not deleted, still Confirmed (33) and not started yet (Pakistan time). Then
    -- dbo.WN_Bookings_CancelFreeMeetingRoom cancels it (status 86) and its usage row, so the hours go back to the month.
    -- Result: BookingId, Cancelled (1 = done), NotFound (1 = no such free booking of this user), ErrorMessage.
    SET NOCOUNT ON;
    DECLARE @Now DATETIME2 = CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2);
    DECLARE @Found BIT = 0;
    DECLARE @StatusId INT = NULL;
    DECLARE @StartOn DATETIME2 = NULL;
    DECLARE @Error NVARCHAR(4000) = NULL;
    SELECT @Found = 1, @StatusId = b.BookingStatusId, @StartOn = b.StartOn
      FROM dbo.WN_Bookings b WITH (NOLOCK)
     WHERE b.Id = @BookingId
       AND b.UserId = @UserId
       AND b.IsFree = 1
       AND b.IsDeleted = 0;
    SET @Error = CASE WHEN @Found = 0 THEN N'Free meeting-room booking not found.'
                      WHEN @StatusId = 86 THEN N'This booking is already cancelled.'
                      WHEN ISNULL(@StatusId, 0) <> 33 THEN N'Only a confirmed booking can be cancelled.'
                      WHEN @StartOn <= @Now THEN N'This booking has already started, so it can no longer be cancelled.'
                      ELSE NULL END;
    IF @Error IS NULL
    BEGIN
        BEGIN TRY
            EXEC dbo.WN_Bookings_CancelFreeMeetingRoom @BookingId = @BookingId, @UserEmail = NULL,
                 @CancelReason = @CancelReason, @UpdatedById = @UpdatedById;
        END TRY
        BEGIN CATCH
            SET @Error = ERROR_MESSAGE();
        END CATCH
    END
    SELECT @BookingId                                              AS BookingId,
           CAST(CASE WHEN @Error IS NULL THEN 1 ELSE 0 END AS BIT) AS Cancelled,
           CAST(CASE WHEN @Found = 0 THEN 1 ELSE 0 END AS BIT)     AS NotFound,
           @Error                                                  AS ErrorMessage;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_MeetingRooms_GetEntitlement]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_MeetingRooms_GetEntitlement]
    @UserId INT,
    @Date   DATE = NULL   -- NULL = today (Pakistan)
AS
BEGIN
    -- MR_01: the free meeting-room allowance of @UserId for the calendar month of @Date.
    -- The private office booking is chosen exactly as dbo.WN_Bookings_InsertFreeMeetingRoom chooses it (own booking,
    -- Confirmed 33, not deleted, PrivateOffice category 1, covering the date, earliest start first), so the hours shown
    -- are the hours a booking can use. No row = no allowance on that date.
    SET NOCOUNT ON;
    IF @Date IS NULL SET @Date = CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE);
    DECLARE @PrivateBookingId INT = NULL;
    DECLARE @MonthStart DATE = DATEFROMPARTS(YEAR(@Date), MONTH(@Date), 1);
    SELECT TOP 1 @PrivateBookingId = b.Id
      FROM dbo.WN_Bookings b WITH (NOLOCK)
      JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = b.SpaceId
      JOIN dbo.WN_SpaceTypes st WITH (NOLOCK) ON st.Id = s.SpaceTypeId
     WHERE b.UserId = @UserId
       AND b.BookingStatusId = 33
       AND b.IsDeleted = 0
       AND st.CategoryId = 1
       AND @Date >= CAST(b.StartOn AS DATE)
       AND @Date <= CAST(b.EndOn AS DATE)
     ORDER BY b.StartOn ASC;
    IF @PrivateBookingId IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM dbo.WN_BookingMeetingRoomEntitlements WITH (NOLOCK)
                        WHERE BookingId = @PrivateBookingId AND MonthStartDate = @MonthStart)
    BEGIN
        BEGIN TRY
            -- creates only the month of @Date (the procedure skips a month that already has a row)
            EXEC dbo.WN_BookingMeetingRoomEntitlements_Generate @BookingId = @PrivateBookingId, @UserId = @UserId, @StartOn = @Date, @EndOn = @Date;
        END TRY
        BEGIN CATCH
            -- 2601 / 2627: a request at the same moment created the same row (UQ_Booking_Month); it is read below
            IF ERROR_NUMBER() NOT IN (2601, 2627) THROW;
        END CATCH
    END
    SELECT e.Id                                  AS EntitlementId,
           e.Guid                                AS EntitlementPublicId,
           e.BookingId                           AS PrivateBookingId,
           e.UserId,
           e.MonthStartDate,
           e.MonthEndDate,
           e.AllocatedMinutes,
           used.UsedMinutes,
           e.AllocatedMinutes - used.UsedMinutes AS RemainingMinutes,
           e.Status,
           ps.Code                               AS PrivateSpaceCode,
           ps.Name                               AS PrivateSpaceName,
           ps.LocationId,
           l.Name                                AS LocationName,
           pb.StartOn                            AS PrivateBookingStartOn,
           pb.EndOn                              AS PrivateBookingEndOn,
           CAST(3 AS INT)                        AS MaxBookingHours -- dbo.WN_Bookings_InsertFreeMeetingRoom: 1, 2 or 3 hours
      FROM dbo.WN_BookingMeetingRoomEntitlements e WITH (NOLOCK)
      JOIN dbo.WN_Bookings pb WITH (NOLOCK) ON pb.Id = e.BookingId
      LEFT JOIN dbo.WN_Spaces ps WITH (NOLOCK) ON ps.Id = pb.SpaceId
      LEFT JOIN dbo.WN_Locations l WITH (NOLOCK) ON l.Id = ps.LocationId
     OUTER APPLY (SELECT ISNULL(SUM(u.UsedMinutes), 0) AS UsedMinutes
                    FROM dbo.WN_MeetingRoomUsageLogs u WITH (NOLOCK)
                   WHERE u.EntitlementId = e.Id AND u.Status <> N'Cancelled') used
     WHERE e.BookingId = @PrivateBookingId
       AND e.MonthStartDate = @MonthStart;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_MeetingRooms_GetMyFree]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_MeetingRooms_GetMyFree]
    @UserId INT
AS
BEGIN
    -- MR_01 (read-only): the free meeting-room bookings of @UserId (WN_Bookings.IsFree = 1, not deleted), newest first.
    -- CanCancel = the rule of dbo.WN_MeetingRooms_CancelFree (Confirmed 33 and not started yet, Pakistan time);
    -- IsPast = already ended. Status code / label from WN_BookingStatuses.
    SET NOCOUNT ON;
    DECLARE @Now DATETIME2 = CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATETIME2);
    SELECT b.Id                                    AS BookingId,
           b.IdGUID                                AS BookingPublicId,
           b.SpaceId,
           s.Code                                  AS SpaceCode,
           s.Name                                  AS SpaceName,
           l.Name                                  AS LocationName,
           b.StartOn,
           b.EndOn,
           DATEDIFF(MINUTE, b.StartOn, b.EndOn)    AS DurationMinutes,
           CAST(b.BookingStatusId AS INT)          AS BookingStatusId,
           bs.Code                                 AS BookingStatusCode,
           bs.Label                                AS BookingStatusLabel,
           b.ChallanNumber,
           b.Notes,
           b.CancelReason,
           b.CreatedOn,
           CAST(CASE WHEN b.BookingStatusId = 33 AND b.StartOn > @Now THEN 1 ELSE 0 END AS BIT) AS CanCancel,
           CAST(CASE WHEN b.EndOn <= @Now THEN 1 ELSE 0 END AS BIT)                             AS IsPast
      FROM dbo.WN_Bookings b WITH (NOLOCK)
      LEFT JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = b.SpaceId
      LEFT JOIN dbo.WN_Locations l WITH (NOLOCK) ON l.Id = s.LocationId
      LEFT JOIN dbo.WN_BookingStatuses bs WITH (NOLOCK) ON bs.Id = b.BookingStatusId
     WHERE b.UserId = @UserId
       AND b.IsFree = 1
       AND b.IsDeleted = 0
     ORDER BY b.StartOn DESC, b.Id DESC;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_MeetingRooms_GetRooms]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_MeetingRooms_GetRooms]
    @UserId INT,
    @Date   DATE = NULL   -- NULL = today (Pakistan)
AS
BEGIN
    -- MR_01 (read-only): the meeting rooms @UserId may book with free hours on @Date = active spaces of the MeetingRoom
    -- category (2, as dbo.WN_Bookings_InsertFreeMeetingRoom) at the location of the private office booking whose hours
    -- are charged on @Date: the one dbo.WN_Bookings_InsertFreeMeetingRoom and dbo.WN_MeetingRooms_GetEntitlement take
    -- (own, Confirmed 33, not deleted, PrivateOffice category 1, covering @Date, earliest start first). None = no rooms.
    -- Result 1: the rooms. Result 2: the times each room is taken that day, from the bookings that block a free booking
    -- in dbo.WN_Bookings_InsertFreeMeetingRoom (not deleted, status 1, 2, 5 or 33). Times only, no customer details.
    SET NOCOUNT ON;
    IF @Date IS NULL SET @Date = CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE);
    DECLARE @DayStart DATETIME2 = CAST(@Date AS DATETIME2);
    DECLARE @DayEnd DATETIME2 = DATEADD(DAY, 1, CAST(@Date AS DATETIME2));
    DECLARE @PrivateBookingId INT = NULL;
    DECLARE @PrivateLocationId INT = NULL;
    DECLARE @Rooms TABLE (SpaceId INT PRIMARY KEY);
    SELECT TOP 1 @PrivateBookingId = b.Id, @PrivateLocationId = s.LocationId
      FROM dbo.WN_Bookings b WITH (NOLOCK)
      JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = b.SpaceId
      JOIN dbo.WN_SpaceTypes st WITH (NOLOCK) ON st.Id = s.SpaceTypeId
     WHERE b.UserId = @UserId
       AND b.BookingStatusId = 33
       AND b.IsDeleted = 0
       AND st.CategoryId = 1
       AND @Date >= CAST(b.StartOn AS DATE)
       AND @Date <= CAST(b.EndOn AS DATE)
     ORDER BY b.StartOn ASC;
    IF @PrivateBookingId IS NOT NULL
        INSERT INTO @Rooms (SpaceId)
        SELECT s.Id
          FROM dbo.WN_Spaces s WITH (NOLOCK)
          JOIN dbo.WN_SpaceTypes st WITH (NOLOCK) ON st.Id = s.SpaceTypeId
         WHERE s.IsActive = 1
           AND st.CategoryId = 2
           AND s.LocationId = @PrivateLocationId;
    SELECT s.Id     AS SpaceId,
           s.IdGUID AS SpacePublicId,
           s.Code   AS SpaceCode,
           s.Name   AS SpaceName,
           s.Capacity,
           s.LocationId,
           l.Name   AS LocationName
      FROM @Rooms r
      JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = r.SpaceId
      LEFT JOIN dbo.WN_Locations l WITH (NOLOCK) ON l.Id = s.LocationId
     ORDER BY l.Name, s.Name, s.Id;
    SELECT b.SpaceId,
           b.StartOn,
           b.EndOn
      FROM dbo.WN_Bookings b WITH (NOLOCK)
      JOIN @Rooms r ON r.SpaceId = b.SpaceId
     WHERE b.IsDeleted = 0
       AND b.BookingStatusId IN (1, 2, 5, 33)
       AND b.StartOn < @DayEnd
       AND b.EndOn > @DayStart
     ORDER BY b.SpaceId, b.StartOn;
END;
GO
