CREATE   PROCEDURE [dbo].[WN_Payments_Delete]
    @Id INT
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE dbo.WN_Payments SET StatusId = 5, UpdatedOn = SYSUTCDATETIME()
    WHERE Id = @Id;
