CREATE   PROCEDURE [dbo].[WN_Payments_UpdateStatus]
    @Id          INT,
    @StatusId    TINYINT,
    @UpdatedById INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE dbo.WN_Payments SET
        StatusId  = @StatusId,
        PaidOn    = CASE WHEN @StatusId = 2 THEN SYSUTCDATETIME() ELSE PaidOn END,
        UpdatedOn = SYSUTCDATETIME()
    WHERE Id = @Id;
END
GO
/****** Object:  StoredProcedure [dbo].[WN_Payments_UpdateStatusByGuid]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_Payments_UpdateStatusByGuid]
    @IdGUID UNIQUEIDENTIFIER,
    @Status NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;
            DECLARE @StatusId TINYINT = ISNULL(TRY_CAST(@Status AS TINYINT), 1);

            UPDATE dbo.WN_Payments
            SET    StatusId  = @StatusId,
                   PaidOn    = CASE WHEN @StatusId = 2 THEN SYSUTCDATETIME() ELSE PaidOn END,
                   UpdatedOn = SYSUTCDATETIME()
            WHERE  IdGUID = @IdGUID;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END
GO
