/****** Object:  StoredProcedure [dbo].[WN_Quotations_GetList]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_Quotations_GetList]
    @Page   INT = 1,
    @Limit  INT = 10,
    @Search NVARCHAR(100) = NULL,
    @LocationId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Offset INT = (@Page - 1) * @Limit;

    DECLARE @Total INT;
    SELECT @Total = COUNT(*)
    FROM dbo.WN_Quotations q
    JOIN dbo.WN_Customers c ON c.Id = q.CustomerId
    JOIN dbo.WN_Spaces s ON s.Id = q.SpaceId
    WHERE (@Search IS NULL OR q.QuotationNumber LIKE '%' + @Search + '%' OR c.FirstName LIKE '%' + @Search + '%' OR c.LastName LIKE '%' + @Search + '%' OR c.Company LIKE '%' + @Search + '%')
      AND (@LocationId IS NULL OR s.LocationId = @LocationId);

    SELECT 
        q.Id,
        q.Guid,
        q.QuotationNumber,
        q.QuotationDate,
        q.ValidUntil,
        q.CustomerId,
        RTRIM(LTRIM(ISNULL(c.FirstName, '') + ' ' + ISNULL(c.LastName, ''))) AS CustomerName,
        c.Company AS CustomerCompany,
        c.Email AS CustomerEmail,
        c.Address AS CustomerAddress,
        q.SpaceId,
        s.Name AS SpaceName,
        s.Code AS SpaceCode,
        st.Name AS SpaceTypeName,
        loc.Name AS LocationName,
        loc.Address AS LocationAddress,
        ISNULL(NULLIF(city.Description, ''), ISNULL(NULLIF(loc.City, ''), 'Islamabad')) AS CityName,
        q.StartDateTime,
        q.EndDateTime,
        q.SubtotalAmount,
        q.DiscountPercentage,
        q.DiscountAmount,
        q.DiscountType,
        q.SecurityDeposit,
        q.TotalAmount,
        ISNULL(q.SupportChargesId, 4) AS SupportChargesId,
        ISNULL(q.AppliedChargePercentage, 10.00) AS AppliedChargePercentage,
        ISNULL(q.AppliedTaxPercentage, 0.00) AS AppliedTaxPercentage,
        ISNULL(q.SupportChargeAmount, 0.00) AS SupportChargeAmount,
        ISNULL(q.TaxAmount, 0.00) AS TaxAmount,
        ISNULL(q.TaxAmount, 0.00) AS TaxAmountOnAdvanceRent,
        ISNULL(q.TaxAmount, 0.00) AS TaxAmountOnContract,
        ISNULL(q.PerSeatSupportRate, 2000.00) AS PerSeatSupportRate,
        q.Remarks,
        q.Status,
        q.Version,
        q.IsActive,
        q.FloorId,
        q.PerSeatBasePrice,
        q.Capacity,
        q.MonthlyBasePrice,
        q.MaxDiscountPercent,
        q.SecurityDepositMonths,
        q.OfferingType,
        q.WHTaxId,
        ISNULL(q.SendWhtInvoice, 0) AS SendWhtInvoice,
        ot.Id AS OfferingTypeId,
        ISNULL(ot.Description, q.OfferingType) AS OfferingTypeDescription,
        ISNULL(ot.DiscountCap, 10.00) AS OfferingTypeDiscountCap,
        ISNULL(q.BillingPeriodMonths, 3) AS BillingPeriodMonths,
        CASE 
          WHEN ISNULL(q.BillingPeriodMonths, 3) = 1 THEN '1 Month (Per Month)'
          WHEN ISNULL(q.BillingPeriodMonths, 3) = 2 THEN '2 Months'
          WHEN ISNULL(q.BillingPeriodMonths, 3) = 3 THEN '3 Months (Quarterly)'
          WHEN ISNULL(q.BillingPeriodMonths, 3) = 6 THEN '6 Months (Semi-Annual)'
          WHEN ISNULL(q.BillingPeriodMonths, 3) = 12 THEN '12 Months (Annual)'
          ELSE CAST(ISNULL(q.BillingPeriodMonths, 3) AS NVARCHAR(10)) + ' Month(s)'
        END AS BillingPeriodLabel,
        CASE 
          WHEN ISNULL(q.BillingPeriodMonths, 3) = 1 THEN '1 Month (Per Month)'
          WHEN ISNULL(q.BillingPeriodMonths, 3) = 2 THEN '2 Months'
          WHEN ISNULL(q.BillingPeriodMonths, 3) = 3 THEN '3 Months (Quarterly)'
          WHEN ISNULL(q.BillingPeriodMonths, 3) = 6 THEN '6 Months (Semi-Annual)'
          WHEN ISNULL(q.BillingPeriodMonths, 3) = 12 THEN '12 Months (Annual)'
          ELSE CAST(ISNULL(q.BillingPeriodMonths, 3) AS NVARCHAR(10)) + ' Month(s)'
        END AS BillingPeriod,
        @Total AS TotalCount
    FROM dbo.WN_Quotations q
    JOIN dbo.WN_Customers c ON c.Id = q.CustomerId
    JOIN dbo.WN_Spaces s ON s.Id = q.SpaceId
    LEFT JOIN dbo.WN_SpaceTypes st ON st.Id = s.SpaceTypeId
    LEFT JOIN dbo.WN_Locations loc ON loc.Id = s.LocationId
    LEFT JOIN dbo.City city ON city.Id = loc.CityId
    LEFT JOIN dbo.WN_OfferingType ot ON (TRY_CAST(q.OfferingType AS INT) = ot.Id OR ot.Description = q.OfferingType)
    WHERE (@Search IS NULL OR q.QuotationNumber LIKE '%' + @Search + '%' OR c.FirstName LIKE '%' + @Search + '%' OR c.LastName LIKE '%' + @Search + '%' OR c.Company LIKE '%' + @Search + '%')
      AND (@LocationId IS NULL OR s.LocationId = @LocationId)
    ORDER BY q.Id DESC
    OFFSET @Offset ROWS FETCH NEXT @Limit ROWS ONLY;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Quotations_GetListFiltered]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_Quotations_GetListFiltered]
    @Page        INT           = 1,
    @Limit       INT           = 10,
    @Search      NVARCHAR(100) = NULL,
    @LocationId  INT           = NULL,
    @Status      NVARCHAR(50)  = NULL,  -- WN_Quotations.Status (NULL = every status)
    @DateFrom    DATETIME2(0)  = NULL,  -- quotation date from (inclusive)
    @DateTo      DATETIME2(0)  = NULL   -- quotation date before (exclusive)
AS
BEGIN
    -- LST_01: the admin Quotations list with filters. Same rows, search and order as dbo.WN_Quotations_GetList
    -- (quotations of a customer and a space; the location is the location of the quoted space). Returns the ids only:
    -- the API reads each quotation in full, as it does for WN_Quotations_GetList. Called only when a status or a
    -- date range is chosen.
    SET NOCOUNT ON;
    IF @Page < 1 SET @Page = 1;
    IF @Limit < 1 SET @Limit = 10;
    DECLARE @Offset INT = (@Page - 1) * @Limit;
    SELECT
        q.Id,
        q.QuotationNumber,
        q.QuotationDate,
        q.Status,
        COUNT(*) OVER () AS TotalCount
    FROM dbo.WN_Quotations q WITH (NOLOCK)
    JOIN dbo.WN_Customers c WITH (NOLOCK) ON c.Id = q.CustomerId
    JOIN dbo.WN_Spaces s WITH (NOLOCK) ON s.Id = q.SpaceId
    WHERE (@Search IS NULL OR q.QuotationNumber LIKE '%' + @Search + '%' OR c.FirstName LIKE '%' + @Search + '%' OR c.LastName LIKE '%' + @Search + '%' OR c.Company LIKE '%' + @Search + '%')
      AND (@LocationId IS NULL OR s.LocationId = @LocationId)
      AND (@Status IS NULL OR LTRIM(RTRIM(q.Status)) = @Status)
      AND (@DateFrom IS NULL OR q.QuotationDate >= @DateFrom)
      AND (@DateTo IS NULL OR q.QuotationDate < @DateTo)
    ORDER BY q.Id DESC
    OFFSET @Offset ROWS FETCH NEXT @Limit ROWS ONLY;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_Quotations_GetLocationAndCompanyDetails]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
