GO
CREATE   PROCEDURE [dbo].[WN_ServiceSwitches_GetAll]
AS
BEGIN
    -- SS_01: every background service switch (the API caches them for 10 seconds). A service without a row runs.
    SET NOCOUNT ON;
    SELECT s.ServiceName, s.IsEnabled, s.UpdatedBy, s.UpdatedAt
      FROM dbo.WN_ServiceSwitches s WITH (NOLOCK)
     ORDER BY s.ServiceName;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_ServiceSwitches_Set]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_ServiceSwitches_Set]
    @ServiceName NVARCHAR(100),
    @IsEnabled   BIT,
    @UpdatedBy   NVARCHAR(100) = NULL
AS
BEGIN
    -- SS_01: turns one background service on (1) or off (0). The row changes only when the value really changes, so
    -- every audit row (dbo.TR_WN_ServiceSwitches_Audit) is a real change; UpdatedBy and UpdatedAt are stamped with it.
    -- Returns the row afterwards; no row = unknown service name.
    SET NOCOUNT ON;
    UPDATE dbo.WN_ServiceSwitches
       SET IsEnabled = @IsEnabled,
           UpdatedBy = @UpdatedBy,
           UpdatedAt = SYSUTCDATETIME()
     WHERE ServiceName = @ServiceName
       AND IsEnabled <> @IsEnabled;
    SELECT s.ServiceName, s.IsEnabled, s.UpdatedBy, s.UpdatedAt
      FROM dbo.WN_ServiceSwitches s WITH (NOLOCK)
     WHERE s.ServiceName = @ServiceName;
END;
GO
