/****** Object:  StoredProcedure [dbo].[WN_SpaceConfig_DeleteSpaces]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[WN_SpaceConfig_DeleteSpaces]
    @ConfigId INT,
    @SpaceGuids NVARCHAR(MAX) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @LocationId INT = 0, @SpaceTypeId INT = 0;

    SELECT 
        @LocationId = ISNULL(LocationId, 0),
        @SpaceTypeId = ISNULL(SpaceTypeId, 0)
    FROM dbo.WN_SpaceConfig
    WHERE Id = @ConfigId;

    IF @LocationId = 0 AND @SpaceTypeId = 0
    BEGIN
        SELECT CAST(NULL AS NVARCHAR(50)) AS DeletedCode WHERE 1 = 0;
        SELECT CAST(NULL AS NVARCHAR(50)) AS BlockedCode WHERE 1 = 0;
        RETURN;
    END

    CREATE TABLE #TargetGuids (GuidStr NVARCHAR(50) PRIMARY KEY);

    IF @SpaceGuids IS NOT NULL AND LTRIM(RTRIM(@SpaceGuids)) <> ''
    BEGIN
        INSERT INTO #TargetGuids (GuidStr)
        SELECT DISTINCT LTRIM(RTRIM(value))
        FROM STRING_SPLIT(@SpaceGuids, ',')
        WHERE LTRIM(RTRIM(value)) <> '';
    END

    SELECT 
        s.Id, 
        s.Code, 
        CAST(ISNULL(s.IdGUID, s.Id) AS NVARCHAR(50)) AS IdGuidStr
    INTO #TargetSpaces
    FROM dbo.WN_Spaces s
    WHERE s.LocationId = @LocationId 
      AND s.SpaceTypeId = @SpaceTypeId 
      AND (s.IsActive IS NULL OR s.IsActive = 1)
      AND (
          NOT EXISTS (SELECT 1 FROM #TargetGuids)
          OR CAST(ISNULL(s.IdGUID, s.Id) AS NVARCHAR(50)) IN (SELECT GuidStr FROM #TargetGuids)
          OR CAST(s.Id AS NVARCHAR(50)) IN (SELECT GuidStr FROM #TargetGuids)
      );

    CREATE TABLE #Deleted (Code NVARCHAR(50));
    CREATE TABLE #Blocked (Code NVARCHAR(50));

    INSERT INTO #Blocked (Code)
    SELECT ts.Code
    FROM #TargetSpaces ts
    WHERE EXISTS (
        SELECT 1 FROM dbo.WN_Bookings b
        WHERE b.SpaceId = ts.Id 
          AND b.IsDeleted = 0 
          AND b.BookingStatusId IN (1, 2, 5, 33) 
          AND b.EndOn > SYSUTCDATETIME()
    );

    INSERT INTO #Deleted (Code)
    SELECT ts.Code
    FROM #TargetSpaces ts
    WHERE ts.Code NOT IN (SELECT Code FROM #Blocked);

    UPDATE s
    SET s.IsActive = 0, s.Status = 0
    FROM dbo.WN_Spaces s
    JOIN #TargetSpaces ts ON ts.Id = s.Id
    WHERE ts.Code IN (SELECT Code FROM #Deleted);

    SELECT Code AS DeletedCode FROM #Deleted;
    SELECT Code AS BlockedCode FROM #Blocked;

    DROP TABLE #TargetGuids;
    DROP TABLE #TargetSpaces;
    DROP TABLE #Deleted;
    DROP TABLE #Blocked;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_SpaceConfig_GenerateSpaces]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[WN_SpaceConfig_GenerateSpaces]
    @ConfigId INT
AS
BEGIN
    SET NOCOUNT ON;
    SET ANSI_NULLS ON;
    SET QUOTED_IDENTIFIER ON;

    DECLARE @SpaceCategory    NVARCHAR(50);
    DECLARE @TotalSpaces      INT;
    DECLARE @CodePrefix       NVARCHAR(20);
    DECLARE @MinCode          INT;
    DECLARE @FloorId          INT;
    DECLARE @PricePerHour     DECIMAL(18,2);
    DECLARE @PricePerDay      DECIMAL(18,2);
    DECLARE @PricePerMonth    DECIMAL(18,2);
    DECLARE @Amenities        NVARCHAR(MAX);
    DECLARE @RentAccountId    INT;
    DECLARE @DepositAccountId INT;
    DECLARE @LocationId       INT;
    DECLARE @SpaceTypeId      INT;

    SELECT
        @SpaceCategory    = COALESCE(sc.SpaceCategory, st.Name, 'Space'),
        @TotalSpaces      = ISNULL(sc.TotalSpaces, 0),
        @CodePrefix       = ISNULL(sc.CodePrefix, ''),
        @MinCode          = ISNULL(sc.MinCode, 1),
        @FloorId          = sc.FloorId,
        @PricePerHour     = ISNULL(sc.PricePerHour, 0),
        @PricePerDay      = ISNULL(sc.PricePerDay, 0),
        @PricePerMonth    = ISNULL(sc.PricePerMonth, 0),
        @Amenities        = sc.Amenities,
        @RentAccountId    = COALESCE(sc.RentAccountId, st.RentAccountId),
        @DepositAccountId = COALESCE(sc.SecurityReceivedId, st.SecurityReceivedId),
        @LocationId       = sc.LocationId,
        @SpaceTypeId      = sc.SpaceTypeId
    FROM dbo.WN_SpaceConfig sc
    LEFT JOIN dbo.WN_SpaceTypes st ON st.Id = sc.SpaceTypeId
    WHERE sc.Id = @ConfigId AND sc.Status = 1;

    IF @SpaceTypeId IS NULL OR @LocationId IS NULL
    BEGIN
        RAISERROR('Configuration not found or inactive.', 16, 1);
        RETURN;
    END

    IF @TotalSpaces <= 0
    BEGIN
        RAISERROR('TotalSpaces must be greater than 0.', 16, 1);
        RETURN;
    END

    DECLARE @EffectivePrice DECIMAL(18,2) = COALESCE(NULLIF(@PricePerMonth, 0), NULLIF(@PricePerDay, 0), NULLIF(@PricePerHour, 0), 0);

    DECLARE @SpaceTypeName NVARCHAR(100);
    SELECT TOP 1 @SpaceTypeName = Name FROM dbo.WN_SpaceTypes WHERE Id = @SpaceTypeId;

    DECLARE @NamePrefix NVARCHAR(50) = CASE
        WHEN @SpaceTypeName LIKE '%Private%' OR @SpaceCategory LIKE '%Private%' THEN 'Office'
        WHEN @SpaceTypeName LIKE '%Meeting%' OR @SpaceCategory LIKE '%Meeting%' THEN 'Meeting Room'
        WHEN @SpaceTypeName IS NOT NULL AND LTRIM(RTRIM(@SpaceTypeName)) <> '' THEN LTRIM(RTRIM(@SpaceTypeName))
        ELSE 'Space'
    END;

    DECLARE @Created INT = 0;
    DECLARE @Skipped INT = 0;
    DECLARE @i       INT = 0;
    DECLARE @Code    NVARCHAR(50);
    DECLARE @Name    NVARCHAR(255);

    WHILE @i < @TotalSpaces
    BEGIN
        SET @Code = @CodePrefix + CAST(@MinCode + @i AS NVARCHAR(20));
        SET @Name = @NamePrefix + ' ' + CAST(@MinCode + @i AS NVARCHAR(20));

        IF EXISTS (
            SELECT 1 FROM dbo.WN_Spaces
            WHERE LocationId = @LocationId
              AND SpaceTypeId = @SpaceTypeId
              AND Code = @Code
              AND (IsActive = 0 OR Status = 0)
        )
        BEGIN
            UPDATE dbo.WN_Spaces 
            SET IsActive = 1, Status = 1, 
                Name = @Name, Price = @EffectivePrice, FloorId = @FloorId, Amenities = @Amenities,
                RentAccountId = COALESCE(RentAccountId, @RentAccountId),
                SecurityRecivedId = COALESCE(SecurityRecivedId, @DepositAccountId)
            WHERE LocationId = @LocationId
              AND SpaceTypeId = @SpaceTypeId
              AND Code = @Code;

            SET @Created = @Created + 1;
        END
        ELSE IF NOT EXISTS (
            SELECT 1 FROM dbo.WN_Spaces
            WHERE LocationId = @LocationId
              AND SpaceTypeId = @SpaceTypeId
              AND Code = @Code
        )
        BEGIN
            INSERT INTO dbo.WN_Spaces
                (IdGUID, Name, Code, LocationId, SpaceTypeId, FloorId,
                 Price, Amenities, RentAccountId, SecurityRecivedId,
                 IsActive, Status, CreatedOn)
            VALUES
                (NEWID(), @Name, @Code, @LocationId, @SpaceTypeId, @FloorId,
                 @EffectivePrice, @Amenities, @RentAccountId, @DepositAccountId,
                 1, 1, GETUTCDATE());

            SET @Created = @Created + 1;
        END
        ELSE
            SET @Skipped = @Skipped + 1;

        SET @i = @i + 1;
    END

    SELECT @Created AS Created, @Skipped AS Skipped, @TotalSpaces AS Configured;
END;

GO
/****** Object:  StoredProcedure [dbo].[WN_SpaceConfig_GetDepositByCategory]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE     PROCEDURE [dbo].[WN_SpaceConfig_GetDepositByCategory]
    @CategoryCode NVARCHAR(30)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT TOP 1
        sp.SecurityDeposit,
        sp.SeatPrice,
        sp.SeatPrice * s.Capacity AS RoomPrice,
        s.Capacity,
        bp.Code AS BillingPeriodCode
    FROM dbo.WN_SpacePricing      sp WITH (NOLOCK)
    JOIN dbo.WN_Spaces            s  WITH (NOLOCK) ON s.Id  = sp.SpaceId
    JOIN dbo.WN_SpaceTypes        st WITH (NOLOCK) ON st.Id = s.SpaceTypeId
    JOIN dbo.WN_SpaceCategories   sc WITH (NOLOCK) ON sc.Id = st.CategoryId
    JOIN dbo.WN_BillingPeriods    bp WITH (NOLOCK) ON bp.Id = sp.BillingPeriodId
    WHERE sc.Code         = @CategoryCode
      AND bp.Code         = 'Monthly'
      AND sp.IsActive     = 1
      AND sp.EffectiveFrom <= CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE)
      AND (sp.EffectiveTo IS NULL OR sp.EffectiveTo > CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE))
    ORDER BY sp.EffectiveFrom DESC;
END
GO
/****** Object:  StoredProcedure [dbo].[WN_SpaceConfig_GetList]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
