CREATE PROCEDURE [dbo].[WN_SpaceConfig_Insert]
    @SpaceCategory       NVARCHAR(50)   = NULL,
    @TotalSpaces         INT            = 0,
    @CodePrefix          NVARCHAR(20)   = NULL,
    @MinCode             INT            = 1,
    @OpeningTime         NVARCHAR(10)   = '08:00',
    @ClosingTime         NVARCHAR(10)   = '20:00',
    @SecurityDeposit     DECIMAL(18,2)  = 0,
    @FloorId             INT            = NULL,
    @PricePerHour        DECIMAL(18,2)  = 0,
    @PricePerDay         DECIMAL(18,2)  = 0,
    @PricePerMonth       DECIMAL(18,2)  = 0,
    @Price               DECIMAL(18,2)  = NULL,
    @BillingPeriodId     TINYINT        = NULL,
    @Amenities           NVARCHAR(MAX)  = NULL,
    @LocationId          INT            = NULL,
    @SpaceTypeId         INT            = NULL,
    @CreatedBy           NVARCHAR(256)  = NULL,
    @RentAccountId       INT            = NULL,
    @SecurityReceivedId  INT            = NULL,
    @AccountReceivableId INT            = NULL,
    @ServicesIncomeId    INT            = NULL,
    @SalesTaxId          INT            = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET ANSI_NULLS ON;
    SET QUOTED_IDENTIFIER ON;

    IF (@PricePerMonth IS NULL OR @PricePerMonth = 0) AND (@PricePerHour IS NULL OR @PricePerHour = 0) AND (@PricePerDay IS NULL OR @PricePerDay = 0) AND @Price IS NOT NULL AND @Price > 0
    BEGIN
        IF @BillingPeriodId = 1 SET @PricePerHour = @Price;
        ELSE IF @BillingPeriodId = 2 SET @PricePerDay = @Price;
        ELSE SET @PricePerMonth = @Price;
    END

    IF @SpaceTypeId IS NOT NULL
    BEGIN
        SELECT 
            @SpaceCategory       = COALESCE(@SpaceCategory, Name, 'Space'),
            @RentAccountId       = COALESCE(@RentAccountId, RentAccountId),
            @SecurityReceivedId  = COALESCE(@SecurityReceivedId, SecurityReceivedId),
            @AccountReceivableId = COALESCE(@AccountReceivableId, AccountReceivableId),
            @ServicesIncomeId    = COALESCE(@ServicesIncomeId, ServicesIncomeId),
            @SalesTaxId          = COALESCE(@SalesTaxId, SalesTaxId)
        FROM dbo.WN_SpaceTypes
        WHERE Id = @SpaceTypeId;
    END

    INSERT INTO dbo.WN_SpaceConfig
        (SpaceCategory, TotalSpaces, CodePrefix, MinCode, OpeningTime, ClosingTime,
         SecurityDeposit, FloorId, PricePerHour, PricePerDay, PricePerMonth,
         Amenities, LocationId, SpaceTypeId, Status,
         RentAccountId, SecurityReceivedId, AccountReceivableId, ServicesIncomeId, SalesTaxId,
         UpdatedBy, UpdatedOn)
    VALUES
        (ISNULL(@SpaceCategory, 'Space'), @TotalSpaces, ISNULL(@CodePrefix, ''), @MinCode, ISNULL(@OpeningTime, '08:00'), ISNULL(@ClosingTime, '20:00'),
         ISNULL(@SecurityDeposit, 0), @FloorId, ISNULL(@PricePerHour, 0), ISNULL(@PricePerDay, 0), ISNULL(@PricePerMonth, 0),
         @Amenities, @LocationId, @SpaceTypeId, 1,
         @RentAccountId, @SecurityReceivedId, @AccountReceivableId, @ServicesIncomeId, @SalesTaxId,
         @CreatedBy, GETUTCDATE());

    SELECT SCOPE_IDENTITY() AS NewId;
END;

GO
/****** Object:  StoredProcedure [dbo].[WN_SpaceConfig_Update]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
