/****** Object:  StoredProcedure [dbo].[WN_SpaceTypes_GetList]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_SpaceTypes_GetList]
    @CategoryId TINYINT = NULL,
    @LocationId INT     = NULL   -- P1: only this location’s types (NULL = every location, as before)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        st.Id,
        st.IdGUID AS PublicId,
        st.Name,
        st.Description,
        st.CategoryId,
        sc.Code AS CategoryCode,
        sc.Label AS CategoryLabel,
        ISNULL(st.Capacity, 1) AS Capacity,
        st.HourlyAllowed,
        st.IsActive,
        st.AccountReceivableId,
        st.RentAccountId,
        st.ServicesIncomeId,
        st.SalesTaxId,
        st.SecurityReceivedId,
        coa_ar.Description   AS AccountReceivableName,
        coa_rent.Description AS RentAccountName,
        coa_serv.Description AS ServicesIncomeName,
        coa_tax.Description  AS SalesTaxName,
        coa_sec.Description  AS SecurityReceivedName,
        st.LocationId,
        CAST(l.Name AS NVARCHAR(200)) AS LocationName
    FROM dbo.WN_SpaceTypes st WITH (NOLOCK)
    LEFT JOIN dbo.WN_SpaceCategories sc WITH (NOLOCK) ON sc.Id = st.CategoryId
    LEFT JOIN dbo.WN_Locations l WITH (NOLOCK) ON l.Id = st.LocationId
    LEFT JOIN dbo.AccountsCOA coa_ar   WITH (NOLOCK) ON coa_ar.Id = st.AccountReceivableId
    LEFT JOIN dbo.AccountsCOA coa_rent WITH (NOLOCK) ON coa_rent.Id = st.RentAccountId
    LEFT JOIN dbo.AccountsCOA coa_serv WITH (NOLOCK) ON coa_serv.Id = st.ServicesIncomeId
    LEFT JOIN dbo.AccountsCOA coa_tax  WITH (NOLOCK) ON coa_tax.Id = st.SalesTaxId
    LEFT JOIN dbo.AccountsCOA coa_sec  WITH (NOLOCK) ON coa_sec.Id = st.SecurityReceivedId
    WHERE st.IsActive = 1
      AND (@CategoryId IS NULL OR st.CategoryId = @CategoryId)
      AND (@LocationId IS NULL OR st.LocationId = @LocationId)
    ORDER BY l.Name, sc.Label, st.Name;
END
GO
/****** Object:  StoredProcedure [dbo].[WN_SpaceTypes_Insert]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_SpaceTypes_Insert]
    @Name                NVARCHAR(100),
    @Description         NVARCHAR(500) = NULL,
    @CategoryId          TINYINT       = NULL,
    @Capacity            SMALLINT      = NULL,
    @HourlyAllowed       BIT           = 1,
    @AccountReceivableId INT           = NULL,
    @RentAccountId       INT           = NULL,
    @ServicesIncomeId    INT           = NULL,
    @SalesTaxId          INT           = NULL,
    @SecurityReceivedId  INT           = NULL,
    @CreatedById         INT           = NULL,
    @LocationId          INT           = NULL   -- P1: the location this type belongs to (NULL = location 1, I-8, where every type was before)
AS
BEGIN
    -- P1 (space types per location): the type is created for @LocationId; one name per location (also inactive types);
    -- the WN_ChargeTypeAccountMapping copy below now updates only THIS location’s rows (it updated every location’s).
    SET NOCOUNT ON;
    SET @LocationId = ISNULL(@LocationId, 1);
    IF NOT EXISTS (SELECT 1 FROM dbo.WN_Locations WITH (NOLOCK) WHERE Id = @LocationId)
        THROW 50000, N'Location not found.', 1;
    IF EXISTS (SELECT 1 FROM dbo.WN_SpaceTypes WITH (NOLOCK) WHERE LocationId = @LocationId AND Name = @Name)
    BEGIN
        DECLARE @Duplicate NVARCHAR(400) = CONCAT(N'A space type named "', @Name, N'" already exists at this location (deleted types count too).');
        THROW 50000, @Duplicate, 1;
    END
    BEGIN TRANSACTION;
    BEGIN TRY
        DECLARE @NewIdGUID UNIQUEIDENTIFIER = NEWID();
        INSERT INTO dbo.WN_SpaceTypes
            (IdGUID, Name, Description, CategoryId, Capacity, HourlyAllowed, IsActive,
             AccountReceivableId, RentAccountId, ServicesIncomeId, SalesTaxId, SecurityReceivedId,
             CreatedBy, CreatedOn, LocationId)
        VALUES
            (@NewIdGUID, @Name, @Description, @CategoryId, ISNULL(@Capacity, 1), @HourlyAllowed, 1,
             @AccountReceivableId, @RentAccountId, @ServicesIncomeId, @SalesTaxId, @SecurityReceivedId,
             @CreatedById, GETUTCDATE(), @LocationId);
        DECLARE @InsertedId INT = SCOPE_IDENTITY();
        -- Synchronize WN_ChargeTypeAccountMapping (P1: this location’s rows only)
        IF @RentAccountId IS NOT NULL
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.WN_ChargeTypeAccountMapping WHERE ChargeTypeId = 1 AND LocationId = @LocationId)
                UPDATE dbo.WN_ChargeTypeAccountMapping SET RentAccountId = @RentAccountId WHERE ChargeTypeId = 1 AND LocationId = @LocationId;
            ELSE
                INSERT INTO dbo.WN_ChargeTypeAccountMapping (ChargeTypeId, RentAccountId, EffectiveFrom, LocationId) VALUES (1, @RentAccountId, CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE), @LocationId);
        END
        IF @SecurityReceivedId IS NOT NULL
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.WN_ChargeTypeAccountMapping WHERE ChargeTypeId = 2 AND LocationId = @LocationId)
                UPDATE dbo.WN_ChargeTypeAccountMapping SET SecurityReceivedId = @SecurityReceivedId WHERE ChargeTypeId = 2 AND LocationId = @LocationId;
            ELSE
                INSERT INTO dbo.WN_ChargeTypeAccountMapping (ChargeTypeId, SecurityReceivedId, EffectiveFrom, LocationId) VALUES (2, @SecurityReceivedId, CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE), @LocationId);
        END
        IF @SalesTaxId IS NOT NULL
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.WN_ChargeTypeAccountMapping WHERE ChargeTypeId = 3 AND LocationId = @LocationId)
                UPDATE dbo.WN_ChargeTypeAccountMapping SET SalesTaxId = @SalesTaxId WHERE ChargeTypeId = 3 AND LocationId = @LocationId;
            ELSE
                INSERT INTO dbo.WN_ChargeTypeAccountMapping (ChargeTypeId, SalesTaxId, EffectiveFrom, LocationId) VALUES (3, @SalesTaxId, CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE), @LocationId);
        END
        IF @ServicesIncomeId IS NOT NULL
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.WN_ChargeTypeAccountMapping WHERE ChargeTypeId = 4 AND LocationId = @LocationId)
                UPDATE dbo.WN_ChargeTypeAccountMapping SET ServicesIncomeId = @ServicesIncomeId WHERE ChargeTypeId = 4 AND LocationId = @LocationId;
            ELSE
                INSERT INTO dbo.WN_ChargeTypeAccountMapping (ChargeTypeId, ServicesIncomeId, EffectiveFrom, LocationId) VALUES (4, @ServicesIncomeId, CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE), @LocationId);
        END
        IF @AccountReceivableId IS NOT NULL
        BEGIN
            UPDATE dbo.WN_ChargeTypeAccountMapping
            SET AccountReceivableId = @AccountReceivableId
            WHERE ChargeTypeId IN (1, 2, 3, 4) AND LocationId = @LocationId;
        END
        COMMIT TRANSACTION;
        SELECT Id, IdGUID, Capacity, LocationId FROM dbo.WN_SpaceTypes WHERE Id = @InsertedId;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[WN_SpaceTypes_Update]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_SpaceTypes_Update]
    @Id                  INT,
    @Name                NVARCHAR(100) = NULL,
    @Description         NVARCHAR(500) = NULL,
    @CategoryId          TINYINT       = NULL,
    @Capacity            SMALLINT      = NULL,
    @HourlyAllowed       BIT           = NULL,
    @AccountReceivableId INT           = NULL,
    @RentAccountId       INT           = NULL,
    @ServicesIncomeId    INT           = NULL,
    @SalesTaxId          INT           = NULL,
    @SecurityReceivedId  INT           = NULL,
    @UpdatedById         INT           = NULL,
    @LocationId          INT           = NULL   -- P1: move the type to this location (NULL = keep its location, as before)
AS
BEGIN
    -- P1 (space types per location): optional @LocationId; a type already used by spaces or space configuration at
    -- another location can’t be moved there; one name per location; the WN_ChargeTypeAccountMapping copy below now
    -- updates only the type’s location (it updated every location’s rows). Everything else as before (accounts are set
    -- as given, NULL clears them, and are cascaded to the type’s spaces).
    SET NOCOUNT ON;
    DECLARE @TypeLocationId INT, @CurrentName NVARCHAR(200);
    SELECT @TypeLocationId = LocationId, @CurrentName = Name FROM dbo.WN_SpaceTypes WITH (NOLOCK) WHERE Id = @Id;
    IF @TypeLocationId IS NULL
        THROW 50000, N'Space type not found.', 1;
    SET @LocationId = ISNULL(@LocationId, @TypeLocationId);
    IF @LocationId <> @TypeLocationId
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM dbo.WN_Locations WITH (NOLOCK) WHERE Id = @LocationId)
            THROW 50000, N'Location not found.', 1;
        IF EXISTS (SELECT 1 FROM dbo.WN_Spaces WITH (NOLOCK) WHERE SpaceTypeId = @Id AND ISNULL(LocationId, -1) <> @LocationId)
           OR EXISTS (SELECT 1 FROM dbo.WN_SpaceConfig WITH (NOLOCK) WHERE SpaceTypeId = @Id AND ISNULL(LocationId, -1) <> @LocationId)
            THROW 50000, N'This space type has spaces or space configuration at its current location, so it can''t be moved to another location. Create a new type at that location instead.', 1;
    END
    IF EXISTS (SELECT 1 FROM dbo.WN_SpaceTypes WITH (NOLOCK) WHERE LocationId = @LocationId AND Name = ISNULL(@Name, @CurrentName) AND Id <> @Id)
    BEGIN
        DECLARE @Duplicate NVARCHAR(400) = CONCAT(N'A space type named "', ISNULL(@Name, @CurrentName), N'" already exists at this location (deleted types count too).');
        THROW 50000, @Duplicate, 1;
    END
    BEGIN TRANSACTION;
    BEGIN TRY
        UPDATE dbo.WN_SpaceTypes SET
            Name                = ISNULL(@Name,                Name),
            Description         = ISNULL(@Description,         Description),
            CategoryId          = ISNULL(@CategoryId,          CategoryId),
            Capacity            = ISNULL(@Capacity,            Capacity),
            HourlyAllowed       = ISNULL(@HourlyAllowed,       HourlyAllowed),
            AccountReceivableId = @AccountReceivableId,
            RentAccountId       = @RentAccountId,
            ServicesIncomeId    = @ServicesIncomeId,
            SalesTaxId          = @SalesTaxId,
            SecurityReceivedId  = @SecurityReceivedId,
            LocationId          = @LocationId,
            UpdatedBy           = @UpdatedById,
            UpdatedOn           = GETUTCDATE()
        WHERE Id = @Id;
        -- Cascade accounts to child spaces of this space type
        UPDATE dbo.WN_Spaces SET
            AccountReceivableId = @AccountReceivableId,
            RentAccountId       = @RentAccountId,
            ServicesIncomeId    = @ServicesIncomeId,
            SalesTaxId          = @SalesTaxId,
            SecurityReceivedId  = @SecurityReceivedId,
            SecurityRecivedId   = @SecurityReceivedId
        WHERE SpaceTypeId = @Id;
        -- Synchronize WN_ChargeTypeAccountMapping (P1: the type’s location only)
        IF @RentAccountId IS NOT NULL
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.WN_ChargeTypeAccountMapping WHERE ChargeTypeId = 1 AND LocationId = @LocationId)
                UPDATE dbo.WN_ChargeTypeAccountMapping SET RentAccountId = @RentAccountId WHERE ChargeTypeId = 1 AND LocationId = @LocationId;
            ELSE
                INSERT INTO dbo.WN_ChargeTypeAccountMapping (ChargeTypeId, RentAccountId, EffectiveFrom, LocationId) VALUES (1, @RentAccountId, CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE), @LocationId);
        END
        IF @SecurityReceivedId IS NOT NULL
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.WN_ChargeTypeAccountMapping WHERE ChargeTypeId = 2 AND LocationId = @LocationId)
                UPDATE dbo.WN_ChargeTypeAccountMapping SET SecurityReceivedId = @SecurityReceivedId WHERE ChargeTypeId = 2 AND LocationId = @LocationId;
            ELSE
                INSERT INTO dbo.WN_ChargeTypeAccountMapping (ChargeTypeId, SecurityReceivedId, EffectiveFrom, LocationId) VALUES (2, @SecurityReceivedId, CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE), @LocationId);
        END
        IF @SalesTaxId IS NOT NULL
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.WN_ChargeTypeAccountMapping WHERE ChargeTypeId = 3 AND LocationId = @LocationId)
                UPDATE dbo.WN_ChargeTypeAccountMapping SET SalesTaxId = @SalesTaxId WHERE ChargeTypeId = 3 AND LocationId = @LocationId;
            ELSE
                INSERT INTO dbo.WN_ChargeTypeAccountMapping (ChargeTypeId, SalesTaxId, EffectiveFrom, LocationId) VALUES (3, @SalesTaxId, CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE), @LocationId);
        END
        IF @ServicesIncomeId IS NOT NULL
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.WN_ChargeTypeAccountMapping WHERE ChargeTypeId = 4 AND LocationId = @LocationId)
                UPDATE dbo.WN_ChargeTypeAccountMapping SET ServicesIncomeId = @ServicesIncomeId WHERE ChargeTypeId = 4 AND LocationId = @LocationId;
            ELSE
                INSERT INTO dbo.WN_ChargeTypeAccountMapping (ChargeTypeId, ServicesIncomeId, EffectiveFrom, LocationId) VALUES (4, @ServicesIncomeId, CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Pakistan Standard Time' AS DATE), @LocationId);
        END
        IF @AccountReceivableId IS NOT NULL
        BEGIN
            UPDATE dbo.WN_ChargeTypeAccountMapping
            SET AccountReceivableId = @AccountReceivableId
            WHERE ChargeTypeId IN (1, 2, 3, 4) AND LocationId = @LocationId;
        END
        COMMIT TRANSACTION;
        SELECT Id, IdGUID, Capacity, LocationId FROM dbo.WN_SpaceTypes WHERE Id = @Id;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[WN_ToggleAccessStatus]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_ToggleAccessStatus]
    @BookingDetailId INT,
    @CustomerId INT,
    @PersonId INT = NULL,
    @IsEnabled BIT
AS
BEGIN
    SET NOCOUNT ON;

    IF @PersonId IS NOT NULL
    BEGIN
        -- Single Person Toggle
        IF EXISTS (SELECT 1 FROM [dbo].[WN_AccessStatus] WHERE BookingDetailId = @BookingDetailId AND PersonId = @PersonId)
        BEGIN
            UPDATE [dbo].[WN_AccessStatus]
            SET IsEnabled = @IsEnabled,
                RevokedAt = CASE WHEN @IsEnabled = 0 THEN SYSUTCDATETIME() ELSE NULL END
            WHERE BookingDetailId = @BookingDetailId AND PersonId = @PersonId;
        END
        ELSE
        BEGIN
            INSERT INTO [dbo].[WN_AccessStatus] (BookingDetailId, PersonId, CustomerId, IsEnabled, GrantedAt, RevokedAt)
            VALUES (@BookingDetailId, @PersonId, @CustomerId, @IsEnabled, SYSUTCDATETIME(), CASE WHEN @IsEnabled = 0 THEN SYSUTCDATETIME() ELSE NULL END);
        END
    END
    ELSE
    BEGIN
        -- Batch Toggle for all attendants under CustomerId & BookingDetailId
        UPDATE [dbo].[WN_AccessStatus]
        SET IsEnabled = @IsEnabled,
            RevokedAt = CASE WHEN @IsEnabled = 0 THEN SYSUTCDATETIME() ELSE NULL END
        WHERE BookingDetailId = @BookingDetailId AND CustomerId = @CustomerId;
    END

    SELECT @@ROWCOUNT AS RowsUpdated;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_UNIFI_SiteLocations_GetAll]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_UNIFI_SiteLocations_GetAll]
AS
BEGIN
    -- NET_01: the WorkNest locations each UniFi site serves (only locations that still exist). A site without rows
    -- uses the network-wide setting (WN_UNIFI_Settings LocationIds); the API caches nothing of this.
    SET NOCOUNT ON;
    SELECT t.SiteId, t.LocationId, t.SiteName, t.UpdatedBy, t.UpdatedAt
      FROM dbo.WN_UNIFI_SiteLocations t WITH (NOLOCK)
      INNER JOIN dbo.WN_Locations l WITH (NOLOCK) ON l.Id = t.LocationId
     ORDER BY t.SiteId, t.LocationId;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_UNIFI_SiteLocations_Set]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_UNIFI_SiteLocations_Set]
    @SiteId      NVARCHAR(64),
    @SiteName    NVARCHAR(200)  = NULL,
    @LocationIds NVARCHAR(1000) = NULL,
    @UpdatedBy   NVARCHAR(200)  = NULL
AS
BEGIN
    -- NET_01: the UniFi site @SiteId serves exactly these WorkNest locations (CSV of dbo.WN_Locations.Id; ids that are
    -- not in WN_Locations are skipped). Empty = none of its own: the network-wide setting applies to it again. Rows
    -- that stay are not touched and missing ones are added, so every audit row (TR_WN_UNIFI_SiteLocations_Audit) is a
    -- real change. Returns the site's rows afterwards.
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @Wanted TABLE (LocationId INT NOT NULL PRIMARY KEY);
    INSERT INTO @Wanted (LocationId)
    SELECT DISTINCT l.Id
      FROM STRING_SPLIT(ISNULL(@LocationIds, N''), N',') s
      INNER JOIN dbo.WN_Locations l WITH (NOLOCK) ON l.Id = TRY_CAST(LTRIM(RTRIM(s.value)) AS INT);
    BEGIN TRAN;
    DELETE t
      FROM dbo.WN_UNIFI_SiteLocations t
     WHERE t.SiteId = @SiteId
       AND NOT EXISTS (SELECT 1 FROM @Wanted w WHERE w.LocationId = t.LocationId);
    INSERT INTO dbo.WN_UNIFI_SiteLocations (SiteId, LocationId, SiteName, UpdatedBy, UpdatedAt)
    SELECT @SiteId, w.LocationId, @SiteName, @UpdatedBy, SYSUTCDATETIME()
      FROM @Wanted w
     WHERE NOT EXISTS (SELECT 1 FROM dbo.WN_UNIFI_SiteLocations t WITH (UPDLOCK, HOLDLOCK)
                        WHERE t.SiteId = @SiteId AND t.LocationId = w.LocationId);
    COMMIT;
    SELECT t.SiteId, t.LocationId, t.SiteName, t.UpdatedBy, t.UpdatedAt
      FROM dbo.WN_UNIFI_SiteLocations t WITH (NOLOCK)
     WHERE t.SiteId = @SiteId
     ORDER BY t.LocationId;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_UpdateInvoiceBreakdown]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_UpdateInvoiceBreakdown]
    @InvoiceId INT,
    @SubTotal DECIMAL(18,2),
    @DiscountTotal DECIMAL(18,2) = 0,
    @TaxTotal DECIMAL(18,2) = 0,
    @GrandTotal DECIMAL(18,2) = 0,
    @BillingPeriodStart DATE = NULL,
    @BillingPeriodEnd DATE = NULL,
    @AdvanceRentMonths INT = NULL,
    @SecurityDepositMonths INT = NULL,
    @SecurityDepositAmount DECIMAL(18,2) = 0,
    @RoomRentExclTax DECIMAL(18,2) = 0,
    @ServiceCharges DECIMAL(18,2) = 0,
    @TaxOnServiceCharges DECIMAL(18,2) = 0,
    @RentAccountId INT = NULL,
    @SecurityReceivedId INT = NULL,
    @ServicesIncomeId INT = NULL,
    @SalesTaxId INT = NULL,
    @AccountReceivableId INT = NULL,
    @AccountsCoaId INT = NULL,
    @DueOn DATE = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- WHT invoices (InvoiceTypeId 6) keep their grossed-up amounts when callers rewrite the breakdown with net
    -- figures (e.g. re-sending the first invoice). Same formula as WN_Invoices_Insert: rent + support grossed up as
    -- one amount, the rent line absorbs the increase; support and tax unchanged. Normal invoices unchanged.
    DECLARE @InvType INT = NULL, @InvWhtRate DECIMAL(9,4) = NULL, @InvWhtAmount DECIMAL(18,4) = NULL;
    SELECT @InvType = InvoiceTypeId, @InvWhtRate = WHTRate FROM dbo.WN_Invoices WITH (NOLOCK) WHERE Id = @InvoiceId;
    IF @InvType = 6 AND @InvWhtRate > 0 AND @InvWhtRate < 100
       AND (ISNULL(@RoomRentExclTax, 0) + ISNULL(@ServiceCharges, 0)) > 0
    BEGIN
        DECLARE @WhtDivisor DECIMAL(18,10) = 1.0 - (@InvWhtRate / 100.0);
        DECLARE @NetAmount DECIMAL(18,4) = ISNULL(@RoomRentExclTax, 0) + ISNULL(@ServiceCharges, 0);   -- RoomRentNet
        SET @ServiceCharges      = ISNULL(@ServiceCharges, 0);
        SET @TaxOnServiceCharges = ISNULL(@TaxOnServiceCharges, 0);
        SET @RoomRentExclTax     = ROUND(@NetAmount / @WhtDivisor, 2) - @ServiceCharges;          -- RentLine
        SET @InvWhtAmount        = (@RoomRentExclTax + @ServiceCharges) - @NetAmount;
        SET @TaxTotal            = @TaxOnServiceCharges;
        SET @SubTotal            = @RoomRentExclTax + @ServiceCharges + ISNULL(@DiscountTotal, 0);
        SET @GrandTotal          = @RoomRentExclTax + @ServiceCharges + @TaxOnServiceCharges + ISNULL(@SecurityDepositAmount, 0);
    END

    UPDATE dbo.WN_Invoices
    SET SubTotal = @SubTotal,
        DiscountTotal = ISNULL(@DiscountTotal, DiscountTotal),
        TaxTotal = ISNULL(@TaxTotal, TaxTotal),
        GrandTotal = CASE WHEN @GrandTotal > 0 THEN @GrandTotal ELSE GrandTotal END,
        BillingPeriodStart = ISNULL(@BillingPeriodStart, BillingPeriodStart),
        BillingPeriodEnd = ISNULL(@BillingPeriodEnd, BillingPeriodEnd),
        AdvanceRentMonths = ISNULL(@AdvanceRentMonths, AdvanceRentMonths),
        SecurityDepositMonths = ISNULL(@SecurityDepositMonths, SecurityDepositMonths),
        SecurityDepositAmount = ISNULL(@SecurityDepositAmount, SecurityDepositAmount),
        RoomRentExclTax = ISNULL(@RoomRentExclTax, RoomRentExclTax),
        ServiceCharges = ISNULL(@ServiceCharges, ServiceCharges),
        TaxOnServiceCharges = ISNULL(@TaxOnServiceCharges, TaxOnServiceCharges),
        RentAccountId = COALESCE(@RentAccountId, RentAccountId),
        SecurityReceivedId = COALESCE(@SecurityReceivedId, SecurityReceivedId),
        ServicesIncomeId = COALESCE(@ServicesIncomeId, ServicesIncomeId),
        SalesTaxId = COALESCE(@SalesTaxId, SalesTaxId),
        AccountReceivableId = COALESCE(@AccountReceivableId, AccountReceivableId),
        AccountsCoaId = COALESCE(@AccountsCoaId, AccountsCoaId, @RentAccountId),
        DueOn = ISNULL(@DueOn, DueOn),
        WHTAmount = ISNULL(@InvWhtAmount, WHTAmount),
        UpdatedOn = SYSUTCDATETIME()
    WHERE Id = @InvoiceId;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_UserPermissions_GetByUser]    Script Date: 28/10/2026 11:43:10 am ******/
