CREATE   PROCEDURE [dbo].[WN_UserPermissions_GetByUser]
    @UserId INT
AS
BEGIN
    -- CI_01: the permissions one user holds (dbo.WN_UserPermissions). The API policy CustomInvoiceAccess reads it.
