/****** Object:  StoredProcedure [dbo].[WN_UserPermissions_ListAdmins]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_UserPermissions_ListAdmins]
    @Permission NVARCHAR(50)
AS
BEGIN
    -- CI_01: every ACTIVE user with role admin (WN_Roles.RoleName), whether they hold the permission, who granted it and
    -- when (UTC), and their locations (WN_Users.LocationId and dbo.WN_UserLocations, comma-separated).
    SET NOCOUNT ON;
    SELECT u.Id AS UserId,
           u.Name,
           u.Email,
           (SELECT STRING_AGG(x.LocationName, N', ') WITHIN GROUP (ORDER BY x.LocationName)
              FROM (SELECT l.Name AS LocationName FROM dbo.WN_Locations l WITH (NOLOCK) WHERE l.Id = u.LocationId
                    UNION
                    SELECT l.Name FROM dbo.WN_UserLocations ul WITH (NOLOCK)
                      JOIN dbo.WN_Locations l WITH (NOLOCK) ON l.Id = ul.LocationId
                     WHERE ul.UserId = u.Id) x) AS LocationNames,
           CAST(CASE WHEN p.UserId IS NULL THEN 0 ELSE 1 END AS BIT) AS HasAccess,
           COALESCE(NULLIF(LTRIM(RTRIM(g.Name)), N''), g.Email) AS GrantedBy,
           p.GrantedAt
      FROM dbo.WN_Users u WITH (NOLOCK)
      JOIN dbo.WN_Roles r WITH (NOLOCK) ON r.Id = u.RoleId
      LEFT JOIN dbo.WN_UserPermissions p WITH (NOLOCK) ON p.UserId = u.Id AND p.Permission = @Permission
      LEFT JOIN dbo.WN_Users g WITH (NOLOCK) ON g.Id = p.GrantedById
     WHERE u.IsActive = 1
       AND r.RoleName = N'admin'
     ORDER BY u.Name, u.Id;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_UserPermissions_Set]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_UserPermissions_Set]
    @UserId      INT,
    @Permission  NVARCHAR(50),
    @Grant       BIT,
    @GrantedById INT
AS
BEGIN
    -- CI_01: grants (@Grant = 1) or revokes (0) a permission of an ACTIVE admin user; anyone else: error 51000 and nothing
    -- changes. Returns the user as dbo.WN_UserPermissions_ListAdmins does. dbo.TR_WN_UserPermissions_Audit records the
    -- change with who made it.
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM dbo.WN_Users u WITH (NOLOCK)
                     JOIN dbo.WN_Roles r WITH (NOLOCK) ON r.Id = u.RoleId
                    WHERE u.Id = @UserId AND u.IsActive = 1 AND r.RoleName = N'admin')
        THROW 51000, N'Only an active admin user can be given this access.', 1;
    IF @Grant = 1
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM dbo.WN_UserPermissions WITH (UPDLOCK, HOLDLOCK) WHERE UserId = @UserId AND Permission = @Permission)
            INSERT INTO dbo.WN_UserPermissions (UserId, Permission, GrantedById, GrantedAt)
            VALUES (@UserId, @Permission, @GrantedById, SYSUTCDATETIME());
    END
    ELSE
        DELETE FROM dbo.WN_UserPermissions WHERE UserId = @UserId AND Permission = @Permission;
    SELECT u.Id AS UserId,
           u.Name,
           u.Email,
           (SELECT STRING_AGG(x.LocationName, N', ') WITHIN GROUP (ORDER BY x.LocationName)
              FROM (SELECT l.Name AS LocationName FROM dbo.WN_Locations l WITH (NOLOCK) WHERE l.Id = u.LocationId
                    UNION
                    SELECT l.Name FROM dbo.WN_UserLocations ul WITH (NOLOCK)
                      JOIN dbo.WN_Locations l WITH (NOLOCK) ON l.Id = ul.LocationId
                     WHERE ul.UserId = u.Id) x) AS LocationNames,
           CAST(CASE WHEN p.UserId IS NULL THEN 0 ELSE 1 END AS BIT) AS HasAccess,
           COALESCE(NULLIF(LTRIM(RTRIM(g.Name)), N''), g.Email) AS GrantedBy,
           p.GrantedAt
      FROM dbo.WN_Users u WITH (NOLOCK)
      JOIN dbo.WN_Roles r WITH (NOLOCK) ON r.Id = u.RoleId
      LEFT JOIN dbo.WN_UserPermissions p WITH (NOLOCK) ON p.UserId = u.Id AND p.Permission = @Permission
      LEFT JOIN dbo.WN_Users g WITH (NOLOCK) ON g.Id = p.GrantedById
     WHERE u.IsActive = 1
       AND r.RoleName = N'admin'
       AND u.Id = @UserId;
END;
GO
