CREATE   PROCEDURE [dbo].[WN_Users_Update]
    @Id             INT,
    @Name           NVARCHAR(200)  = NULL,
    @PhoneNumber    NVARCHAR(50)   = NULL,
    @CompanyId      INT            = NULL,
    @CityId         INT            = NULL,
    @Address        NVARCHAR(500)  = NULL,
    @CnicOrPassport NVARCHAR(50)   = NULL,
    @AvatarUrl      NVARCHAR(500)  = NULL,
    @Notes          NVARCHAR(1000) = NULL,
    @LocationId     INT            = NULL,
    @Email          NVARCHAR(256)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE dbo.WN_Users SET
        Name           = ISNULL(@Name,           Name),
        PhoneNumber    = ISNULL(@PhoneNumber,     PhoneNumber),
        CompanyId      = ISNULL(@CompanyId,       CompanyId),
        CityId         = ISNULL(@CityId,          CityId),
        Address        = ISNULL(@Address,         Address),
        CnicOrPassport = ISNULL(@CnicOrPassport,  CnicOrPassport),
        AvatarUrl      = ISNULL(@AvatarUrl,       AvatarUrl),
        Notes          = ISNULL(@Notes,           Notes),
        LocationId     = ISNULL(@LocationId,      LocationId),
        Email          = ISNULL(@Email,           Email)
    WHERE Id = @Id;
    SELECT @@ROWCOUNT AS AffectedRows;
END;
GO
/****** Object:  StoredProcedure [dbo].[WN_WHTaxRate_GetList]    Script Date: 28/10/2026 11:43:10 am ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[WN_WHTaxRate_GetList]
    @IncludeInactive BIT = 0
AS
BEGIN
    SET NOCOUNT ON;
    SELECT Id, Code, Description, WHRate, ProvinceId, WHAccountId, Status
    FROM dbo.WN_WHTaxRate WITH (NOLOCK)
    WHERE (@IncludeInactive = 1 OR ISNULL(Status, 1) = 1)
      AND NULLIF(LTRIM(RTRIM(Description)), '') IS NOT NULL
      AND WHRate > 0 AND WHRate < 100
    ORDER BY Description, Id;
END
GO
